const execAsync = promisify(exec);
const execFileAsync = promisify(execFile);

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Restore execute permissions on SynaBun's own native helpers (node-pty's
// spawn-helper). npm and cpSync drop the execute bit, and a checkout with
// core.filemode=false materializes them 0644, so terminals failed to spawn.
// The agent tools are not here: Claude Code and Codex are the user's own
// installations (lib/claude-executable.js, getCodexBin).
//
// This sweeps ALL platform directories, not just this host's: a vendored
// checkout can carry several, and repairing only the current one left e.g.
// prebuilds/darwin-x64/spawn-helper broken for Intel Macs.
// Both node_modules an install can have: the package root's (`npm i -g synabun` puts every dependency there) and
// the Neural Interface's own (a development checkout, a desktop build).
try {
  // SYNABUN_REPAIR_EXECUTABLES=off: a temporary instance booted beside the app leaves the real node_modules alone.
  for (const root of (process.env.SYNABUN_REPAIR_EXECUTABLES === 'off' ? [] : new Set([__dirname, resolve(__dirname, '..')]))) {
    const sweep = ensureVendoredExecutables({ root, log: (msg) => console.log(msg) });
    for (const failure of sweep.failed) {
      console.warn(`[binaries] ${failure.path} is not launchable (${failure.state}).`
        + (failure.repairCommand ? ` Try: ${failure.repairCommand}` : ''));
    }
  }
} catch (err) {
  console.warn('[binaries] Could not verify vendored binary permissions:', err.message);
}

// Load only the canonical data-home environment. Importing `dotenv/config`
// above would first read PACKAGE_ROOT/.env from the server cwd, allowing a
// stale checkout-local SQLITE_DB_PATH to override the external data home.
// SYNABUN_ALLOWED_HOSTS is the one value that is not kept from the file: a name taken out of the file would stay
// allowed until a restart. What the environment itself gives is noted first and put back after the load; the
// file's own line is read when a request asks (publicWebOrigins).
const startedAllowedHosts = startedValueOf(process.env);
dotenvConfig({ path: resolve(getDataHome(), '.env') });
startedAllowedHosts.restore();

const app = express();
const SERVER_BOOT_ID = randomUUID();
let _nativeLoopRuntime = null;
// Main assistant (bottom CLI region): brains + orchestration. Wired after the
// native loop runtime exists; see the "Main assistant" block below.
let _assistantRuntime = null;
// The greeting engine (lib/greeting/): one greeting for every agent. null until it is built (or when it did not start).
let _greeting = null;
let _greetingRouter = null;
let _greetingError = null;
let _assistantDispatcher = null;
// The Assistant's settings store (assistant-config.json), once the Assistant is built: Skills Studio's AI drafting reads
// the owner's saved route for Coding from it (skillDraftDefaultTarget).
let _assistantConfigStore = null;
// The Assistant's model catalog (lib/assistant-catalog.js): Settings → WhatsApp checks its brain choice against it.
let _assistantCatalog = null;
// The Claude account the Assistant's Claude Code workers use when a dispatch names none (assistant-config.json
// `workers.claudeAccount`); a function once the Assistant is wired. An account it names cannot be removed.
let _assistantClaudeWorkerAccount = null;
// The same for Codex workers (`workers.codexAccount`).
let _assistantCodexWorkerAccount = null;
// Who may ask, in front of every route (lib/request-gate.js). A request for the owner's data must name this
// server: everything under /api and /mcp, the invite sign-in, the rendered offline page and the uploaded icons
// answer 403 BAD_HOST to any other Host (a page whose name was re-pointed at this machine sends its own); the
// app's static files stay open, the images uploaded for categories excepted. A request from outside (Cloudflare's
// tunnel, or anything that arrives under the tunnel's or the invite proxy's name) needs an invite session, and
// with one it is a guest: `remote`, below. An invite guest is refused on the admin-only routes and on the
// features the owner has not opened, however the path is spelled: those two checks are mounted after it.
// Everything the gates read is read when a request arrives, never while this file is still being evaluated.
const requestGates = createRequestGates({
  isGuestRequest,
  permissions: () => invitePermissions,
  allowedHosts: publicWebOrigins,
  publicHosts: remoteWebOrigins,
  hasInviteSession: isValidInviteSession,
  uploadedImages: isCategoryUpload,
  mcpKey: () => activeMcpKey,
  settingsHint: () => ENV_PATH,
});
app.use(requestGates.host);
app.use(express.json({ limit: '25mb' }));

// Clean body-parser error handler: ui-state / whiteboard persist base64 images and can
// exceed the JSON limit. Default Express handler dumps a 10-line raw-body stack with no
// URL — this logs one line with context and responds 413 instead.
app.use((err, req, res, next) => {
  if (/^\/api\/provider-panel-auth\/[^/]+\/[^/]+\/api-key(?:\?|$)/.test(req.originalUrl || req.url || '')) return providerApiKeyBodyError(err, req, res, next);
  if (err && (err.type === 'entity.too.large' || err.type === 'entity.parse.failed')) {
    const len = req.headers['content-length'] || '?';
    console.warn(`[body-parser] ${err.type} ${req.method} ${req.originalUrl || req.url} content-length=${len} limit=${err.limit || '?'}`);
    if (!res.headersSent) res.status(err.status || 413).json({ error: err.type, limit: err.limit });
    return;
  }
  next(err);
});

// Cookies are read with parseCookies (lib/http-guards.js): one that cannot be decoded is kept as it was written,
// so a cookie another app left on this host name never fails a request.

// Check if request has a valid invite session cookie
function isValidInviteSession(req) {
  const cookies = parseCookies(req.headers.cookie);
  const token = cookies['synabun_invite'];
  if (!token) return false;
  const session = inviteSessions.get(token);
  if (!session) return false;
  // 24-hour TTL
  if (Date.now() - session.createdAt > 24 * 60 * 60 * 1000) {
    inviteSessions.delete(token);
    persistInviteSessions();
    return false;
  }
  session.lastSeen = Date.now();
  return true;
}

// What comes in from outside reaches /mcp and /invite, and with an invite session whatever a guest may reach:
// 403 Forbidden for the rest (lib/request-gate.js `remote`). From outside is what cloudflared marks with
// CF-Connecting-IP, and whatever arrives under the tunnel's or the invite proxy's name, with that header or
// without it: a proxy that does not set it is no way around the invite.
app.use(requestGates.remote);

// Guest detection — works for both Cloudflare tunnel and custom proxy
function isGuestRequest(req) {
  const cookies = parseCookies(req.headers.cookie);
  const token = cookies['synabun_invite'];
  return !!token && inviteSessions.has(token);
}

// Admin-only protection (guests never reach the sensitive endpoints) and feature permissions (a guest changes
// nothing of a feature that is not opened to guests). The two lists, ADMIN_ONLY_PREFIXES and
// FEATURE_PERMISSION_MAP, and the checks are lib/request-gate.js: they decide on the path as the router will
// match it (letter case, percent-escapes, a doubled slash, `;` parameters), not on the path as it was written.
app.use(requestGates.adminOnly);
app.use(requestGates.features);
// Owner authority by peer-process identity (lib/peer-identity.js): for a request that asks for the page secret or
// carries it, for one of the owner's writes (lib/owner-authority.js), and for one with a brain credential, the process
// at the other end of the connection is looked up in the kernel's TCP table (macOS netstat, ~4 ms per new
// connection, kept on the connection) and its parents walked: SynaBun's automation browser or any browser started
// for automation, an AI agent's process tree, another SynaBun server or a relay (ssh, socat, a proxy, a tunnel, any
// program that listens and calls SynaBun) is never handed the secret and never counts as the owner, whatever host,
// cookie or marker it sends. A brain credential (X-Synabun-Brain-Token) from a process outside the brain's own tree
// is dropped from the request. A lookup that cannot run changes nothing (the rules from before apply). Mounted here,
// in front of every route (the page secret's pieces are made further down and read only when a request comes).
// This install's root (PACKAGE_ROOT, defined further down): SynaBun's own MCP server over HTTP is the one listening
// program the lookup knows, by its main script under it (mcp-server/dist/http.js, `npm run start:http`).
const _peerIdentity = createPeerIdentity({ log: (line) => console.warn(line), disabled: String(process.env.SYNABUN_PEER_IDENTITY || '').toLowerCase() === 'off', synabunRoots: [resolve(__dirname, '..')] });
// The one decision for the owner's routes and sockets (lib/owner-authority.js): every write to /api but the hooks'
// and the agents' feature data, the two reads that hand out a secret, and the owner's sockets are refused to the
// automation browser (its marker or its process), relays, other SynaBun servers, remote logins and an agent's tree
// that does not say it is an agent's call. Requests from outside keep the guest rules.
const _ownerAuthority = createOwnerAuthority({ pageSession: () => _pageSession, isRemote: (req) => requestGates.isRemote(req), peer: _peerIdentity, log: (line) => console.warn(line) });
app.use(_peerIdentity.middleware({ needs: peerLookupWanted }));
app.use(_ownerAuthority.restGate);

