// --- Category Helpers (per-connection) ---

const CATEGORIES_DATA_DIR = resolve(DATA_HOME, 'mcp-data');
const GLOBAL_CATEGORIES_PATH = resolve(CATEGORIES_DATA_DIR, 'custom-categories.json');
const NAME_PATTERN = /^[a-z][a-z0-9-]*$/;
const CATEGORIES_POINT_ID = '00000000-0000-0000-0000-000000000000';

// No default categories: a fresh install has none. A project's defaults are made
// when the project is added (ensureProjectCategories), a feature's category the
// first time the feature saves into it.
function getCategoriesPath() {
  // Single categories file — no per-connection paths needed with SQLite
  return GLOBAL_CATEGORIES_PATH;
}

// The file not written yet: what SQLite (the source of truth) holds, which is nothing on a fresh install.
function categoriesFromDb() {
  try {
    return dbGetCategories().map((row) => {
      const category = { name: row.name, description: row.description || '', created_at: row.created_at };
      if (row.parent) category.parent = row.parent;
      if (row.color) category.color = row.color;
      if (row.is_parent) category.is_parent = true;
      return category;
    });
  } catch {
    return [];
  }
}

function loadCategories() {
  if (!existsSync(GLOBAL_CATEGORIES_PATH)) return categoriesFromDb();
  try {
    const raw = readFileSync(getCategoriesPath(), 'utf-8');
    const data = JSON.parse(raw);
    if (data.version === 1 && Array.isArray(data.categories)) {
      return data.categories;
    }
    return [];
  } catch {
    return [];
  }
}

// The categories file is written by the hooks' helpers (the file the MCP server watches); SQLite gets a copy, as with every other category write.
function syncCategoriesToDb(created) {
  if (!created?.length) return created || [];
  try { dbSaveCategories(loadCategories()); } catch (err) { console.error('Failed to sync categories to SQLite:', err.message); }
  return created;
}

// A project's default categories (parent + project / architecture / bugs / config), made once, when the project is
// registered; never for a project already in the registry. Adds what is missing only.
function ensureProjectCategories(projects) {
  return syncCategoriesToDb(ensureProjectCategoriesInFile(projects).created);
}

// A feature's own category (FEATURE_CATEGORIES: conversations, communication-style, plans, uncategorized), made the
// first time the feature saves into it; a fresh install has none. Adds it only when it is missing.
function ensureFeatureCategory(name) {
  const feature = Object.prototype.hasOwnProperty.call(FEATURE_CATEGORIES, name) ? FEATURE_CATEGORIES[name] : null;
  if (!feature) return [];
  return syncCategoriesToDb(ensureCategoriesInFile([{ name, description: feature.description, is_parent: feature.is_parent }]).created);
}

function saveCategories(categories) {
  const filePath = getCategoriesPath();
  const dir = resolve(filePath, '..');
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  writeFileSync(filePath, JSON.stringify({ version: 1, categories }, null, 2), 'utf-8');

  // Write-through to SQLite categories table
  try {
    dbSaveCategories(categories);
  } catch (err) {
    console.error('Failed to sync categories to SQLite:', err.message);
  }
}

// Is this root file ("/logo-<name>.<ext>", lower-case) the image a category recorded as its upload? Uploads are
// written beside the app's own files (POST /api/categories/:name/logo) and are the owner's: the Host rule
// (lib/request-gate.js) refuses them to a foreign Host by their name, and asks this for the one name the app
// ships a file under, which stays open until a category's upload takes it.
function isCategoryUpload(path) {
  // (asked for a request under a foreign Host: it reads the store when there is one, and never creates it)
  if (!existsSync(GLOBAL_CATEGORIES_PATH)) return false;
  return loadCategories().some((category) => typeof category.logo === 'string' && category.logo.toLowerCase() === path);
}

// SQLite queries use direct WHERE clauses

// --- .env Helpers ---

const ENV_PATH = resolve(DATA_HOME, '.env');

// .env is read on hot request paths (bridge config) — cache by mtime+size
let _envCache = null; // { mtimeMs, size, vars }

function parseEnvFile(filePath) {
  try {
    const isMainEnv = filePath === ENV_PATH;
    let st = null;
    if (isMainEnv) {
      st = statSync(filePath);
      if (_envCache && _envCache.mtimeMs === st.mtimeMs && _envCache.size === st.size) {
        return { ..._envCache.vars }; // copy — callers mutate the result
      }
    }
    const content = readFileSync(filePath, 'utf-8');
    const vars = {};
    for (const line of content.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const eq = trimmed.indexOf('=');
      if (eq === -1) continue;
      vars[trimmed.slice(0, eq)] = trimmed.slice(eq + 1);
    }
    if (isMainEnv && st) _envCache = { mtimeMs: st.mtimeMs, size: st.size, vars: { ...vars } };
    return vars;
  } catch {
    return {};
  }
}

function writeEnvFile(filePath, vars) {
  const globalVars = {};
  const bridgeVars = {};    // { bridgeId: { FIELD: value } }

  for (const [key, value] of Object.entries(vars)) {
    let match;
    // Skip legacy env vars
    if (key.match(/^QDRANT__|^EMBEDDING__|^QDRANT_ACTIVE$|^EMBEDDING_ACTIVE$|^OPENAI_EMBEDDING_API_KEY$|^OPENAI_API_KEY$/)) {
      continue;
    } else if ((match = key.match(/^BRIDGE__([a-z0-9_]+)__(.+)$/))) {
      const [, id, field] = match;
      if (!bridgeVars[id]) bridgeVars[id] = {};
      bridgeVars[id][field] = value;
    } else {
      globalVars[key] = value;
    }
  }

  const lines = [];

  // Section: Bridges
  const bridgeIds = Object.keys(bridgeVars).sort();
  for (const id of bridgeIds) {
    const fields = bridgeVars[id];
    lines.push(`# -- Bridge: ${id} --`);
    for (const field of ['ENABLED', 'WORKSPACE_PATH', 'LAST_SYNC']) {
      if (fields[field] !== undefined) lines.push(`BRIDGE__${id}__${field}=${fields[field]}`);
    }
    lines.push('');
  }

  // Section: Remaining global keys (SETUP_COMPLETE, NEURAL_PORT, etc.)
  const remaining = Object.keys(globalVars);
  if (remaining.length > 0) {
    lines.push('# -- System --');
    for (const k of remaining) lines.push(`${k}=${globalVars[k]}`);
    lines.push('');
  }

  writeFileSync(filePath, lines.join('\n'), 'utf-8');
  if (filePath === ENV_PATH) _envCache = null;
}

// --- Connection management removed (SQLite uses a single local file) ---

// --- Bridge Helpers (read/write BRIDGE__<id>__* in .env) ---

function loadBridgeConfig(bridgeId) {
  const vars = parseEnvFile(ENV_PATH);
  const prefix = `BRIDGE__${bridgeId}__`;
  const fields = {};
  let hasAny = false;

  for (const [key, value] of Object.entries(vars)) {
    if (key.startsWith(prefix)) {
      fields[key.slice(prefix.length)] = value;
      hasAny = true;
    }
  }

  if (!hasAny) return null;

  return {
    enabled: fields.ENABLED === 'true',
    workspacePath: fields.WORKSPACE_PATH || null,
    lastSync: fields.LAST_SYNC || null,
  };
}

function saveBridgeConfig(bridgeId, config) {
  const vars = parseEnvFile(ENV_PATH);
  const prefix = `BRIDGE__${bridgeId}__`;

  vars[`${prefix}ENABLED`] = String(config.enabled ?? false);
  if (config.workspacePath) vars[`${prefix}WORKSPACE_PATH`] = config.workspacePath;
  if (config.lastSync) vars[`${prefix}LAST_SYNC`] = config.lastSync;

  writeEnvFile(ENV_PATH, vars);
}

function removeBridgeConfig(bridgeId) {
  const vars = parseEnvFile(ENV_PATH);
  const prefix = `BRIDGE__${bridgeId}__`;

  for (const key of Object.keys(vars)) {
    if (key.startsWith(prefix)) delete vars[key];
  }

  writeEnvFile(ENV_PATH, vars);
}

// migrateConnectionsJsonToEnv() removed

function maskKey(value) {
  if (!value) return '';
  if (value.length <= 4) return '****';
  return '*'.repeat(value.length - 4) + value.slice(-4);
}

