// The Start Server button on the offline page hands the OS a synabun:// link.
// Whether the handler for it is registered is read once (after the boot-time
// repair below) and told to the pages, which remember it for when we are down.
let _startLauncherState = null;
function getStartLauncherState() {
  if (_startLauncherState === null) {
    try { _startLauncherState = startLauncherState({ packageRoot: PACKAGE_ROOT }); } catch { _startLauncherState = 'missing'; }
  }
  return _startLauncherState;
}
// Set when this server runs inside a packaged application (packaging/): the
// code is then replaced by installing a newer build, never by npm or git.
const PACKAGED_RUNTIME = packagedRuntime();
const INSTALL_KIND = PACKAGED_RUNTIME ? 'app' : isGlobalInstall() ? 'npm' : 'git';
// What a person types to start a packaged application: its entry executable,
// when that is a path that will still be there once this run is over.
const START_ENTRY = durableEntry(PACKAGED_RUNTIME) || '';
// What the desktop app's window asks /api/health (lib/desktop-app.js): the version this server runs and which
// data home it uses, as a hash and never the path, so it can tell its own server from another installation's.
const SERVER_VERSION = (() => { try { return String(JSON.parse(readFileSync(resolve(PACKAGE_ROOT, 'package.json'), 'utf-8')).version || ''); } catch { return ''; } })();
const DATA_HOME_ID = dataHomeId(DATA_HOME);
// The entry this install runs from, even when it does not outlive the run (START_ENTRY is then empty): how the
// desktop app tells its own server from another install's (lib/desktop-app.js classifyServer).
const INSTALL_ENTRY = PACKAGED_RUNTIME?.entry || '';
// A packaged application's own Node runtime, and the global bin of the npm that came with it (where `npm i -g`
// through it puts commands: the prefix as npm settles it from npm_config_prefix, the user's config file and the
// global one, else SynaBun's per-user folder its builtin npmrc names, never the application: lib/child-path.js,
// lib/packaged-runtime.js packagedNpmPrefix). On the PATH of everything this server starts, after everything of
// the user's: the user's own Node and npm stay first, these are the fallback on a machine without. The bin is asked
// for each PATH (cached for seconds), so a prefix set later counts without a restart. This process's own environment
// gets the same order, for every child that simply inherits it (an npm install, git, a CLI); the server's own
// Node children are started by process.execPath, never through PATH.
rememberPackagedPath({
  last: packagedPathFolders(PACKAGED_RUNTIME).last,
  npmBin: PACKAGED_RUNTIME ? () => packagedNpmPrefix(PACKAGED_RUNTIME)?.bin || null : null,
});
applyPackagedChildPath(process.env, PACKAGED_RUNTIME);

// Serve offline.html with what it needs once we are down: the install path,
// how it was installed, the launcher's state and the bridge code itself.
app.get('/offline.html', (req, res) => {
  const html = readFileSync(join(__dirname, 'public', 'offline.html'), 'utf-8');
  let bridgeSource = '';
  try { bridgeSource = readFileSync(join(__dirname, 'public', 'shared', 'start-bridge.js'), 'utf-8'); } catch {}
  res.type('html').send(renderOfflinePage(html, {
    bridgeSource,
    facts: { projectDir: PACKAGE_ROOT, install: INSTALL_KIND, launcher: getStartLauncherState(), entry: START_ENTRY },
  }));
});

// The standalone Claude chat page was retired (the sidepanel replaced it): its
// old address lands on the main interface.
app.get('/claude-chat.html', (req, res) => res.redirect('/'));

app.use('/i18n', express.static(join(__dirname, 'i18n')));
app.use('/games', express.static(join(__dirname, 'games')));
// ETag + no-cache (not no-store): browsers revalidate every load and get a
// zero-body 304 unless the file changed — edits still show up on next reload.
app.use('/skins', express.static(join(__dirname, 'skins'), {
  etag: true,
  lastModified: true,
  setHeaders: (res) => res.setHeader('Cache-Control', 'no-cache'),
}));
// The user's own file icons (POST /api/file-icons, SVG among them): an <img> shows them, opened by their address
// they run nothing and an SVG is a download (lib/untrusted-file-headers.js).
app.use('/custom-icons', express.static(CUSTOM_ICONS_DIR, {
  etag: true,
  lastModified: true,
  setHeaders: (res, path) => { res.setHeader('Cache-Control', 'no-cache'); setUntrustedFileHeaders(res, path); },
}));
// A category's uploaded logo sits beside the app's own files ("/logo-<name>.<ext>"): it gets the same headers.
app.use(function uploadedLogoHeaders(req, res, next) {
  const path = String(req.path || '').toLowerCase();
  if (UPLOADED_IMAGE_PATH.test(path) && (!BUNDLED_LOGO_FILES.includes(path) || isCategoryUpload(path))) setUntrustedFileHeaders(res, path);
  next();
});
// The page secret (lib/page-session.js): one per boot, an HttpOnly cookie the app's own pages get, asked of the
// owner's writes to Skills Studio and the Assistant. A worker never has it; a guest is never handed it. Named by
// this server's port, as the browser's cookie jar is one for every localhost port. Made here, before the first
// middleware that sets it. GET /api/page-session is how an open tab gets this boot's cookie after a restart
// (public/shared/page-session.js retries the refused write once with it).
// The page secret, asked of the peer lookup mounted in front of every route (_peerIdentity, above).
const _pageSession = createPageSession({ port: Number(PORT), isGuest: isGuestRequest, peer: _peerIdentity });
/** Whether a request asks for the page secret (the app's pages, the refresh route, the Studio's owner reads, the
 *  service worker's script), is one of the owner's writes, or carries this boot's secret on an API request: only
 *  then is its peer looked up. */
function peerLookupWanted(req) {
  const path = String(req.path || '');
  if (req.method === 'GET' || req.method === 'HEAD') {
    if (PAGE_SECRET_PATHS.includes(path) || path === PAGE_SECRET_REFRESH_PATH || path === SERVICE_WORKER_PATH) return true;
    // A Studio read hands the owner's page the secret (lib/skills/api-v2.js reader, creation-api.js); an agent's read
    // (its headers) never gets it, so it is not looked up.
    if (path.startsWith('/api/skills-studio/') && !AGENT_HEADERS.some((name) => req.headers[name] !== undefined)) return true;
  }
  // One of the owner's writes, or a read that hands out a secret (lib/owner-authority.js).
  if (_ownerAuthority.needsLookup(req)) return true;
  return path.startsWith('/api/') && _pageSession.carriesSecret(req);
}
app.use(_pageSession.serviceWorker); // GET /sw.js: a worker that takes itself away, for a browser refused the secret
app.use(_pageSession.pages);
app.get('/api/page-session', (req, res) => _pageSession.refresh(req, res)); // PAGE_SECRET_REFRESH_PATH
// Retired 2D bookmarks and explicit variant links always enter the 3D page. Keep their other URL state.
app.get(['/', '/index.html', '/index2d.html'], (req, res, next) => {
  const target = normalizeViewUrl(req.originalUrl);
  if (target !== req.originalUrl) return res.redirect(target);
  next();
});
app.use(express.static(join(__dirname, 'public'), {
  etag: true,
  lastModified: true,
  setHeaders: (res) => res.setHeader('Cache-Control', 'no-cache'),
}));

// --- Helpers ---

// cosineSimilarity and getEmbedding imported from lib/db.js

// --- Link cache ---
// Persisted to disk and keyed on (pointCount, maxUpdatedAt) so restarts and
// unrelated requests never pay the O(n²) recompute. Single-memory changes
// are patched incrementally via patchLinksForMemory().
const LINKS_CACHE_PATH = resolve(DATA_HOME, 'data', 'links-cache.json');
const LINK_SIM_THRESHOLD = 0.65;
const LINK_MAX_PER_NODE = 8;

let _linkCache = null;          // { links, pointCount, maxUpdatedAt, timestamp }
let _linkCacheDiskLoaded = false;
let _linkPersistTimer = null;

function linkCacheValidity() {
  const row = getDb().prepare(
    'SELECT COUNT(*) AS cnt, MAX(updated_at) AS maxUpd FROM memories WHERE trashed_at IS NULL'
  ).get();
  return { pointCount: row.cnt, maxUpdatedAt: row.maxUpd || '' };
}

function getValidLinkCache() {
  if (!_linkCacheDiskLoaded) {
    _linkCacheDiskLoaded = true;
    if (!_linkCache) {
      try {
        const data = JSON.parse(readFileSync(LINKS_CACHE_PATH, 'utf-8'));
        if (Array.isArray(data.links)) _linkCache = data;
      } catch { /* no disk cache yet */ }
    }
  }
  if (!_linkCache) return null;
  const v = linkCacheValidity();
  if (_linkCache.pointCount !== v.pointCount || _linkCache.maxUpdatedAt !== v.maxUpdatedAt) return null;
  return _linkCache;
}

function persistLinkCache() {
  if (_linkPersistTimer) clearTimeout(_linkPersistTimer);
  _linkPersistTimer = setTimeout(() => {
    _linkPersistTimer = null;
    try {
      if (_linkCache) writeFileSync(LINKS_CACHE_PATH, JSON.stringify(_linkCache));
      else if (existsSync(LINKS_CACHE_PATH)) unlinkSync(LINKS_CACHE_PATH);
    } catch { /* best effort */ }
  }, 2000);
}

function setLinkCache(links) {
  const v = linkCacheValidity();
  _linkCache = { links, pointCount: v.pointCount, maxUpdatedAt: v.maxUpdatedAt, timestamp: Date.now() };
  persistLinkCache();
}

// Category → parent lookup, cached on the categories file mtime
let _catParentCache = null; // { mtimeMs, map }
function getCategoryParentMap() {
  const catPath = getCategoriesPath();
  let mtimeMs = -1;
  try { mtimeMs = statSync(catPath).mtimeMs; } catch { /* missing file */ }
  if (_catParentCache && _catParentCache.mtimeMs === mtimeMs) return _catParentCache.map;

  const map = {};
  try {
    const catData = JSON.parse(readFileSync(catPath, 'utf-8'));
    for (const cat of catData.categories) map[cat.name] = cat.parent || cat.name;
  } catch { /* no categories file */ }
  for (const cat of _openclawCategories) map[cat.name] = cat.parent || cat.name;
  _catParentCache = { mtimeMs, map };
  return map;
}

function invalidateMemoriesCache(reason, changedId) {
  if (!_linkCache) return;
  if (changedId) {
    try {
      patchLinksForMemory(changedId);
      console.log(`[cache] Link cache patched incrementally (${reason}: ${changedId.slice(0, 8)})`);
      return;
    } catch (e) {
      console.warn(`[cache] Incremental link patch failed (${e.message}) — dropping cache`);
    }
  }
  _linkCache = null;
  _catParentCache = null;
  persistLinkCache();
  console.log(`[cache] Link cache invalidated (${reason})`);
}

/**
 * Recompute links for ONE memory against the rest: O(n) vector sweep via the
 * in-memory matrix plus one light payload scan, instead of the O(n²) full pass.
 */
function patchLinksForMemory(id) {
  if (!_linkCache) return;
  const links = _linkCache.links.filter(l => l.source !== id && l.target !== id);

  const mem = getMemoryWithVector(id); // null if hard-deleted
  if (mem && !mem.trashed_at) {
    const candidates = new Map(); // otherId → { strength, types }
    const addCand = (otherId, str, type) => {
      const c = candidates.get(otherId);
      if (c) {
        c.strength = Math.max(c.strength, str);
        if (!c.types.includes(type)) c.types.push(type);
      } else {
        candidates.set(otherId, { strength: str, types: [type] });
      }
    };

    for (const s of memoryVectors.topK(mem.vector, LINK_MAX_PER_NODE * 3, LINK_SIM_THRESHOLD)) {
      if (s.id !== id) {
        addCand(s.id, (s.score - LINK_SIM_THRESHOLD) / (1 - LINK_SIM_THRESHOLD), 'similarity');
      }
    }

    const parentMap = getCategoryParentMap();
    const myParent = parentMap[mem.category];
    const myTags = new Set(mem.tags || []);
    const myFiles = new Set(mem.related_files || []);
    const myRel = new Set(mem.related_memory_ids || []);

    const rows = getDb().prepare(`
      SELECT id, category, tags, related_files, related_memory_ids
      FROM memories WHERE trashed_at IS NULL AND id != ?
    `).all(id);

    for (const r of rows) {
      let tags, files, rel;
      try { tags = JSON.parse(r.tags || '[]'); } catch { tags = []; }
      try { files = JSON.parse(r.related_files || '[]') || []; } catch { files = []; }
      try { rel = JSON.parse(r.related_memory_ids || '[]') || []; } catch { rel = []; }

      if (myRel.has(r.id) || rel.includes(id)) addCand(r.id, 0.9, 'manual');

      if (myFiles.size > 0 && files.length > 0) {
        const shared = files.filter(f => myFiles.has(f)).length;
        if (shared > 0) addCand(r.id, 0.3 + shared * 0.15, 'files');
      }
      if (myTags.size > 0 && tags.length > 0) {
        const shared = tags.filter(t => myTags.has(t)).length;
        if (shared > 0) addCand(r.id, 0.25 + shared * 0.1, 'tags');
      }
      if (myParent && parentMap[r.category] === myParent) {
        const c = candidates.get(r.id);
        if (!c || c.strength < 0.3) addCand(r.id, 0.2, 'family');
      }
    }

    const sorted = [...candidates.entries()]
      .map(([otherId, c]) => ({ otherId, strength: Math.min(c.strength, 1), types: c.types }))
      .filter(c => c.strength > 0.1)
      .sort((a, b) => b.strength - a.strength);

    let kept = 0;
    for (const c of sorted) {
      const isManual = c.types.includes('manual');
      if (!isManual && kept >= LINK_MAX_PER_NODE) continue;
      links.push({ source: id, target: c.otherId, strength: c.strength, types: c.types });
      kept++;
    }
  }

  setLinkCache(links);
}

/**
 * Compute links between nodes. Uses pre-computed magnitudes and inverted indexes
 * for file/tag overlap instead of O(n² × m) array intersections.
 */
let _linksInFlight = null;

async function computeLinks(nodes) {
  // De-dupe concurrent cold recomputes: callers share one in-flight result.
  if (_linksInFlight) return _linksInFlight;
  _linksInFlight = (async () => {
  const SIM_THRESHOLD = LINK_SIM_THRESHOLD;
  const MAX_LINKS_PER_NODE = LINK_MAX_PER_NODE;
  // Weak links (family/files/tags) are pruned to the top MAX_LINKS_PER_NODE by
  // strength anyway, so cap how many we even GENERATE per node. Without this, a
  // dense parent category or a widely-shared file/tag produces O(k²) raw links —
  // ~13M objects on 9.8k memories — which OOM-crashes the process before the prune
  // below ever runs. The cap keeps headroom over the final cap so the graph is
  // visually identical (dropped links are equal-weight filler that pruning discards).
  const WEAK_GEN_CAP = LINK_MAX_PER_NODE * 2;

  const categoryParentMap = getCategoryParentMap();

  const linkMap = new Map();
  function addLink(idA, idB, str, type) {
    const key = idA < idB ? `${idA}|${idB}` : `${idB}|${idA}`;
    const existing = linkMap.get(key);
    if (existing) {
      existing.strength = Math.max(existing.strength, str);
      if (!existing.types.includes(type)) existing.types.push(type);
    } else {
      linkMap.set(key, { source: idA, target: idB, strength: str, types: [type] });
    }
  }

  // Pre-compute vector magnitudes (halves cosine computation)
  const magnitudes = new Float64Array(nodes.length);
  for (let i = 0; i < nodes.length; i++) {
    if (!nodes[i].vector) continue;
    const v = nodes[i].vector;
    let sum = 0;
    for (let k = 0; k < v.length; k++) sum += v[k] * v[k];
    magnitudes[i] = Math.sqrt(sum);
  }

  // Build inverted indexes for shared files, tags and parent category (O(n))
  const fileIndex = new Map();   // filename → [nodeIndex, ...]
  const tagIndex = new Map();    // tag → [nodeIndex, ...]
  const parentIndex = new Map(); // parentCategory → [nodeIndex, ...]
  const nodeIdIndex = new Map(); // id → nodeIndex
  for (let i = 0; i < nodes.length; i++) {
    nodeIdIndex.set(nodes[i].id, i);
    const p = nodes[i].payload;
    if (p.related_files) {
      for (const f of p.related_files) {
        let arr = fileIndex.get(f);
        if (!arr) { arr = []; fileIndex.set(f, arr); }
        arr.push(i);
      }
    }
    if (p.tags) {
      for (const t of p.tags) {
        let arr = tagIndex.get(t);
        if (!arr) { arr = []; tagIndex.set(t, arr); }
        arr.push(i);
      }
    }
    const parent = categoryParentMap[p.category];
    if (parent) {
      let arr = parentIndex.get(parent);
      if (!arr) { arr = []; parentIndex.set(parent, arr); }
      arr.push(i);
    }
  }

  // Per-node generation budget for the weak link sources.
  const genDegree = new Int32Array(nodes.length);
  function addWeakLink(ia, ib, str, type, guardStrong) {
    const idA = nodes[ia].id, idB = nodes[ib].id;
    const key = idA < idB ? `${idA}|${idB}` : `${idB}|${idA}`;
    const existing = linkMap.get(key);
    if (existing) {
      // family: don't tag or touch a pair that already has a stronger link
      if (guardStrong && existing.strength >= 0.3) return;
      existing.strength = Math.max(existing.strength, str);
      if (!existing.types.includes(type)) existing.types.push(type);
      return;
    }
    if (genDegree[ia] >= WEAK_GEN_CAP && genDegree[ib] >= WEAK_GEN_CAP) return;
    linkMap.set(key, { source: idA, target: idB, strength: str, types: [type] });
    genDegree[ia]++; genDegree[ib]++;
  }

  // Generate capped pairwise links within one inverted-index group.
  function linkGroup(indices, type, strengthFor, guardStrong) {
    const n = indices.length;
    if (n < 2) return;
    for (let x = 0; x < n; x++) {
      const ix = indices[x];
      if (genDegree[ix] >= WEAK_GEN_CAP) continue;
      for (let y = x + 1; y < n; y++) {
        if (genDegree[ix] >= WEAK_GEN_CAP) break;
        const iy = indices[y];
        if (genDegree[iy] >= WEAK_GEN_CAP) continue;
        const str = strengthFor(ix, iy);
        if (str > 0) addWeakLink(ix, iy, str, type, guardStrong);
      }
    }
  }

  // Cosine similarity (O(n²)) + explicit related_memory_ids. Time-based yield:
  // early rows are the most expensive (j spans nearly all of n), so a fixed
  // iteration stride still produced multi-hundred-ms stalls on large graphs.
  // Yielding whenever ~20ms of compute has accumulated bounds every stall.
  const t0 = Date.now();
  let _lastYield = Date.now();
  for (let i = 0; i < nodes.length; i++) {
    const a = nodes[i];
    if (a.vector && magnitudes[i] > 0) {
      const va = a.vector, magA = magnitudes[i];
      for (let j = i + 1; j < nodes.length; j++) {
        if (!nodes[j].vector || magnitudes[j] <= 0) continue;
        const vb = nodes[j].vector;
        let dot = 0;
        for (let k = 0; k < va.length; k++) dot += va[k] * vb[k];
        const sim = dot / (magA * magnitudes[j]);
        if (sim > SIM_THRESHOLD) {
          addLink(a.id, nodes[j].id, (sim - SIM_THRESHOLD) / (1 - SIM_THRESHOLD), 'similarity');
        }
      }
    }

    // Explicit related_memory_ids (strongest; never capped)
    if (a.payload.related_memory_ids) {
      for (const relId of a.payload.related_memory_ids) {
        if (nodeIdIndex.has(relId)) addLink(a.id, relId, 0.9, 'manual');
      }
    }

    if (Date.now() - _lastYield > 20) {
      await new Promise(r => setImmediate(r));
      _lastYield = Date.now();
    }
  }

  // Weak sources, strongest first, so each node spends its cap on its best links.
  for (const [, indices] of fileIndex) {
    linkGroup(indices, 'files', (ix, iy) => {
      const aFiles = new Set(nodes[ix].payload.related_files);
      const shared = nodes[iy].payload.related_files.filter(f => aFiles.has(f)).length;
      return shared > 0 ? 0.3 + shared * 0.15 : 0;
    }, false);
  }
  for (const [, indices] of tagIndex) {
    linkGroup(indices, 'tags', (ix, iy) => {
      const aTags = new Set(nodes[ix].payload.tags);
      const shared = nodes[iy].payload.tags.filter(t => aTags.has(t)).length;
      return shared > 0 ? 0.25 + shared * 0.1 : 0;
    }, false);
  }
  for (const [, indices] of parentIndex) {
    linkGroup(indices, 'family', () => 0.2, true);
  }

  const elapsed = Date.now() - t0;
  console.log(`[links] Computed ${linkMap.size} raw links from ${nodes.length} nodes in ${elapsed}ms`);

  // Filter and cap per node
  const allCandidates = [];
  for (const link of linkMap.values()) {
    if (link.strength > 0.1) {
      allCandidates.push({ source: link.source, target: link.target, strength: Math.min(link.strength, 1), types: link.types });
    }
  }
  allCandidates.sort((a, b) => b.strength - a.strength);
  const nodeLinkCount = new Map();
  const links = [];
  for (const link of allCandidates) {
    const sc = nodeLinkCount.get(link.source) || 0;
    const tc = nodeLinkCount.get(link.target) || 0;
    const isManual = link.types.includes('manual');
    if (!isManual && sc >= MAX_LINKS_PER_NODE && tc >= MAX_LINKS_PER_NODE) continue;
    links.push(link);
    nodeLinkCount.set(link.source, sc + 1);
    nodeLinkCount.set(link.target, tc + 1);
  }

  return links;
  })();
  try { return await _linksInFlight; } finally { _linksInFlight = null; }
}

// --- Routes ---

// GET /api/memories — All memories, optionally with pre-computed graph edges
// Use ?links=false to skip the expensive link computation (default for initial 3D load)
app.get('/api/memories', async (req, res) => {
  try {
    const includeLinks = req.query.links !== 'false';
    // fields=graph: slim payload for graph views — content truncated (flagged
    // so clients hydrate via /api/memory/:id before showing/editing), heavy
    // metadata columns dropped. ~4x smaller JSON for large graphs.
    const slim = req.query.fields === 'graph';
    const SLIM_CONTENT_CHARS = 500;

    const cachedLinks = includeLinks ? getValidLinkCache() : null;
    const needVectors = includeLinks && !cachedLinks;
    const allPoints = needVectors ? getAllMemoriesWithVectors() : getAllMemories();

    // Build nodes
    const nodes = allPoints.map(p => ({
      id: p.id,
      payload: { content: p.content, category: p.category, subcategory: p.subcategory, project: p.project, tags: p.tags, importance: p.importance, source: p.source, created_at: p.created_at, updated_at: p.updated_at, accessed_at: p.accessed_at, access_count: p.access_count, related_files: p.related_files, related_memory_ids: p.related_memory_ids, file_checksums: p.file_checksums, trashed_at: p.trashed_at, source_session_chunks: p.source_session_chunks },
      vector: p.vector || null,
    }));

    // Merge OpenClaw bridge nodes
    const ocBridge = loadBridgeConfig('openclaw');
    if (ocBridge?.enabled && _openclawNodes.length > 0) {
      for (const ocNode of _openclawNodes) {
        nodes.push({ ...ocNode, vector: null });
      }
    }

    // Compute or serve cached links
    let links = [];
    if (includeLinks) {
      if (cachedLinks) {
        links = cachedLinks.links;
        console.log(`[cache] Serving ${links.length} cached links`);
      } else {
        links = await computeLinks(nodes);
        setLinkCache(links);
      }
    }

    // Strip vectors; apply slim mode
    const clientNodes = nodes.map(({ vector, ...rest }) => {
      if (!slim) return rest;
      const p = rest.payload;
      const slimPayload = {
        content: p.content && p.content.length > SLIM_CONTENT_CHARS
          ? p.content.slice(0, SLIM_CONTENT_CHARS) + '…'
          : p.content,
        category: p.category, subcategory: p.subcategory, project: p.project,
        tags: p.tags, importance: p.importance, source: p.source,
        created_at: p.created_at, updated_at: p.updated_at,
        accessed_at: p.accessed_at, access_count: p.access_count,
        related_files: p.related_files, related_memory_ids: p.related_memory_ids,
        trashed_at: p.trashed_at,
      };
      if (p.content && p.content.length > SLIM_CONTENT_CHARS) slimPayload.contentTruncated = true;
      return { ...rest, payload: slimPayload };
    });

    res.json({ nodes: clientNodes, links, totalVectors: allPoints.length, openclawNodes: ocBridge?.enabled ? _openclawNodes.length : 0 });
  } catch (err) {
    console.error('GET /api/memories error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/links — Fetch only the links (lazy-loaded by client when user enables link mode)
app.get('/api/links', async (req, res) => {
  try {
    const cached = getValidLinkCache();
    if (cached) {
      console.log(`[cache] Serving ${cached.links.length} cached links (dedicated endpoint)`);
      return res.json({ links: cached.links });
    }

    const allPoints = getAllMemoriesWithVectors();
    const nodes = allPoints.map(p => ({
      id: p.id,
      payload: { content: p.content, category: p.category, project: p.project, tags: p.tags, importance: p.importance, related_files: p.related_files, related_memory_ids: p.related_memory_ids },
      vector: p.vector,
    }));
    const ocBridge = loadBridgeConfig('openclaw');
    if (ocBridge?.enabled && _openclawNodes.length > 0) {
      for (const ocNode of _openclawNodes) nodes.push({ ...ocNode, vector: null });
    }

    const links = await computeLinks(nodes);
    setLinkCache(links);

    res.json({ links });
  } catch (err) {
    console.error('GET /api/links error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/cache/invalidate — External cache invalidation (called by MCP server)
app.post('/api/cache/invalidate', (req, res) => {
  invalidateMemoriesCache(req.body?.reason || 'external', req.body?.id);
  res.json({ ok: true });
});

app.use('/api', createMemoryApi({
  heartbeat: (id) => { const entry = sessionRegistry.get(id); if (entry) entry.lastActivity = Date.now(); },
  invalidate: (id, type = 'memory:updated') => { invalidateMemoriesCache(type,id); broadcastSync({type,id}); },
  // The TypeSafe key lives in ~/.synabun/.env beside the other secrets; the
  // router cannot import these helpers from here, so they are handed in.
  envPath: ENV_PATH, parseEnvFile, writeEnvFile,
  benchDir: resolve(PACKAGE_ROOT, 'benchmarks'),
}));

// Memory map (the 3D view): positions for every memory, computed in a worker
// and kept current from the memory_changes feed. See lib/memory-map-api.js.
const memoryMap = createMemoryMapService({
  getDb,
  memoryVectors,
  cachePath: resolve(DATA_HOME, 'data', 'memory-map.json'),
  loadCategories,
  categoriesPath: getCategoriesPath,
  getBridgeNodes: () => (loadBridgeConfig('openclaw')?.enabled ? _openclawNodes : []),
  getBridgeCategories: () => (loadBridgeConfig('openclaw')?.enabled ? _openclawCategories : []),
  broadcast: (message) => broadcastSync(message),
});
app.use('/api', createMemoryMapApi(memoryMap));

// ── WhatsApp Link (lib/whatsapp/, docs/whatsapp.md) ──
// Mounted here, synchronously, so the Settings tab never meets a 404 while the
// Assistant boots; the service itself is built by startWhatsAppLink() at the
// end of the Assistant block (its bridge drives the runtime and dispatcher).
// Until then GET /status reports "unavailable" with a reason and every other
// route answers 503. Nothing on this app compresses or buffers responses, so
// the NDJSON link and claim streams reach the tab as they are written.
let _whatsapp = null;
let _whatsappDownReason = String(process.env.SYNABUN_WHATSAPP || '').trim().toLowerCase() === 'off' ? 'env' : 'starting';
app.use('/api/whatsapp', (req, res, next) => {
  if (_whatsapp) return _whatsapp.router(req, res, next);
  res.set('Cache-Control', 'no-store');
  if (req.method === 'GET' && req.path === '/status') return res.json({ ok: true, v: 1, state: 'unavailable', reason: _whatsappDownReason });
  const error = _whatsappDownReason === 'starting' ? 'WhatsApp is still starting. Try again in a few seconds.' : 'WhatsApp is not available on this computer.';
  return res.status(503).json({ ok: false, code: 'UNAVAILABLE', error });
});

/** The Assistant panel's last-used brain (asst-state.js readStoredBrain), for new WhatsApp conversations. */
function readAssistantPanelBrain() {
  try {
    const raw = loadUiState()['neural-assistant-brain'];
    const brain = typeof raw === 'string' ? JSON.parse(raw) : raw;
    return brain && typeof brain === 'object' && !Array.isArray(brain) ? brain : null;
  } catch { return null; }
}

// What lets a WhatsApp conversation control the Mac is a capability, not the string "whatsapp"
// (lib/remote-policy.js createPhoneAuthority). Made once, here, and split: the Assistant runtime
// gets the verifier, the WhatsApp service the issuer, the one bridge it builds the capability.
// Not exported, on no object, in no route: nothing else in the process can grant computer use.
const _phoneAuthority = createPhoneAuthority();
/**
 * Build and start the WhatsApp Link once the Assistant runtime and dispatcher
 * exist (or failed to: the tab can still pause and unlink). Never throws:
 * SYNABUN_WHATSAPP=off loads nothing, and a failure leaves the tab reporting
 * "unavailable" instead of taking the server down. The runtime, dispatcher,
 * bridge and service share the process-wide remote-policy registry.
 */
async function startWhatsAppLink() {
  // (the phone's authority is _phoneAuthority above: this service gets the issuer, the runtime the verifier)
  if (_whatsappDownReason === 'env') { console.log('  WhatsApp:  off (SYNABUN_WHATSAPP=off)'); return; }
  let service = null;
  try {
    const { createWhatsAppService } = await import('./lib/whatsapp/service.js');
    service = createWhatsAppService({
      dataHome: DATA_HOME,
      port: Number(PORT),
      getRuntime: () => _assistantRuntime,
      getDispatcher: () => _assistantDispatcher,
      getKvConfig, setKvConfig, broadcastSync, isGuestRequest,
      log: (message, level) => (level === 'warn' || level === 'error' ? console.warn(message) : console.log(message)),
      getDefaultBrain: readAssistantPanelBrain,
      // "Same as the Assistant" or a model of the Assistant's own catalog (enabled models only).
      getCatalog: () => _assistantCatalog,
      // The issuer only: each bridge the service builds gets a fresh capability, the one before dies.
      phoneAuthority: { issue: _phoneAuthority.issue, revoke: _phoneAuthority.revoke },
      // Folders a backup copies besides DATA_HOME/data and mcp-data: the session keys never go there.
      extraBackupRoots: getBackupAdditionalEntries().map((entry) => entry.diskPath),
    });
  } catch (err) {
    _whatsappDownReason = 'error';
    console.warn('[whatsapp] unavailable:', err?.message || err);
    return;
  }
  _whatsapp = service;
  try {
    const status = await service.start();
    console.log(`  WhatsApp:  ${status?.state || 'ready'}`);
  } catch (err) {
    console.warn('[whatsapp] start failed:', err?.message || err);
  }
}

// GET /api/stats — Memory count including trash count (5s cache — UI polls this)
let _statsCache = null; // { data, ts }
app.get('/api/stats', async (req, res) => {
  try {
    if (_statsCache && Date.now() - _statsCache.ts < 5000) {
      return res.json(_statsCache.data);
    }
    const stats = getMemoryStats();
    const sessionChunks = countSessionChunks();

    const data = {
      count: stats.total,
      vectors: stats.total + sessionChunks,
      status: 'green',
      trash_count: stats.trashedCount,
    };
    _statsCache = { data, ts: Date.now() };
    res.json(data);
  } catch (err) {
    console.error('GET /api/stats error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/recall-impact — Memory counts by importance threshold for recall settings UI
app.get('/api/recall-impact', (req, res) => {
  try {
    const d = getDb();
    const rows = d.prepare(`
      SELECT importance, COUNT(*) as cnt, CAST(AVG(LENGTH(content)) AS INTEGER) as avg_len,
             CAST(AVG(CASE WHEN tags IS NOT NULL AND tags != '[]' THEN LENGTH(tags) ELSE 0 END) AS INTEGER) as avg_tags_len,
             CAST(AVG(CASE WHEN related_files IS NOT NULL AND related_files != '[]' THEN LENGTH(related_files) ELSE 0 END) AS INTEGER) as avg_files_len
      FROM memories WHERE trashed_at IS NULL GROUP BY importance ORDER BY importance
    `).all();
    // Session chunk stats for token estimation
    let sessionStats = { count: 0, avg_summary_len: 0, avg_details_len: 0 };
    try {
      const sc = d.prepare(`
        SELECT COUNT(*) as count,
               CAST(AVG(LENGTH(summary)) AS INTEGER) as avg_summary_len,
               CAST(AVG(
                 COALESCE(LENGTH(tools_used), 0) +
                 COALESCE(LENGTH(files_modified), 0) +
                 COALESCE(LENGTH(related_memory_ids), 0)
               ) AS INTEGER) as avg_details_len
        FROM session_chunks
      `).get();
      if (sc) sessionStats = sc;
    } catch { /* session_chunks table may not exist */ }
    res.json({ rows, sessionStats });
  } catch (err) {
    console.error('GET /api/recall-impact error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

