    const catalogPath = resolve(codexHome, 'models_cache.json');
    if (!existsSync(catalogPath)) return { models: [] };
    const parsed = JSON.parse(readFileSync(catalogPath, 'utf-8'));
    return parsed && typeof parsed === 'object' ? parsed : { models: [] };
