// ── Provider credentials (OpenCode 2's integrations) ──
// OpenCode 2 keeps provider credentials in its own database and uses a change at once: a key saved, a sign-in
// finished or a credential removed needs no restart. A secret never comes back from these routes: an
// integration's connections name a credential, never its value.

// The shared serve's client, for a route that needs OpenCode running (null when it is not).
function sharedOpencodeClient() {
  return _ocpReady ? opencodeV2Client.getClient() : null;
}

// A failed OpenCode answer as `{ status, error }` for a route's reply.
function opencodeFailure(result, fallback) {
  const error = result?.error;
  const status = Number(result?.response?.status);
  const message = typeof error === 'string' ? error : (error?.message || error?.data?.message || error?._tag || fallback);
  return { status: status >= 400 && status < 600 ? status : 502, error: message || fallback };
}

// The answer a sign-in method's form gets without the user: its hidden fields and the fields with a default.
async function opencodeOAuthDefaults(client, integrationID, methodID) {
  const listed = await client.integration.list({});
  const integration = (Array.isArray(listed.data) ? listed.data : []).find((row) => row?.id === integrationID);
  const method = (Array.isArray(integration?.methods) ? integration.methods : []).find((row) => row?.type === 'oauth' && row.id === methodID);
  const answer = {};
  for (const field of Array.isArray(method?.form) ? method.form : []) {
    if (field?.key && field.default !== undefined) answer[field.key] = field.default;
  }
  return Object.keys(answer).length ? answer : null;
}

// How each provider can be connected: { [id]: [{ type: 'api' | 'oauth', label, id }] }.
app.get('/api/opencode/providers/auth', async (req, res) => {
  try {
    const client = sharedOpencodeClient();
    if (!client) return res.json({ ok: false, error: 'OpenCode server not running', data: {} });
    const r = await client.provider.auth({});
    if (r.error) { const failed = opencodeFailure(r, 'OpenCode did not list its integrations'); return res.status(failed.status).json({ ok: false, error: failed.error, data: {} }); }
    res.json({ ok: true, data: r.data });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// The providers OpenCode holds a credential of (ids only).
app.get('/api/opencode/auth/stored', async (req, res) => {
  try {
    const client = sharedOpencodeClient();
    if (!client) return res.json({ ok: true, data: [] });
    const r = await client.integration.list({});
    res.json({ ok: true, data: r.error ? [] : integrationsWithCredentials(r.data) });
  } catch (err) {
    res.json({ ok: true, data: [] });
  }
});

// Save an API key for a provider: { key }.
app.put('/api/opencode/auth/:providerId', async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ ok: false, error: 'Admin only' });
  try {
    const client = sharedOpencodeClient();
    if (!client) return res.status(503).json({ ok: false, error: 'OpenCode server not running' });
    const key = typeof req.body?.key === 'string' ? req.body.key.trim() : '';
    if (!key) return res.status(400).json({ ok: false, error: 'An API key is required' });
    const r = await client.integration.connectKey({ integrationID: req.params.providerId, key });
    if (r.error) { const failed = opencodeFailure(r, 'OpenCode did not save the key'); return res.status(failed.status).json({ ok: false, error: failed.error }); }
    console.log(`[opencode] Saved a key for ${req.params.providerId}`);
    broadcastToOpencodeV2Clients({ type: 'providers:changed' });
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Remove every credential OpenCode holds for a provider.
app.delete('/api/opencode/auth/:providerId', async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ ok: false, error: 'Admin only' });
  try {
    const client = sharedOpencodeClient();
    if (!client) return res.status(503).json({ ok: false, error: 'OpenCode server not running' });
    const providerId = req.params.providerId;
    const listed = await client.integration.list({});
    if (listed.error) { const failed = opencodeFailure(listed, 'OpenCode did not list its integrations'); return res.status(failed.status).json({ ok: false, error: failed.error }); }
    const ids = integrationCredentialIds((Array.isArray(listed.data) ? listed.data : []).find((row) => row?.id === providerId));
    if (!ids.length) return res.status(404).json({ ok: false, error: `OpenCode holds no credential of ${providerId}.` });
    for (const credentialID of ids) {
      const removed = await client.credential.remove({ credentialID });
      if (removed.error && Number(removed.response?.status) !== 404) {
        const failed = opencodeFailure(removed, 'OpenCode did not remove the credential');
        return res.status(failed.status).json({ ok: false, error: failed.error });
      }
    }
    console.log(`[opencode] Removed ${ids.length} credential(s) of ${providerId}`);
    broadcastToOpencodeV2Clients({ type: 'providers:changed' });
    res.json({ ok: true, removed: ids.length });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Start a sign-in: { methodID } (or `method`, its place in the provider's list of /providers/auth). Answers
// { url, instructions, method: 'auto' | 'code', attemptID }: 'auto' finishes by itself (poll …/status), 'code'
// when the user pastes the code the provider showed (…/callback).
app.post('/api/opencode/oauth/:providerId/authorize', async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ ok: false, error: 'Admin only' });
  try {
    const client = sharedOpencodeClient();
    if (!client) return res.status(503).json({ ok: false, error: 'OpenCode server not running' });
    const providerId = req.params.providerId;
    let methodID = typeof req.body?.methodID === 'string' ? req.body.methodID.trim() : '';
    if (!methodID) {
      const auth = await client.provider.auth({});
      const methods = Array.isArray(auth.data?.[providerId]) ? auth.data[providerId] : [];
      const picked = methods[Number(req.body?.method)];
      methodID = (picked?.type === 'oauth' ? picked.id : methods.find((method) => method.type === 'oauth')?.id) || '';
    }
    if (!methodID) return res.status(400).json({ ok: false, error: `${providerId} has no sign-in SynaBun can start.` });
    const answer = await opencodeOAuthDefaults(client, providerId, methodID);
    const r = await client.integration.connectOAuth({ integrationID: providerId, methodID, ...(answer ? { answer } : {}) });
    if (r.error) { const failed = opencodeFailure(r, 'OpenCode did not start the sign-in'); return res.status(failed.status).json({ ok: false, error: failed.error }); }
    res.json({ ok: true, data: { url: r.data.url || '', instructions: r.data.instructions || '', method: r.data.mode === 'code' ? 'code' : 'auto', attemptID: r.data.attemptID || '' } });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// How a sign-in is going: ?attemptID= → { status: 'pending' | 'complete' | 'failed' | 'expired', message? }.
app.get('/api/opencode/oauth/:providerId/status', async (req, res) => {
  try {
    const client = sharedOpencodeClient();
    if (!client) return res.status(503).json({ ok: false, error: 'OpenCode server not running' });
    const attemptID = String(req.query?.attemptID || '').trim();
    if (!attemptID) return res.status(400).json({ ok: false, error: 'attemptID is required' });
    const r = await client.integration.oauthStatus({ integrationID: req.params.providerId, attemptID });
    if (r.error) { const failed = opencodeFailure(r, 'OpenCode did not say how the sign-in is going'); return res.status(failed.status).json({ ok: false, error: failed.error }); }
    if (r.data?.status === 'complete') broadcastToOpencodeV2Clients({ type: 'providers:changed' });
    res.json({ ok: true, data: { status: String(r.data?.status || 'pending'), ...(r.data?.message ? { message: String(r.data.message) } : {}) } });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Finish a sign-in with the code the provider showed: { attemptID, code }.
app.post('/api/opencode/oauth/:providerId/callback', async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ ok: false, error: 'Admin only' });
  try {
    const client = sharedOpencodeClient();
    if (!client) return res.status(503).json({ ok: false, error: 'OpenCode server not running' });
    const attemptID = typeof req.body?.attemptID === 'string' ? req.body.attemptID.trim() : '';
    const code = typeof req.body?.code === 'string' ? req.body.code.trim() : '';
    if (!attemptID || !code) return res.status(400).json({ ok: false, error: 'attemptID and code are required' });
    const r = await client.integration.oauthComplete({ integrationID: req.params.providerId, attemptID, code });
    if (r.error) { const failed = opencodeFailure(r, 'OpenCode did not accept the code'); return res.status(failed.status).json({ ok: false, error: failed.error }); }
    broadcastToOpencodeV2Clients({ type: 'providers:changed' });
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// List available agents
app.get('/api/opencode/agents', async (req, res) => {
  try {
    if (!_ocpReady) return res.json({ ok: false, error: 'OpenCode server not running', data: [] });
    const r = await ocpProxy('GET', '/agent');
    res.status(r.status).json({ ok: r.status === 200, data: r.data });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Providers with default model mappings
app.get('/api/opencode/config/providers', async (req, res) => {
  try {
    if (!_ocpReady) return res.json({ ok: false, error: 'OpenCode server not running', data: {} });
    const r = await ocpProxy('GET', '/config/providers');
    res.status(r.status).json({ ok: r.status === 200, data: r.data });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/opencode/mcp — the global configuration is the source of truth (opencode.json, then opencode.jsonc
// over it: the MCP servers OpenCode 2 starts). OpenCode doesn't need to be running for the toggle to reflect a
// persisted install. `data` is the `mcp.servers` OpenCode reads.
app.get('/api/opencode/mcp', async (req, res) => {
  try {
    const servers = mcpServersOf(readOpencodeGlobalConfig().config);
    res.json({ ok: true, connected: !!servers.SynaBun, runtimeReady: !!_ocpReady, file: getOpencodeConfigPath(), data: servers });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/opencode/mcp — persist to the global opencode.json (OpenCode 2's mcp.servers), which OpenCode reads
// at once; the shared serve is asked to read it again before the answer. No body → installs SynaBun with
// canonical config (parity with the other provider endpoints).
app.post('/api/opencode/mcp', async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ ok: false, error: 'Admin only' });
  try {
    let { name, config: mcpConfig } = req.body || {};
    if (!name) {
      name = 'SynaBun';
      const { envPath, mcpCommand, mcpArgs } = getMcpPaths();
      mcpConfig = {
        command: mcpCommand,
        args: mcpArgs,
        env: { DOTENV_PATH: envPath, SYNABUN_DATA_HOME: DATA_HOME, MEMORY_DATA_DIR: resolve(DATA_HOME, 'mcp-data') },
      };
    }
    try { persistMcpToOpencodeConfig(name, mcpConfig); } catch (e) {
      return res.status(500).json({ ok: false, error: `Persist failed: ${e.message}` });
    }
    // Allow the SynaBun memory tools so CLI sessions skip prompts.
    injectOpenCodeMemoryPerms();
    await reloadSharedOpencodeConfig();
    const response = { ok: true, message: `${name} MCP saved to ${getOpencodeConfigPath()}; OpenCode starts it with its next session.` };
    if (name === 'SynaBun') response.rules = syncRulesWithMcp('opencode', 'install', req.body);
    res.json(response);
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// DELETE /api/opencode/mcp — remove the entry from the global opencode.json. One that only the user's
// opencode.jsonc holds stays (SynaBun never edits that file): the answer says so.
app.delete('/api/opencode/mcp', async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ ok: false, error: 'Admin only' });
  try {
    const name = (req.body && req.body.name) || req.query?.name || 'SynaBun';
    const configPath = getOpencodeConfigPath();
    if (mcpServersOf(readOpencodeConfigDocument(configPath).config)[name]) {
      try {
        updateOpencodeConfigFile(getOpencodeConfigDir(), (cfg) => removeMcpServer(cfg, name));
        console.log(`[opencode] Removed MCP server "${name}" from ${configPath}`);
      } catch (e) {
        return res.status(500).json({ ok: false, error: `Config rewrite failed: ${e.message}` });
      }
    }
    await reloadSharedOpencodeConfig();
    const left = mcpServersOf(readOpencodeGlobalConfig().config)[name];
    const response = { ok: true, message: `${name} MCP removed from ${configPath}.`, ...(left ? { warning: `${name} is still set up in ${join(getOpencodeConfigDir(), 'opencode.jsonc')}, which SynaBun does not edit: remove it there.` } : {}) };
    if (name === 'SynaBun') response.rules = syncRulesWithMcp('opencode', 'remove');
    res.json(response);
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

app.get('/api/opencode/config/file', (req, res) => {
  try {
    const path = ensureOpencodeConfigFile().replace(/\\/g, '/');
    res.json({ ok: true, path });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Return the OpenCode config directory for editor flows.
app.post('/api/opencode/config/reveal', (req, res) => {
  try {
    const configDir = dirname(ensureOpencodeConfigFile());
    res.json({ ok: true, path: configDir });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// ── Claude Agent SDK bridge ──
// The sidepanel's only engine: one long-lived interactive session per tab with
// real pre-execution permissions (canUseTool), live streaming, subagent
// visibility, native plan approval and rewind. A bridge that fails to load is a
// visible error on the socket (lib/claude-skin-connect.js).
let _claudeBridge = null;
let _claudeBridgeError = null;
// Settles when the import below finished, either way; connections wait on it.
const _claudeBridgeReady = (async () => {
  try {
    _claudeBridge = await import('./lib/claude-agent-bridge.js');
    _claudeBridge.configureClaudeBridge({
      accountRateLimit: (id, info) => _assistantAccountUsage?.note('claude-code', id, info),
      // The greeting a panel conversation opened with, as the one note its model gets (lib/greeting/).
      greetingNote: (id, opts) => _greeting?.consumeNote(id, opts) || '',
      // A prompt typed in the panel: when the person was last here (a temporary chat is named to nobody).
      greetingActivity: ({ cwd, words, temporary }) => { if (!temporary) _greeting?.noteActivity({ cwd: cwd || PACKAGE_ROOT, surface: 'claude-panel', words }); },
      addCost,
      getSessionCost,
      acquireSessionLock: _acquireSessionLock,
      heartbeatLock: _heartbeatLock,
      releaseAllLocks: _releaseAllLocks,
      writePlanFile,
      maybeInjectSkillPrompt,
      toCliModelName,
      PACKAGE_ROOT,
      DATA_HOME,
      // Per-chat-session SynaBun MCP entry (HTTP + X-Synabun-Terminal header)
      // so each sidepanel session gets its own browser tab.
      mcpUrl: `http://localhost:${PORT}/mcp`,
      // In-process release of a sidepanel session's owned tab on destroy.
      releaseBrowserOwner: (ownerKey) => {
        if (!ownerKey) return;
        for (const [sid, s] of browserSessions) {
          if (s._interactiveOwned?.has(ownerKey) || s._tabOwners?.has(ownerKey)) {
            releaseSharedBrowserTab(sid, ownerKey).catch(() => {});
          }
        }
      },
      // Live token streaming. Default OFF on Windows until pipe-backpressure
      // burn-in (#771-class deadlocks); override via cli-config
      // { "claude-skin": { "partials": true } }.
      get includePartialMessages() {
        const cfg = _readClaudeSkinConfig();
        if (typeof cfg.partials === 'boolean') return cfg.partials;
        return process.platform !== 'win32';
      },
      // The Claude Code every session runs: the user's own installation, or the
      // explicit override from cli-config.json ("claude-skin": { "sdkExecutable":
      // "…" }, a .js entrypoint or a native binary path). SynaBun carries none, so
      // a session without one is refused with the install hint. Lazy, so the
      // (memoized) resolution happens on demand, not at boot.
      claudeExecutable: () => getClaudeSdkExecutable(),
      // On Windows, the Git Bash every session's Claude Code gets (lib/git-bash/): SynaBun's copy where the PC has
      // none, so the Bash tool exists and the hooks run in bash. Panel tabs and the Assistant's brain.
      childEnv: (env) => claudeChildEnv(env),
      // Sidepanel tabs can run under another Claude account (its own config
      // directory). The default account adds nothing to the environment.
      claudeAccountEnv: (accountId) => _panelClaudeAccounts().envFor(accountId),
      // How a session runs under an account: inherited credentials removed, the
      // account's directory and, in API-key mode, its key added (launchFor() in
      // lib/claude-accounts.js). Panel tabs and the Assistant's brain.
      claudeAccountLaunch: (accountId) => _panelClaudeAccounts().launchFor(accountId),
      // This server has the session routes (rename, tag, fork, delete, subagent
      // transcripts): the panel offers those actions only when told so.
      sessionOps: true,
      // …and DELETE /api/claude-code/permission-rules (remove a rule from a settings file).
      permissionRulesEdit: true,
      // …and GET /api/claude-code/settings/resolved (the settings in effect).
      settingsView: true,
      // Those settings routes take `account`: a tab under a named Claude account
      // sees and edits that account's user settings, never the default one's.
      accountSettings: true,
      // …and GET /api/claude-code/bypass-policy (is Bypass turned off, and by what).
      bypassPolicy: true,
      // Where a tab's debug log is written when its session settings ask for one.
      debugDir: resolve(DATA_HOME, 'logs', 'claude-debug'),
      // A conversation rewind resumes at the entry the prompt follows in the
      // transcript ('' = it is the first entry, null = not found).
      transcriptParentOf: async ({ sessionId, uuid, cwd, accountId }) => {
        const chain = await claudeTranscriptChain({ sessionId, project: cwd || '', accountId: accountId || '' });
        return chain ? chain.parentOf(uuid) : null;
      },
    });
    const shutdown = () => { try { _claudeBridge.shutdownAllBridges(); } catch {} };
    process.on('exit', shutdown);
    process.on('SIGINT', shutdown);
    process.on('SIGTERM', shutdown);
    console.log(`[claude-sdk] bridge ready (sdk ${_claudeBridge.SDK_VERSION})`);
  } catch (err) {
    _claudeBridgeError = `the Claude Agent SDK bridge failed to load (${err.message})`;
    console.warn('[claude-sdk] bridge unavailable, sidepanel connections will be refused:', err.message);
  }
})();

// The Claude accounts registry: one instance for the sidepanel, the Assistant
// (brain, workers, catalog) and every route, so one account state is shown
// everywhere (lib/claude-accounts.js describe()). Its subscription half is
// Claude Code's own `auth status --json` for each account; a change of any
// account reaches every window as `claude:accounts-changed`.
let _panelClaudeAccountsInstance = null;
function _panelClaudeAccounts() {
  if (!_panelClaudeAccountsInstance) {
    _panelClaudeAccountsInstance = createPanelClaudeAccounts({
      dataHome: DATA_HOME, homeDir: getHomePath(),
      readNativeStatus: (accountId) => panelClaudeAuth().nativeStatus(accountId),
      log: (tag, message) => console.log(`[${tag}]`, message),
    });
    _panelClaudeAccountsInstance.subscribe((event) => {
      try {
        broadcastSync({ type: 'claude:accounts-changed', accountId: event.accountId || null, removed: !!event.removed, created: !!event.created });
        // The Assistant's account list and catalog listen to their own event.
        broadcastSync({ type: 'assistant:accounts-changed', provider: 'claude-code', accountId: event.accountId || null, removed: !!event.removed });
        _assistantCatalog?.invalidate?.();
        // The model list is read under the default account: asked again (another sign-in is another key).
        if (!event.accountId || event.accountId === 'default') { markClaudeModelsStale(); scheduleLaunchRefresh('claude-models'); }
      } catch {}
    });
  }
  return _panelClaudeAccountsInstance;
}

// Why a Claude account cannot be removed now ('' when it can): a live session
// (a panel tab, the Assistant's brain), a dispatched run, or the Assistant's
// choice of worker account names it.
function claudeAccountInUse(accountId) {
  try { if (_claudeBridge?.accountInUse?.(accountId)) return 'A Claude tab or the Assistant is running under this account. End that session first.'; } catch {}
  try { if (_assistantDispatcher?.accountInUse?.('claude-code', accountId)) return 'Dispatched runs are using this account. Stop them first.'; } catch {}
  try { if (_assistantRuntime?.accountInUse?.('claude-code', accountId)) return 'An Assistant session uses this account. Close it first.'; } catch {}
  try { if (_assistantClaudeWorkerAccount?.() === accountId) return 'This is the Assistant\'s Claude worker account. Choose another one first.'; } catch {}
  return '';
}

// The config directory of the Claude account a sidepanel request names: '' for
// the default account. An account that is no longer set up is an error (404,
// `account_unavailable`), never the default account's folder in its place.
function panelAccountHome(value) {
  const wanted = typeof value === 'string' ? value : '';
  if (!wanted || wanted === 'default') return '';
  let home = null;
  try { home = _panelClaudeAccounts().homeFor(wanted); } catch { home = null; }
  if (!home) throw Object.assign(new Error('That Claude account is no longer set up in SynaBun.'), { status: 404, code: 'account_unavailable' });
  return home;
}

// GET /api/claude/accounts — every Claude account with its state (mode,
// signed in, identity: an email or a masked key, never a key). Emails are
// personal data: not for invite guests. `?refresh=true` asks Claude Code about
// every account's subscription first; otherwise an answer older than a few
// minutes is asked again in the background and announced when it changes.
app.get('/api/claude/accounts', async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ ok: false, error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try {
    const accounts = _panelClaudeAccounts();
    if (req.query.refresh === 'true') await accounts.refreshStatus(null, { force: true });
    else accounts.refreshStatus().catch(() => {});
    res.json({ ok: true, accounts: accounts.listForClient() });
  }
  catch (err) { res.status(500).json({ ok: false, error: err.message }); }
});

let _panelClaudeAuthInstance = null;
const panelAuthOwnerGuard = ownerRouteGuard({ isGuestRequest, port: PORT, allowedOrigins: publicWebOrigins, refuseCrossSite: true });
function panelClaudeAuth() {
  if (!_panelClaudeAuthInstance) {
    _panelClaudeAuthInstance = createClaudePanelAuth({ accounts: _panelClaudeAccounts(), executable: getClaudeSdkExecutable, env: () => (withPathEnv(process.env, getAugmentedPath())), changeCredentials: (id, change) => _claudeBridge?.withPanelAccountAuthChange ? _claudeBridge.withPanelAccountAuthChange(id, change) : change() });
    process.once('exit', () => _panelClaudeAuthInstance?.close());
  }
  return _panelClaudeAuthInstance;
}

// Admin-only account auth; OAuth stays native and pasted keys are profile-scoped.
app.get('/api/claude/accounts/:id/auth', panelAuthOwnerGuard, async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try {
    panelAccountHome(req.params.id);
    const result = req.query.refresh === 'true' ? await panelClaudeAuth().read(req.params.id) : { state: panelClaudeAuth().snapshot(req.params.id) };
    res.json(result);
  } catch (error) { res.status(error.status || 500).json({ error: error.message }); }
});
app.post('/api/claude/accounts/:id/auth/:action', panelAuthOwnerGuard, async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try {
    panelAccountHome(req.params.id);
    const auth = panelClaudeAuth();
    if (req.params.action === 'start') return res.json({ state: auth.start(req.params.id) });
    if (req.params.action === 'cancel') return res.json({ state: auth.cancel(req.params.id, req.body?.operationId) });
    if (req.params.action === 'code') return res.json({ state: auth.submitCode(req.params.id, req.body?.operationId, req.body?.code) });
    if (req.params.action === 'logout') {
      // `credential`: 'apiKey', 'subscription', or both when left out (the older /logout).
      const credential = typeof req.body?.credential === 'string' ? req.body.credential : 'all';
      await auth.signOut(req.params.id, credential);
      return res.json({ ok: true, account: _panelClaudeAccounts().describeForClient(req.params.id) });
    }
    res.status(404).json({ error: 'Unknown authentication action' });
  } catch (error) { res.status(error.status || 500).json({ error: error.message }); }
});

registerProviderPanelApiKeyAuthRoutes(app, {
  guard: panelAuthOwnerGuard,
  claude: (id, key) => panelClaudeAuth().signInApiKey(id, key),
  // A Codex key is checked with OpenAI and kept by SynaBun for that account (lib/codex-account-auth.js);
  // the account's idle Codex processes restart on it. Codex's own store (its ChatGPT login) is not touched.
  codex: (id, key) => codexAccountAuth().signInApiKey(id, key),
});

// Codex accounts: the same model and routes as Claude's (lib/codex-accounts.js describe(), launchFor()).
// Everything but the list carries the owner guard; a credential or mode change restarts the
// account's idle panel processes and is refused while one of them is mid-turn.
app.post('/api/codex/accounts', panelAuthOwnerGuard, (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try {
    const created = _codexAccounts().create({ label: req.body?.label });
    res.json({ account: _codexAccounts().describeForClient(created.id) });
  } catch (error) { res.status(error.status || 500).json({ code: error.code || null, error: error.message }); }
});
// Rename (`label`) and/or choose what the account's sessions use (`mode`: 'subscription' (ChatGPT) | 'apiKey').
app.patch('/api/codex/accounts/:id', panelAuthOwnerGuard, async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try {
    const accounts = _codexAccounts();
    if (accounts.describe(req.params.id)?.id !== req.params.id) return res.status(404).json({ code: 'ACCOUNT_NOT_FOUND', error: 'That Codex account is no longer set up in SynaBun.' });
    const { label, mode } = req.body || {};
    if (label === undefined && mode === undefined) return res.status(400).json({ code: 'NOTHING_TO_CHANGE', error: 'Send a label or a mode.' });
    if (label !== undefined) accounts.rename(req.params.id, label);
    if (mode !== undefined) await codexAccountAuth().setMode(req.params.id, mode);
    res.json({ ok: true, account: accounts.describeForClient(req.params.id) });
  } catch (error) { res.status(error.status || 500).json({ code: error.code || null, error: error.message }); }
});
// Remove an added account and its folder. Default stays; an account something uses stays.
app.delete('/api/codex/accounts/:id', panelAuthOwnerGuard, (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try { res.json(_codexAccounts().remove(req.params.id, { inUse: (id) => codexAccountInUse(id) })); }
  catch (error) { res.status(error.status || 500).json({ code: error.code || null, error: error.message }); }
});
// `?refresh=true` asks Codex what the account's own store holds first.
app.get('/api/codex/accounts/:id/auth', panelAuthOwnerGuard, async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try {
    if (_codexAccounts().describe(req.params.id)?.id !== req.params.id) return res.status(404).json({ code: 'ACCOUNT_NOT_FOUND', error: 'That Codex account is no longer set up in SynaBun.' });
    if (req.query.refresh === 'true') return res.json(await codexAccountAuth().read(req.params.id));
    res.json({ accountId: req.params.id, account: _codexAccounts().describeForClient(req.params.id) });
  } catch (error) { res.status(error.status || 500).json({ code: error.code || null, error: error.message }); }
});
// `credential`: 'apiKey' (the account's key), 'subscription' (Codex's own logout in its home), or both when left out.
app.post('/api/codex/accounts/:id/auth/logout', panelAuthOwnerGuard, async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try {
    if (_codexAccounts().describe(req.params.id)?.id !== req.params.id) return res.status(404).json({ code: 'ACCOUNT_NOT_FOUND', error: 'That Codex account is no longer set up in SynaBun.' });
    const credential = typeof req.body?.credential === 'string' ? req.body.credential : 'all';
    const account = await codexAccountAuth().signOut(req.params.id, credential);
    res.json({ ok: true, account });
  } catch (error) { res.status(error.status || 500).json({ code: error.code || null, error: error.message }); }
});

app.post('/api/claude/accounts', panelAuthOwnerGuard, (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  try {
    const created = _panelClaudeAccounts().create({ label: req.body?.label });
    const row = _panelClaudeAccounts().listForClient().find(a => a.id === created.id);
    res.json({ account: row });
  } catch (error) { res.status(error.status || 500).json({ error: error.message }); }
});

// Rename an account (`label`) or choose what its sessions use (`mode`:
// 'subscription' | 'apiKey'; the chosen credential must be there). A mode
// change ends the account's idle sessions so the next message starts under it.
app.patch('/api/claude/accounts/:id', panelAuthOwnerGuard, async (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try {
    const accounts = _panelClaudeAccounts();
    if (!accounts.describe(req.params.id) || accounts.describe(req.params.id).id !== req.params.id) return res.status(404).json({ code: 'ACCOUNT_NOT_FOUND', error: 'That Claude account is no longer set up in SynaBun.' });
    const { label, mode } = req.body || {};
    if (label === undefined && mode === undefined) return res.status(400).json({ code: 'NOTHING_TO_CHANGE', error: 'Send a label or a mode.' });
    if (label !== undefined) accounts.rename(req.params.id, label);
    if (mode !== undefined) await panelClaudeAuth().setMode(req.params.id, mode);
    res.json({ ok: true, account: accounts.describeForClient(req.params.id) });
  } catch (error) { res.status(error.status || 500).json({ code: error.code || null, error: error.message }); }
});

// Remove an added account and its config directory. Default stays; an account
// a live session, a dispatched run or the Assistant's worker choice uses stays.
app.delete('/api/claude/accounts/:id', panelAuthOwnerGuard, (req, res) => {
  if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
  res.setHeader('Cache-Control', 'no-store');
  try { res.json(_panelClaudeAccounts().remove(req.params.id, { inUse: claudeAccountInUse })); }
  catch (error) { res.status(error.status || 500).json({ code: error.code || null, error: error.message }); }
});

function _readClaudeSkinConfig() {
  try {
    const cfg = JSON.parse(readFileSync(resolve(DATA_HOME, 'data', 'cli-config.json'), 'utf-8'));
    return cfg['claude-skin'] || {};
  } catch { return {}; }
}

function handleClaudeSkinWebSocket(ws) {
  connectClaudeSkin(ws, {
    bridgeReady: _claudeBridgeReady,
    getBridge: () => _claudeBridge,
    getBridgeError: () => _claudeBridgeError,
    log: (...args) => console.warn('[claude-sdk]', ...args),
  }).catch((err) => console.warn('[claude-sdk] connection setup failed:', err?.message || err));
}

// Ask the installed CLI which models this account can run. Falls back to a small
// static list so the picker still renders when the CLI is missing or errors.
// The sign-in the CLI reads its model list under (the default account: discovery runs with no
// CLAUDE_CONFIG_DIR of its own), as a hash: another account can be entitled to other models, so the
// kept list is keyed on it and never given for another account.
function claudeModelAccountKey() {
  try {
    const row = _panelClaudeAccounts().describe('default');
    if (!row) return '';
    return createHash('sha256').update(`${row.mode || ''}\n${row.identity || ''}\n${row.signedIn}`).digest('hex').slice(0, 16);
  } catch { return ''; }
}

// The last verified Claude list survives a restart (DATA_HOME/cache/launch/claude-models.json).
setClaudeModelStore(createSnapshotStore({ dir: LAUNCH_CACHE_DIR, name: 'claude-models', log: (message) => console.warn(message) }));

// What Codex said about its settings schema and feature switches (lib/codex-settings-schema.js), per binary
// (path, mtime, size: an update is another binary), kept across restarts: asking costs a Codex start per value.
const _codexSettingsProbes = createLaunchCache({
  name: 'codex-settings',
  dir: LAUNCH_CACHE_DIR,
  ttlMs: Number.MAX_SAFE_INTEGER,
  maxEntries: 8,
  load: async () => { throw new Error('asked by lib/codex-settings-schema.js'); },
});
setCodexSettingsStore({ get: (key) => _codexSettingsProbes.peek(key), set: (key, value) => _codexSettingsProbes.set(key, value) });

async function getClaudeModelsForClient(force = false) {
  try {
    const bin = getClaudeBin();
    // Sidepanel sessions and native loops run this same installation. The Agent
    // SDK that starts it was built against one Claude Code release; an older
    // installation is worth one line in the log. Cached per binary (a spawn only
    // when the CLI changes).
    checkClaudeCliSkew(bin).catch(() => {});
    // Answered from the kept list at once (asked again in the background when it is old);
    // only a first read, another binary or account, or ?refresh=1 waits for the CLI.
    const result = await discoverClaudeModels(bin, { force, cwd: PACKAGE_ROOT, account: claudeModelAccountKey() });
    if (result?.models?.length) return result;
  } catch (err) {
    console.warn('[claude-models] discovery failed:', err.message);
  }
  return { source: 'fallback', models: [...CLAUDE_FALLBACK_MODELS] };
}

// GET /api/claude/models — live model list from the CLI. Mirrors /api/codex/models.
app.get('/api/claude/models', async (req, res) => {
  const { source, models } = await getClaudeModelsForClient(req.query?.refresh === '1');
  res.json({ ok: true, source, models });
});

// GET /api/claude/config — config for the skin UI (cwd, model, projects, models)
app.get('/api/claude/config', async (req, res) => {
  try {
    const cliCfg = (() => {
      try { return JSON.parse(readFileSync(resolve(DATA_HOME, 'data', 'cli-config.json'), 'utf-8')); }
      catch { return {}; }
    })();
    const projects = (() => {
      try { return JSON.parse(readFileSync(resolve(DATA_HOME, 'data', 'claude-code-projects.json'), 'utf-8')); }
      catch { return []; }
    })();
    // Model ids come straight from the CLI and are already spawn-ready (they carry
    // the `[1m]` suffix where applicable), so the client uses them verbatim — no
    // "<id>:<contextWindow>" composite. See toCliModelName() for the legacy form.
    const { source, models } = await getClaudeModelsForClient();
    res.json({ ok: true, config: cliCfg, projects, models, modelsSource: source, bootId: SERVER_BOOT_ID });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// --- Claude Skin Cost Tracking ---

const COST_PATH = resolve(DATA_HOME, 'data', 'cost-tracking.json');

// In-memory journal with a debounced async flush — addCost fires on every
// result event of every session; a sync read+write of the whole file per
// event stalls all streaming sessions. Single-writer (this process only).
let _costCache = null;
let _costDirty = false;
let _costFlushTimer = null;
const COST_FLUSH_MS = 2000;

function loadCostData() {
  if (_costCache) return _costCache;
  try { _costCache = JSON.parse(readFileSync(COST_PATH, 'utf-8')); }
  catch { _costCache = { months: {} }; }
  return _costCache;
}

function saveCostData(data) {
  _costCache = data;
  _costDirty = true;
  if (!_costFlushTimer) {
    _costFlushTimer = setTimeout(() => {
      _costFlushTimer = null;
      flushCostDataAsync();
    }, COST_FLUSH_MS);
    _costFlushTimer.unref?.();
  }
}

async function flushCostDataAsync() {
  if (!_costDirty || !_costCache) return;
  _costDirty = false;
  const json = JSON.stringify(_costCache, null, 2);
  try {
    await fsp.writeFile(COST_PATH + '.tmp', json);
    await fsp.rename(COST_PATH + '.tmp', COST_PATH);
  } catch (err) {
    console.error('[cost] async flush failed:', err.message);
    _costDirty = true;
  }
}

function flushCostDataSync() {
  if (!_costDirty || !_costCache) return;
  try {
    writeFileSync(COST_PATH + '.tmp', JSON.stringify(_costCache, null, 2));
    renameSync(COST_PATH + '.tmp', COST_PATH);
    _costDirty = false;
  } catch (err) {
    console.error('[cost] sync flush failed:', err.message);
  }
}

function addCost(amount, sessionId) {
  const data = loadCostData();
  const now = new Date();
  const key = now.toISOString().slice(0, 7); // "2026-03"
  if (!data.months[key]) data.months[key] = { totalUsd: 0, queries: 0, sessions: [], days: {}, lastUpdated: null };
  const month = data.months[key];
  month.totalUsd = Math.round((month.totalUsd + amount) * 1e6) / 1e6; // avoid float drift
  month.queries += 1;
  if (sessionId && !month.sessions.includes(sessionId)) month.sessions.push(sessionId);
  // Per-session cost accumulation
  if (sessionId) {
    if (!data.sessionCosts) data.sessionCosts = {};
    data.sessionCosts[sessionId] = Math.round(((data.sessionCosts[sessionId] || 0) + amount) * 1e6) / 1e6;
  }
  // Daily granularity
  if (!month.days) month.days = {};
  const day = now.getDate().toString().padStart(2, '0');
  if (!month.days[day]) month.days[day] = { totalUsd: 0, queries: 0 };
  month.days[day].totalUsd = Math.round((month.days[day].totalUsd + amount) * 1e6) / 1e6;
  month.days[day].queries += 1;
  month.lastUpdated = now.toISOString();
  saveCostData(data);
  return month;
}

function getSessionCost(sessionId) {
  const data = loadCostData();
  return data.sessionCosts?.[sessionId] || 0;
}

app.get('/api/claude-skin/cost/session/:sid', (req, res) => {
  const cost = getSessionCost(req.params.sid);
  res.json({ sessionId: req.params.sid, cost });
});

app.get('/api/claude-skin/cost', (req, res) => {
  const data = loadCostData();
  const current = new Date().toISOString().slice(0, 7);
  res.json({
    currentMonth: current,
    month: data.months[current] || { totalUsd: 0, queries: 0, sessions: [] },
    history: data.months,
  });
});

app.post('/api/claude-skin/cost', express.json(), (req, res) => {
  const { amount, sessionId } = req.body || {};
  if (typeof amount !== 'number' || amount <= 0) return res.status(400).json({ error: 'Invalid amount' });
  const month = addCost(amount, sessionId);
  res.json({ ok: true, month });
});

// --- CLI Session Cost Scanner ---
// Parses JSONL session files to extract costs from direct CLI usage (not via skin)

// Normalize a model selector into a Claude Code CLI-ready model id.
// Accepts three forms:
//   "claude-opus-4-6"             → "claude-opus-4-6" (CLI defaults to 200K)
//   "claude-opus-4-6[1m]"         → passthrough
//   "claude-opus-4-6:1000000"     → "claude-opus-4-6[1m]" (composite from UI)
//   "claude-opus-4-6:200000"      → "claude-opus-4-6"
// The `[1m]` beta suffix is the only way to activate the 1M-token context
// window in CLI 2.1.x — without it the CLI silently falls back to 200K.
function toCliModelName(model) {
  if (!model || typeof model !== 'string') return model;
  if (!model.includes(':')) return model;
  const [id, cwRaw] = model.split(':');
  const cw = parseInt(cwRaw, 10);
  if (!id) return model;
  return Number.isFinite(cw) && cw > 200000 ? `${id}[1m]` : id;
}

// $/MTok — [input, output, cache_write_5m, cache_read], derived from the one list-price table
// (lib/assistant-pricing.js: checked against the providers' pricing pages; the Assistant's
// catalog and usage ledger read the same table).
const MODEL_PRICING = claudeLegacyPricing();

function calcMessageCost(model, usage) {
  // JSONL strips the `[1m]` suffix before persisting, but result.modelUsage keys include it;
  // the table lookup takes either. A 1-hour cache write (usage.cache_creation) is priced at
  // its own rate. An unknown model falls back to Sonnet 4.6 rates.
  const priced = claudeUsageCostUsd(model, usage);
  if (priced !== null) return Math.round(priced * 1e6) / 1e6;
  const [pIn, pOut, pCacheW, pCacheR] = MODEL_PRICING['claude-sonnet-4-6']; // safe fallback
  const input = (usage.input_tokens || 0) / 1e6 * pIn;
  const output = (usage.output_tokens || 0) / 1e6 * pOut;
  const cacheWrite = (usage.cache_creation_input_tokens || 0) / 1e6 * pCacheW;
  const cacheRead = (usage.cache_read_input_tokens || 0) / 1e6 * pCacheR;
  return Math.round((input + output + cacheWrite + cacheRead) * 1e6) / 1e6;
}

async function scanSessionCosts() {
  const homeDir = process.env.USERPROFILE || process.env.HOME;
  const claudeProjectsDir = join(homeDir, '.claude', 'projects');
  if (!existsSync(claudeProjectsDir)) return { scanned: 0, added: 0, totalNew: 0 };

  const data = loadCostData();
  if (!data.scannedSessions) data.scannedSessions = {};

  // Collect all session IDs already tracked by the skin
  const skinSessions = new Set();
  for (const m of Object.values(data.months)) {
    for (const sid of (m.sessions || [])) skinSessions.add(sid);
  }

  let scanned = 0, added = 0, totalNew = 0;

  const projDirs = readdirSync(claudeProjectsDir, { withFileTypes: true }).filter(d => d.isDirectory());
  for (const projDir of projDirs) {
    const projPath = join(claudeProjectsDir, projDir.name);
    let files;
    try { files = readdirSync(projPath).filter(f => f.endsWith('.jsonl')); }
    catch { continue; }

    for (const file of files) {
      const sessionId = file.replace('.jsonl', '');
      // Skip if already scanned or tracked by skin
      if (data.scannedSessions[sessionId] || skinSessions.has(sessionId)) continue;

      const filePath = join(projPath, file);

      // Skip files modified in the last 5 minutes (likely active sessions)
      // Skip tiny files (<500 bytes — no meaningful cost data)
      let fstat;
      try { fstat = await fsp.stat(filePath); } catch { continue; }
      if (Date.now() - fstat.mtimeMs < 5 * 60 * 1000) continue;
      if (fstat.size < 500) { data.scannedSessions[sessionId] = 'empty'; continue; }

      scanned++;
      let content;
      try { content = await fsp.readFile(filePath, 'utf-8'); }
      catch { continue; }
      // Yield between files — line-parsing a multi-MB transcript is sync CPU
      // and this scan runs while sessions may already be streaming.
      await new Promise(r => setImmediate(r));

      // Parse line by line, extract assistant messages with usage
      // IMPORTANT: Claude Code writes multiple JSONL entries per API call (streaming chunks).
      // Each requestId may appear 2-3 times with increasing token counts.
      // We must keep only the LAST entry per requestId for accurate cost.
      const lines = content.split('\n');
      const requestMap = new Map(); // requestId → { model, usage, timestamp }

      for (const line of lines) {
        if (!line.trim()) continue;
        let entry;
        try { entry = JSON.parse(line); } catch { continue; }

        if (entry.type !== 'assistant' || !entry.message?.usage) continue;
        const { model, usage } = entry.message;
        const requestId = entry.requestId || entry.message?.id;
        if (!model || !usage || !requestId) continue;

        // Always overwrite — last entry per requestId has final token counts
        requestMap.set(requestId, { model, usage, timestamp: entry.timestamp });
      }

      let sessionCost = 0;
      let sessionQueries = 0;
      let sessionDate = null;
      const dailyCosts = {}; // { "2026-03-09": { cost, queries } }

      for (const { model, usage, timestamp } of requestMap.values()) {
        const cost = calcMessageCost(model, usage);
        if (cost <= 0) continue;

        sessionCost += cost;
        sessionQueries++;

        if (timestamp) {
          const dayStr = timestamp.slice(0, 10);
          if (!dailyCosts[dayStr]) dailyCosts[dayStr] = { cost: 0, queries: 0 };
          dailyCosts[dayStr].cost += cost;
          dailyCosts[dayStr].queries++;
          if (!sessionDate) sessionDate = dayStr;
        }
      }

      if (sessionCost > 0) {
        // Merge into months/days
        for (const [dayStr, dc] of Object.entries(dailyCosts)) {
          const monthKey = dayStr.slice(0, 7); // "2026-03"
          const dayKey = dayStr.slice(8, 10); // "09"
          if (!data.months[monthKey]) data.months[monthKey] = { totalUsd: 0, queries: 0, sessions: [], days: {}, lastUpdated: null };
          const month = data.months[monthKey];
          const rounded = Math.round(dc.cost * 1e6) / 1e6;
          month.totalUsd = Math.round((month.totalUsd + rounded) * 1e6) / 1e6;
          month.queries += dc.queries;
          if (!month.days) month.days = {};
          if (!month.days[dayKey]) month.days[dayKey] = { totalUsd: 0, queries: 0 };
          month.days[dayKey].totalUsd = Math.round((month.days[dayKey].totalUsd + rounded) * 1e6) / 1e6;
          month.days[dayKey].queries += dc.queries;
          month.lastUpdated = new Date().toISOString();
          if (!month.sessions.includes(sessionId)) month.sessions.push(sessionId);
        }
        added++;
        totalNew = Math.round((totalNew + sessionCost) * 1e6) / 1e6;
      }

      // Mark as scanned regardless (to avoid re-processing empty/no-cost sessions)
      data.scannedSessions[sessionId] = sessionDate || new Date().toISOString().slice(0, 10);
    }
  }

  // Always save if we scanned anything (even zero-cost sessions get marked)
  if (scanned > 0) saveCostData(data);
  return { scanned, added, totalNew };
}

// Scan on startup (async to not block)
setTimeout(async () => {
  try {
    const result = await scanSessionCosts();
    if (result.added > 0) console.log(`[cost-tracker] Imported ${result.added} CLI sessions (+$${result.totalNew.toFixed(2)})`);
  } catch (err) { console.error('[cost-tracker] Scan error:', err.message); }
}, 3000);

// Sweep the temp files of the retired per-turn engine (it wrote each turn's
// prompt and output to tmpdir, and a crash leaked them). Nothing creates them
// any more: this only clears what an earlier version left behind.
setTimeout(async () => {
  try {
    const dir = os.tmpdir();
    const cutoff = Date.now() - 24 * 3600 * 1000;
    for (const f of await fsp.readdir(dir)) {
      if (!/^claude-skin-.+-(in\.txt|out\.jsonl)$/.test(f)) continue;
      try {
        const st = await fsp.stat(join(dir, f));
        if (st.mtimeMs < cutoff) await fsp.unlink(join(dir, f));
      } catch { /* in use or already gone */ }
    }
  } catch { /* best effort */ }
}, 10_000);

app.post('/api/claude-skin/cost/scan', async (req, res) => {
  try {
    const result = await scanSessionCosts();
    res.json({ ok: true, ...result });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// --- Session Lock API ---

app.post('/api/claude-skin/session-lock', express.json(), (req, res) => {
  const { action, sessionId, windowId } = req.body || {};
  if (!windowId) return res.status(400).json({ error: 'windowId required' });

  if (action === 'acquire') {
    if (!sessionId) return res.status(400).json({ error: 'sessionId required' });
    const result = _acquireSessionLock(sessionId, windowId, null);
    return res.json(result);
  }
  if (action === 'release') {
    if (sessionId) {
      _releaseSessionLock(sessionId, windowId);
    } else {
      _releaseAllLocks(windowId);
    }
    return res.json({ ok: true });
  }
  if (action === 'heartbeat') {
    if (!sessionId) return res.status(400).json({ error: 'sessionId required' });
    _heartbeatLock(sessionId, windowId);
    return res.json({ ok: true });
  }
  if (action === 'force-take') {
    if (!sessionId) return res.status(400).json({ error: 'sessionId required' });
    _sessionLocks.set(sessionId, { windowId, wsId: null, lockedAt: Date.now(), lastHeartbeat: Date.now() });
    return res.json({ ok: true });
  }
  res.status(400).json({ error: 'Unknown action' });
});

app.get('/api/claude-skin/session-locks', (req, res) => {
  const locks = {};
  for (const [sid, lock] of _sessionLocks) {
    locks[sid] = { windowId: lock.windowId, lockedAt: lock.lockedAt, lastHeartbeat: lock.lastHeartbeat };
  }
  res.json({ locks });
});

// --- Keybinds Persistence ---

const KEYBINDS_PATH = resolve(DATA_HOME, 'data', 'keybinds.json');

function loadKeybinds() {
  try { return JSON.parse(readFileSync(KEYBINDS_PATH, 'utf-8')); }
  catch { return null; }
}

function saveKeybinds(data) {
  const dir = resolve(KEYBINDS_PATH, '..');
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  data._version = data._version || 1;
  data._updated = new Date().toISOString();
  writeFileSync(KEYBINDS_PATH, JSON.stringify(data, null, 2) + '\n', 'utf-8');
}

app.get('/api/keybinds', (req, res) => {
  try {
    res.json(loadKeybinds() || {});
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.put('/api/keybinds', (req, res) => {
  try {
    if (!req.body || typeof req.body !== 'object') {
      return res.status(400).json({ error: 'Body must be a JSON object' });
    }
    saveKeybinds(req.body);
    res.json({ ok: true });
  } catch (err) {
    console.error('PUT /api/keybinds error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// --- UI State Persistence (replaces browser localStorage) ---

const UI_STATE_PATH = resolve(DATA_HOME, 'data', 'ui-state.json');

// ui-state.json is multi-MB; synchronously re-reading and rewriting it on every
// PATCH stalls the event loop (and every streaming WebSocket) for tens of ms.
// Serve from an in-memory cache and persist with a debounced async atomic write.
// Callers mutate the object returned by loadUiState() and pass it back to
// saveUiState(), so the cache must hand out the live object, never a copy.
let _uiStateCache = null;
let _uiStateDirty = false;
let _uiStateFlushTimer = null;
let _uiStateWriteChain = Promise.resolve();
const UI_STATE_FLUSH_MS = 1000;

function loadUiState() {
  if (_uiStateCache) return _uiStateCache;
  try {
    _uiStateCache = JSON.parse(readFileSync(UI_STATE_PATH, 'utf-8'));
  } catch {
    _uiStateCache = { _version: 1, _updated: new Date().toISOString() };
  }
  return _uiStateCache;
}

function saveUiState(data) {
  _uiStateCache = data;
  data._updated = new Date().toISOString();
  _uiStateDirty = true;
  if (!_uiStateFlushTimer) {
    _uiStateFlushTimer = setTimeout(() => {
      _uiStateFlushTimer = null;
      flushUiStateAsync();
    }, UI_STATE_FLUSH_MS);
    _uiStateFlushTimer.unref?.();
  }
}

function flushUiStateAsync() {
  if (!_uiStateDirty || !_uiStateCache) return _uiStateWriteChain;
  _uiStateDirty = false;
  const json = JSON.stringify(_uiStateCache, null, 2) + '\n';
  _uiStateWriteChain = _uiStateWriteChain.then(async () => {
    const dir = resolve(UI_STATE_PATH, '..');
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const tmp = UI_STATE_PATH + '.tmp';
    await fsp.writeFile(tmp, json, 'utf-8');
    await fsp.rename(tmp, UI_STATE_PATH);
  }).catch((err) => {
    console.error('[ui-state] async flush failed:', err.message);
    _uiStateDirty = true;
  });
  return _uiStateWriteChain;
}

// For exit paths only — process.on('exit') cannot await.
function flushUiStateSync() {
  if (!_uiStateDirty || !_uiStateCache) return;
  try {
    const dir = resolve(UI_STATE_PATH, '..');
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const tmp = UI_STATE_PATH + '.tmp';
    writeFileSync(tmp, JSON.stringify(_uiStateCache, null, 2) + '\n', 'utf-8');
    renameSync(tmp, UI_STATE_PATH);
    _uiStateDirty = false;
  } catch (err) {
    console.error('[ui-state] sync flush failed:', err.message);
  }
}

// ── Whiteboard store ──────────────────────────────────────────────
// The whiteboard (with base64 images) used to live inside ui-state.json,
// fattening it to multiple MB so every unrelated ui-state write re-stringified
// the board. It now persists to its own file with the same in-memory-cache +
// debounced async atomic write as ui-state. Every server-side consumer (REST
// endpoints, MCP tools, the WS state:sync handler) goes through
// loadWhiteboard()/saveWhiteboard(); loadWhiteboard() hands out the live object
// (mutate it and pass back), mirroring loadUiState()/saveUiState().
const WHITEBOARD_PATH = resolve(DATA_HOME, 'data', 'whiteboard.json');
let _whiteboardCache = null;
let _whiteboardDirty = false;
let _whiteboardFlushTimer = null;
let _whiteboardWriteChain = Promise.resolve();
const WHITEBOARD_FLUSH_MS = 1000;

function loadWhiteboard() {
  if (_whiteboardCache) return _whiteboardCache;
  try {
    _whiteboardCache = JSON.parse(readFileSync(WHITEBOARD_PATH, 'utf-8'));
  } catch {
    // No file yet — one-time migrate the board out of ui-state.json if present.
    const ui = loadUiState();
    const legacy = ui['neural-whiteboard'];
    if (legacy && Array.isArray(legacy.elements)) {
      _whiteboardCache = { elements: legacy.elements, nextZIndex: legacy.nextZIndex || 1 };
      _whiteboardDirty = true;
      flushWhiteboardSync();          // persist to whiteboard.json BEFORE dropping it from ui-state
      delete ui['neural-whiteboard'];
      saveUiState(ui);                // shrink ui-state.json (debounced)
      console.log('[whiteboard] migrated neural-whiteboard out of ui-state.json');
    } else {
      _whiteboardCache = { elements: [], nextZIndex: 1 };
    }
  }
  if (!Array.isArray(_whiteboardCache.elements)) _whiteboardCache.elements = [];
  if (!_whiteboardCache.nextZIndex) _whiteboardCache.nextZIndex = 1;
  // One-time geometry normalisation of older boards: estimated sizes for
  // text/list cards, 160x100 for size-less shapes, section defaults.
  if (normalizeWhiteboardElements(_whiteboardCache.elements)) {
    console.log('[whiteboard] normalized element geometry (estimated sizes / defaults)');
    saveWhiteboard(_whiteboardCache);
  }
  return _whiteboardCache;
}

/** Fill defaults / estimated sizes on every element lacking them (never touches
 *  browser-measured text/list sizes). Returns true when anything changed. */
function normalizeWhiteboardElements(elements) {
  let changed = false;
  for (const el of elements) {
    if (!el || typeof el !== 'object') continue;
    const reasons = wbEnsureElementGeometry(el);
    if (reasons.some(r => r !== 'image:no-size')) changed = true;
  }
  return changed;
}

/** Client snapshots may omit sizes the server already holds as measured —
 *  carry them over by id so a full-board sync never regresses geometry truth. */
function mergeMeasuredSizes(incoming, current) {
  if (!Array.isArray(incoming) || !Array.isArray(current)) return;
  const byId = new Map(current.map(e => [e.id, e]));
  for (const el of incoming) {
    if (!el || (el.type !== 'text' && el.type !== 'list')) continue;
    if (el.width > 0 && el.height > 0) continue;
    const prev = byId.get(el.id);
    if (prev && prev.measured && prev.width > 0 && prev.height > 0) {
      el.width = prev.width;
      el.height = prev.height;
      el.measured = true;
      delete el.estimated;
    }
  }
}

function saveWhiteboard(data) {
  _whiteboardCache = data;
  _whiteboardDirty = true;
  if (!_whiteboardFlushTimer) {
    _whiteboardFlushTimer = setTimeout(() => {
      _whiteboardFlushTimer = null;
      flushWhiteboardAsync();
    }, WHITEBOARD_FLUSH_MS);
    _whiteboardFlushTimer.unref?.();
  }
}

function flushWhiteboardAsync() {
  if (!_whiteboardDirty || !_whiteboardCache) return _whiteboardWriteChain;
  _whiteboardDirty = false;
  const json = JSON.stringify(_whiteboardCache) + '\n';
  _whiteboardWriteChain = _whiteboardWriteChain.then(async () => {
    const dir = resolve(WHITEBOARD_PATH, '..');
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const tmp = WHITEBOARD_PATH + '.tmp';
    await fsp.writeFile(tmp, json, 'utf-8');
    await fsp.rename(tmp, WHITEBOARD_PATH);
  }).catch((err) => {
    console.error('[whiteboard] async flush failed:', err.message);
    _whiteboardDirty = true;
  });
  return _whiteboardWriteChain;
}

// For exit paths only — process.on('exit') cannot await.
function flushWhiteboardSync() {
  if (!_whiteboardDirty || !_whiteboardCache) return;
  try {
    const dir = resolve(WHITEBOARD_PATH, '..');
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
    const tmp = WHITEBOARD_PATH + '.tmp';
    writeFileSync(tmp, JSON.stringify(_whiteboardCache) + '\n', 'utf-8');
    renameSync(tmp, WHITEBOARD_PATH);
    _whiteboardDirty = false;
  } catch (err) {
    console.error('[whiteboard] sync flush failed:', err.message);
  }
}

// Fat keys that historically lived inside ui-state.json. They now reside in
// the blob store (lib/ui-blob-store.js) — split:true maps are exploded into
// one row per entry. mergeUiState routes incoming writes from stale clients
// (open tabs from before the migration) into the store so the main file can
// never re-fatten.
const FAT_KEY_ROUTES = {
  'synabun-claude-panel-session-snapshots': { ns: 'claude-snapshots', split: true },
  'synabun-codex-panel-thread-snapshots':   { ns: 'codex-snapshots',  split: true },
  'synabun-ocp-session-snapshots':          { ns: 'ocp-snapshots',    split: true },
  'synabun-node-positions':                 { ns: 'kv', split: false },
  'synabun-node-positions-2d':              { ns: 'kv', split: false },
};
const BLOB_NS_ALLOWLIST = new Set(['claude-snapshots', 'codex-snapshots', 'ocp-snapshots', 'kv', EDITOR_BACKUP_NAMESPACE]);

function routeFatKeyToBlobStore(key, value) {
  const fat = FAT_KEY_ROUTES[key];
  if (!fat || value === null || value === undefined) return;
  // storage.js values arrive JSON-encoded as strings; tolerate both forms.
  if (fat.split) {
    const map = typeof value === 'string' ? JSON.parse(value) : value;
    if (map && typeof map === 'object' && !Array.isArray(map)) {
      for (const [id, entry] of Object.entries(map)) blobPut(fat.ns, id, entry);
    }
  } else {
    blobPut(fat.ns, key, value);
  }
}

// Shared merge logic for PATCH and POST (sendBeacon)
function mergeUiState(updates) {
  const current = loadUiState();
  for (const [key, value] of Object.entries(updates)) {
    if (key.startsWith('_')) continue; // protect metadata keys
    if (FAT_KEY_ROUTES[key]) {
      try { routeFatKeyToBlobStore(key, value); } catch (err) { console.warn(`[ui-blobs] shim for ${key} failed:`, err.message); }
      continue;
    }
    if (value === null) {
      delete current[key];
    } else {
      current[key] = value;
    }
  }
  saveUiState(current);
  return current;
}

// One-time idempotent migration: move fat keys out of ui-state.json into the
// blob store. Shrinks the file (and every boot GET) from multi-MB to ~30KB.
function migrateFatKeysToBlobStore() {
  const state = loadUiState();
  const fatKeys = Object.keys(FAT_KEY_ROUTES).filter(k => state[k] !== undefined);
  if (!fatKeys.length) return;
  const bak = resolve(DATA_HOME, 'data', 'ui-state.pre-blob-migration.bak.json');
  try { if (!existsSync(bak) && existsSync(UI_STATE_PATH)) copyFileSync(UI_STATE_PATH, bak); } catch {}
  for (const key of fatKeys) {
    try {
      routeFatKeyToBlobStore(key, state[key]);
      delete state[key];
      console.log(`[ui-blobs] migrated ${key} → ${FAT_KEY_ROUTES[key].ns}`);
    } catch (err) {
      console.warn(`[ui-blobs] migration of ${key} failed (kept in ui-state):`, err.message);
    }
  }
  saveUiState(state);
}

try {
  initBlobStore(resolve(DATA_HOME, 'data', 'ui-blobs.db'));
  migrateFatKeysToBlobStore();
} catch (err) {
  console.warn('[ui-blobs] init failed:', err.message);
}

// GET /api/ui-state — Full state dump (boot hydration)
app.get('/api/ui-state', (req, res) => {
  try {
    res.json(loadUiState());
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PATCH /api/ui-state — Partial key update (debounced writes from client)
app.patch('/api/ui-state', (req, res) => {
  try {
    if (!req.body || typeof req.body !== 'object') {
      return res.status(400).json({ error: 'Body must be a JSON object' });
    }
    mergeUiState(req.body);
    res.json({ ok: true });
  } catch (err) {
    console.error('PATCH /api/ui-state error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/ui-state — Same as PATCH (needed for navigator.sendBeacon on page unload)
app.post('/api/ui-state', (req, res) => {
  try {
    if (!req.body || typeof req.body !== 'object') {
      return res.status(400).json({ error: 'Body must be a JSON object' });
    }
    mergeUiState(req.body);
    res.json({ ok: true });
  } catch (err) {
    console.error('POST /api/ui-state error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// The code editor's routes (the files, their committed versions, the preferences, AI autocomplete) and the
// editor's namespace of the blob store below refuse everybody but the owner by themselves: an invite guest, a
// Host that is not this server's (DNS rebinding), a write from another site's page. See lib/http-guards.js.
// The checks in front of the routes (lib/request-gate.js) refuse the same callers; these routes do not rely on them.
const editorOwnerGuard = ownerRouteGuard({ isGuestRequest, port: PORT, allowedOrigins: publicWebOrigins });

// ── UI blob store — per-entry storage for fat keys (transcript snapshots, node positions, the editor's copies
// of unsaved buffers). lib/ui-blob-api.js: GET a namespace or an entry, PUT / POST / DELETE one entry. A write
// sends only the changed entry; of two requests of one page for an entry, the newer one is what stays, in
// whatever order they arrive; the editor's namespace asks the owner's guard on every route.
app.use(createUiBlobRouter({
  namespaces: BLOB_NS_ALLOWLIST,
  store: { getNamespace: blobGetNamespace, get: blobGet, put: blobPut, delete: blobDelete, prune: blobPrune },
  ownerNamespace: EDITOR_BACKUP_NAMESPACE,
  ownerGuard: editorOwnerGuard,
}));


// ═══════════════════════════════════════════
// IMAGE GALLERY API
// ═══════════════════════════════════════════

// GET /api/images — list all images with metadata
app.get('/api/images', (req, res) => {
  try {
    const favs = new Set(loadImageFavorites());
    const files = readdirSync(IMAGES_DIR)
      .filter(f => /\.(png|jpe?g|gif|webp|bmp|svg)$/i.test(f))
      .map(f => {
        const fp = join(IMAGES_DIR, f);
        const st = statSync(fp);
        let type = 'other';
        if (f.startsWith('screenshot-')) type = 'screenshot';
        else if (f.startsWith('synabun-img-')) type = 'attachment';
        else if (f.startsWith('synabun-wbimg-')) type = 'whiteboard';
        else if (f.startsWith('synabun-paste-')) type = 'paste';
        return {
          filename: f,
          type,
          size: st.size,
          path: fp,
          createdAt: st.birthtimeMs || st.ctimeMs,
          modifiedAt: st.mtimeMs,
          favorite: favs.has(f),
        };
      })
      .sort((a, b) => b.modifiedAt - a.modifiedAt);
    res.json({ images: files, total: files.length });
  } catch (err) {
    console.error('GET /api/images error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/images/file/:filename — serve an image file. These are the user's files (screenshots, pastes,
// attachments, whiteboard images), and an SVG is a document: opened as a page it runs its own script in this origin.
// So every answer runs nothing (a CSP with no script source, a sandbox) and is read only as the type it is sent as,
// and an SVG is a download when it is opened as a page. An <img> in the app ignores all three and shows the image.
app.get('/api/images/file/:filename', (req, res) => {
  const filename = basename(req.params.filename);
  const fp = join(IMAGES_DIR, filename);
  if (!existsSync(fp)) return res.status(404).json({ error: 'Not found' });
  setUntrustedFileHeaders(res, filename);
  res.sendFile(fp);
});

// POST /api/images/favorite — toggle favorite status
app.post('/api/images/favorite', (req, res) => {
  try {
    const { filename, favorite } = req.body;
    if (!filename) return res.status(400).json({ error: 'filename required' });
    const favs = loadImageFavorites();
    const idx = favs.indexOf(filename);
    if (favorite && idx === -1) favs.push(filename);
    else if (!favorite && idx !== -1) favs.splice(idx, 1);
    saveImageFavorites(favs);
    res.json({ ok: true, favorite: favs.includes(filename) });
  } catch (err) {
    console.error('POST /api/images/favorite error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// DELETE /api/images/:filename — delete an image
app.delete('/api/images/:filename', (req, res) => {
  try {
    const filename = basename(req.params.filename);
    const fp = join(IMAGES_DIR, filename);
    if (!existsSync(fp)) return res.status(404).json({ error: 'Not found' });
    unlinkSync(fp);
    // Remove from favorites too
    const favs = loadImageFavorites().filter(f => f !== filename);
    saveImageFavorites(favs);
    res.json({ ok: true });
  } catch (err) {
    console.error('DELETE /api/images error:', err.message);
    res.status(500).json({ error: err.message });
  }
});


// ═══════════════════════════════════════════
// YOUTUBE TRAILER PIPELINE — sourcing (IGDB+Steam), download (Steam mp4 / yt-dlp),
// config, test, analytics, OAuth. Browser upload/publish is handled by the
// youtube_* MCP tools driving Studio directly; these endpoints back the
// non-browser parts (the MCP server calls them via neural-interface.ts wrappers).
// ═══════════════════════════════════════════

const YT_CONFIG_PATH = resolve(DATA_HOME, 'data', 'youtube-config.json');
const YT_DOWNLOAD_DIR = resolve(DATA_HOME, 'data', 'youtube-downloads');
const YT_SECRET_KEYS = [
  'YT_OAUTH_CLIENT_ID', 'YT_OAUTH_CLIENT_SECRET', 'YT_REFRESH_TOKEN', 'YT_API_KEY',
  'YT_CHANNEL_ID', 'IGDB_CLIENT_ID', 'IGDB_CLIENT_SECRET', 'STEAM_API_KEY',
];

function ytReadSecrets() {
  const vars = parseEnvFile(ENV_PATH);
  const out = {};
  for (const k of YT_SECRET_KEYS) out[k] = vars[k] || process.env[k] || '';
  return out;
}

function ytDefaultPipelineConfig() {
  return {
    uploadTransport: 'browser',        // 'browser' (default, avoids API private-lock) | 'api'
    channelId: '',
    sources: { genres: [], platforms: [], minHype: 0, lookbackDays: 60, upcoming: true },
    download: { quality: 'bestvideo[height<=1080]+bestaudio/best[height<=1080]', outputDir: YT_DOWNLOAD_DIR, useCookies: false, cookiesBrowser: 'chrome', preferSteam: true },
    cadence: { postsPerDay: 1, scheduleWindow: ['16:00', '20:00'] },
  };
}

function ytReadPipelineConfig() {
  try {
    if (existsSync(YT_CONFIG_PATH)) return { ...ytDefaultPipelineConfig(), ...JSON.parse(readFileSync(YT_CONFIG_PATH, 'utf-8')) };
  } catch { /* fall through to defaults */ }
  return ytDefaultPipelineConfig();
}

function ytWritePipelineConfig(cfg) {
  mkdirSync(dirname(YT_CONFIG_PATH), { recursive: true });
  writeFileSync(YT_CONFIG_PATH, JSON.stringify(cfg, null, 2), 'utf-8');
}

function ytSanitizeFilename(name) {
  return String(name || 'trailer').replace(/[^a-z0-9._-]+/gi, '_').slice(0, 80) || 'trailer';
}

// ── IGDB (authenticated via a Twitch app-access token, cached until expiry) ──
let _igdbToken = null;
let _igdbTokenExp = 0;

async function igdbToken() {
  const s = ytReadSecrets();
  if (!s.IGDB_CLIENT_ID || !s.IGDB_CLIENT_SECRET) {
    throw new Error('IGDB not configured — set IGDB_CLIENT_ID + IGDB_CLIENT_SECRET in Settings → YouTube.');
  }
  if (_igdbToken && Date.now() < _igdbTokenExp - 60_000) return _igdbToken;
  const url = `https://id.twitch.tv/oauth2/token?client_id=${encodeURIComponent(s.IGDB_CLIENT_ID)}&client_secret=${encodeURIComponent(s.IGDB_CLIENT_SECRET)}&grant_type=client_credentials`;
  const r = await fetch(url, { method: 'POST' });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || !j.access_token) throw new Error(`IGDB token failed: ${j.message || r.status}`);
  _igdbToken = j.access_token;
  _igdbTokenExp = Date.now() + (j.expires_in || 3600) * 1000;
  return _igdbToken;
}

async function igdbQuery(endpoint, body) {
  const s = ytReadSecrets();
  const token = await igdbToken();
  const r = await fetch(`https://api.igdb.com/v4/${endpoint}`, {
    method: 'POST',
    headers: { 'Client-ID': s.IGDB_CLIENT_ID, 'Authorization': `Bearer ${token}`, 'Accept': 'application/json' },
    body,
  });
  const txt = await r.text();
  if (!r.ok) throw new Error(`IGDB ${endpoint} ${r.status}: ${txt.slice(0, 200)}`);
  const trimmed = txt.trim();
  if (!trimmed) return []; // 200 with an empty body = legitimately no results
  try { return JSON.parse(trimmed); } catch {
    // Don't swallow a malformed body as "no results" — surface it as a real error.
    console.error(`IGDB ${endpoint} returned non-JSON (${trimmed.length}b): ${trimmed.slice(0, 120)}`);
    throw new Error(`IGDB ${endpoint} returned a non-JSON response — likely an API or token problem.`);
  }
}

// ── Steam Storefront appdetails → official publisher trailers (direct mp4) ──
async function steamMovies(appid) {
  try {
    const r = await fetch(`https://store.steampowered.com/api/appdetails?appids=${appid}&filters=movies`);
    const j = await r.json().catch(() => ({}));
    const entry = j && j[appid];
    if (!entry || !entry.success || !entry.data || !Array.isArray(entry.data.movies)) return [];
    const https = (u) => (u ? String(u).replace(/^http:/, 'https:') : null);
    return entry.data.movies.map((m) => ({
      id: m.id,
      name: m.name,
      thumbnail: https(m.thumbnail),
      mp4: https(m.mp4 && (m.mp4.max || m.mp4['480'])),
      webm: https(m.webm && (m.webm.max || m.webm['480'])),
    }));
  } catch { return []; }
}

// IGDB external_games category 1 == Steam; uid is the Steam appid.
function steamAppidFromExternal(externals) {
  if (!Array.isArray(externals)) return null;
  const steam = externals.find((e) => e && e.category === 1 && e.uid);
  if (!steam) return null;
  const n = parseInt(steam.uid, 10);
  return Number.isFinite(n) ? n : null;
}

function ytDaysAgoIso(days, fallback = 7) {
  const n = parseInt(days, 10);
  const safeDays = Number.isFinite(n) ? Math.min(Math.max(n, 1), 365) : fallback;
  return new Date(Date.now() - safeDays * 86400_000).toISOString();
}

function ytDecodeText(value) {
  return String(value || '')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function ytTrailerSearchQuery(query) {
  const q = String(query || '').trim();
  if (!q) return 'official game trailer video game';
  if (/\b(game|gaming|video game|pc|steam|xbox|playstation|ps5|ps4|nintendo|switch)\b/i.test(q)) return q;
  return `${q} video game`;
}

function inferGameFromYoutubeTitle(title) {
  let name = ytDecodeText(title)
    .replace(/\s*\[[^\]]+\]/g, ' ')
    .replace(/\s*\([^)]*(?:ps5|ps4|xbox|switch|nintendo|pc|steam|official|trailer|gameplay)[^)]*\)/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const marker = name.search(/\b(official\s+)?(announce(?:ment)?|reveal|launch|release date|gameplay|story|cinematic|teaser|overview|accolades|dlc|update|early access)?\s*trailer\b/i);
  if (marker > 0) name = name.slice(0, marker);
  name = name.split(/\s+[-|:]\s+/)[0] || name;
  name = name
    .replace(/\b(official|trailer|gameplay|reveal|launch|announcement|announce|teaser|ps5|ps4|xbox|series x|series s|nintendo switch|switch|pc|steam|games)\b/gi, ' ')
    .replace(/[-:|]+$/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  return name || ytDecodeText(title).slice(0, 80);
}

const YT_TRAILER_KEEP_RE = /\b(official\s+)?(trailer|launch trailer|release date trailer|gameplay trailer|story trailer|announcement trailer|announce trailer|reveal trailer|teaser trailer|cinematic trailer|overview trailer|accolades trailer|dlc trailer|update trailer|early access trailer)\b/i;
const YT_TRAILER_REJECT_RE = /\b(reaction|reacts|breakdown|analysis|review|walkthrough|let'?s play|longplay|playthrough|compilation|all trailers|top\s*\d+|fan[- ]?made|soundtrack|music video|ost|livestream|live stream|podcast|interview|behind the scenes|movie trailer|film trailer|tv spot)\b/i;

async function youtubeRecentTrailers({ query = '', limit = 10, lookbackDays = 7 } = {}) {
  const s = ytReadSecrets();
  if (!s.YT_API_KEY) throw new Error('YouTube API key not configured — set YT_API_KEY in Settings → YouTube.');

  const lim = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 50);
  const url = new URL('https://www.googleapis.com/youtube/v3/search');
  url.searchParams.set('part', 'snippet');
  url.searchParams.set('type', 'video');
  url.searchParams.set('order', 'date');
  url.searchParams.set('maxResults', String(Math.min(Math.max(lim * 2, 10), 50)));
  url.searchParams.set('publishedAfter', ytDaysAgoIso(lookbackDays, 7));
  url.searchParams.set('q', ytTrailerSearchQuery(query));
  url.searchParams.set('videoCategoryId', '20');
  url.searchParams.set('relevanceLanguage', 'en');
  url.searchParams.set('safeSearch', 'none');
  url.searchParams.set('key', s.YT_API_KEY);

  const r = await fetch(url);
  const j = await r.json().catch(() => ({}));
  if (!r.ok) {
    const msg = j?.error?.message || j?.message || r.status;
    throw new Error(`YouTube search failed: ${msg}`);
  }

  const candidates = [];
  for (const item of j.items || []) {
    const videoId = item?.id?.videoId;
    const snip = item?.snippet || {};
    const title = ytDecodeText(snip.title);
    if (!videoId || !title) continue;
    if (!YT_TRAILER_KEEP_RE.test(title)) continue;
    if (YT_TRAILER_REJECT_RE.test(title)) continue;
    const publishedAt = snip.publishedAt || null;
    const thumbnail = snip.thumbnails?.maxres?.url || snip.thumbnails?.high?.url || snip.thumbnails?.medium?.url || null;
    candidates.push({
      source: 'youtube',
      game: inferGameFromYoutubeTitle(title),
      igdbId: null,
      appid: null,
      steamMovies: [],
      ytTrailerIds: [videoId],
      releaseDate: publishedAt ? String(publishedAt).slice(0, 10) : null,
      trailerPublishedAt: publishedAt,
      trailerTitle: title,
      channelTitle: ytDecodeText(snip.channelTitle),
      summary: ytDecodeText(snip.description) || null,
      cover: thumbnail,
      url: `https://www.youtube.com/watch?v=${videoId}`,
    });
    if (candidates.length >= lim) break;
  }
  return candidates;
}

// POST /api/sources/discover — YouTube/IGDB/Steam trailer discovery.
app.post('/api/sources/discover', async (req, res) => {
  try {
    const { source = 'auto', query = '', limit = 10, filters = {} } = req.body || {};
    const lim = Math.min(Math.max(parseInt(limit, 10) || 10, 1), 50);

    // YouTube direct search: newest published trailer videos first.
    if (source === 'youtube') {
      const candidates = await youtubeRecentTrailers({
        query,
        limit: lim,
        lookbackDays: filters.lookbackDays ?? 7,
      });
      return res.json({ ok: true, candidates });
    }

    // Steam-only: caller supplies explicit appids.
    if (source === 'steam') {
      const appids = Array.isArray(req.body?.appids) ? req.body.appids : [];
      const candidates = [];
      for (const appid of appids.slice(0, lim)) {
        candidates.push({ source: 'steam', game: String(appid), appid, steamMovies: await steamMovies(appid), ytTrailerIds: [] });
      }
      return res.json({ ok: true, candidates });
    }

    // IGDB discovery ('igdb' = metadata only, 'auto' = also resolve Steam mp4s).
    const cfg = ytReadPipelineConfig();
    const lookbackDays = (filters.lookbackDays ?? cfg.sources?.lookbackDays) || 60;
    const nowSec = Math.floor(Date.now() / 1000);
    const sinceSec = nowSec - lookbackDays * 86400;
    const aheadSec = nowSec + 120 * 86400;
    const fields = 'fields name,summary,first_release_date,genres.name,videos.video_id,videos.name,external_games.category,external_games.uid,cover.image_id,hypes;';

    let bodyStr;
    if (query && query.trim()) {
      bodyStr = `search "${query.replace(/"/g, '')}"; ${fields} where videos != null; limit ${lim};`;
    } else {
      bodyStr = `${fields} where first_release_date >= ${sinceSec} & first_release_date <= ${aheadSec} & videos != null & category = 0; sort hypes desc; limit ${lim};`;
    }

    const games = await igdbQuery('games', bodyStr);
    const candidates = [];
    for (const g of games || []) {
      const appid = steamAppidFromExternal(g.external_games);
      const ytTrailerIds = Array.isArray(g.videos) ? g.videos.map((v) => v.video_id).filter(Boolean) : [];
      const movies = appid && source === 'auto' ? await steamMovies(appid) : [];
      candidates.push({
        source: 'igdb',
        game: g.name,
        igdbId: g.id,
        appid: appid || null,
        steamMovies: movies,
        ytTrailerIds,
        releaseDate: g.first_release_date ? new Date(g.first_release_date * 1000).toISOString().slice(0, 10) : null,
        genres: Array.isArray(g.genres) ? g.genres.map((x) => x.name) : [],
        summary: g.summary || null,
        cover: g.cover?.image_id ? `https://images.igdb.com/igdb/image/upload/t_cover_big/${g.cover.image_id}.jpg` : null,
      });
    }
    if (candidates.length === 0) {
      // IGDB succeeded (a token/credential failure would have thrown above) but
      // matched nothing — say so, so an empty pool isn't mistaken for a broken token.
      return res.json({ ok: true, candidates: [], diagnostic: `IGDB reachable but returned 0 games for the ${lookbackDays}-day window${query && query.trim() ? ` matching "${query}"` : ''}. Broaden lookbackDays/query, or use source:youtube.` });
    }
    res.json({ ok: true, candidates });
  } catch (err) {
    console.error('POST /api/sources/discover error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// Resolve a yt-dlp invocation: explicit path → PATH binary → common install
// dirs (a GUI-launched server may not inherit the user's full PATH) → python module.
function resolveYtDlp() {
  const envPath = process.env.YTDLP_PATH;
  if (envPath && existsSync(envPath)) return { cmd: envPath, args: [] };
  try { execSync(process.platform === 'win32' ? 'where yt-dlp' : 'command -v yt-dlp', { stdio: 'ignore' }); return { cmd: 'yt-dlp', args: [] }; } catch { /* not on PATH */ }
  const home = os.homedir();
  for (const p of [join(home, '.local/bin/yt-dlp'), '/opt/homebrew/bin/yt-dlp', '/usr/local/bin/yt-dlp']) {
    if (existsSync(p)) return { cmd: p, args: [] };
  }
  try { execSync(process.platform === 'win32' ? 'where python3' : 'command -v python3', { stdio: 'ignore' }); return { cmd: 'python3', args: ['-m', 'yt_dlp'] }; } catch { /* no python */ }
  return null;
}

// Resolve an ffmpeg binary for yt-dlp's --ffmpeg-location (needed to merge the
// separate hi-res video+audio streams). Same PATH-independence as resolveYtDlp.
function resolveFfmpeg() {
  const envPath = process.env.FFMPEG_PATH;
  if (envPath && existsSync(envPath)) return envPath;
  const home = os.homedir();
  for (const p of ['/opt/homebrew/bin/ffmpeg', '/usr/local/bin/ffmpeg', join(home, '.local/bin/ffmpeg')]) {
    if (existsSync(p)) return p;
  }
  try {
    const out = execSync(process.platform === 'win32' ? 'where ffmpeg' : 'command -v ffmpeg', { encoding: 'utf-8' }).trim().split(/\r?\n/)[0];
    if (out && existsSync(out)) return out;
  } catch { /* not found */ }
  return null;
}

// POST /api/youtube/download — Steam direct-mp4 (preferred) or yt-dlp fallback.
app.post('/api/youtube/download', async (req, res) => {
  try {
    const cfg = ytReadPipelineConfig();
    const outDir = req.body?.outputDir || cfg.download?.outputDir || YT_DOWNLOAD_DIR;
    mkdirSync(outDir, { recursive: true });
    const baseName = ytSanitizeFilename(req.body?.filename || req.body?.ytId || (req.body?.appid ? `steam_${req.body.appid}` : 'trailer'));

    // 1) Steam direct mp4 — plain stream-to-disk, no yt-dlp/ffmpeg required.
    const steamUrl = req.body?.steamMp4Url;
    if (steamUrl) {
      const filePath = join(outDir, `${baseName}.mp4`);
      const r = await fetch(steamUrl);
      if (!r.ok || !r.body) throw new Error(`Steam mp4 fetch failed: HTTP ${r.status}`);
      await new Promise((ok, fail) => {
        Readable.fromWeb(r.body).pipe(createWriteStream(filePath)).on('finish', ok).on('error', fail);
      });
      return res.json({ ok: true, filePath, bytes: statSync(filePath).size, source: 'steam' });
    }

    // 2) yt-dlp fallback for an official YouTube trailer.
    const ytId = req.body?.ytId;
    const url = req.body?.url || (ytId ? `https://www.youtube.com/watch?v=${ytId}` : null);
    if (!url) return res.status(400).json({ error: 'Provide steamMp4Url, ytId, or url.' });

    const yd = resolveYtDlp();
    if (!yd) return res.status(501).json({ error: 'yt-dlp not found. Install it (brew install yt-dlp / pip install yt-dlp) or set YTDLP_PATH. ffmpeg is also required for merging.' });

    const quality = req.body?.quality || cfg.download?.quality || 'bestvideo[height<=1080]+bestaudio/best[height<=1080]';
    // yt-dlp 2026.06+ requires a JS runtime (node/deno) to extract YouTube — pass
    // --js-runtimes node so a fresh box doesn't fail extraction silently.
    const baseArgs = [...yd.args, '-f', quality, '--merge-output-format', 'mp4', '--no-playlist', '--js-runtimes', 'node', '-o', join(outDir, `${baseName}.%(ext)s`)];
    const ffmpeg = resolveFfmpeg();
    if (ffmpeg) baseArgs.push('--ffmpeg-location', dirname(ffmpeg)); // the flag wants the directory, not the binary path
    // Allow the cookie fallback by default; a caller can hard-disable with useCookies:false.
    const cookiesAllowed = req.body?.useCookies !== false;
    const cookieBrowser = cfg.download?.cookiesBrowser || 'chrome';

    // A GUI-launched NI may not inherit the user's shell PATH, so yt-dlp can't find
    // node/deno/ffmpeg. Prepend the running node's dir + the common Homebrew/local bins.
    // A packaged application's own runtime still goes last (withPackagedPathLast): the user's node first when there is one.
    const extraPath = [dirname(process.execPath), '/opt/homebrew/bin', '/usr/local/bin', join(os.homedir(), '.local/bin')].join(delimiter);
    const childEnv = withPackagedPathLast(withPathEnv(process.env, `${extraPath}${delimiter}${pathEnvValue(process.env)}`));

    const runYtDlp = (finalArgs) => new Promise((done) => {
      const child = spawn(yd.cmd, finalArgs, { windowsHide: true, env: childEnv });
      let stderr = '';
      child.stderr.on('data', (d) => { stderr += d.toString(); });
      child.on('error', (e) => done({ code: -1, stderr: `spawn failed: ${e.message}` }));
      child.on('close', (code) => done({ code, stderr }));
    });

    // Cookieless first (fast, no browser profile-lock risk); fall back to
    // browser cookies on auth errors OR 403/bot-detection failures.
    let run = await runYtDlp([...baseArgs, url]);
    const needsAuth = run.code !== 0 && /sign in|confirm your age|age-restrict|consent|login|private video|members-only|account|403|forbidden|bot|proof\s+of\s+humanity/i.test(run.stderr);
    if ((needsAuth || run.code !== 0) && cookiesAllowed) run = await runYtDlp([...baseArgs, '--cookies-from-browser', cookieBrowser, url]);
    if (run.code !== 0) return res.status(500).json({ error: `yt-dlp exited ${run.code}: ${run.stderr.slice(-400)}` });

    const produced = readdirSync(outDir).filter((f) => f.startsWith(`${baseName}.`)).map((f) => join(outDir, f));
    const mp4 = produced.find((f) => f.endsWith('.mp4')) || produced[0];
    if (!mp4) return res.status(500).json({ error: 'yt-dlp finished but no output file was found.' });
    res.json({ ok: true, filePath: mp4, bytes: statSync(mp4).size, source: 'yt-dlp' });
  } catch (err) {
    console.error('POST /api/youtube/download error:', err.message);
    if (!res.headersSent) res.status(500).json({ error: err.message });
  }
});

// GET /api/youtube/config — masked secrets + which credential sets are complete + pipeline config.
app.get('/api/youtube/config', (req, res) => {
  try {
    const secrets = ytReadSecrets();
    const masked = {};
    for (const k of YT_SECRET_KEYS) masked[k] = secrets[k] ? (k === 'YT_CHANNEL_ID' ? secrets[k] : maskKey(secrets[k])) : '';
    res.json({
      ok: true,
      secrets: masked,
      configured: {
        youtube: !!(secrets.YT_OAUTH_CLIENT_ID && secrets.YT_OAUTH_CLIENT_SECRET && secrets.YT_REFRESH_TOKEN),
        igdb: !!(secrets.IGDB_CLIENT_ID && secrets.IGDB_CLIENT_SECRET),
        steam: !!secrets.STEAM_API_KEY,
      },
      pipeline: ytReadPipelineConfig(),
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PUT /api/youtube/config — secrets → .env, pipeline → json. Masked values are ignored (treated as unchanged).
app.put('/api/youtube/config', (req, res) => {
  try {
    const body = req.body || {};
    if (body.secrets && typeof body.secrets === 'object') {
      const vars = parseEnvFile(ENV_PATH);
      for (const k of YT_SECRET_KEYS) {
        const v = body.secrets[k];
        if (v === undefined) continue;
        if (typeof v === 'string' && v.includes('*')) continue; // masked → unchanged
        if (v === '') { delete vars[k]; delete process.env[k]; continue; }
        vars[k] = v;
        process.env[k] = v;
      }
      writeEnvFile(ENV_PATH, vars);
      _igdbToken = null; _ytAccess = null; // force token refresh after a credential change
    }
    if (body.pipeline && typeof body.pipeline === 'object') ytWritePipelineConfig(body.pipeline);
    res.json({ ok: true });
  } catch (err) {
    console.error('PUT /api/youtube/config error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// POST /api/youtube/test — connectivity check per credential set.
app.post('/api/youtube/test', async (req, res) => {
  const target = (req.body?.target || 'all').toLowerCase();
  const results = {};
  if (target === 'igdb' || target === 'all') {
    try { await igdbToken(); const g = await igdbQuery('games', 'fields name; limit 1;'); results.igdb = { ok: Array.isArray(g) }; }
    catch (e) { results.igdb = { ok: false, error: e.message }; }
  }
  if (target === 'steam' || target === 'all') {
    try { const m = await steamMovies(620); results.steam = { ok: true, sampleMovies: m.length }; }
    catch (e) { results.steam = { ok: false, error: e.message }; }
  }
  if (target === 'youtube' || target === 'all') {
    try { await ytAccessToken(); results.youtube = { ok: true }; }
    catch (e) { results.youtube = { ok: false, error: e.message }; }
  }
  res.json({ ok: true, results });
});

// ── YouTube OAuth (refresh-token → short-lived access-token, cached) ──
let _ytAccess = null;
let _ytAccessExp = 0;

async function ytAccessToken() {
  const s = ytReadSecrets();
  if (!s.YT_OAUTH_CLIENT_ID || !s.YT_OAUTH_CLIENT_SECRET || !s.YT_REFRESH_TOKEN) {
    throw new Error('YouTube API not configured — OAuth client id/secret + refresh token required (use Authorize in Settings → YouTube).');
  }
  if (_ytAccess && Date.now() < _ytAccessExp - 60_000) return _ytAccess;
  const body = new URLSearchParams({
    client_id: s.YT_OAUTH_CLIENT_ID, client_secret: s.YT_OAUTH_CLIENT_SECRET,
    refresh_token: s.YT_REFRESH_TOKEN, grant_type: 'refresh_token',
  });
  const r = await fetch('https://oauth2.googleapis.com/token', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || !j.access_token) throw new Error(`YouTube token refresh failed: ${j.error_description || j.error || r.status}`);
  _ytAccess = j.access_token;
  _ytAccessExp = Date.now() + (j.expires_in || 3600) * 1000;
  return _ytAccess;
}

// POST /api/youtube/analytics — read-only reports via the YouTube Analytics API.
app.post('/api/youtube/analytics', async (req, res) => {
  try {
    const { videoId, channelId, metrics, startDate, endDate } = req.body || {};
    const token = await ytAccessToken();
    const s = ytReadSecrets();
    const ch = channelId || s.YT_CHANNEL_ID;
    const end = endDate || new Date().toISOString().slice(0, 10);
    const start = startDate || new Date(Date.now() - 28 * 86400 * 1000).toISOString().slice(0, 10);
    const mets = (Array.isArray(metrics) && metrics.length ? metrics : ['views', 'estimatedMinutesWatched', 'likes', 'subscribersGained']).join(',');
    const params = new URLSearchParams({ ids: ch ? `channel==${ch}` : 'channel==MINE', startDate: start, endDate: end, metrics: mets });
    if (videoId) { params.set('filters', `video==${videoId}`); params.set('dimensions', 'video'); }
    const r = await fetch(`https://youtubeanalytics.googleapis.com/v2/reports?${params}`, { headers: { Authorization: `Bearer ${token}` } });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(j.error?.message || `Analytics HTTP ${r.status}`);
    res.json({ ok: true, report: j });
  } catch (err) {
    console.error('POST /api/youtube/analytics error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// GET /api/youtube/oauth/start — returns the Google consent URL for the UI to open.
app.get('/api/youtube/oauth/start', (req, res) => {
  try {
    const s = ytReadSecrets();
    if (!s.YT_OAUTH_CLIENT_ID) return res.status(400).json({ error: 'Set YT_OAUTH_CLIENT_ID first.' });
    const redirect = `http://localhost:${PORT}/api/youtube/oauth/callback`;
    const url = 'https://accounts.google.com/o/oauth2/v2/auth?' + new URLSearchParams({
      client_id: s.YT_OAUTH_CLIENT_ID,
      redirect_uri: redirect,
      response_type: 'code',
      access_type: 'offline',
      prompt: 'consent',
      scope: ['https://www.googleapis.com/auth/youtube', 'https://www.googleapis.com/auth/youtube.upload', 'https://www.googleapis.com/auth/yt-analytics.readonly'].join(' '),
    });
    res.json({ ok: true, url, redirect });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET /api/youtube/oauth/callback — exchange the code for a refresh token, save to .env.
app.get('/api/youtube/oauth/callback', async (req, res) => {
  try {
    const code = req.query.code;
    if (!code) return res.status(400).send('Missing authorization code.');
    const s = ytReadSecrets();
    const redirect = `http://localhost:${PORT}/api/youtube/oauth/callback`;
    const body = new URLSearchParams({ code, client_id: s.YT_OAUTH_CLIENT_ID, client_secret: s.YT_OAUTH_CLIENT_SECRET, redirect_uri: redirect, grant_type: 'authorization_code' });
    const r = await fetch('https://oauth2.googleapis.com/token', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.refresh_token) {
      return res.status(500).send(`<h3>Authorization failed</h3><pre>${j.error_description || j.error || 'No refresh_token returned. Revoke the prior grant at myaccount.google.com and retry.'}</pre>`);
    }
    const vars = parseEnvFile(ENV_PATH);
    vars.YT_REFRESH_TOKEN = j.refresh_token;
    process.env.YT_REFRESH_TOKEN = j.refresh_token;
    writeEnvFile(ENV_PATH, vars);
    _ytAccess = null;
    res.send('<h3>YouTube connected ✓</h3><p>You can close this tab and return to SynaBun.</p>');
  } catch (err) { res.status(500).send(`Error: ${err.message}`); }
});


// ═══════════════════════════════════════════
// WHITEBOARD API — Claude MCP integration
// ═══════════════════════════════════════════

// The geometry engine (size estimation, anchor math, clamping, pct conversion)
// is shared with the MCP tools: mcp-server/src/services/whiteboard-geometry.ts,
// imported here from dist. Keep the two consumers on the same math.

const WB_PUBLIC_ROOT = join(__dirname, 'public');
const WB_GAMES_ROOT = join(__dirname, 'games');
const WB_ELEMENT_TYPES = new Set(['text', 'list', 'shape', 'arrow', 'pen', 'image', 'section']);
// Keys an update may touch. id/type/zIndex/measured/estimated/dataUrlBytes are server-owned.
const WB_UPDATABLE_KEYS = new Set([
  'x', 'y', 'width', 'height', 'content', 'items', 'levels', 'ordered', 'fontSize', 'color', 'bold', 'italic',
  'shape', 'points', 'startAnchor', 'endAnchor', 'rotation', 'strokeWidth', 'sectionType', 'label',
  'dataUrl', 'pathD',
]);

function wbNewId() {
  return 'wb-' + Date.now() + '-' + randomBytes(2).toString('hex').slice(0, 3);
}

// Layout engine for whiteboard auto-positioning. `frame` is the rect to lay
// out inside (usable viewport or a parent section box); sizes are already
// filled by ensureElementGeometry so the fallbacks only hit arrows/pen.
function applyWhiteboardLayout(elements, layout, frame) {
  const gap = 40;
  const pad = 60;
  const n = elements.length;
  if (!n) return;
  const w = (el) => el.width || 200;
  const h = (el) => el.height || 100;

  if (layout === 'center' || layout === 'column') {
    const totalH = elements.reduce((s, el) => s + h(el), 0) + gap * (n - 1);
    let y = frame.y + (frame.height - totalH) / 2;
    for (const el of elements) {
      el.x = Math.round(frame.x + (frame.width - w(el)) / 2);
      el.y = Math.round(y);
      y += h(el) + gap;
    }
  } else if (layout === 'row') {
    const totalW = elements.reduce((s, el) => s + w(el), 0) + gap * (n - 1);
    let x = frame.x + (frame.width - totalW) / 2;
    for (const el of elements) {
      el.x = Math.round(x);
      el.y = Math.round(frame.y + (frame.height - h(el)) / 2);
      x += w(el) + gap;
    }
  } else if (layout === 'grid') {
    const cols = n <= 2 ? 2 : n <= 6 ? 3 : 4;
    const rows = Math.ceil(n / cols);
    const cellW = (frame.width - pad * 2 - gap * (cols - 1)) / cols;
    const cellH = (frame.height - pad * 2 - gap * (rows - 1)) / rows;
    elements.forEach((el, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      el.x = Math.round(frame.x + pad + col * (cellW + gap) + (cellW - w(el)) / 2);
      el.y = Math.round(frame.y + pad + row * (cellH + gap) + (cellH - h(el)) / 2);
    });
  }
}

/** Resolve an image `url` to a base64 dataUrl. Only files inside public/
 *  (or games/ for "/games/…") are served — no path traversal. */
function wbResolveImageUrl(el, reasons) {
  if (typeof el.url !== 'string' || !el.url) return;
  const rel = el.url.replace(/^\/+/, '');
  const isGame = rel.startsWith('games/');
  const filePath = isGame ? join(__dirname, rel) : join(WB_PUBLIC_ROOT, rel);
  if (!pathIsInside(filePath, isGame ? WB_GAMES_ROOT : WB_PUBLIC_ROOT)) { reasons.push('image:outside-static-root'); return; }
  if (!existsSync(filePath)) { reasons.push('image:not-found'); return; }
  try {
    const buf = readFileSync(filePath);
    const ext = extname(filePath).toLowerCase();
    const mime = ext === '.svg' ? 'image/svg+xml'
      : ext === '.png' ? 'image/png'
      : ext === '.webp' ? 'image/webp'
      : ext === '.gif' ? 'image/gif'
      : 'image/jpeg';
    el.dataUrl = `data:${mime};base64,${buf.toString('base64')}`;
  } catch {
    reasons.push('image:not-found');
  }
}

/** Placement frame for `parent` (a section id): its box, or an error code. */
function wbSectionFrame(parentId, lookup) {
  const parent = lookup(parentId);
  if (!parent) return { error: 'parent:not-found' };
  if (parent.type !== 'section') return { error: 'parent:not-a-section' };
  const frame = wbElementBox(parent, lookup);
  if (!frame) return { error: 'parent:not-found' };
  return { frame, parent };
}

/** Translate px coordinates given relative to a parent section into canvas px. */
function wbOffsetByFrame(target, frame) {
  if (Number.isFinite(target.x)) target.x += frame.x;
  if (Number.isFinite(target.y)) target.y += frame.y;
  if (Array.isArray(target.points)) {
    target.points = target.points.map(p => [(Number(p[0]) || 0) + frame.x, (Number(p[1]) || 0) + frame.y]);
  }
}

/** Keep an element inside `frame`: boxes by their real size, arrows/pen by
 *  translating the whole polyline (anchored endpoints are left to the anchor). */
function wbClampElement(el, frame, reasons, lookup) {
  if (el.type === 'arrow' || el.type === 'pen') {
    if (!Array.isArray(el.points) || el.points.length < 2) return;
    const skip = [];
    if (el.type === 'arrow' && el.startAnchor) skip.push(0);
    if (el.type === 'arrow' && el.endAnchor) skip.push(el.points.length - 1);
    const { points, dx, dy } = wbClampPointsToRect(el.points, frame, skip);
    if (dx || dy) {
      el.points = points;
      if (el.type === 'pen') {
        if (Number.isFinite(el.x)) el.x += dx;
        if (Number.isFinite(el.y)) el.y += dy;
        delete el.pathD;   // derived from points — the client recomputes it
      }
      reasons.push('clamp:points');
    }
    return;
  }
  if (!Number.isFinite(el.x) || !Number.isFinite(el.y)) return;
  const box = wbElementBox(el, lookup);
  if (!box) return;
  const c = wbClampBoxToRect(box, frame);
  if (c.reasons.length) {
    el.x = c.x;
    el.y = c.y;
    reasons.push(...c.reasons);
  }
}

/** Final geometry summary echoed to callers (what actually landed). */
function wbGeometrySummary(el, lookup) {
  const box = wbElementBox(el, lookup);
  const out = { id: el.id, type: el.type, zIndex: el.zIndex };
  if (box) {
    out.x = Math.round(box.x);
    out.y = Math.round(box.y);
    out.width = Math.round(box.width);
    out.height = Math.round(box.height);
  }
  if (el.estimated) out.estimated = true;
  if (el.type === 'arrow' || el.type === 'pen') out.points = el.points;
  return out;
}

/** Drop anchors that do not resolve to an existing non-arrow element. */
function wbValidateAnchors(el, lookup, reasons, touched) {
  if (el.type !== 'arrow') return;
  for (const key of ['startAnchor', 'endAnchor']) {
    if (el[key] == null) continue;
    const target = lookup(String(el[key]));
    if (!target || target.type === 'arrow' || target.id === el.id) {
      reasons.push(`anchor:${key === 'startAnchor' ? 'start' : 'end'}-dropped`);
      el[key] = null;
      if (touched) touched.add(key);
    }
  }
}

/**
 * Apply update/remove ops to the live board. Shared by PUT /elements/:id,
 * DELETE /elements/:id and POST /elements/batch so all three validate, clamp,
 * re-estimate and cascade identically. Returns per-op results plus the ops to
 * broadcast (final values, so old and new clients converge on the same state).
 */
function applyWhiteboardOps(wb, ops, { coordMode } = {}) {
  const viewport = getWhiteboardViewport();
  const usable = wbUsableRect(viewport);
  const lookup = (id) => wb.elements.find(e => e.id === id);
  const results = [];
  const broadcastOps = [];

  for (const op of ops) {
    if (!op || typeof op !== 'object') { results.push({ op: undefined, id: undefined, ok: false, error: 'op:invalid' }); continue; }
    const id = op.id != null ? String(op.id) : '';

    if (op.op === 'update') {
      const el = lookup(id);
      if (!el) { results.push({ op: 'update', id, ok: false, error: 'not found' }); continue; }
      const reasons = [];
      const updates = (op.updates && typeof op.updates === 'object') ? op.updates : {};

      let frame = usable;
      if (op.parent != null) {
        const r = wbSectionFrame(String(op.parent), lookup);
        if (r.error) { results.push({ op: 'update', id, ok: false, error: `${r.error} "${op.parent}"` }); continue; }
        frame = r.frame;
        reasons.push(`parent:${r.parent.id}`);
      }

      // Whitelisted patch; text/list are auto-sized so their sizes are never caller-set
      const patch = {};
      for (const [key, value] of Object.entries(updates)) {
        if (WB_UPDATABLE_KEYS.has(key)) patch[key] = value;
      }
      if (el.type === 'text' || el.type === 'list') { delete patch.width; delete patch.height; }
      // List items as strings + levels (public/shared/whiteboard-list.js): plain strings stay level 0,
      // { text, level } objects and a levels array are fitted to the nesting rules.
      if (el.type === 'list') Object.assign(patch, normalizeListUpdate(el.items, patch));
      else delete patch.levels;
      if (coordMode === 'pct') { wbConvertPctInPlace(patch, frame, { pointsToo: true }); reasons.push('pct'); }
      else if (op.parent != null) wbOffsetByFrame(patch, frame);   // px relative to the parent section
      if (patch.points !== undefined) {
        if (!Array.isArray(patch.points) || patch.points.length < 2) { results.push({ op: 'update', id, ok: false, error: 'points:min-2' }); continue; }
        patch.points = patch.points.map(p => [Number(p[0]) || 0, Number(p[1]) || 0]);
        if (el.type === 'pen') delete el.pathD;
      }

      const touched = new Set(Object.keys(patch));
      const sizeInputsChanged = ['content', 'items', 'levels', 'fontSize'].some(k => k in patch);
      Object.assign(el, patch);
      if (el.levels == null) delete el.levels;   // a flat list is stored without levels
      wbValidateAnchors(el, lookup, reasons, touched);

      let reEstimated = false;
      if ((el.type === 'text' || el.type === 'list') && sizeInputsChanged) {
        reasons.push(...wbEnsureElementGeometry(el, { force: true }));
        reEstimated = true;
        for (const k of ['width', 'height', 'estimated']) touched.add(k);
      } else {
        const filled = wbEnsureElementGeometry(el);
        if (filled.length) {
          reasons.push(...filled);
          for (const k of ['width', 'height', 'color', 'label', 'sectionType']) if (el[k] !== undefined) touched.add(k);
        }
      }

      const before = { x: el.x, y: el.y, points: el.points };
      wbClampElement(el, frame, reasons, lookup);
      if (el.x !== before.x) touched.add('x');
      if (el.y !== before.y) touched.add('y');
      if (el.points !== before.points) { touched.add('points'); if (el.type === 'pen') { touched.add('x'); touched.add('y'); } }

      const updatesOut = {};
      for (const k of touched) updatesOut[k] = el[k] === undefined ? null : el[k];
      if (reEstimated) updatesOut.measured = false;   // tell the browser to re-measure this card
      broadcastOps.push({ op: 'update', id, updates: updatesOut });
      results.push({ op: 'update', id, ok: true, element: wbGeometrySummary(el, lookup), adjusted: reasons, warnings: [] });
      continue;
    }

    if (op.op === 'remove') {
      const idx = wb.elements.findIndex(e => e.id === id);
      if (idx < 0) { results.push({ op: 'remove', id, ok: false, error: 'not found' }); continue; }
      const removed = wb.elements[idx];
      const center = wbElementCenter(removed, lookup) || { x: removed.x || 0, y: removed.y || 0 };
      wb.elements.splice(idx, 1);
      // Detach arrows anchored to it and park their endpoint on its centre
      // (parity with the client's deleteElement).
      const cascade = [];
      for (const a of wb.elements) {
        if (a.type !== 'arrow' || !Array.isArray(a.points) || a.points.length < 2) continue;
        const upd = {};
        let hit = false;
        if (a.startAnchor === id) { a.points[0] = [center.x, center.y]; a.startAnchor = null; upd.startAnchor = null; hit = true; }
        if (a.endAnchor === id) { a.points[a.points.length - 1] = [center.x, center.y]; a.endAnchor = null; upd.endAnchor = null; hit = true; }
        if (hit) {
          upd.points = a.points;
          cascade.push({ id: a.id, updates: upd });
          broadcastOps.push({ op: 'update', id: a.id, updates: upd });
        }
      }
      broadcastOps.push({ op: 'remove', id });
      results.push({ op: 'remove', id, ok: true, type: removed.type, cascade });
      continue;
    }

    results.push({ op: op.op, id, ok: false, error: 'op:invalid' });
  }

  return { results, broadcastOps };
}

// GET /api/whiteboard — Read current whiteboard state from its dedicated store.
// ?images=0 replaces image dataUrls with their byte size (MCP reads never need
// the base64 payload).
app.get('/api/whiteboard', (req, res) => {
  try {
    const wb = loadWhiteboard();
    const stripImages = req.query.images === '0' || req.query.images === 'false';
    const elements = stripImages
      ? wb.elements.map(el => {
          if (el.type !== 'image' || typeof el.dataUrl !== 'string') return el;
          const { dataUrl, ...rest } = el;
          return { ...rest, dataUrlBytes: Buffer.byteLength(dataUrl, 'utf8') };
        })
      : wb.elements;
    res.json({
      ok: true,
      elements,
      nextZIndex: wb.nextZIndex || 1,
      viewport: getWhiteboardViewport(),
      connection: getWhiteboardConnection(),
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PUT /api/whiteboard — Bulk replace. Client persistence fallback for when the
// whiteboard WS is down; the WS state:sync path is preferred when connected.
app.put('/api/whiteboard', (req, res) => {
  try {
    const { elements, nextZIndex } = req.body || {};
    if (!Array.isArray(elements)) return res.status(400).json({ error: 'elements must be an array' });
    const current = loadWhiteboard();
    mergeMeasuredSizes(elements, current.elements);
    normalizeWhiteboardElements(elements);
    saveWhiteboard({ elements, nextZIndex: nextZIndex || 1 });
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/whiteboard/elements — Add one or more elements.
// Pipeline per element: validate type → image url → defaults + size estimate
// (BEFORE layout/pct/clamp so real sizes drive them) → parent frame → pct →
// layout (per frame group) → anchor validation → clamp → id → zIndex.
// The response echoes the FINAL geometry with every adjustment named.
app.post('/api/whiteboard/elements', (req, res) => {
  try {
    const { elements, coordMode, layout } = req.body || {};
    if (!Array.isArray(elements) || elements.length === 0) {
      return res.status(400).json({ error: 'elements must be a non-empty array' });
    }
    if (elements.length > 100) return res.status(400).json({ error: 'at most 100 elements per call' });

    const wb = loadWhiteboard();
    const viewport = getWhiteboardViewport();
    const usable = wbUsableRect(viewport);
    const staged = [];   // { el, reasons, frame, frameKey, requestedId }
    const errors = [];
    const lookupAll = (id) => wb.elements.find(e => e.id === id) || staged.find(s => s.el.id === id)?.el;

    elements.forEach((raw, index) => {
      if (!raw || typeof raw !== 'object' || !WB_ELEMENT_TYPES.has(raw.type)) {
        errors.push({ index, type: raw?.type, error: 'type:invalid' });
        return;
      }
      const el = { ...raw };
      const reasons = [];
      const parentId = el.parent;
      delete el.parent;
      delete el.coordMode;

      // List items as strings + levels (public/shared/whiteboard-list.js), before the size estimate reads them.
      if (el.type === 'list') { if (Array.isArray(el.items)) writeListItems(el, el.items, el.levels); else delete el.levels; }
      else delete el.levels;
      if (el.type === 'image' && el.url && !el.dataUrl) wbResolveImageUrl(el, reasons);
      if (el.type === 'image' && !(el.width > 0 && el.height > 0)) reasons.push('image:no-size');
      reasons.push(...wbEnsureElementGeometry(el).filter(r => r !== 'image:no-size'));

      let frame = usable;
      let frameKey = 'viewport';
      if (parentId != null && parentId !== '') {
        const r = wbSectionFrame(String(parentId), lookupAll);
        if (r.error) { errors.push({ index, type: el.type, error: `${r.error} "${parentId}"` }); return; }
        frame = r.frame;
        frameKey = r.parent.id;
        reasons.push(`parent:${r.parent.id}`);
      }
      if (coordMode === 'pct') { wbConvertPctInPlace(el, frame, { pointsToo: true }); reasons.push('pct'); }
      else if (frameKey !== 'viewport') wbOffsetByFrame(el, frame);   // px relative to the parent section

      if (el.type === 'arrow' || el.type === 'pen') {
        if (!Array.isArray(el.points) || el.points.length < 2) { errors.push({ index, type: el.type, error: 'points:min-2' }); return; }
        el.points = el.points.map(p => [Number(p[0]) || 0, Number(p[1]) || 0]);
      }
      wbValidateAnchors(el, lookupAll, reasons, null);

      let requestedId;
      if (el.id != null && el.id !== '') {
        el.id = String(el.id);
        if (lookupAll(el.id)) { requestedId = el.id; el.id = wbNewId(); reasons.push('id:regenerated'); }
      } else {
        el.id = wbNewId();
      }
      staged.push({ el, reasons, frame, frameKey, requestedId });
    });

    // Layout per frame group, with real sizes (defaults already applied)
    if (layout && staged.length) {
      const groups = new Map();
      for (const s of staged) {
        if (!groups.has(s.frameKey)) groups.set(s.frameKey, []);
        groups.get(s.frameKey).push(s);
      }
      for (const group of groups.values()) {
        applyWhiteboardLayout(group.map(s => s.el), layout, group[0].frame);
        for (const s of group) s.reasons.push(`layout:${layout}`);
      }
    }

    const added = [];
    for (const s of staged) {
      wbClampElement(s.el, s.frame, s.reasons, lookupAll);
      s.el.zIndex = wb.nextZIndex++;
      wb.elements.push(s.el);
      const summary = wbGeometrySummary(s.el, lookupAll);
      if (s.requestedId) summary.requestedId = s.requestedId;
      summary.adjusted = s.reasons;
      summary.warnings = [];
      added.push(summary);
    }

    if (!added.length) return res.status(400).json({ error: 'No elements could be added', errors });

    saveWhiteboard(wb);
    broadcastToWhiteboard({ type: 'add', elements: staged.map(s => s.el) });

    res.json({ ok: true, viewport, connection: getWhiteboardConnection(), added, errors });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/whiteboard/elements/batch — Several update/remove ops atomically:
// one save, one broadcast, per-op results (a missing id fails only that op).
app.post('/api/whiteboard/elements/batch', (req, res) => {
  try {
    const { ops, coordMode } = req.body || {};
    if (!Array.isArray(ops) || ops.length === 0) return res.status(400).json({ error: 'ops must be a non-empty array' });
    if (ops.length > 200) return res.status(400).json({ error: 'at most 200 ops per call' });
    const wb = loadWhiteboard();
    const { results, broadcastOps } = applyWhiteboardOps(wb, ops, { coordMode });
    if (broadcastOps.length) {
      saveWhiteboard(wb);
      broadcastWhiteboardOps(broadcastOps);
    }
    res.json({ ok: true, viewport: getWhiteboardViewport(), connection: getWhiteboardConnection(), results, broadcast: { ops: broadcastOps.length } });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// PUT /api/whiteboard/elements/:id — Update an element (same engine as batch)
app.put('/api/whiteboard/elements/:id', (req, res) => {
  try {
    const { id } = req.params;
    const body = req.body || {};
    const { updates, coordMode, parent } = body.updates
      ? body
      : { updates: body, coordMode: body.coordMode, parent: body.parent };
    const wb = loadWhiteboard();
    const { results, broadcastOps } = applyWhiteboardOps(wb, [{ op: 'update', id, updates, parent }], { coordMode });
    const r = results[0];
    if (!r.ok) {
      if (r.error === 'not found') return res.status(404).json({ error: `Element ${id} not found` });
      return res.status(400).json({ error: r.error });
    }
    saveWhiteboard(wb);
    broadcastWhiteboardOps(broadcastOps);
    res.json({ ok: true, element: wb.elements.find(e => e.id === id), geometry: r.element, adjusted: r.adjusted, warnings: r.warnings });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// DELETE /api/whiteboard/elements/:id — Remove an element (arrows anchored to
// it are detached and parked on its centre; reported as `cascade`)
app.delete('/api/whiteboard/elements/:id', (req, res) => {
  try {
    const { id } = req.params;
    const wb = loadWhiteboard();
    const { results, broadcastOps } = applyWhiteboardOps(wb, [{ op: 'remove', id }]);
    const r = results[0];
    if (!r.ok) return res.status(404).json({ error: `Element ${id} not found` });
    saveWhiteboard(wb);
    broadcastWhiteboardOps(broadcastOps);
    res.json({ ok: true, removed: { id, type: r.type }, cascade: r.cascade });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/whiteboard/clear — Clear all elements
app.post('/api/whiteboard/clear', (req, res) => {
  try {
    saveWhiteboard({ elements: [], nextZIndex: 1 });
    broadcastToWhiteboard({ type: 'clear' });

    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/whiteboard/screenshot — Ask the primary (focus-active) browser
// window for a re-render. ?crop=usable crops to the usable viewport. The
// response carries the coordinate mapping so callers can turn image pixels
// back into canvas coordinates.
app.get('/api/whiteboard/screenshot', async (req, res) => {
  const target = getPrimaryWhiteboardClient();
  const anyOpen = target || [...whiteboardClients].some(c => c.readyState === 1);
  if (!anyOpen) {
    return res.status(503).json({ error: 'No browser connected to whiteboard. Open the Neural Interface and enter Focus mode.' });
  }

  const requestId = randomBytes(8).toString('hex');
  const crop = req.query.crop === 'usable' ? 'usable' : 'full';
  try {
    const msg = await new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        whiteboardPendingScreenshots.delete(requestId);
        reject(new Error('Screenshot timed out after 12s'));
      }, 12000);

      whiteboardPendingScreenshots.set(requestId, { resolve, reject, timer });
      const payload = { type: 'screenshot:request', requestId, crop };
      if (target) target.send(JSON.stringify(payload));
      else broadcastToWhiteboard(payload);
    });

    const from = msg.from || {};
    const vp = from.viewport || getWhiteboardViewport();
    const hasMeta = Number.isFinite(msg.width) && Number.isFinite(msg.height);
    res.json({
      ok: true,
      data: msg.data, // base64 JPEG
      width: hasMeta ? msg.width : vp.width + (vp.xOffset || 0),
      height: hasMeta ? msg.height : vp.height + (vp.yOffset || 0),
      scale: hasMeta && Number.isFinite(msg.scale) ? msg.scale : 1,
      xOffset: Number.isFinite(msg.xOffset) ? msg.xOffset : (vp.xOffset || 0),
      yOffset: Number.isFinite(msg.yOffset) ? msg.yOffset : (vp.yOffset || 0),
      crop: msg.crop || 'full',
      viewport: vp,
      clientId: from.clientId || null,
      elements: loadWhiteboard().elements.length,
      metadataSource: hasMeta ? 'client' : 'derived',
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


// ══════════════════════════════════════════════════
// STYLE GUIDE — per-project brand and design system
// ══════════════════════════════════════════════════

// /api/style-guide/* — the guide, DESIGN.md and the token files it writes, imports,
// presets, history and agent proposals. The logic is lib/style-guide/ (docs/style-guide.md);
// the routes are its api.js. A path inside a registered project resolves to that project.
const styleGuideStore = createStyleGuideStore({
  dataHome: DATA_HOME,
  projects: () => loadHookProjects(),
  log: (tag, message) => console.warn(`[${tag}] ${message}`),
});
registerStyleGuideRoutes(app, { store: styleGuideStore, log: (tag, message) => console.error(`[${tag}] ${message}`) });


// ══════════════════════════════════════════════════
// TIC TAC TOE — REST API (dedicated game endpoints)
// ══════════════════════════════════════════════════

const TTT_BOARD_SIZE = 500;
const TTT_CELL_SIZE = Math.round(TTT_BOARD_SIZE / 3);
const TTT_PIECE_SIZE = 120;
const TTT_PIECE_OFFSET = Math.round((TTT_CELL_SIZE - TTT_PIECE_SIZE) / 2);
const TTT_NUMBER_SIZE = 60;
const TTT_NUMBER_OFFSET = Math.round((TTT_CELL_SIZE - TTT_NUMBER_SIZE) / 2);

const TTT_WIN_LINES = [
  [0,1,2], [3,4,5], [6,7,8], // rows
  [0,3,6], [1,4,7], [2,5,8], // columns
  [0,4,8], [2,4,6],          // diagonals
];

function tttCheckResult(board) {
  for (const [a,b,c] of TTT_WIN_LINES) {
    if (board[a] && board[a] === board[b] && board[b] === board[c]) return board[a];
  }
  return board.every(c => c !== null) ? 'draw' : null;
}

function tttBoardAscii(board) {
  const display = board.map((c, i) => c || String(i + 1));
  return [
    `  ${display[0]} | ${display[1]} | ${display[2]}`,
    '  ---------',
    `  ${display[3]} | ${display[4]} | ${display[5]}`,
    '  ---------',
    `  ${display[6]} | ${display[7]} | ${display[8]}`,
  ].join('\n');
}

function tttLoadAsset(name) {
  const filePath = join(__dirname, 'games', 'TicTacToe', `${name}.svg`);
  if (!existsSync(filePath)) return null;
  const buf = readFileSync(filePath);
  return `data:image/svg+xml;base64,${buf.toString('base64')}`;
}

function tttCellPosition(cellNum, boardX, boardY, size, offset) {
  const idx = cellNum - 1;
  const col = idx % 3;
  const row = Math.floor(idx / 3);
  return {
    x: boardX + col * TTT_CELL_SIZE + offset,
    y: boardY + row * TTT_CELL_SIZE + offset,
  };
}

// POST /api/games/tictactoe/start — Set up board and initialize game
app.post('/api/games/tictactoe/start', (req, res) => {
  try {
    const piece = (req.body.piece || 'X').toUpperCase();
    if (piece !== 'X' && piece !== 'O') {
      return res.status(400).json({ error: 'piece must be "X" or "O"' });
    }

    // Fresh whiteboard for the board — persisted to its own store, not ui-state.
    const wb = { elements: [], nextZIndex: 1 };

    // Calculate centered board position (inside the usable viewport, past the
    // tool rail / navbar offsets)
    const vp = getWhiteboardViewport();
    const boardX = Math.round((vp.xOffset || 0) + (vp.width - TTT_BOARD_SIZE) / 2);
    const boardY = Math.round((vp.yOffset || 0) + (vp.height - TTT_BOARD_SIZE) / 2);

    // Build board elements
    const elements = [];

    // Board grid
    const boardDataUrl = tttLoadAsset('Board');
    elements.push({
      id: 'ttt-board',
      type: 'image',
      x: boardX,
      y: boardY,
      width: TTT_BOARD_SIZE,
      height: TTT_BOARD_SIZE,
      dataUrl: boardDataUrl,
      zIndex: wb.nextZIndex++,
    });

    // Number markers (1-9)
    for (let i = 1; i <= 9; i++) {
      const pos = tttCellPosition(i, boardX, boardY, TTT_NUMBER_SIZE, TTT_NUMBER_OFFSET);
      const dataUrl = tttLoadAsset(String(i));
      elements.push({
        id: `ttt-cell-${i}`,
        type: 'image',
        x: pos.x,
        y: pos.y,
        width: TTT_NUMBER_SIZE,
        height: TTT_NUMBER_SIZE,
        dataUrl,
        zIndex: wb.nextZIndex++,
      });
    }

    wb.elements = elements;

    // Initialize game state
    const gameState = {
      board: [null,null,null, null,null,null, null,null,null],
      turn: 'X',
      status: 'playing',
      winner: null,
      piece,
      boardX,
      boardY,
    };
    saveWhiteboard(wb);
    const state = loadUiState();
    state['tictactoe-game'] = gameState;
    saveUiState(state);

    // Broadcast to whiteboard clients
    broadcastToWhiteboard({ type: 'clear' });
    broadcastToWhiteboard({ type: 'add', elements });
    broadcastToWhiteboard({ type: 'ttt-started', boardX, boardY });

    res.json({
      ok: true,
      board: gameState.board,
      ascii: tttBoardAscii(gameState.board),
      turn: gameState.turn,
      status: gameState.status,
      piece,
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/games/tictactoe/move — Make a move
app.post('/api/games/tictactoe/move', (req, res) => {
  try {
    const cell = parseInt(req.body.cell, 10);
    if (isNaN(cell) || cell < 1 || cell > 9) {
      return res.status(400).json({ error: 'cell must be a number 1-9' });
    }

    const state = loadUiState();
    const game = state['tictactoe-game'];
    if (!game) {
      return res.status(400).json({ error: 'No active TicTacToe game. Use start first.' });
    }
    if (game.status !== 'playing') {
      return res.status(400).json({ error: `Game is over: ${game.status}${game.winner ? ' — ' + game.winner + ' wins' : ''}` });
    }

    const idx = cell - 1;
    if (game.board[idx] !== null) {
      return res.status(400).json({ error: `Cell ${cell} is already taken by ${game.board[idx]}` });
    }

    // Place the piece
    const currentPiece = game.turn;
    game.board[idx] = currentPiece;

    // Update whiteboard: remove number marker, add piece
    const wb = loadWhiteboard();
    if (wb.elements.length) {
      // Remove number marker
      const markerIdx = wb.elements.findIndex(e => e.id === `ttt-cell-${cell}`);
      let removedMarker = null;
      if (markerIdx !== -1) {
        removedMarker = wb.elements.splice(markerIdx, 1)[0];
      }

      // Add piece at correct position
      const assetName = currentPiece === 'X' ? 'Cross' : 'Circle';
      const dataUrl = tttLoadAsset(assetName);
      const pos = tttCellPosition(cell, game.boardX, game.boardY, TTT_PIECE_SIZE, TTT_PIECE_OFFSET);
      const pieceEl = {
        id: `ttt-piece-${cell}`,
        type: 'image',
        x: pos.x,
        y: pos.y,
        width: TTT_PIECE_SIZE,
        height: TTT_PIECE_SIZE,
        dataUrl,
        zIndex: wb.nextZIndex++,
      };
      wb.elements.push(pieceEl);

      // Broadcast whiteboard changes
      if (removedMarker) broadcastToWhiteboard({ type: 'remove', id: `ttt-cell-${cell}` });
      broadcastToWhiteboard({ type: 'add', elements: [pieceEl] });
      saveWhiteboard(wb);
    }

    // Check for win/draw
    const result = tttCheckResult(game.board);
    if (result === 'draw') {
      game.status = 'draw';
    } else if (result) {
      game.status = 'won';
      game.winner = result;
    } else {
      // Toggle turn
      game.turn = game.turn === 'X' ? 'O' : 'X';
    }

    state['tictactoe-game'] = game;
    saveUiState(state);

    const response = {
      ok: true,
      board: game.board,
      ascii: tttBoardAscii(game.board),
      turn: game.turn,
      status: game.status,
    };
    if (game.winner) response.winner = game.winner;

    res.json(response);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/games/tictactoe/state — Get current game state
app.get('/api/games/tictactoe/state', (req, res) => {
  try {
    const state = loadUiState();
    const game = state['tictactoe-game'];
    if (!game) {
      return res.json({ ok: true, active: false, message: 'No active game' });
    }

    const response = {
      ok: true,
      active: true,
      board: game.board,
      ascii: tttBoardAscii(game.board),
      turn: game.turn,
      status: game.status,
      piece: game.piece,
    };
    if (game.winner) response.winner = game.winner;

    res.json(response);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/games/tictactoe/end — Tear down game
app.post('/api/games/tictactoe/end', (req, res) => {
  try {
    const state = loadUiState();
    delete state['tictactoe-game'];
    saveUiState(state);
    saveWhiteboard({ elements: [], nextZIndex: 1 });

    broadcastToWhiteboard({ type: 'clear' });
    broadcastToWhiteboard({ type: 'ttt-ended' });

    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


