// LOOP TEMPLATES
// ═══════════════════════════════════════════

const LOOP_DATA_DIR = resolve(DATA_HOME, 'data');
const LOOP_TEMPLATES_FILE = 'loop-templates.json';
const LOOP_SCHEDULES_FILE = 'loop-schedules.json';
const LOOP_TEMPLATES_PATH = resolve(LOOP_DATA_DIR, LOOP_TEMPLATES_FILE);
const LOOP_SCHEDULES_PATH = resolve(LOOP_DATA_DIR, LOOP_SCHEDULES_FILE);
const LOOP_FOLDERS_PATH = resolve(LOOP_DATA_DIR, 'loop-folders.json');
const LOOP_DIR = resolve(LOOP_DATA_DIR, 'loop');
const LOOP_TEMPLATES_PATTERN = /^loop-templates.*\.json$/;
const LOOP_SCHEDULES_PATTERN = /^loop-schedules.*\.json$/;

function unknownAutomationContextMode(mode) {
  return mode != null && mode !== '' && !['default', 'extended', '1m'].includes(mode);
}

// The model list of the account that lives in `codexHome` (Default when none does): the one the
// Codex panel's selector reads, from the same cache as GET /api/codex/models.
async function codexAutomationModels(codexHome) {
  const home = codexHome || CODEX_DEFAULT_HOME;
  let accountId = 'default';
  try {
    const owner = _codexAccounts().list().find((row) => row?.home && samePath(row.home, home));
    if (owner?.id) accountId = owner.id;
  } catch { /* the default account */ }
  const models = await _codexModelListCache.get(codexModelListKey(accountId));
  return Array.isArray(models) ? models : [];
}

async function resolveAutomationLaunchChoice(profile, model, contextMode, codexHome) {
  const selection = normalizeAutomationSelection(profile, model, contextMode);
  const mode = selection.contextMode || 'default';
  if (profile === 'codex' && /[:\[\]]/.test(selection.model || '')) {
    throw new Error(`Invalid Codex model ID: ${selection.model}. Choose a model from this account's list.`);
  }
  if (profile === 'claude-code' && /\[(?:extended|1m)\]$/i.test(selection.model || '')) {
    throw new Error(`Invalid Claude model ID: ${selection.model}. Choose Context separately.`);
  }
  if (!validAutomationContextMode(profile, mode)) {
    throw new Error(`Context ${mode} is unavailable for ${profile}.`);
  }
  if (mode !== 'default' && !selection.model) {
    throw new Error(`Choose a model before selecting ${mode} context.`);
  }
  if (profile === 'codex' && mode === 'extended') {
    let models;
    try { models = await codexAutomationModels(codexHome); }
    catch (error) { throw new Error(`Could not verify Codex extended context: ${error.message}`); }
    const result = resolveCodexExtendedContext({ models, selectedModel: selection.model, contextMode: 'extended' });
    if (!result.applied) {
      throw new Error(`Extended context is unavailable for ${selection.model} on this Codex account (${result.reason}).`);
    }
    return { ...selection, contextMode: mode, modelContextWindow: result.requestedContextWindow };
  }
  if (profile === 'claude-code' && mode === '1m') {
    const { source, models } = await getClaudeModelsForClient();
    const variant = `${selection.model}[1m]`;
    const base = models.find((entry) => entry?.id === selection.model);
    if (source === 'fallback' || !(models.some((entry) => entry?.id === variant) || claudeAutomationSupportsOneMillion(base))) {
      throw new Error(`1M context is unavailable for ${selection.model} in the installed Claude CLI.`);
    }
  }
  return { ...selection, contextMode: mode, modelContextWindow: null };
}

function isLoopRuntimeAlive(loopState) {
  if (!loopState) return false;
  const runId = loopState.runId || loopState.terminalSessionId;
  if (loopState.runtimeType === 'native' || loopState.driverType === 'native' || loopState.surface === 'sidepanel') {
    // A dispatched worker a restart cut off waits (suspended) for its resume: its state file is what it resumes from.
    return !!runId && (!!_nativeLoopRuntime?.isAlive(runId) || !!_nativeLoopRuntime?.isSuspended?.(runId));
  }
  return !!loopState.terminalSessionId && terminalSessions.has(loopState.terminalSessionId);
}

function isLoopObject(value) {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function sortLoopDataFiles(mainFile) {
  return (a, b) => {
    if (a === mainFile) return -1;
    if (b === mainFile) return 1;
    return a.localeCompare(b);
  };
}

function listLoopDataPaths(pattern, mainFile, mainPath) {
  try {
    if (!existsSync(LOOP_DATA_DIR)) return existsSync(mainPath) ? [mainPath] : [];
    return readdirSync(LOOP_DATA_DIR)
      .filter(file => pattern.test(file))
      .sort(sortLoopDataFiles(mainFile))
      .map(file => resolve(LOOP_DATA_DIR, file));
  } catch {
    return existsSync(mainPath) ? [mainPath] : [];
  }
}

function normalizeLoopStorageKey(value) {
  return String(value || '').trim().toLowerCase();
}

function slugLoopStorageName(value) {
  return normalizeLoopStorageKey(value)
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

function preferLoopStoragePath(currentPath, nextPath, mainPath) {
  if (!currentPath) return nextPath;
  if (currentPath === mainPath && nextPath !== mainPath) return nextPath;
  return currentPath;
}

function mergeLoopItemsById(files, key) {
  const byId = new Map();
  const withoutId = [];
  for (const file of files) {
    for (const item of file[key]) {
      if (item.id) byId.set(String(item.id), item);
      else withoutId.push(item);
    }
  }
  return [...byId.values(), ...withoutId];
}

function readLoopTemplateFiles() {
  return listLoopDataPaths(LOOP_TEMPLATES_PATTERN, LOOP_TEMPLATES_FILE, LOOP_TEMPLATES_PATH).map(path => {
    try {
      const data = JSON.parse(readFileSync(path, 'utf-8'));
      if (Array.isArray(data)) return { path, templates: data.filter(isLoopObject), format: 'array' };
      if (isLoopObject(data) && Array.isArray(data.templates)) {
        return { path, templates: data.templates.filter(isLoopObject), format: 'object' };
      }
    } catch { /* corrupt file */ }
    return { path, templates: [], format: 'array' };
  });
}

function readLoopTemplates() {
  return mergeLoopItemsById(readLoopTemplateFiles(), 'templates').map((template) => {
    normalizeAutomationRecord(template);
    return readStoredToolListRecord(template, toolListOptions());
  });
}

function templateStoragePathForName(name) {
  const slug = slugLoopStorageName(name);
  return slug ? resolve(LOOP_DATA_DIR, `loop-templates-${slug}.json`) : LOOP_TEMPLATES_PATH;
}

function resolveTemplateStoragePath(template, routing, foldersById) {
  const id = template?.id ? String(template.id) : '';
  if (id && routing.byId.has(id)) return routing.byId.get(id);

  const folderId = template?.folderId ? String(template.folderId) : '';
  if (folderId) {
    if (routing.byFolderId.has(folderId)) return routing.byFolderId.get(folderId);
    const folder = foldersById.get(folderId);
    if (folder?.name) return templateStoragePathForName(folder.name);
  }

  const categoryKey = normalizeLoopStorageKey(template?.category);
  if (categoryKey && categoryKey !== 'custom') {
    if (routing.byCategory.has(categoryKey)) return routing.byCategory.get(categoryKey);
    if (routing.ambiguousCategories.has(categoryKey)) return LOOP_TEMPLATES_PATH;
    return templateStoragePathForName(template.category);
  }

  return LOOP_TEMPLATES_PATH;
}

function buildTemplateRouting(files) {
  const byId = new Map();
  const byFolderId = new Map();
  const byCategory = new Map();
  const categorySources = new Map();
  for (const file of files) {
    for (const template of file.templates) {
      if (template.id) {
        const id = String(template.id);
        byId.set(id, preferLoopStoragePath(byId.get(id), file.path, LOOP_TEMPLATES_PATH));
      }
      if (template.folderId) {
        const folderId = String(template.folderId);
        byFolderId.set(folderId, preferLoopStoragePath(byFolderId.get(folderId), file.path, LOOP_TEMPLATES_PATH));
      }
      const categoryKey = normalizeLoopStorageKey(template.category);
      if (categoryKey && categoryKey !== 'custom') {
        if (!categorySources.has(categoryKey)) categorySources.set(categoryKey, new Set());
        categorySources.get(categoryKey).add(file.path);
      }
    }
  }
  for (const [category, sources] of categorySources) {
    if (sources.size === 1) byCategory.set(category, [...sources][0]);
  }
  return { byId, byFolderId, byCategory, ambiguousCategories: new Set([...categorySources].filter(([, sources]) => sources.size > 1).map(([category]) => category)) };
}

function writeLoopTemplateFile(path, templates, format = 'array') {
  templates = templates.map(record => record.externalMcpVersion === 2 ? toolListRecord(record, toolListOptions()) : readStoredToolListRecord(record, toolListOptions()));
  mkdirSync(dirname(path), { recursive: true });
  const data = format === 'object' ? { templates } : templates;
  writeFileSync(path, JSON.stringify(data, null, 2));
}

function writeLoopTemplates(templates) {
  const files = readLoopTemplateFiles();
  const routing = buildTemplateRouting(files);
  const formatByPath = new Map(files.map(file => [file.path, file.format]));
  const byPath = new Map(files.map(file => [file.path, []]));
  if (!byPath.has(LOOP_TEMPLATES_PATH)) byPath.set(LOOP_TEMPLATES_PATH, []);

  const foldersById = new Map(readLoopFolders().map(folder => [String(folder.id), folder]));
  for (const template of Array.isArray(templates) ? templates : []) {
    if (!isLoopObject(template)) continue;
    const targetPath = resolveTemplateStoragePath(template, routing, foldersById);
    if (!byPath.has(targetPath)) byPath.set(targetPath, []);
    byPath.get(targetPath).push(template);
  }

  for (const [path, fileTemplates] of byPath) {
    writeLoopTemplateFile(path, fileTemplates, formatByPath.get(path) || 'array');
  }
}

function readLoopFolders() {
  try {
    if (existsSync(LOOP_FOLDERS_PATH)) {
      const data = JSON.parse(readFileSync(LOOP_FOLDERS_PATH, 'utf-8'));
      if (Array.isArray(data)) return data;
    }
  } catch { /* corrupt file */ }
  return [];
}

function writeLoopFolders(folders) {
  writeFileSync(LOOP_FOLDERS_PATH, JSON.stringify(folders, null, 2));
}

// GET /api/loop/templates — list all saved templates
app.get('/api/loop/templates', (req, res) => {
  res.json(readLoopTemplates());
});

// POST /api/loop/templates — create a template
app.post('/api/loop/templates', (req, res) => {
  const { name, description, task, context, iterations, maxMinutes, icon, category, usesBrowser, profile, model, contextMode, effort, tools, platform, folderId, codexAccountId } = req.body;
  if (!name?.trim() || !task?.trim()) {
    return res.status(400).json({ error: 'name and task are required' });
  }
  const selection = normalizeAutomationSelection(profile || 'claude-code', model, contextMode);
  if (!validAutomationContextMode(profile || 'claude-code', selection.contextMode)) {
    return res.status(400).json({ error: `Invalid context mode: ${selection.contextMode}` });
  }
  let toolFields;
  try { toolFields = toolListRecord({ tools, platform }, toolListOptions()); }
  catch (error) { return res.status(400).json({ error: error.message, code: error.code, problems: error.problems }); }
  const templates = readLoopTemplates();
  const id = randomBytes(12).toString('hex');
  const template = {
    id,
    name: name.trim(),
    description: (description || '').trim(),
    task: task.trim(),
    context: (context || '').trim() || null,
    iterations: Math.min(Math.max(iterations || 10, 1), 200),
    maxMinutes: Math.min(Math.max(maxMinutes || 30, 1), 480),
    usesBrowser: usesBrowser || false,
    icon: icon || '\u{1F504}',
    category: category || 'custom',
    profile: profile || null,
    model: selection.model,
    contextMode: selection.contextMode || null,
    effort: effort || null,
    ...toolFields,
    codexAccountId: codexAccountId || null,
    folderId: folderId || null,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  templates.push(template);
  writeLoopTemplates(templates);
  res.json(toolListRecord(template, toolListOptions()));
});

// GET /api/loop/templates/export — export all templates as JSON (must be before /:id)
app.get('/api/loop/templates/export', (req, res) => {
  const templates = readLoopTemplates();
  const folders = readLoopFolders();
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Disposition', 'attachment; filename="synabun-loop-templates.json"');
  res.json({
    version: 2,
    type: 'synabun-loop-templates',
    exportedAt: new Date().toISOString(),
    templates,
    folders,
  });
});

// POST /api/loop/templates/import — import templates from JSON
app.post('/api/loop/templates/import', (req, res) => {
  const { templates: incoming, template: single, folders: incomingFolders } = req.body;
  const toImport = incoming || (single ? [single] : null);
  if (!toImport || !Array.isArray(toImport)) {
    return res.status(400).json({ error: 'Invalid import format: expected templates array or template object' });
  }
  for (const item of toImport) {
    const selection = normalizeAutomationSelection(item?.profile || 'claude-code', item?.model, item?.contextMode);
    if (!validAutomationContextMode(item?.profile || 'claude-code', selection.contextMode)) {
      return res.status(400).json({ error: `Invalid context mode: ${selection.contextMode}` });
    }
  }

  // Merge incoming folders first (match by name) so we can remap template folderIds.
  const folderIdMap = new Map();
  let foldersAdded = 0;
  if (Array.isArray(incomingFolders) && incomingFolders.length > 0) {
    const existingFolders = readLoopFolders();
    for (const f of incomingFolders) {
      if (!f?.name?.trim()) continue;
      const match = existingFolders.find(e => e.name.trim().toLowerCase() === f.name.trim().toLowerCase());
      if (match) {
        if (f.id) folderIdMap.set(f.id, match.id);
      } else {
        const newId = f.id && !existingFolders.some(e => e.id === f.id)
          ? f.id
          : `f_${randomBytes(6).toString('hex')}`;
        if (f.id && f.id !== newId) folderIdMap.set(f.id, newId);
        else if (f.id) folderIdMap.set(f.id, newId);
        existingFolders.push({
          id: newId,
          name: f.name.trim(),
          icon: f.icon || null,
          color: f.color || null,
          order: typeof f.order === 'number' ? f.order : existingFolders.length,
          collapsed: !!f.collapsed,
          createdAt: f.createdAt || new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        });
        foldersAdded++;
      }
    }
    writeLoopFolders(existingFolders);
  }

  const existing = readLoopTemplates();
  let added = 0;
  let updated = 0;
  for (const t of toImport) {
    if (!t.name?.trim() || !t.task?.trim()) continue;
    const selection = normalizeAutomationSelection(t.profile || 'claude-code', t.model, t.contextMode);
    const existingIdx = existing.findIndex(e => e.name === t.name);
    const template = {
      id: t.id || randomBytes(12).toString('hex'),
      name: t.name.trim(),
      description: (t.description || '').trim(),
      task: t.task.trim(),
      context: (t.context || '').trim() || null,
      iterations: Math.min(Math.max(t.iterations || 10, 1), 200),
      maxMinutes: Math.min(Math.max(t.maxMinutes || 30, 1), 480),
      usesBrowser: t.usesBrowser || false,
      icon: t.icon || '\u{1F504}',
      category: t.category || 'custom',
      profile: t.profile || null,
      model: selection.model,
      contextMode: selection.contextMode || null,
      effort: t.effort || null,
      tools: storedToolList(t, toolListOptions()),
      platform: automationPlatform(t),
      folderId: folderIdMap.get(t.folderId) || t.folderId || null,
      createdAt: t.createdAt || new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    if (existingIdx >= 0) {
      template.id = existing[existingIdx].id; // keep original id
      existing[existingIdx] = template;
      updated++;
    } else {
      existing.push(template);
      added++;
    }
  }
  writeLoopTemplates(existing);
  res.json({ ok: true, added, updated, total: existing.length, foldersAdded });
});

// PUT /api/loop/templates/:id — update a template
app.put('/api/loop/templates/:id', (req, res) => {
  const templates = readLoopTemplates();
  const idx = templates.findIndex(t => t.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Template not found' });
  const { name, description, task, context, iterations, maxMinutes, icon, category, usesBrowser, profile, model, contextMode, effort, tools, platform, folderId, codexAccountId } = req.body;
  const effectiveProfile = profile !== undefined ? (profile || 'claude-code') : (templates[idx].profile || 'claude-code');
  const selection = normalizeAutomationSelection(effectiveProfile, model !== undefined ? model : templates[idx].model, contextMode !== undefined ? contextMode : templates[idx].contextMode);
  if (!validAutomationContextMode(effectiveProfile, selection.contextMode)) {
    return res.status(400).json({ error: `Invalid context mode: ${selection.contextMode}` });
  }
  if (name !== undefined) templates[idx].name = name.trim();
  if (description !== undefined) templates[idx].description = description.trim();
  if (task !== undefined) templates[idx].task = task.trim();
  if (context !== undefined) templates[idx].context = context.trim() || null;
  if (iterations !== undefined) templates[idx].iterations = Math.min(Math.max(iterations, 1), 200);
  if (maxMinutes !== undefined) templates[idx].maxMinutes = Math.min(Math.max(maxMinutes, 1), 480);
  if (icon !== undefined) templates[idx].icon = icon;
  if (category !== undefined) templates[idx].category = category;
  if (usesBrowser !== undefined) templates[idx].usesBrowser = !!usesBrowser;
  if (profile !== undefined) templates[idx].profile = profile || null;
  if (model !== undefined) templates[idx].model = selection.model;
  if (contextMode !== undefined || model !== undefined) templates[idx].contextMode = selection.contextMode;
  if (effort !== undefined) templates[idx].effort = effort || null;
  try { applyStoredToolList(templates[idx], { tools, platform }, toolListOptions()); }
  catch (error) { return res.status(400).json({ error: error.message, code: error.code, problems: error.problems }); }
  if (codexAccountId !== undefined) templates[idx].codexAccountId = codexAccountId || null;
  if (platform !== undefined) templates[idx].platform = platform || null;
  if (folderId !== undefined) templates[idx].folderId = folderId || null;
  templates[idx].updatedAt = new Date().toISOString();
  writeLoopTemplates(templates);
  res.json(toolListRecord(templates[idx], toolListOptions()));
});

// DELETE /api/loop/templates/:id — delete a template
app.delete('/api/loop/templates/:id', (req, res) => {
  const templates = readLoopTemplates();
  const idx = templates.findIndex(t => t.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Template not found' });
  templates.splice(idx, 1);
  writeLoopTemplates(templates);
  res.json({ ok: true });
});

// ─── LOOP FOLDERS ──────────────────────────────
// User-created folders for organizing custom automation templates in the sidebar.
// Folders apply to custom templates only; presets are grouped by their hard-coded category.

// GET /api/loop/folders — list all folders (sorted by order)
app.get('/api/loop/folders', (req, res) => {
  const folders = readLoopFolders();
  folders.sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  res.json(folders);
});

// POST /api/loop/folders — create a folder
app.post('/api/loop/folders', (req, res) => {
  const { name, icon, color } = req.body || {};
  if (!name || !name.trim()) {
    return res.status(400).json({ error: 'name is required' });
  }
  const folders = readLoopFolders();
  const folder = {
    id: `f_${randomBytes(6).toString('hex')}`,
    name: name.trim(),
    icon: icon || null,
    color: color || null,
    order: folders.length,
    collapsed: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  folders.push(folder);
  writeLoopFolders(folders);
  res.json(folder);
});

// PUT /api/loop/folders/:id — rename, recolor, change icon, toggle collapsed, or reorder
app.put('/api/loop/folders/:id', (req, res) => {
  const folders = readLoopFolders();
  const idx = folders.findIndex(f => f.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Folder not found' });
  const { name, icon, color, collapsed, order } = req.body || {};
  if (name !== undefined && name.trim()) folders[idx].name = name.trim();
  if (icon !== undefined) folders[idx].icon = icon || null;
  if (color !== undefined) folders[idx].color = color || null;
  if (collapsed !== undefined) folders[idx].collapsed = !!collapsed;
  if (order !== undefined && typeof order === 'number') folders[idx].order = order;
  folders[idx].updatedAt = new Date().toISOString();
  writeLoopFolders(folders);
  res.json(folders[idx]);
});

// DELETE /api/loop/folders/:id — delete folder; unassigns templates (does NOT delete them)
app.delete('/api/loop/folders/:id', (req, res) => {
  const folders = readLoopFolders();
  const idx = folders.findIndex(f => f.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Folder not found' });
  folders.splice(idx, 1);
  writeLoopFolders(folders);

  const templates = readLoopTemplates();
  let moved = 0;
  for (const t of templates) {
    if (t.folderId === req.params.id) {
      t.folderId = null;
      t.updatedAt = new Date().toISOString();
      moved++;
    }
  }
  if (moved > 0) writeLoopTemplates(templates);
  res.json({ ok: true, templatesUnassigned: moved });
});

// POST /api/loop/folders/reorder — batch reorder { orderedIds: [...] }
app.post('/api/loop/folders/reorder', (req, res) => {
  const { orderedIds } = req.body || {};
  if (!Array.isArray(orderedIds)) {
    return res.status(400).json({ error: 'orderedIds array required' });
  }
  const folders = readLoopFolders();
  const byId = new Map(folders.map(f => [f.id, f]));
  let n = 0;
  for (const id of orderedIds) {
    const f = byId.get(id);
    if (f) { f.order = n++; f.updatedAt = new Date().toISOString(); }
  }
  // Append any folders not in the orderedIds list (preserves safety on partial updates)
  for (const f of folders) {
    if (!orderedIds.includes(f.id)) { f.order = n++; }
  }
  writeLoopFolders(folders);
  res.json({ ok: true });
});

// GET /api/loop/active — scan for active loop status
app.get('/api/loop/active', (req, res) => {
  try {
    if (!existsSync(LOOP_DIR)) return res.json({ active: false, loops: [] });
    const files = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json'));
    const activeLoops = [];
    for (const f of files) {
      try {
        const filePath = resolve(LOOP_DIR, f);
        const data = JSON.parse(readFileSync(filePath, 'utf-8'));
        if (data?.active) {
          const elapsed = Date.now() - new Date(data.startedAt).getTime();
          const maxMs = ((data.maxMinutes || 30) + 5) * 60 * 1000;
          // Stale loop — past time cap + grace, delete it. Not a dispatched worker's (runMode
          // 'task'): its maxMinutes is work time, which the dispatcher enforces, and a warm run
          // idles for a follow-up far past it; a dead one goes with the check below.
          if (data.runMode !== 'task' && elapsed >= maxMs) {
            try { unlinkSync(filePath); } catch { /* ok */ }
            continue;
          }
          // Dead provider runtime (abrupt close) — delete after 2min grace.
          if (data.terminalSessionId && !isLoopRuntimeAlive(data)) {
            const lastActivity = new Date(data.lastIterationAt || data.startedAt || 0).getTime();
            if (Date.now() - lastActivity > 2 * 60 * 1000) {
              try { unlinkSync(filePath); } catch { /* ok */ }
              continue;
            }
          }
          // A dispatched worker's time left is its work time left (the dispatcher's work clock); null
          // while the dispatcher does not know the run (right after a restart): never the wall clock.
          const isTaskRun = data.runMode === 'task';
          const work = isTaskRun && data.runId ? (_assistantDispatcher?.peek?.(data.runId) || null) : null;
          activeLoops.push({
            sessionId: f.replace('.json', ''),
            task: data.task,
            context: data.context,
            currentIteration: data.currentIteration || 0,
            totalIterations: data.totalIterations || 10,
            maxMinutes: data.maxMinutes || 30,
            elapsedMinutes: Math.round(elapsed / 60000),
            remainingMinutes: work && Number.isFinite(work.workLeftMs)
              ? Math.round(work.workLeftMs / 60000)
              : isTaskRun ? null : Math.max(0, Math.round(((data.maxMinutes || 30) * 60 * 1000 - elapsed) / 60000)),
            startedAt: data.startedAt,
            lastIterationAt: data.lastIterationAt,
            browserSessionId: data.browserSessionId || null,
            browserTabId: data.browserTabId || null,
            terminalSessionId: data.terminalSessionId || null,
            runId: data.runId || null,
            profile: data.profile || null,
            model: data.model || null,
            effort: data.effort || null,
            runtimeType: data.runtimeType || 'pty',
            surface: data.surface || 'terminal',
            providerSessionId: data.runId ? (_nativeLoopRuntime?.get(data.runId)?.providerSessionId || null) : null,
            providerThreadId: data.runId ? (_nativeLoopRuntime?.get(data.runId)?.providerThreadId || null) : null,
          });
        } else {
          // Inactive loop file — delete it (no history keeping)
          try { unlinkSync(filePath); } catch { /* ok */ }
        }
      } catch { /* skip corrupt */ }
    }
    // Backward compat: first active loop populates top-level fields
    if (activeLoops.length > 0) {
      const first = activeLoops[0];
      return res.json({ active: true, ...first, loops: activeLoops });
    }
    return res.json({ active: false, loops: [] });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// GET /api/loop/list — full loop inventory for the Session Monitor.
// Unlike /api/loop/active, this returns ALL loop files (active + inactive)
// classified by state so the UI can show stale/finished/orphaned entries
// alongside running ones. Does NOT delete anything (read-only).
app.get('/api/loop/list', (_req, res) => {
  try {
    if (!existsSync(LOOP_DIR)) return res.json({ loops: [], staleCount: 0 });
    const files = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json') && f !== '.gitkeep' && !f.startsWith('pending-') && f !== 'active-pointer.json');
    const now = Date.now();
    const loops = [];
    let staleCount = 0;
    for (const f of files) {
      try {
        const filePath = resolve(LOOP_DIR, f);
        const data = JSON.parse(readFileSync(filePath, 'utf-8'));
        const startedAtMs = data.startedAt ? new Date(data.startedAt).getTime() : 0;
        const lastIterAtMs = data.lastIterationAt ? new Date(data.lastIterationAt).getTime() : startedAtMs;
        const elapsedMs = startedAtMs ? now - startedAtMs : 0;
        const stalledMs = lastIterAtMs ? now - lastIterAtMs : 0;
        const terminalAlive = isLoopRuntimeAlive(data);
        const iterDone = (data.currentIteration || 0) >= (data.totalIterations || 0) && (data.totalIterations || 0) > 0;
        let state;
        if (data.active === false) {
          state = 'stale-inactive';
          staleCount++;
        } else if (data.terminalSessionId && !terminalAlive) {
          state = data.runtimeType === 'native' ? 'orphaned-native' : 'orphaned-pty';
        } else if (iterDone) {
          state = 'finished';
        } else {
          state = 'active';
        }
        loops.push({
          sessionId: f.replace('.json', ''),
          terminalSessionId: data.terminalSessionId || null,
          terminalAlive,
          runId: data.runId || null,
          profile: data.profile || null,
          runtimeType: data.runtimeType || 'pty',
          surface: data.surface || 'terminal',
          task: typeof data.task === 'string' ? data.task.slice(0, 200) : '',
          currentIteration: data.currentIteration || 0,
          totalIterations: data.totalIterations || 0,
          startedAt: data.startedAt || null,
          lastIterationAt: data.lastIterationAt || null,
          elapsedMinutes: Math.round(elapsedMs / 60000),
          stalledMinutes: Math.round(stalledMs / 60000),
          stalledMs,
          state,
          browserSessionId: data.browserSessionId || null,
          browserTabId: data.browserTabId || null,
          usesBrowser: !!data.usesBrowser,
        });
      } catch { /* skip corrupt */ }
    }
    // Newest first
    loops.sort((a, b) => (b.startedAt || '').localeCompare(a.startedAt || ''));
    res.json({ loops, staleCount });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// POST /api/loop/cleanup — delete stale loop files (active === false only).
// No PTY/browser side-effects since these are leftover files for already-ended
// loops. For force-stopping running loops, use POST /api/loop/stop instead.
app.post('/api/loop/cleanup', (_req, res) => {
  try {
    if (!existsSync(LOOP_DIR)) return res.json({ ok: true, cleaned: 0, remaining: 0 });
    const files = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json') && f !== '.gitkeep' && !f.startsWith('pending-') && f !== 'active-pointer.json');
    let cleaned = 0;
    let remaining = 0;
    for (const f of files) {
      const filePath = resolve(LOOP_DIR, f);
      try {
        const data = JSON.parse(readFileSync(filePath, 'utf-8'));
        if (data.active === false) {
          try { unlinkSync(filePath); cleaned++; } catch { /* ok */ }
        } else {
          remaining++;
        }
      } catch {
        // Corrupt — also count as stale and delete
        try { unlinkSync(filePath); cleaned++; } catch { /* ok */ }
      }
    }
    res.json({ ok: true, cleaned, remaining });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// GET /api/loop/log/:terminalSessionId — fetch raw per-loop logfile (text)
app.get('/api/loop/log/:terminalSessionId', (req, res) => {
  try {
    const tsid = req.params.terminalSessionId;
    if (!tsid || !/^[a-f0-9]{32}$/i.test(tsid)) {
      return res.status(400).json({ error: 'invalid terminalSessionId' });
    }
    const p = loopLogPath(tsid);
    if (!p || !existsSync(p)) {
      return res.status(404).type('text/plain').send(`No log file for ${tsid} (yet?)`);
    }
    res.type('text/plain').send(readFileSync(p, 'utf-8'));
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// POST /api/loop/client-log — accept browser-side logs, append to per-loop file
app.post('/api/loop/client-log', (req, res) => {
  try {
    const { terminalSessionId, tag, msg, meta } = req.body || {};
    if (!tag || !msg) return res.status(400).json({ error: 'tag and msg required' });
    loopLog(terminalSessionId || null, `ui:${tag}`, msg, meta || undefined);
    res.json({ ok: true });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

const _releasedSidepanelClaimTokens = new Map();
const SIDEPANEL_CLAIM_TOKEN_TTL_MS = 10 * 60 * 1000;

function sidepanelClaimKey(windowId, claimToken) {
  const window = String(windowId || '').trim().slice(0, 128);
  const token = String(claimToken || '').trim().slice(0, 128);
  return window && token ? `${window}:${token}` : '';
}

function revokeSidepanelClaimToken(windowId, claimToken) {
  const key = sidepanelClaimKey(windowId, claimToken);
  if (!key) return;
  const now = Date.now();
  _releasedSidepanelClaimTokens.set(key, now);
  if (_releasedSidepanelClaimTokens.size <= 2000) return;
  for (const [entry, releasedAt] of _releasedSidepanelClaimTokens) {
    if (now - releasedAt > SIDEPANEL_CLAIM_TOKEN_TTL_MS || _releasedSidepanelClaimTokens.size > 2000) {
      _releasedSidepanelClaimTokens.delete(entry);
    }
  }
}

function isSidepanelClaimTokenRevoked(windowId, claimToken) {
  const key = sidepanelClaimKey(windowId, claimToken);
  if (!key) return false;
  const releasedAt = _releasedSidepanelClaimTokens.get(key);
  if (!releasedAt) return false;
  if (Date.now() - releasedAt <= SIDEPANEL_CLAIM_TOKEN_TTL_MS) return true;
  _releasedSidepanelClaimTokens.delete(key);
  return false;
}

// Native provider run ledger. A sidepanel can attach after a page refresh or
// after a schedule started while no Neural Interface window was open.
app.get('/api/sidepanel-runs', (req, res) => {
  const activeOnly = req.query.active === '1' || req.query.active === 'true';
  res.json({ ok: true, runs: _nativeLoopRuntime?.list({ activeOnly }) || [] });
});

app.post('/api/sidepanel-runs/release-window', (req, res) => {
  revokeSidepanelClaimToken(req.body?.windowId, req.body?.claimToken);
  const released = _nativeLoopRuntime?.releaseClaimsByWindow(req.body?.windowId) || 0;
  res.json({ ok: true, released });
});

app.get('/api/sidepanel-runs/:runId', (req, res) => {
  const run = _nativeLoopRuntime?.get(req.params.runId);
  if (!run) return res.status(404).json({ error: 'Native sidepanel run not found' });
  res.json({ ok: true, run });
});

app.post('/api/sidepanel-runs/:runId/claim', (req, res) => {
  if (isSidepanelClaimTokenRevoked(req.body?.windowId, req.body?.claimToken)) {
    return res.status(409).json({ ok: false, reason: 'window_released' });
  }
  const result = _nativeLoopRuntime?.claim(req.params.runId, req.body?.windowId);
  if (!result?.ok) return res.status(result?.reason === 'not_found' ? 404 : 409).json(result || { ok: false });
  res.json(result);
});

app.post('/api/sidepanel-runs/:runId/release', (req, res) => {
  const released = _nativeLoopRuntime?.releaseClaim(req.params.runId, req.body?.windowId) || false;
  res.json({ ok: true, released });
});

// POST /api/loop/launch — create loop state + provider runtime atomically
app.post('/api/loop/launch', async (req, res) => {
  let pendingNativeBrowserCleanup = null;
  try {
    const { task: rawTask, context, iterations, maxMinutes, usesBrowser, cwd, profile, model: requestedModel, contextMode: requestedContextMode, effort, tools, platform, codexAccountId, browserSessionId: requestedBrowserSessionId, sidepanelWindowId, sidepanelClaimToken } = req.body;
    if (!rawTask?.trim()) return res.status(400).json({ error: 'task is required' });
    // Resolve Facebook deal-link tokens against current fresh-release deals before the task is
    // stored, so the post links a real game page (/games/<slug>) — never the /deals listing.
    const { task, resolved: dealResolved, link: dealLink } = await resolveDealLink(rawTask);
    if (dealResolved) loopLog(null, 'launch:deal-link', 'resolved deal link (manual launch)', { dealLink });

    // Validate profile if provided
    const cliProfile = profile || 'claude-code';
    const nativeRuntime = isNativeLoopProfile(cliProfile);
    const cliTools = launchToolList({ tools }, { usesBrowser, provider: cliProfile }).items;
    const validProfiles = Object.keys(loadCliConfig());
    if (!validProfiles.includes(cliProfile) && cliProfile !== 'shell') {
      return res.status(400).json({ error: `Invalid profile: ${cliProfile}. Valid: ${validProfiles.join(', ')}` });
    }
    // An OpenCode SynaBun does not drive (OpenCode 0 / 1, an OpenCode 2 older than the minimum, OpenCode 3) starts
    // nothing, on the native runtime or a terminal's: no browser tab, loop file, configuration or process. The answer
    // is the sentence that says what was found and how to get OpenCode 2.
    if (cliProfile === 'opencode') {
      const refusal = await opencodeStartRefusal();
      if (refusal) return res.status(400).json({ error: refusal.message, code: refusal.code });
    }
    const codexAccount = cliProfile === 'codex'
      ? (codexAccountId ? findCodexAccount(codexAccountId) : getCodexAccount(null))
      : null;
    if (cliProfile === 'codex' && !codexAccount) {
      return res.status(400).json({ error: `Codex account not found: ${codexAccountId || 'default'}` });
    }
    let launchChoice;
    try {
      launchChoice = await resolveAutomationLaunchChoice(
        cliProfile, requestedModel, requestedContextMode, codexAccount?.home || CODEX_DEFAULT_HOME,
      );
    } catch (error) { return res.status(400).json({ error: error.message }); }
    const model = launchChoice.model;
    const contextMode = launchChoice.contextMode;

    // Log incoming launch request (terminalSessionId not yet generated — log to console only,
    // file logging starts after we mint the id below)
    loopLog(null, 'launch:request', 'POST /api/loop/launch received', {
      profile: cliProfile,
      taskLen: task.trim().length,
      contextLen: context?.trim()?.length || 0,
      iterations: iterations || 10,
      maxMinutes: maxMinutes || 30,
      usesBrowser: !!usesBrowser,
      cwd: cwd || null,
      model: model || null,
      effort: effort || null,
      tools: cliTools, externalMcpVersion: 2,
      requestedBrowserSessionId: requestedBrowserSessionId || null,
    });

    // 1. Ensure loop directory exists
    if (!existsSync(LOOP_DIR)) mkdirSync(LOOP_DIR, { recursive: true });

    // 1b. Clean up stale/dead loop files — but allow multiple concurrent loops
    const existing = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json') && f !== '.gitkeep');
    for (const f of existing) {
      try {
        const data = JSON.parse(readFileSync(resolve(LOOP_DIR, f), 'utf-8'));
        if (!data.active && !data.pending) continue; // already finished
        // Only kill loops whose provider runtime is dead (stale cleanup)
        const termAlive = isLoopRuntimeAlive(data);
        if (!termAlive) {
          console.log(`[loop] Cleaning up stale loop file ${f} (runtime gone)`);
          try { unlinkSync(resolve(LOOP_DIR, f)); } catch { /* ok */ }
        }
        // Active loops with live terminals are left running — multi-loop coexistence
      } catch { /* skip corrupt */ }
    }

    // 1c. Acquire the shared browser session and create a fresh tab for this loop.
    // Automations share the same browser/profile, but each loop owns a distinct
    // tabId and all browser tools are pinned to that tab.
    let browserSessionId = null;
    let browserTabId = null;
    const terminalSessionId = randomBytes(16).toString('hex');
    loopLog(terminalSessionId, 'launch:id', 'minted terminalSessionId', { terminalSessionId });
    if (usesBrowser) {
      // Serialized reuse-or-create of the shared loop browser + a dedicated tab.
      // The mutex inside acquireLoopBrowserAndTab() prevents concurrent launches
      // from each spawning a separate "shared" browser (find-or-create race).
      const acq = await acquireLoopBrowserAndTab({ requestedBrowserSessionId, terminalSessionId });
      if (acq.error) {
        loopLog(terminalSessionId, 'launch:browser', 'ABORT: browser acquisition failed — returning 500', { error: acq.error });
        return res.status(500).json({ error: acq.error });
      }
      browserSessionId = acq.browserSessionId;
      browserTabId = acq.browserTabId;
      pendingNativeBrowserCleanup = { sessionId: browserSessionId, ownerKey: terminalSessionId };
    }

    // 2. Prepare loop state and write file BEFORE spawning PTY.
    // This prevents a race where Claude starts before the hook can find the pending file.
    const loopCwd = cwd || PACKAGE_ROOT;
    const pendingId = nativeRuntime ? terminalSessionId : 'pending-' + randomBytes(8).toString('hex');
    const loopState = {
      active: true,
      task: task.trim(),
      context: context?.trim() || null,
      totalIterations: Math.min(Math.max(iterations || 10, 1), 200),
      currentIteration: 0,
      maxMinutes: Math.min(Math.max(maxMinutes || 30, 1), 480),
      startedAt: new Date().toISOString(),
      lastIterationAt: null,
      retries: 0,
      pending: !nativeRuntime,
      terminalSessionId,
      usesBrowser: !!usesBrowser,
      browserSessionId,
      browserTabId: browserTabId || null,
      profile: cliProfile,
      model: model || null,
      contextMode,
      modelContextWindow: launchChoice.modelContextWindow,
      effort: effort || null,
      tools: cliTools, externalMcpVersion: 2,
      codexAccountId: codexAccount?.id || null,
      codexHome: codexAccount ? (codexAccount.home || CODEX_DEFAULT_HOME) : null,
      // A Codex exec loop keeps the Admin sandbox setting it started with (every iteration is its own `codex exec`).
      adminSandbox: cliProfile === 'codex' ? adminSandboxOn() : undefined,
      // Continuation mechanism. 'hook': Claude Code ONLY — the Stop/UserPromptSubmit hooks in
      // .claude/ set awaitingNext and attachLoopDriver() drives /clear + re-prompt; if those
      // hooks are absent (e.g. a claude-code task run under a hookless harness) the loop STALLS.
      // 'exec': harness-agnostic — attachExecLoopDriver() owns iteration via sentinel echoes, so
      // OpenCode/Codex/Gemini self-advance. Facebook seeding must stay profile:opencode for this.
      driverType: nativeRuntime ? 'native' : (cliProfile === 'claude-code' ? 'hook' : 'exec'),
      runtimeType: nativeRuntime ? 'native' : 'pty',
      surface: nativeRuntime ? 'sidepanel' : 'terminal',
      runId: nativeRuntime ? terminalSessionId : null,
      cwd: loopCwd,
    };
    writeFileSync(resolve(LOOP_DIR, `${pendingId}.json`), JSON.stringify(loopState, null, 2));
    loopLog(terminalSessionId, 'launch:state', 'wrote pending loop file', { pendingId, loopFile: `${pendingId}.json`, loopState });

    // 3. Create terminal PTY session + attach appropriate loop driver.
    // SYNABUN_TERMINAL_SESSION lets hooks correlate with the correct loop file
    // after /clear changes the Claude session ID. This is the key to multi-loop isolation.
    const loopExtraEnv = { SYNABUN_TERMINAL_SESSION: terminalSessionId };
    if (browserSessionId) loopExtraEnv.SYNABUN_BROWSER_SESSION = browserSessionId;
    if (browserTabId) loopExtraEnv.SYNABUN_BROWSER_TAB = browserTabId;
    // Codex reads auth.json from CODEX_HOME — pin the selected ChatGPT account.
    if (cliProfile === 'codex') {
      const codexHome = codexAccount.home || CODEX_DEFAULT_HOME;
      loopExtraEnv.CODEX_HOME = codexHome;
      loopLog(terminalSessionId, 'launch:codex-account', 'pinned CODEX_HOME for account', { codexAccountId: codexAccount.id, codexHome });
    }
    if (cliProfile === 'opencode') {
      loopExtraEnv.OPENCODE_EXPERIMENTAL_BASH_DEFAULT_TIMEOUT_MS =
        process.env.OPENCODE_EXPERIMENTAL_BASH_DEFAULT_TIMEOUT_MS || '300000';
    }
    // Claude Code uses ToolSearch for deferred loading — always give it the full profile
    loopExtraEnv.SYNABUN_TOOLS = runtimeToolsValue(cliTools);

    // Per-loop opencode config dir: OpenCode reads $XDG_CONFIG_HOME/opencode/opencode.json
    // at startup and uses the MCP environment block verbatim. Spawn each opencode loop
    // with its own XDG_CONFIG_HOME so the MCP
    // child inherits this loop's browser pins AND the permission bypass block.
    // Written for ALL opencode loops (not just browser ones) so external_directory
    // access is pre-allowed even for non-browser tasks.
    if (cliProfile === 'opencode' && !nativeRuntime) {
      try {
        const xdgRoot = setupOpencodeLoopConfig(
          terminalSessionId,
          browserSessionId,
          browserTabId,
          cliTools,
          model, {}, { cwd: loopCwd },
        );
        if (xdgRoot) {
          loopExtraEnv.XDG_CONFIG_HOME = xdgRoot;
          loopExtraEnv.OPENCODE_CONFIG_CONTENT = buildOpencodeRuntimeConfigOverlay(xdgRoot, { unattended: true });
          loopLog(terminalSessionId, 'launch:opencode-config', 'per-loop XDG_CONFIG_HOME wired', { xdgRoot });
        }
      } catch (err) {
        loopLog(terminalSessionId, 'launch:opencode-config', 'setup FAILED — refusing global config fallback', { err: err.message });
        try { unlinkSync(resolve(LOOP_DIR, `${pendingId}.json`)); } catch {}
        throw new Error(`OpenCode isolated loop config failed: ${err.message}`);
      }
    }

    loopLog(terminalSessionId, 'launch:env', 'extraEnv prepared for spawned PTY', {
      keys: Object.keys(loopExtraEnv),
      SYNABUN_TERMINAL_SESSION: loopExtraEnv.SYNABUN_TERMINAL_SESSION,
      SYNABUN_BROWSER_SESSION: loopExtraEnv.SYNABUN_BROWSER_SESSION || null,
      SYNABUN_BROWSER_TAB: loopExtraEnv.SYNABUN_BROWSER_TAB || null,
    });

    if (nativeRuntime) {
      loopLog(terminalSessionId, 'launch:native', 'starting server-owned native sidepanel run', { profile: cliProfile });
      const initialClaimWindow = String(sidepanelWindowId || '').trim().slice(0, 128);
      const initialClaimRevoked = isSidepanelClaimTokenRevoked(initialClaimWindow, sidepanelClaimToken);
      const run = await _nativeLoopRuntime.launch({
        runId: terminalSessionId,
        state: loopState,
        source: 'manual',
        focus: true,
        title: task.trim().split('\n')[0].slice(0, 80),
        claimedBy: initialClaimWindow && !initialClaimRevoked ? initialClaimWindow : null,
      });
      pendingNativeBrowserCleanup = null;
      if (run.status === 'failed') {
        return res.status(500).json({ error: run.error || 'Native provider failed to start', run });
      }
      reconcileKeepAwake();
      const responsePayload = {
        ok: true,
        pendingId,
        runId: terminalSessionId,
        terminalSessionId,
        surface: 'sidepanel',
        runtimeType: 'native',
        driverType: 'native',
        provider: cliProfile,
        profile: cliProfile,
        providerSessionId: run.providerSessionId,
        providerThreadId: run.providerThreadId,
        browserSessionId,
        browserTabId: loopState.browserTabId,
        run,
      };
      loopLog(terminalSessionId, 'launch:response', 'sending native sidepanel response', responsePayload);
      return res.json(responsePayload);
    }

    if (cliProfile === 'claude-code') {
      // Claude Code: spawn interactive CLI, hook-driven iteration transitions (/clear + re-prompt)
      // Per-loop --mcp-config: the HTTP MCP server never sees PTY env, so the
      // loop's browser pins ride as headers on its own SynaBun entry instead.
      let mcpConfigPath = null;
      try {
        mcpConfigPath = setupClaudeLoopMcpConfig(terminalSessionId, browserSessionId, browserTabId, cliTools, loopCwd);
        loopLog(terminalSessionId, 'launch:mcp-config', 'per-loop claude mcp config written', { mcpConfigPath, headerKeys: ['X-Synabun-Terminal', browserSessionId && 'X-Synabun-Browser-Session', browserTabId && 'X-Synabun-Browser-Tab'].filter(Boolean) });
      } catch (err) {
        // Without the config the loop still gets an isolated tab via its own
        // Mcp-Session-Id — only deterministic pinning to the pre-acquired tab
        // is lost. Log loudly so a missing pin is attributable.
        throw Object.assign(new Error('Claude MCP scope config could not be written'), { code: 'MCP_SCOPE_UNENFORCED' });
      }
      loopLog(terminalSessionId, 'launch:spawn', 'creating claude-code PTY session', { profile: cliProfile, cwd: loopCwd, model, effort });
      createTerminalSession(cliProfile, 120, 30, loopCwd, { model, effort, extraEnv: loopExtraEnv, sessionId: terminalSessionId, loopBypass: true, mcpConfigPath });
      loopLog(terminalSessionId, 'launch:driver', 'attaching hook-driven loop driver (claude-code)');
      attachLoopDriver(terminalSessionId);
    } else {
      // Codex/Gemini/other: spawn shell, server drives `<cli> exec` commands per iteration.
      // The driver invokes a platform-native wrapper that captures the CLI
      // status and emits a sentinel. Immune to PS1/PROMPT overrides.
      loopLog(terminalSessionId, 'launch:spawn', 'creating shell PTY for exec-driven CLI', { profile: cliProfile, cwd: loopCwd });
      createTerminalSession('shell', 120, 30, loopCwd, { extraEnv: loopExtraEnv, sessionId: terminalSessionId });
      loopLog(terminalSessionId, 'launch:driver', 'attaching exec loop driver (codex/gemini/other)', { profile: cliProfile });
      attachExecLoopDriver(terminalSessionId);
    }

    // Browser ownership is now held by the successfully launched PTY; normal
    // loop-stop cleanup owns it from this point onward.
    pendingNativeBrowserCleanup = null;
    broadcastSync({ type: 'terminal:session-created', sessionId: terminalSessionId, profile: cliProfile });

    const responsePayload = {
      ok: true,
      pendingId,
      terminalSessionId,
      surface: 'terminal',
      runtimeType: 'pty',
      driverType: loopState.driverType,
      provider: cliProfile,
      profile: cliProfile,
      browserSessionId,
      browserTabId: loopState.browserTabId,
    };
    loopLog(terminalSessionId, 'launch:response', 'sending 200 response', responsePayload);
    res.json(responsePayload);
  } catch (err) {
    if (pendingNativeBrowserCleanup) {
      await releaseSharedBrowserTab(
        pendingNativeBrowserCleanup.sessionId,
        pendingNativeBrowserCleanup.ownerKey,
      ).catch(() => {});
    }
    loopLog(null, 'launch:error', 'POST /api/loop/launch threw', { err: err.message, stack: err.stack?.slice(0, 800) });
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// POST /api/loop/stop — force-stop loops and clean up PTY sessions
// Body: { runId?: string, terminalSessionId?: string } — if provided, stop only that loop; otherwise stop all
app.post('/api/loop/stop', async (req, res) => {
  try {
    const targetTerminalId = req.body?.runId || req.body?.terminalSessionId || null;
    let directlyStopped = false;
    if (targetTerminalId && _nativeLoopRuntime?.isAlive(targetTerminalId)) {
      directlyStopped = await _nativeLoopRuntime.stop(targetTerminalId, 'user');
    }
    if (!existsSync(LOOP_DIR)) return res.json({ ok: true, stopped: directlyStopped ? 1 : 0 });
    const files = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json') && f !== '.gitkeep');
    let stopped = 0;
    for (const f of files) {
      try {
        const filePath = resolve(LOOP_DIR, f);
        const data = JSON.parse(readFileSync(filePath, 'utf-8'));
        if (directlyStopped && (data.runId === targetTerminalId || data.terminalSessionId === targetTerminalId)) {
          try { unlinkSync(filePath); } catch {}
          stopped++;
          continue;
        }
        if (data.active || data.pending) {
          // Per-loop stop: skip loops that don't match the target
          if (targetTerminalId && data.runId !== targetTerminalId && data.terminalSessionId !== targetTerminalId) continue;
          if (!directlyStopped && (data.runtimeType === 'native' || data.driverType === 'native')) {
            await _nativeLoopRuntime?.stop(data.runId || data.terminalSessionId, 'user');
          }
          if (data.driverType === 'exec' && data.scheduledBy) {
            data.active = false;
            data.pending = false;
            data.completedAt = new Date().toISOString();
            data.stoppedReason = 'user';
            try { writeFileSync(filePath, JSON.stringify(data, null, 2)); } catch {}
            persistExecScheduleOutcome(data, 'stopped', 'user');
          }
          // Kill PTY session if still alive
          if (data.terminalSessionId && terminalSessions.has(data.terminalSessionId)) {
            const session = terminalSessions.get(data.terminalSessionId);
            cleanupExecLoopArtifacts(session);
            try { session.pty.kill(); } catch {}
            terminalSessions.delete(data.terminalSessionId);
          }
          if (data.browserSessionId && browserSessions.has(data.browserSessionId)) {
            const bSession = browserSessions.get(data.browserSessionId);
            bSession?._loopOwned?.delete(data.terminalSessionId);
            bSession?._tabOwners?.delete(data.terminalSessionId);
            if (data.browserTabId && bSession?.tabs?.has(data.browserTabId) && bSession.tabs.size > 1) {
              // Close only this loop's tab and keep the shared browser session alive.
              try {
                const tab = bSession.tabs.get(data.browserTabId);
                if (tab?.page) await tab.page.close().catch(() => {});
                bSession.tabs.delete(data.browserTabId);
                if (bSession.activeTabId === data.browserTabId) {
                  const nextTabId = bSession.tabs.keys().next().value;
                  if (nextTabId) _switchSessionTab(bSession, data.browserSessionId, nextTabId).catch(() => {});
                }
                console.log(`[loop/stop] Closed loop tab ${data.browserTabId} in shared session ${data.browserSessionId}`);
              } catch (err) {
                console.warn(`[loop/stop] Failed to close loop tab: ${err.message}`);
              }
            }
          }
          // Per-CLI per-loop config dir cleanup (opencode XDG_CONFIG_HOME, etc.)
          if (data.profile === 'opencode' && data.terminalSessionId) {
            cleanupOpencodeLoopConfig(data.terminalSessionId);
          }
          if (data.profile === 'claude-code' && data.terminalSessionId) {
            cleanupClaudeLoopMcpConfig(data.terminalSessionId);
          }
          // Delete the loop file — no history keeping
          try { unlinkSync(filePath); } catch { /* ok */ }
          stopped++;
        }
      } catch { /* skip corrupt */ }
    }
    res.json({ ok: true, stopped: Math.max(stopped, directlyStopped ? 1 : 0) });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// POST /api/loop/resolve-from-ancestors — process-tree fallback for MCP env loss.
// The MCP server walks its ancestor PID chain (codex/opencode/gemini → shell PTY)
// and POSTs the chain here. We match any PID against terminalSessions[*].pty.pid
// and return that loop's browserSessionId/browserTabId. Layer B of the
// defense-in-depth browser tab isolation fix.
app.post('/api/loop/resolve-from-ancestors', (req, res) => {
  try {
    const pids = Array.isArray(req.body?.pids) ? req.body.pids.map(Number).filter(Number.isFinite) : [];
    if (pids.length === 0) return res.json({ matched: false });
    const pidSet = new Set(pids);
    let matchedTerminal = null;
    for (const [tsid, session] of terminalSessions.entries()) {
      const pid = session?.pty?.pid;
      if (pid && pidSet.has(pid)) { matchedTerminal = tsid; break; }
    }
    if (!matchedTerminal) return res.json({ matched: false });
    const loopFile = findLoopFileForTerminal(matchedTerminal);
    if (!loopFile) return res.json({ matched: false, terminalSessionId: matchedTerminal });
    try {
      const data = JSON.parse(readFileSync(resolve(LOOP_DIR, loopFile), 'utf-8'));
      return res.json({
        matched: true,
        terminalSessionId: matchedTerminal,
        browserSessionId: data.browserSessionId || null,
        browserTabId: data.browserTabId || null,
      });
    } catch {
      return res.json({ matched: false, terminalSessionId: matchedTerminal });
    }
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// POST /api/loop/recover-browser — recover a dead pinned browser session.
// When a loop's pinned browser session has died, the MCP server calls this to
// rejoin the SHARED loop browser with a FRESH, owned tab — instead of spawning
// an isolated new browser and reusing a now-invalid tabId (which 404s on every
// subsequent call). If terminalSessionId is known, the loop's state file is
// updated so future ancestor lookups and /api/loop/stop stay consistent.
// Body: { terminalSessionId?: string }. Returns { ok, sessionId, tabId }.
app.post('/api/loop/recover-browser', async (req, res) => {
  try {
    const terminalSessionId = req.body?.terminalSessionId || randomBytes(16).toString('hex');
    const acq = await acquireLoopBrowserAndTab({ terminalSessionId, logTag: 'recover:browser' });
    if (acq.error) {
      return res.status(500).json({ error: acq.error });
    }
    // Persist the new pins onto the loop's state file when we can identify it,
    // so resolve-from-ancestors and loop/stop operate on the live session/tab.
    if (req.body?.terminalSessionId) {
      const loopFile = findLoopFileForTerminal(req.body.terminalSessionId);
      if (loopFile) {
        try {
          const fp = resolve(LOOP_DIR, loopFile);
          const data = JSON.parse(readFileSync(fp, 'utf-8'));
          data.browserSessionId = acq.browserSessionId;
          data.browserTabId = acq.browserTabId || null;
          writeFileSync(fp, JSON.stringify(data, null, 2));
        } catch (err) {
          console.warn(`[loop/recover-browser] Failed to update loop state file: ${err.message}`);
        }
      }
    }
    res.json({ ok: true, sessionId: acq.browserSessionId, tabId: acq.browserTabId || null });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// GET /api/loop/history — no history keeping, always empty
app.get('/api/loop/history', (_req, res) => { res.json([]); });

// DELETE /api/loop/history/:id — no-op, files are deleted on stop
app.delete('/api/loop/history/:id', (_req, res) => { res.json({ ok: true }); });

// POST /api/loop/complete — store a completed loop as a SQLite memory
app.post('/api/loop/complete', async (req, res) => {
  try {
    const { task, context, template, iterations, duration, result, tags } = req.body;
    if (!task) return res.status(400).json({ error: 'task is required' });

    const content = [
      `Automation: ${task}`,
      context ? `Context: ${context}` : null,
      template ? `Template: ${template}` : null,
      `Iterations: ${iterations || '?'}`,
      `Duration: ${duration || '?'}`,
      result ? `Result: ${result}` : null,
    ].filter(Boolean).join('\n');

    const embedding = await getEmbedding(content);
    const id = randomUUID();
    const now = new Date().toISOString();
    const d = getDb();

    d.prepare(`INSERT OR REPLACE INTO memories (id, vector, content, category, subcategory, project, importance, tags, source, created_at, updated_at, accessed_at, access_count)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`).run(
      id, encodeVector(embedding), content, 'automations', 'loop-result', 'synabun',
      6, JSON.stringify(tags || ['automation', 'loop']), 'auto-saved',
      now, now, now, 0
    );
    memoryVectors.set(id, embedding);

    invalidateMemoriesCache('loop:complete', id);
    res.json({ ok: true, id });
  } catch (err) {
    console.error('POST /api/loop/complete error:', err.message);
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// ═══════════════════════════════════════════════════════════════
// LOOP SCHEDULES — Cron-driven social engagement scheduler
// Server-side setInterval evaluator that auto-launches loops
// at scheduled times, respecting timezones and day themes.
// ═══════════════════════════════════════════════════════════════

// Schedule-file cache: the queue window polls every 5s and dozens of CRUD
// routes call loadSchedules(); re-reading + parsing every loop-schedules*.json
// per call is pure waste. Invalidated by fs.watch (the MCP server writes these
// files from another process) plus explicitly on our own writes. Returns a
// clone — several handlers mutate schedule objects in place before saving.
let _scheduleFilesCache = null;
let _scheduleFilesWatcher = null;

function _armScheduleFilesWatcher() {
  if (_scheduleFilesWatcher) return true;
  try {
    const w = fsWatch(LOOP_DATA_DIR, (eventType, filename) => {
      if (filename && !LOOP_SCHEDULES_PATTERN.test(filename)) return;
      _scheduleFilesCache = null;
    });
    w.unref?.();
    w.on('error', () => {
      _scheduleFilesCache = null;
      _scheduleFilesWatcher = null;
      try { w.close(); } catch {}
    });
    _scheduleFilesWatcher = w;
    return true;
  } catch { return false; /* dir missing — caching disabled until it exists */ }
}

function readLoopScheduleFiles() {
  if (_scheduleFilesCache) return structuredClone(_scheduleFilesCache);
  const files = listLoopDataPaths(LOOP_SCHEDULES_PATTERN, LOOP_SCHEDULES_FILE, LOOP_SCHEDULES_PATH).map(path => {
    try {
      const data = JSON.parse(readFileSync(path, 'utf-8'));
      if (Array.isArray(data)) return { path, schedules: data.filter(isLoopObject), groups: [], format: 'array' };
      if (isLoopObject(data)) {
        return {
          path,
          schedules: Array.isArray(data.schedules) ? data.schedules.filter(isLoopObject) : [],
          groups: path === LOOP_SCHEDULES_PATH && Array.isArray(data.groups) ? data.groups.filter(isLoopObject) : [],
          format: 'object',
        };
      }
    } catch { /* corrupt */ }
    return { path, schedules: [], groups: [], format: 'object' };
  });
  // Only cache when the watcher is armed — without it we'd serve stale data
  // forever after an external (MCP) write.
  if (_armScheduleFilesWatcher()) _scheduleFilesCache = files;
  return structuredClone(files);
}

function loadScheduleStore() {
  const store = { schedules: [], groups: [] };
  const files = readLoopScheduleFiles();
  store.schedules = mergeLoopItemsById(files, 'schedules');
  for (const file of files) {
    if (file.path === LOOP_SCHEDULES_PATH) store.groups = file.groups;
  }
  store.groups = store.groups.map(record => { normalizeAutomationRecord(record); return readStoredToolListRecord(record, toolListOptions()); });
  store.schedules = store.schedules.map(record => { normalizeAutomationRecord(record); return readStoredToolListRecord(record, toolListOptions()); });
  return store;
}

function scheduleStoragePathForName(name) {
  const slug = slugLoopStorageName(name);
  return slug ? resolve(LOOP_DATA_DIR, `loop-schedules-${slug}.json`) : LOOP_SCHEDULES_PATH;
}

function buildScheduleRouting(files) {
  const byId = new Map();
  const byGroupId = new Map();
  for (const file of files) {
    for (const schedule of file.schedules) {
      if (schedule.id) {
        const id = String(schedule.id);
        byId.set(id, preferLoopStoragePath(byId.get(id), file.path, LOOP_SCHEDULES_PATH));
      }
      if (schedule.groupId) {
        const groupId = String(schedule.groupId);
        byGroupId.set(groupId, preferLoopStoragePath(byGroupId.get(groupId), file.path, LOOP_SCHEDULES_PATH));
      }
    }
  }
  return { byId, byGroupId };
}

function resolveScheduleStoragePath(schedule, routing, groupsById) {
  const id = schedule?.id ? String(schedule.id) : '';
  if (id && routing.byId.has(id)) return routing.byId.get(id);

  const groupId = schedule?.groupId ? String(schedule.groupId) : '';
  if (groupId) {
    if (routing.byGroupId.has(groupId)) return routing.byGroupId.get(groupId);
    const group = groupsById.get(groupId);
    if (group?.name) return scheduleStoragePathForName(group.name);
  }

  return LOOP_SCHEDULES_PATH;
}

function writeLoopScheduleFile(path, schedules, groups, format = 'object', previousFiles = readLoopScheduleFiles()) {
  const previousSchedules = new Map(previousFiles.flatMap(file => file.schedules || []).map(record => [record.id, record]));
  const previousGroups = new Map(previousFiles.flatMap(file => file.groups || []).map(record => [record.id, record]));
  schedules = schedules.map(record => toolListRecordForUpdate(record, previousSchedules.get(record.id), toolListOptions()));
  groups = (groups || []).map(record => toolListRecordForUpdate(record, previousGroups.get(record.id), toolListOptions()));
  mkdirSync(dirname(path), { recursive: true });
  const isMain = path === LOOP_SCHEDULES_PATH;
  const data = isMain
    ? { schedules, groups: Array.isArray(groups) ? groups : [] }
    : (format === 'array' ? schedules : { schedules });
  writeFileSync(path, JSON.stringify(data, null, 2));
  _scheduleFilesCache = null; // deterministic invalidation (watcher is async)
}

function saveScheduleStore(store) {
  const files = readLoopScheduleFiles();
  const routing = buildScheduleRouting(files);
  const formatByPath = new Map(files.map(file => [file.path, file.format]));
  const byPath = new Map(files.map(file => [file.path, []]));
  if (!byPath.has(LOOP_SCHEDULES_PATH)) byPath.set(LOOP_SCHEDULES_PATH, []);

  const groups = Array.isArray(store?.groups) ? store.groups.filter(isLoopObject) : [];
  const groupsById = new Map(groups.map(group => [String(group.id), group]));
  for (const schedule of Array.isArray(store?.schedules) ? store.schedules : []) {
    if (!isLoopObject(schedule)) continue;
    const targetPath = resolveScheduleStoragePath(schedule, routing, groupsById);
    if (!byPath.has(targetPath)) byPath.set(targetPath, []);
    byPath.get(targetPath).push(schedule);
  }

  for (const [path, schedules] of byPath) {
    writeLoopScheduleFile(path, schedules, path === LOOP_SCHEDULES_PATH ? groups : [], formatByPath.get(path) || 'object', files);
  }
}

function loadSchedules() {
  return loadScheduleStore().schedules;
}

function saveSchedules(schedules) {
  const store = loadScheduleStore();
  store.schedules = Array.isArray(schedules) ? schedules : [];
  saveScheduleStore(store);
}

function loadScheduleGroups() {
  return loadScheduleStore().groups.sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
}

function saveScheduleGroups(groups) {
  const store = loadScheduleStore();
  store.groups = Array.isArray(groups) ? groups : [];
  saveScheduleStore(store);
}

function validateScheduleGroupId(groupId) {
  if (!groupId) return null;
  const id = String(groupId);
  return loadScheduleGroups().some(g => g.id === id) ? id : false;
}

function applyScheduleLaunchOverrides(schedule, source) {
  applyStoredToolList(schedule, source, toolListOptions());
  const fields = ['profile', 'model', 'contextMode', 'effort', 'platform', 'codexAccountId'];
  for (const field of fields) {
    if (source[field] !== undefined) {
      if (source[field] === null || source[field] === '') delete schedule[field];
      else schedule[field] = source[field];
    }
  }
  if (source.usesBrowser !== undefined) {
    if (source.usesBrowser === null) delete schedule.usesBrowser;
    else schedule.usesBrowser = !!source.usesBrowser;
  }
  normalizeAutomationRecord(schedule);
  delete schedule.mcpProfile;
}

function boundedScheduleNumber(value, fallback, min, max) {
  const n = Number(value);
  const resolved = Number.isFinite(n) ? n : fallback;
  return Math.min(Math.max(Math.trunc(resolved), min), max);
}

// ── Cron Parser ──

function parseCronField(field, min, max) {
  const values = new Set();
  for (const part of field.split(',')) {
    const trimmed = part.trim();
    if (trimmed === '*') {
      for (let i = min; i <= max; i++) values.add(i);
    } else if (trimmed.includes('/')) {
      const [range, step] = trimmed.split('/');
      const stepNum = parseInt(step, 10);
      let start = min, end = max;
      if (range !== '*') {
        if (range.includes('-')) {
          const parts = range.split('-').map(Number);
          start = parts[0]; end = parts[1];
        } else {
          start = parseInt(range, 10);
        }
      }
      for (let i = start; i <= end; i += stepNum) values.add(i);
    } else if (trimmed.includes('-')) {
      const parts = trimmed.split('-').map(Number);
      for (let i = parts[0]; i <= parts[1]; i++) values.add(i);
    } else {
      const n = parseInt(trimmed, 10);
      if (!isNaN(n)) values.add(n);
    }
  }
  return values;
}

function cronMatchesDate(cronStr, date) {
  const fields = cronStr.trim().split(/\s+/);
  if (fields.length !== 5) return false;
  const [minute, hour, dayOfMonth, month, dayOfWeek] = fields;
  return parseCronField(minute, 0, 59).has(date.getMinutes()) &&
    parseCronField(hour, 0, 23).has(date.getHours()) &&
    parseCronField(dayOfMonth, 1, 31).has(date.getDate()) &&
    parseCronField(month, 1, 12).has(date.getMonth() + 1) &&
    parseCronField(dayOfWeek, 0, 6).has(date.getDay());
}

// Get the current time in a given timezone as a Date object
function getNowInTimezone(tz) {
  try {
    const str = new Date().toLocaleString('en-US', { timeZone: tz });
    return new Date(str);
  } catch {
    return new Date();
  }
}

// Compute next cron fire time (for display), up to 7 days ahead
function getNextCronRun(cronStr, tz) {
  const now = getNowInTimezone(tz);
  const candidate = new Date(now);
  candidate.setSeconds(0, 0);
  candidate.setMinutes(candidate.getMinutes() + 1);
  const maxIterations = 7 * 24 * 60;
  for (let i = 0; i < maxIterations; i++) {
    if (cronMatchesDate(cronStr, candidate)) {
      return candidate.toISOString();
    }
    candidate.setMinutes(candidate.getMinutes() + 1);
  }
  return null;
}

// Count how many times a cron fires in a representative 24h day. Used to give
// low-frequency schedules (e.g. a once-daily morning post) a longer mutex-deferral
// window and higher retry priority, so they are not starved by hourly loops that
// hog the shared mutual-exclusion lock. Cheap: 1440 cheap set lookups, cached by cron.
const _cronFiresPerDayCache = new Map();
function cronFiresPerDay(cronStr) {
  if (_cronFiresPerDayCache.has(cronStr)) return _cronFiresPerDayCache.get(cronStr);
  let count = 0;
  // A fixed reference day (no Date.now dependence on the result): walk one 24h span.
  const d = new Date(2025, 0, 1, 0, 0, 0, 0);
  for (let i = 0; i < 24 * 60; i++) {
    if (cronMatchesDate(cronStr, d)) count++;
    d.setMinutes(d.getMinutes() + 1);
  }
  count = Math.max(1, count);
  _cronFiresPerDayCache.set(cronStr, count);
  return count;
}

// Describe a cron expression in human-readable form
function describeCron(cronStr) {
  const fields = cronStr.trim().split(/\s+/);
  if (fields.length !== 5) return cronStr;
  const [minute, hour, , , dayOfWeek] = fields;
  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  let dayPart = '';
  if (dayOfWeek === '*') dayPart = 'Every day';
  else if (dayOfWeek === '1-5') dayPart = 'Weekdays';
  else if (dayOfWeek === '0,6') dayPart = 'Weekends';
  else {
    const days = [...parseCronField(dayOfWeek, 0, 6)].sort().map(d => dayNames[d]);
    dayPart = days.join(', ');
  }
  const timePart = hour === '*' ? `every hour at :${minute.padStart(2, '0')}` :
    [...parseCronField(hour, 0, 23)].sort((a, b) => a - b)
      .map(h => `${String(h).padStart(2, '0')}:${minute.padStart(2, '0')}`).join(', ');
  return `${dayPart} at ${timePart}`;
}

// ── Schedule Evaluator ──

let _scheduleEvaluatorTimer = null;
const SCHEDULE_EVAL_INTERVAL = 60_000;
// Freshness window for overdue catch-up. A schedule whose fire time was missed
// (machine slept/server down) is caught up ONLY if it's overdue by less than this.
// Older misses are stale — a "Morning Native Post" must not publish in the
// afternoon — so they skip to their next future slot without firing. This bounds
// the on-wake backlog after an overnight clamshell sleep to recent slots only.
const CATCHUP_FRESHNESS_MS = 90 * 60 * 1000; // 90 minutes
const _scheduleFiringLock = new Set();
const _scheduleTimers = new Map(); // scheduleId → { timeoutId, firesAt, minutes }
let _scheduleEvalCount = 0;

// Re-validate a queued/deferred schedule against the CURRENT persisted state right
// before it launches. A schedule can be disabled ("halted") or deleted by the user
// while it sits in _scheduleQueue or the mutex-deferral backlog — e.g. a clamshell-sleep
// catch-up backlog that piles up on wake and that the user then halts. Those queues hold
// stale object snapshots captured at enqueue time (enabled:true), so without this re-read
// the catch-up path fires automations the user already turned off. Returns the fresh
// schedule object if it still exists AND is still enabled, else null.
function getLaunchableSchedule(scheduleId) {
  try {
    const fresh = loadSchedules().find(s => s.id === scheduleId);
    if (!fresh || !fresh.enabled) return null; // deleted or halted/disabled since enqueue
    return fresh;
  } catch {
    return null;
  }
}

// True if a schedule already has a pending fire in flight: sitting in the launch
// queue, deferred behind a mutex, or actively running. The overdue catch-up path
// re-evaluates every 60s tick while a slow loop holds the mutex, so without this
// guard the SAME overdue schedule gets pushed onto _scheduleQueue once per minute
// for the whole ~25-min loop. When the mutex frees, that backlog drains 30s apart
// and every duplicate launches — the "they all stacked and multiple opened on wake"
// stampede. Enqueue only when nothing for this schedule is already pending.
function isSchedulePending(scheduleId) {
  if (_scheduleQueue.some(s => s.id === scheduleId)) return true;
  if (_deferredMutexSchedules.some(d => d.schedule.id === scheduleId)) return true;
  for (const info of _runningScheduledLoops.values()) {
    if (info.scheduleId === scheduleId) return true;
  }
  return false;
}

async function launchScheduledLoop(schedule) {
  // Final guard: never fire a schedule that was disabled/deleted after it was queued.
  // Re-read persisted state and launch from the FRESH object so any edits (cron,
  // template, overrides) made while it waited are honored too. Forced fires include
  // synthetic quick-timer schedules that are NOT persisted — keep the passed snapshot
  // for those instead of aborting.
  const persisted = getLaunchableSchedule(schedule.id);
  const current = persisted
    ? mergeScheduleLaunchSnapshot(persisted, schedule)
    : (schedule._forced ? schedule : null);
  if (!current) {
    console.log(`[schedule] Aborting launch of "${schedule.name}" — disabled or deleted before launch`);
    return;
  }
  schedule = current;

  const templates = readLoopTemplates();
  const template = templates.find(t => t.id === schedule.templateId);
  if (!template) {
    console.warn(`[schedule] Template ${schedule.templateId} not found for schedule ${schedule.id}`);
    const schedules = loadSchedules();
    const idx = schedules.findIndex(s => s.id === schedule.id);
    if (idx !== -1) {
      schedules[idx].lastRun = new Date().toISOString();
      schedules[idx].lastRunResult = 'template_missing';
      schedules[idx].nextRun = getNextCronRun(schedule.cron, schedule.timezone);
      saveSchedules(schedules);
    }
    broadcastSync({ type: 'schedule:failed', scheduleId: schedule.id, reason: 'template_missing' });
    return;
  }

  // Merge dayTheme context if available
  const now = getNowInTimezone(schedule.timezone);
  const dayOfWeek = now.getDay();
  const dayTheme = schedule.dayThemes?.[String(dayOfWeek)];
  let context = template.context || '';
  if (dayTheme?.contextOverride) {
    context = context ? `${context}\n\n--- Day Theme ---\n${dayTheme.contextOverride}` : dayTheme.contextOverride;
  }

  console.log(`[schedule] Firing schedule "${schedule.name}" (template: ${template.name}, day: ${dayOfWeek})`);
  broadcastSync({ type: 'schedule:fired', scheduleId: schedule.id, scheduleName: schedule.name, templateName: template.name, dayOfWeek });

  // Defense in depth: a conflicting mutex group may have started between this
  // schedule passing the queue's mutex check and reaching launch. Never launch while
  // blocked — re-defer so the next eval tick retries when the mutex clears.
  if (isMutexBlocked(schedule)) {
    console.log(`[schedule] Re-deferred "${schedule.name}" at launch — a mutex-conflicting group is running`);
    if (!_deferredMutexSchedules.some(d => d.schedule.id === schedule.id)) {
      _deferredMutexSchedules.push({ schedule, deferredAt: Date.now() });
      broadcastSync({ type: 'schedule:deferred', scheduleId: schedule.id, scheduleName: schedule.name, reason: 'mutex_blocked' });
    }
    return;
  }

  let pendingNativeBrowserCleanup = null;
  let registeredScheduledRunId = null;
  let scheduledLaunchTerminalId = null;
  let scheduledLaunchPendingId = null;
  let scheduledLaunchProfile = null;
  try {
    if (!existsSync(LOOP_DIR)) mkdirSync(LOOP_DIR, { recursive: true });

    // Clean up stale/dead loop files — but allow multiple concurrent loops
    const existing = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json') && f !== '.gitkeep');
    for (const f of existing) {
      try {
        const data = JSON.parse(readFileSync(resolve(LOOP_DIR, f), 'utf-8'));
        if (!data.active && !data.pending) continue; // already finished
        // Only kill loops whose provider runtime is dead (stale cleanup)
        const termAlive = isLoopRuntimeAlive(data);
        if (!termAlive) {
          console.log(`[schedule] Cleaning up stale loop file ${f} (runtime gone)`);
          try { unlinkSync(resolve(LOOP_DIR, f)); } catch { /* ok */ }
        }
        // Active loops with live terminals are left running — multi-loop coexistence
      } catch { /* skip corrupt */ }
    }

    const group = schedule.groupId ? loadScheduleGroups().find(g => g.id === schedule.groupId) : null;
    const launchOverrides = resolveAutomationOverrides(schedule, group, template);
    const cliProfile = launchOverrides.profile;
    scheduledLaunchProfile = cliProfile;
    // An OpenCode SynaBun does not drive starts nothing (no browser tab, loop file, configuration or process): the
    // schedule's result is the sentence that says what was found and how to get OpenCode 2.
    if (cliProfile === 'opencode') {
      const refusal = await opencodeStartRefusal();
      if (refusal) throw refusal;
    }
    const requestedModel = launchOverrides.model;
    const requestedContextMode = launchOverrides.contextMode;
    const cliEffort     = schedule.effort     || group?.effort     || template.effort     || null;
    const nativeRuntime = isNativeLoopProfile(cliProfile);
    const storedTools = [schedule, group, template].map(record => storedToolList(record, toolListOptions())).find(value => value !== null);
    const cliTools = launchToolList({ tools: storedTools }, { provider: cliProfile,
      usesBrowser: schedule.usesBrowser ?? group?.usesBrowser ?? template.usesBrowser }).items;
    const platform = automationPlatform(schedule, group, template);
    const cliCodexAccountId = launchOverrides.codexAccountId;
    const codexAccount = cliProfile === 'codex' ? findCodexAccount(cliCodexAccountId) : null;
    if (cliProfile === 'codex' && !codexAccount) {
      throw new Error(`Codex account not found: ${cliCodexAccountId}`);
    }
    const launchChoice = await resolveAutomationLaunchChoice(
      cliProfile, requestedModel, requestedContextMode, codexAccount?.home || CODEX_DEFAULT_HOME,
    );
    const cliModel = launchChoice.model;
    const cliContextMode = launchChoice.contextMode;
    const scheduledUsesBrowser = schedule.usesBrowser !== undefined
      ? !!schedule.usesBrowser
      : group?.usesBrowser !== undefined
        ? !!group.usesBrowser
        : !!template.usesBrowser;
    const scheduleOverrides = schedule.overrides && typeof schedule.overrides === 'object' ? schedule.overrides : {};
    const loopIterations = boundedScheduleNumber(scheduleOverrides.iterations, template.iterations || 10, 1, 200);
    const loopMaxMinutes = boundedScheduleNumber(scheduleOverrides.maxMinutes, template.maxMinutes || 30, 1, 480);

    // Pre-generate terminalSessionId so isolation env vars can carry it.
    // Without SYNABUN_TERMINAL_SESSION, hooks in the spawned CLI fall back to
    // legacy "match any loop" logic and leak context between concurrent sessions
    // (e.g., a sidepanel plan session and a scheduled CLI loop in the same cwd).
    const terminalSessionId = randomBytes(16).toString('hex');
    scheduledLaunchTerminalId = terminalSessionId;

    // Reuse the shared browser session and create a fresh tab for this scheduled loop.
    let scheduledBrowserSessionId = null;
    let scheduledBrowserTabId = null;
    const schedExtraEnv = { SYNABUN_TERMINAL_SESSION: terminalSessionId };
    schedExtraEnv.SYNABUN_TOOLS = runtimeToolsValue(cliTools);
    // Codex reads auth.json from CODEX_HOME — pin the schedule's selected ChatGPT account.
    if (cliProfile === 'codex') {
      schedExtraEnv.CODEX_HOME = codexAccount.home || CODEX_DEFAULT_HOME;
      console.log(`[schedule] "${schedule.name}" codex account=${codexAccount.id} CODEX_HOME=${schedExtraEnv.CODEX_HOME}`);
    }
    if (cliProfile === 'opencode') {
      schedExtraEnv.OPENCODE_EXPERIMENTAL_BASH_DEFAULT_TIMEOUT_MS =
        process.env.OPENCODE_EXPERIMENTAL_BASH_DEFAULT_TIMEOUT_MS || '300000';
    }
    if (scheduledUsesBrowser) {
      // Same serialized shared-browser + dedicated-tab acquisition as manual loops.
      const acq = await acquireLoopBrowserAndTab({ terminalSessionId, logTag: 'schedule:browser' });
      if (acq.error) {
        throw new Error(acq.error);
      }
      scheduledBrowserSessionId = acq.browserSessionId;
      scheduledBrowserTabId = acq.browserTabId;
      pendingNativeBrowserCleanup = { sessionId: scheduledBrowserSessionId, ownerKey: terminalSessionId };
      schedExtraEnv.SYNABUN_BROWSER_SESSION = scheduledBrowserSessionId;
      if (scheduledBrowserTabId) schedExtraEnv.SYNABUN_BROWSER_TAB = scheduledBrowserTabId;
    }

    if (cliProfile === 'opencode' && !nativeRuntime) {
      try {
        const xdgRoot = setupOpencodeLoopConfig(
          terminalSessionId,
          scheduledBrowserSessionId,
          scheduledBrowserTabId,
          cliTools,
          cliModel, {}, { cwd: PACKAGE_ROOT },
        );
        if (xdgRoot) {
          schedExtraEnv.XDG_CONFIG_HOME = xdgRoot;
          schedExtraEnv.OPENCODE_CONFIG_CONTENT = buildOpencodeRuntimeConfigOverlay(xdgRoot, { unattended: true });
        }
      } catch (err) {
        console.warn(`[schedule] opencode per-loop config setup failed; refusing global config fallback: ${err.message}`);
        throw new Error(`OpenCode isolated schedule config failed: ${err.message}`);
      }
    }

    // Resolve Facebook deal-link tokens for SCHEDULED runs too (separate launch path from
    // POST /api/loop/launch) — schedules are the primary way these deal loops fire.
    const { task: resolvedSchedTask, resolved: schedDealResolved, link: schedDealLink } = await resolveDealLink(template.task);
    if (schedDealResolved) loopLog(terminalSessionId, 'launch:deal-link', 'resolved deal link (schedule)', { schedDealLink });

    // Cross-schedule, per-account dedup: inject a "do not re-engage" skip-list of
    // handles + tweet IDs engaged in the last 7 days, plus the permanent blocklist
    // (accounts that blocked us). Deterministic and shared across all X schedules
    // for this account (the prior per-template memory recall was model-discretion
    // and namespaced, so the same post/author got hit by multiple schedules — a
    // shadow-ban driver). Detection follows the template platform.
    // Read-only; never blocks launch.
    const isXAutomation = platform === 'twitter';
    if (isXAutomation) {
      try {
        const xAccount = (template.account || (/^cp_/.test(schedule.templateId || '') ? 'Crit_Pix' : '')).trim();
        const { handles, statusIds, blocked, error: ledgerErr } = getRecentXEngagements({ account: xAccount || null, days: 7, limit: 200 });
        if (ledgerErr) {
          loopLog(terminalSessionId, 'launch:dedup', 'engagement ledger read failed (continuing)', { err: ledgerErr });
        } else if (handles.length || statusIds.length || blocked.length) {
          const hLine = handles.slice(0, 150).map(h => '@' + h).join(', ');
          const sLine = statusIds.slice(0, 150).join(', ');
          const bLine = blocked.slice(0, 100).map(h => '@' + h).join(', ');
          const acctLabel = xAccount ? ` for @${xAccount}` : '';
          const block = [
            `=== ALREADY ENGAGED${acctLabel} — do NOT reply, quote, or follow these again (last 7 days) ===`,
            hLine ? `handles: ${hLine}` : null,
            sLine ? `tweet IDs: ${sLine}` : null,
            bLine ? `=== BLOCKED — these accounts blocked us; NEVER engage (permanent) ===\n${bLine}` : null,
            'This list is authoritative. If a candidate handle or tweet ID is here, skip it and move on, even if the post looks fresh.',
          ].filter(Boolean).join('\n');
          context = context ? `${context}\n\n${block}` : block;
          loopLog(terminalSessionId, 'launch:dedup', 'injected X engagement skip-list', { account: xAccount || 'all', handles: handles.length, statusIds: statusIds.length, blocked: blocked.length });
        }

        // Shared per-day action budget. The skip-list stops the same TARGET being hit
        // twice; this stops six independent lanes each spending a full day's quota
        // because none of them can see what the others already did. Counts come from
        // the same ledger, ceilings from the ramp tier — both deterministic, so the
        // budget does not depend on the agent recalling its own run.
        const tz = schedule.timezone || 'America/Sao_Paulo';
        const nowLocal = getNowInTimezone(tz);
        const msIntoDay = ((nowLocal.getHours() * 60 + nowLocal.getMinutes()) * 60 + nowLocal.getSeconds()) * 1000 + nowLocal.getMilliseconds();
        const spent = getXActionBudget({ account: xAccount || null, sinceIso: new Date(Date.now() - msIntoDay).toISOString() });
        const { tier, caps, source: tierSource } = getXEngagementTier({ account: xAccount || null });
        if (spent.error) {
          loopLog(terminalSessionId, 'launch:budget', 'action budget read failed (continuing)', { err: spent.error });
        } else {
          const line = X_ACTION_TYPES.map(t => `${t} ${spent[t]}/${caps[t]}`).join(' | ');
          const exhausted = X_ACTION_TYPES.filter(t => spent[t] >= caps[t]);
          const budgetBlock = [
            `=== TODAY'S ACTION BUDGET${xAccount ? ` for @${xAccount}` : ''} (${tz} day so far) ===`,
            line,
            `Tier: ${tier}${tierSource === 'default' ? ' (no caps memory found — defaulted to the most conservative tier)' : ''}`,
            exhausted.length
              ? `CLOSED for the rest of today: ${exhausted.join(', ')}. Do NOT perform these, and do NOT substitute another action type to compensate.`
              : null,
            'These counters are authoritative and shared across every X schedule for this account. Stop the run when your own per-run cap or any ceiling above is reached, whichever comes first.',
          ].filter(Boolean).join('\n');
          context = context ? `${context}\n\n${budgetBlock}` : budgetBlock;
          loopLog(terminalSessionId, 'launch:budget', 'injected X action budget', { account: xAccount || 'all', tier, tierSource, spent: spent.total, exhausted });
        }
      } catch (err) {
        loopLog(terminalSessionId, 'launch:dedup', 'skip-list injection failed (continuing)', { err: err.message });
      }
    }

    // Facebook lanes: every Facebook schedule group posts through one Page, one
    // profile and one browser, so they share one per-day action budget.
    // Same deterministic idea as X: counts from the ledger (memories + fb_post_log),
    // ceilings from the ramp tier in code. This block is what replaced the old
    // "no Page post in the previous 20 hours" rule, under which one automatic share
    // could hold back every other lane. Read-only; never blocks launch.
    // Every FB template carries mcpProfile "facebook".
    // Lanes whose template name matches the pattern below always post. They are
    // exempt from the shared FB budget block, and their templates carry no SHARED
    // BUDGET text, so nothing in such a run stops for budget reasons.
    const isFbDealsLane = /Facebook Deals/i.test(template.name || '');
    const isFbAutomation = !isFbDealsLane && platform === 'facebook';
    if (isFbAutomation) {
      try {
        const tz = schedule.timezone || 'America/Sao_Paulo';
        const nowLocal = getNowInTimezone(tz);
        const msIntoDay = ((nowLocal.getHours() * 60 + nowLocal.getMinutes()) * 60 + nowLocal.getSeconds()) * 1000 + nowLocal.getMilliseconds();
        const spent = getFbActionBudget({ sinceIso: new Date(Date.now() - msIntoDay).toISOString() });
        const { tier, caps, source: tierSource } = getFbEngagementTier();
        if (spent.error) {
          loopLog(terminalSessionId, 'launch:budget', 'FB action budget read failed (continuing)', { err: spent.error });
        } else {
          const line = FB_ACTION_TYPES.map(t => `${t} ${spent[t]}/${caps[t]}`).join(' | ');
          const exhausted = FB_ACTION_TYPES.filter(t => spent[t] >= caps[t]);
          const budgetBlock = [
            `=== TODAY'S FACEBOOK ACTION BUDGET (${tz} day so far) ===`,
            line,
            `Tier: ${tier}${tierSource === 'default' ? ' (no caps memory found — defaulted to the most conservative tier)' : ''}`,
            exhausted.length
              ? `CLOSED for the rest of today: ${exhausted.join(', ')}. Do NOT perform these, and do NOT substitute another action type to compensate.`
              : null,
            'These counters are authoritative and shared across every Facebook schedule. page_post counts the Page\'s own posts, group_post counts group submissions (visible or pending) from the fb_groups ledger, comment/invite/join count Page-identity actions. Stop the run when your own per-run cap or any ceiling above is reached, whichever comes first.',
          ].filter(Boolean).join('\n');
          context = context ? `${context}\n\n${budgetBlock}` : budgetBlock;
          loopLog(terminalSessionId, 'launch:budget', 'injected FB action budget', { tier, tierSource, spent: spent.total, exhausted });
        }
      } catch (err) {
        loopLog(terminalSessionId, 'launch:budget', 'FB budget injection failed (continuing)', { err: err.message });
      }
    }

    const pendingId = nativeRuntime ? terminalSessionId : 'pending-' + randomBytes(8).toString('hex');
    scheduledLaunchPendingId = pendingId;
    const loopState = {
      active: true,
      task: resolvedSchedTask,
      context: context || null,
      totalIterations: loopIterations,
      currentIteration: 0,
      maxMinutes: loopMaxMinutes,
      startedAt: new Date().toISOString(),
      lastIterationAt: null,
      retries: 0,
      pending: !nativeRuntime,
      terminalSessionId,
      usesBrowser: scheduledUsesBrowser,
      browserSessionId: scheduledBrowserSessionId,
      browserTabId: scheduledBrowserTabId || null,
      profile: cliProfile,
      model: cliModel,
      contextMode: cliContextMode,
      modelContextWindow: launchChoice.modelContextWindow,
      effort: cliEffort || null,
      tools: cliTools, externalMcpVersion: 2,
      ...(platform ? { platform } : {}),
      codexAccountId: codexAccount?.id || null,
      codexHome: codexAccount ? (codexAccount.home || CODEX_DEFAULT_HOME) : null,
      // A Codex exec loop keeps the Admin sandbox setting it started with (every iteration is its own `codex exec`).
      adminSandbox: cliProfile === 'codex' ? adminSandboxOn() : undefined,
      driverType: nativeRuntime ? 'native' : (cliProfile === 'claude-code' ? 'hook' : 'exec'),
      runtimeType: nativeRuntime ? 'native' : 'pty',
      surface: nativeRuntime ? 'sidepanel' : 'terminal',
      runId: nativeRuntime ? terminalSessionId : null,
      cwd: PACKAGE_ROOT,
      scheduledBy: schedule.id,
    };
    writeFileSync(resolve(LOOP_DIR, `${pendingId}.json`), JSON.stringify(loopState, null, 2));

    // Register before the provider starts. A one-turn native run can finish
    // before launch() returns its identity, so registering afterward can leave
    // a completed run stuck in the pending-schedule registry forever.
    registeredScheduledRunId = terminalSessionId;
    _runningScheduledLoops.set(terminalSessionId, {
      groupId: schedule.groupId || null,
      scheduleId: schedule.id,
      name: schedule.name,
      startedAt: Date.now(),
      maxMinutes: loopState.maxMinutes,
    });

    // Stamp the accepted launch before provider bootstrap. Native startup runs
    // asynchronously and may fail or complete before this function resumes;
    // writing "launched" afterward would overwrite that terminal outcome.
    const schedules = loadSchedules();
    const idx = schedules.findIndex(s => s.id === schedule.id);
    if (idx !== -1) {
      schedules[idx].lastRun = new Date().toISOString();
      schedules[idx].lastRunResult = 'launched';
      schedules[idx].runCount = (schedules[idx].runCount || 0) + 1;
      schedules[idx].nextRun = getNextCronRun(schedule.cron, schedule.timezone);
      schedules[idx].updatedAt = new Date().toISOString();
      saveSchedules(schedules);
    }

    // Native providers run headlessly in their durable provider conversation.
    // Gemini and unsupported profiles retain the existing PTY drivers.
    let runDescriptor = null;
    if (nativeRuntime) {
      const presentation = resolveScheduleRunPresentation(
        schedule,
        isSidepanelClaimTokenRevoked,
      );
      runDescriptor = await _nativeLoopRuntime.launch({
        runId: terminalSessionId,
        state: loopState,
        source: presentation.source,
        focus: presentation.focus,
        title: schedule.name || template.name,
        scheduleId: schedule.id,
        claimedBy: presentation.claimedBy,
      });
      pendingNativeBrowserCleanup = null;
      reconcileKeepAwake();
    } else if (cliProfile === 'claude-code') {
      // Per-loop --mcp-config (same as /api/loop/launch): browser pins ride as
      // headers on the loop's own SynaBun HTTP entry — PTY env never reaches
      // the NI-hosted MCP server.
      let schedMcpConfigPath = null;
      try {
        schedMcpConfigPath = setupClaudeLoopMcpConfig(terminalSessionId, scheduledBrowserSessionId, scheduledBrowserTabId, cliTools, PACKAGE_ROOT);
        loopLog(terminalSessionId, 'launch:mcp-config', 'per-loop claude mcp config written (scheduled)', { schedMcpConfigPath });
      } catch (err) {
        throw Object.assign(new Error('Claude MCP scope config could not be written'), { code: 'MCP_SCOPE_UNENFORCED' });
      }
      createTerminalSession(cliProfile, 120, 30, PACKAGE_ROOT, { model: cliModel, effort: cliEffort, extraEnv: schedExtraEnv, sessionId: terminalSessionId, loopBypass: true, mcpConfigPath: schedMcpConfigPath });
      attachLoopDriver(terminalSessionId);
    } else {
      createTerminalSession('shell', 120, 30, PACKAGE_ROOT, { extraEnv: schedExtraEnv, sessionId: terminalSessionId });
      attachExecLoopDriver(terminalSessionId);
    }
    // Browser ownership is now held by the successfully launched runtime/PTY;
    // from this point normal loop-stop cleanup owns it rather than this catch.
    pendingNativeBrowserCleanup = null;
    scheduledLaunchTerminalId = null;
    scheduledLaunchPendingId = null;
    scheduledLaunchProfile = null;
    if (!nativeRuntime) {
      broadcastSync({ type: 'terminal:session-created', sessionId: terminalSessionId, profile: cliProfile });
    }

    broadcastSync({
      type: 'schedule:completed',
      scheduleId: schedule.id,
      pendingId,
      terminalSessionId,
      runId: nativeRuntime ? terminalSessionId : null,
      surface: nativeRuntime ? 'sidepanel' : 'terminal',
      runtimeType: nativeRuntime ? 'native' : 'pty',
      driverType: loopState.driverType,
      provider: cliProfile,
      profile: cliProfile,
      run: runDescriptor,
    });
    console.log(`[schedule] Launched loop for "${schedule.name}" → ${nativeRuntime ? 'sidepanel run' : 'terminal'} ${terminalSessionId} (${cliProfile}/${cliModel || 'default'}/${cliEffort || 'off'}${'/tools:' + serializeToolList(cliTools)})`);
  } catch (err) {
    if (registeredScheduledRunId) _runningScheduledLoops.delete(registeredScheduledRunId);
    if (scheduledLaunchTerminalId) {
      const terminal = terminalSessions.get(scheduledLaunchTerminalId);
      if (terminal) {
        cleanupExecLoopArtifacts(terminal);
        try { terminal.pty.kill(); } catch {}
        terminalSessions.delete(scheduledLaunchTerminalId);
      }
      if (scheduledLaunchProfile === 'opencode') cleanupOpencodeLoopConfig(scheduledLaunchTerminalId);
      if (scheduledLaunchProfile === 'claude-code') cleanupClaudeLoopMcpConfig(scheduledLaunchTerminalId);
    }
    if (scheduledLaunchPendingId) {
      try { unlinkSync(resolve(LOOP_DIR, `${scheduledLaunchPendingId}.json`)); } catch {}
    }
    if (pendingNativeBrowserCleanup) {
      await releaseSharedBrowserTab(
        pendingNativeBrowserCleanup.sessionId,
        pendingNativeBrowserCleanup.ownerKey,
      ).catch(() => {});
    }
    console.error(`[schedule] Failed to launch loop for "${schedule.name}":`, err.message);
    const schedules = loadSchedules();
    const idx = schedules.findIndex(s => s.id === schedule.id);
    if (idx !== -1) {
      schedules[idx].lastRun = new Date().toISOString();
      schedules[idx].lastRunResult = `error: ${err.message}`;
      schedules[idx].nextRun = getNextCronRun(schedule.cron, schedule.timezone);
      saveSchedules(schedules);
    }
    broadcastSync({ type: 'schedule:failed', scheduleId: schedule.id, reason: err.message });
  }
}

// Stagger queue for concurrent schedules firing at the same minute
const _scheduleQueue = [];
let _scheduleQueueRunning = false;
const _deferredMutexSchedules = []; // schedules blocked by mutex, retried each eval tick
// Authoritative in-memory registry of loops launched this process.
// terminalSessionId -> { groupId, scheduleId, name, startedAt, maxMinutes }.
// Closes the launch-to-active gap (loop committed but its loop file not yet visible
// as active) and survives the file-scan window. Self-heals on read (see prune below).
const _runningScheduledLoops = new Map();

// Returns the set of schedule-group ids that currently have a live loop running.
// A group counts as active while ANY of its loops has an active loop file AND a live
// terminal. There is deliberately NO maxMinutes cutoff here: the previous
// `elapsed >= maxMinutes + 5` window let a still-running (but slightly long) loop stop
// blocking, which is exactly how mutex-excluded automations ended up overlapping.
// Liveness is now governed by the loop's own `active` flag plus terminal liveness, so a
// group stops blocking the instant its loop driver marks the loop finished.
// Loop-state file cache (data/loop/*.json) — polled by the queue window every
// 5s and consulted by the scheduler mutex. Written by this server AND the MCP
// server's loop tool (another process), so fs.watch invalidation is mandatory.
// Entries are treated as READ-ONLY by consumers; mutate via the file paths.
let _loopStateCache = null;
let _loopStateWatcher = null;

function _armLoopStateWatcher() {
  if (_loopStateWatcher) return true;
  try {
    const w = fsWatch(LOOP_DIR, () => { _loopStateCache = null; });
    w.unref?.();
    w.on('error', () => {
      _loopStateCache = null;
      _loopStateWatcher = null;
      try { w.close(); } catch {}
    });
    _loopStateWatcher = w;
    return true;
  } catch { return false; /* dir missing — caching disabled until it exists */ }
}

function readLoopStateFiles() {
  if (_loopStateCache) return _loopStateCache;
  const out = [];
  if (existsSync(LOOP_DIR)) {
    let files = [];
    try { files = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json')); } catch {}
    for (const f of files) {
      try { out.push({ file: f, data: JSON.parse(readFileSync(resolve(LOOP_DIR, f), 'utf-8')) }); }
      catch { /* skip corrupt/in-flight file */ }
    }
  }
  if (_armLoopStateWatcher()) _loopStateCache = out;
  return out;
}

function getActiveLoopGroupIds() {
  const activeGroupIds = new Set();
  const activeTsids = new Set(); // compatibility run ids with an active loop file + live runtime

  {
    const allSchedules = loadSchedules();
    for (const { data } of readLoopStateFiles()) {
      if (!data?.active) continue;
      if (data.terminalSessionId && !isLoopRuntimeAlive(data)) continue;
      if (data.terminalSessionId) activeTsids.add(data.terminalSessionId);
      if (data.scheduledBy) {
        const sched = allSchedules.find(s => s.id === data.scheduledBy);
        if (sched?.groupId) activeGroupIds.add(sched.groupId);
      }
    }
  }

  // In-memory registry closes the brief window between "loop committed to launch" and
  // "its loop file is visible as active". Prune entries that are: terminal-dead,
  // finished (file handed off then went inactive, after a launch grace), or wedged
  // (a hard safety cap so a stuck terminal can never block forever).
  const now = Date.now();
  for (const [tsid, info] of [..._runningScheduledLoops]) {
    const ageMs = now - info.startedAt;
    const terminalAlive = terminalSessions.has(tsid) || !!_nativeLoopRuntime?.isAlive(tsid);
    const finished = ageMs > 90_000 && !activeTsids.has(tsid);
    // Hard safety: free the mutex once a loop overruns its own maxMinutes by a small
    // grace (+5, matching the loop-active grace used elsewhere). A slow/stalled
    // claude-code loop must not hold the mutual-exclusion lock for an extra half hour
    // and starve the codex/opencode groups (whose deferred fires get dropped after 1h).
    const wedged = ageMs > ((info.maxMinutes || 30) + 5) * 60_000;
    if (!terminalAlive || finished || wedged) {
      _runningScheduledLoops.delete(tsid);
      continue;
    }
    if (info.groupId) activeGroupIds.add(info.groupId);
  }

  return activeGroupIds;
}

function isMutexBlocked(schedule) {
  if (!schedule.groupId) return false;
  const groups = loadScheduleGroups();
  const myGroup = groups.find(g => g.id === schedule.groupId);
  if (!myGroup?.mutualExclusion) return false;
  const mutexGroupIds = new Set(groups.filter(g => g.mutualExclusion).map(g => g.id));
  const activeGroupIds = getActiveLoopGroupIds();
  for (const gid of mutexGroupIds) {
    if (activeGroupIds.has(gid)) return true;
  }
  return false;
}

async function processScheduleQueue() {
  if (_scheduleQueueRunning) return;
  _scheduleQueueRunning = true;
  while (_scheduleQueue.length > 0) {
    const schedule = _scheduleQueue.shift();
    // Forced fires (manual "Run now", schedule timer fire, quick-timer) are user-initiated
    // and must launch even though they are not "due" by cron. They also include synthetic
    // quick-timer schedules that are NOT persisted, so fall back to the queued snapshot.
    const forced = schedule._forced === true;
    // Drop schedules halted/deleted while they waited in the queue (the backlog can
    // span minutes when staggered or mutex-deferred — the user may halt one mid-wait).
    const persistedQueued = getLaunchableSchedule(schedule.id);
    const freshQueued = persistedQueued
      ? mergeScheduleLaunchSnapshot(persistedQueued, schedule)
      : (forced ? schedule : null);
    if (!freshQueued) {
      console.log(`[schedule] Skipping queued "${schedule.name}" — disabled or deleted before launch`);
      continue;
    }
    // Skip if no longer due: a prior drain in this same pass may have already
    // launched it and advanced nextRun to a future slot. Without this, a stale
    // duplicate queue entry would launch the same schedule a second time. Forced
    // fires bypass this — by definition they are "not due yet" and the user asked
    // for them to run now anyway.
    if (!forced) {
      const stillDue = !freshQueued.nextRun
        || new Date(freshQueued.nextRun) <= new Date()
        || cronMatchesDate(freshQueued.cron, getNowInTimezone(freshQueued.timezone));
      if (!stillDue) {
        console.log(`[schedule] Skipping queued "${schedule.name}" — already launched (nextRun now ${freshQueued.nextRun})`);
        continue;
      }
    }
    // Re-attach the forced flag to the fresh object so launchScheduledLoop honors it too.
    const launchTarget = forced ? { ...freshQueued, _forced: true } : schedule;
    const activeGroups = getActiveLoopGroupIds();
    const blocked = isMutexBlocked(launchTarget);
    console.log(`[schedule:mutex] "${schedule.name}" group=${schedule.groupId} blocked=${blocked} activeGroups=[${[...activeGroups].join(',')}]`);
    if (blocked) {
      const alreadyDeferred = _deferredMutexSchedules.some(d => d.schedule.id === schedule.id);
      if (!alreadyDeferred) {
        // Preserve the forced flag so a mutex-deferred manual fire still bypasses
        // stillDue when the mutex clears and it is retried.
        _deferredMutexSchedules.push({ schedule: launchTarget, deferredAt: Date.now() });
        console.log(`[schedule] Deferred "${schedule.name}" — mutex group conflict (another group is running)`);
        broadcastSync({ type: 'schedule:deferred', scheduleId: schedule.id, scheduleName: schedule.name, reason: 'mutex_blocked' });
      }
      continue;
    }
    await launchScheduledLoop(launchTarget);
    if (_scheduleQueue.length > 0) {
      await new Promise(r => setTimeout(r, 30_000)); // 30s stagger
    }
  }
  _scheduleQueueRunning = false;
}

// How long a deferred schedule is allowed to wait for the mutex before being dropped.
// High-frequency loops keep the original 1h window (they get another fire soon anyway);
// rarely-firing loops (a once- or twice-daily content post) get a longer window so their
// single daily fire is not starved by hourly loops holding the shared lock. Capped so a
// morning post still publishes in the morning, never the afternoon.
function mutexDeferWindowMs(schedule) {
  const perDay = cronFiresPerDay(schedule.cron || '');
  if (perDay <= 2) return 3 * 60 * 60 * 1000;   // <=2x/day -> 3h
  if (perDay <= 6) return 2 * 60 * 60 * 1000;   // <=6x/day -> 2h
  return 60 * 60 * 1000;                          // hourly+ -> 1h (unchanged)
}

function retryDeferredMutexSchedules() {
  if (_deferredMutexSchedules.length === 0) return;
  const now = Date.now();
  const expired = [];
  const retryable = [];
  for (const entry of _deferredMutexSchedules) {
    if (now - entry.deferredAt > mutexDeferWindowMs(entry.schedule)) {
      expired.push(entry);
    } else {
      retryable.push(entry);
    }
  }
  _deferredMutexSchedules.length = 0;
  // Rarest-firing schedules win the freed lock first: a once-daily content post should
  // beat an hourly reply loop when the mutex clears, since the hourly loop gets another
  // chance shortly and the daily one does not.
  retryable.sort((a, b) => cronFiresPerDay(a.schedule.cron || '') - cronFiresPerDay(b.schedule.cron || ''));
  for (const entry of expired) {
    const windowMin = Math.round(mutexDeferWindowMs(entry.schedule) / 60000);
    console.log(`[schedule] Dropping deferred "${entry.schedule.name}" — exceeded ${windowMin}m deferral window`);
    broadcastSync({ type: 'schedule:deferred-expired', scheduleId: entry.schedule.id, scheduleName: entry.schedule.name });
  }
  for (const entry of retryable) {
    // Drop schedules the user halted/deleted while they sat in the mutex backlog,
    // instead of re-queuing them or holding them for the full 1h deferral window.
    if (!getLaunchableSchedule(entry.schedule.id)) {
      console.log(`[schedule] Dropping deferred "${entry.schedule.name}" — disabled or deleted`);
      broadcastSync({ type: 'schedule:deferred-expired', scheduleId: entry.schedule.id, scheduleName: entry.schedule.name });
      continue;
    }
    if (!isMutexBlocked(entry.schedule)) {
      console.log(`[schedule] Retrying deferred "${entry.schedule.name}" — mutex cleared`);
      _scheduleQueue.push(entry.schedule);
    } else {
      _deferredMutexSchedules.push(entry);
    }
  }
  if (_scheduleQueue.length > 0) processScheduleQueue();
}

// ── Keep-awake manager (macOS) ──
// In clamshell / idle, macOS freezes JS timers, which stalls the hook-driven
// claude-code loop driver mid-iteration (codex/opencode exec loops survive
// because their work runs in a child process, but claude-code needs the
// server's setInterval timers alive to advance iterations and to fire the
// evaluator on time). Hold a `caffeinate -i` assertion whenever there is at
// least one enabled schedule OR an active loop terminal, so the machine never
// idle-sleeps while there is scheduling work to do. `-w <pid>` makes caffeinate
// exit automatically if the server is hard-killed, preventing an orphan.
let _caffeinateProc = null;
// pmset disablesleep state: caffeinate -i only blocks *idle* sleep, NOT clamshell
// (lid-closed) sleep, which macOS forces unless on AC + external display. To keep
// firing on time with the lid closed we also flip `pmset -a disablesleep`. This
// needs root, so we try `sudo -n` (non-interactive). If passwordless sudo isn't
// set up it fails gracefully — the overdue catch-up still recovers missed fires,
// just slightly late (on wake) instead of exactly on time.
let _disableSleepApplied = false;
let _disableSleepWarned = false;

function setDisableSleep(on) {
  if (process.platform !== 'darwin') return;
  if (on && _disableSleepApplied) return;
  if (!on && !_disableSleepApplied) return;
  try {
    const child = spawn('sudo', ['-n', 'pmset', '-a', 'disablesleep', on ? '1' : '0'], { stdio: 'ignore' });
    child.on('exit', (code) => {
      if (code === 0) {
        _disableSleepApplied = on;
        console.log(`[keep-awake] pmset disablesleep ${on ? 'ON (lid-close sleep blocked)' : 'OFF (sleep restored)'}`);
      } else if (on && !_disableSleepWarned) {
        _disableSleepWarned = true;
        console.warn('[keep-awake] Could not set `pmset disablesleep` (needs root). Clamshell sleep will still freeze timers; missed fires recover via overdue catch-up on wake. To prevent sleep entirely, run once: `sudo pmset -a disablesleep 1` (or add a NOPASSWD sudoers entry for /usr/bin/pmset).');
      }
    });
    child.on('error', (err) => {
      if (on && !_disableSleepWarned) {
        _disableSleepWarned = true;
        console.warn('[keep-awake] pmset spawn failed:', err.message);
      }
    });
    child.unref();
  } catch (err) {
    if (on && !_disableSleepWarned) {
      _disableSleepWarned = true;
      console.warn('[keep-awake] pmset spawn failed:', err.message);
    }
  }
}

// Synchronous restore for the `exit` handler — async spawn never completes once
// the event loop is tearing down, so leaving disablesleep=1 would wedge the
// machine permanently awake. Best-effort, fast, non-interactive.
function restoreSleepSync() {
  if (process.platform !== 'darwin' || !_disableSleepApplied) return;
  try {
    spawnSync('sudo', ['-n', 'pmset', '-a', 'disablesleep', '0'], { stdio: 'ignore', timeout: 3000 });
    _disableSleepApplied = false;
  } catch { /* best-effort */ }
}

function setKeepAwake(on) {
  if (process.platform !== 'darwin') return;
  if (on) {
    setDisableSleep(true);
    if (_caffeinateProc && _caffeinateProc.exitCode === null) return;
    try {
      _caffeinateProc = spawn('caffeinate', ['-i', '-w', String(process.pid)], { stdio: 'ignore' });
      _caffeinateProc.on('exit', () => { _caffeinateProc = null; });
      _caffeinateProc.on('error', (err) => { console.warn('[keep-awake] caffeinate error:', err.message); _caffeinateProc = null; });
      _caffeinateProc.unref();
      console.log('[keep-awake] caffeinate ON (preventing idle sleep)');
    } catch (err) {
      console.warn('[keep-awake] caffeinate spawn failed:', err.message);
    }
  } else {
    setDisableSleep(false);
    if (_caffeinateProc) {
      try { _caffeinateProc.kill('SIGTERM'); } catch { /* ok */ }
      _caffeinateProc = null;
      console.log('[keep-awake] caffeinate OFF (no scheduling work)');
    }
  }
}

// Reconcile the keep-awake assertion against current desired state. Cheap and
// idempotent — safe to call from the evaluator tick, loop start, and loop exit.
function reconcileKeepAwake() {
  let active = false;
  try { active = loadSchedules().some(s => s.enabled); } catch { /* ok */ }
  if (!active) {
    for (const s of terminalSessions.values()) {
      if (s && s._loopTerminalSessionId) { active = true; break; }
    }
  }
  if (!active && _nativeLoopRuntime?.list({ activeOnly: true }).length) active = true;
  setKeepAwake(active);
}

function evaluateSchedules() {
  // P5 deterministic health shares the scheduler's tick; disabled until enabled in Skills Studio.
  skillsService?.health.tick().catch((error) => console.error('[skills-health]', error?.code || 'check_failed'));
  _scheduleEvalCount++;
  const schedules = loadSchedules();
  const enabled = schedules.filter(s => s.enabled);

  // Log every 5th eval (~5 min) or when schedules exist
  if (enabled.length > 0 || _scheduleEvalCount % 5 === 0) {
    console.log(`[schedule] Eval #${_scheduleEvalCount}: ${enabled.length} enabled / ${schedules.length} total`);
  }

  let staleAdvanced = false;
  for (const schedule of schedules) {
    if (!schedule.enabled) continue;
    const tz = schedule.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone;
    const now = getNowInTimezone(tz);

    // Minute-level dedup key to prevent double-fires
    const fireKey = `${schedule.id}:${now.getFullYear()}-${now.getMonth()}-${now.getDate()}-${now.getHours()}-${now.getMinutes()}`;
    if (_scheduleFiringLock.has(fireKey)) continue;

    const matches = cronMatchesDate(schedule.cron, now);
    // Overdue catch-up: fire when nextRun has passed even if no evaluator tick
    // landed inside the exact cron minute (e.g. macOS froze JS timers during
    // clamshell/idle sleep). launchScheduledLoop advances nextRun to the next
    // *future* slot, so a schedule that slept through several slots fires once and
    // skips ahead — it never replays every missed slot and never silently drops
    // the fire (the previous "%5 stale refresh" used to discard missed fires).
    const overdueMs = schedule.nextRun ? (Date.now() - new Date(schedule.nextRun).getTime()) : -1;
    const overdue = overdueMs >= 0;
    if (enabled.length > 0 && _scheduleEvalCount % 5 === 0) {
      console.log(`[schedule]   "${schedule.name}" cron=${schedule.cron} now=${now.getHours()}:${String(now.getMinutes()).padStart(2,'0')} match=${matches} overdue=${overdue}`);
    }

    // Stale miss: overdue by more than the freshness window and NOT a current cron
    // match. Don't fire a late run (a morning post must not publish in the
    // afternoon) — advance nextRun to the next future slot so it resumes on
    // schedule. Skip while pending so we don't race launchScheduledLoop's own
    // nextRun update. Fresh misses (within the window) still fire as catch-up below.
    if (overdue && !matches && overdueMs > CATCHUP_FRESHNESS_MS) {
      if (!isSchedulePending(schedule.id)) {
        const fresh = getNextCronRun(schedule.cron, schedule.timezone);
        if (fresh && fresh !== schedule.nextRun) {
          schedule.nextRun = fresh;
          schedule.updatedAt = new Date().toISOString();
          staleAdvanced = true;
          console.log(`[schedule] Stale miss for "${schedule.name}" (overdue ${Math.round(overdueMs / 60000)}m > ${CATCHUP_FRESHNESS_MS / 60000}m window) — skipped, advanced nextRun to ${fresh}`);
        }
      }
      continue;
    }

    if (matches || overdue) {
      // If dayThemes are defined and current day has no entry, skip
      if (schedule.dayThemes && Object.keys(schedule.dayThemes).length > 0) {
        if (!schedule.dayThemes[String(now.getDay())]) {
          console.log(`[schedule]   Skipped "${schedule.name}" — no dayTheme for day ${now.getDay()}`);
          continue;
        }
      }

      // Stampede guard: never pile a second copy of a schedule that is already
      // queued, mutex-deferred, or actively running. Stops the overdue catch-up
      // from re-enqueuing the same schedule every tick while a long loop holds
      // the mutex (which caused the on-wake stack of duplicate launches).
      if (isSchedulePending(schedule.id)) {
        if (_scheduleEvalCount % 5 === 0) {
          console.log(`[schedule]   "${schedule.name}" already pending (queued/deferred/running) — skip re-enqueue`);
        }
        continue;
      }

      if (overdue && !matches) {
        console.log(`[schedule] ✓ Overdue catch-up for "${schedule.name}" at ${now.toLocaleString()} (was due ${schedule.nextRun})`);
      } else {
        console.log(`[schedule] ✓ Cron match for "${schedule.name}" at ${now.toLocaleString()}`);
      }
      _scheduleFiringLock.add(fireKey);
      setTimeout(() => _scheduleFiringLock.delete(fireKey), 120_000);

      _scheduleQueue.push(schedule);
      processScheduleQueue();
    }
  }

  // Persist any nextRun values advanced past stale (beyond-window) misses so they
  // don't re-trigger the stale-skip every tick.
  if (staleAdvanced) saveSchedules(schedules);

  retryDeferredMutexSchedules();

  // Keep the machine awake whenever there is scheduling work, so this very
  // evaluator (and the hook-driven claude-code loop driver) can't be frozen by
  // macOS idle-sleep in clamshell. Cheap + idempotent.
  reconcileKeepAwake();

  // NOTE: the old "%5 stale nextRun refresh" was removed here. It advanced an
  // overdue nextRun to the next slot *without firing*, which is exactly how
  // morning posts were silently dropped after the machine slept through their
  // fire minute. Overdue schedules now fire via the catch-up branch above, and
  // nextRun is advanced by launchScheduledLoop only after the fire is queued.
}

function startScheduleEvaluator() {
  stopScheduleEvaluator();
  _scheduleEvaluatorTimer = setInterval(evaluateSchedules, SCHEDULE_EVAL_INTERVAL);
  console.log('[schedule] Evaluator started (60s interval)');

  // Assert keep-awake just after boot so the very first fire isn't missed to an
  // idle-sleep that started before the first evaluator tick. Deferred one tick so
  // the module-level globals it reads (terminalSessions, declared later in the
  // file) are initialized — calling it synchronously here is a TDZ ReferenceError
  // on a fresh boot with no enabled schedules.
  setTimeout(reconcileKeepAwake, 0);

  // Deferred missed-fire check (wait for terminalSessions and other globals to init).
  // Boot-time counterpart to the evaluator's overdue catch-up, with the same
  // freshness window: a fire missed within CATCHUP_FRESHNESS_MS is caught up once;
  // an older (stale) miss is skipped and its nextRun advanced to the next future
  // slot, so restarting after an overnight sleep doesn't dump a backlog of stale
  // runs. launchScheduledLoop resets nextRun for the ones that do fire.
  setTimeout(() => {
    const schedules = loadSchedules();
    const now = Date.now();
    let caughtUp = 0, staleAdvanced = false;
    for (const schedule of schedules) {
      if (!schedule.enabled || !schedule.nextRun) continue;
      const overdueMs = now - new Date(schedule.nextRun).getTime();
      if (overdueMs < 0) continue;
      if (overdueMs > CATCHUP_FRESHNESS_MS) {
        const fresh = getNextCronRun(schedule.cron, schedule.timezone);
        if (fresh && fresh !== schedule.nextRun) {
          schedule.nextRun = fresh;
          schedule.updatedAt = new Date().toISOString();
          staleAdvanced = true;
          console.log(`[schedule] Boot: stale miss for "${schedule.name}" (overdue ${Math.round(overdueMs / 60000)}m) — skipped, advanced nextRun to ${fresh}`);
        }
        continue;
      }
      if (isSchedulePending(schedule.id)) continue;
      console.log(`[schedule] Boot catch-up for "${schedule.name}" (was due ${schedule.nextRun})`);
      _scheduleQueue.push(schedule);
      caughtUp++;
    }
    if (staleAdvanced) saveSchedules(schedules);
    if (caughtUp > 0) processScheduleQueue();
  }, 10_000);
}

function stopScheduleEvaluator() {
  if (_scheduleEvaluatorTimer) {
    clearInterval(_scheduleEvaluatorTimer);
    _scheduleEvaluatorTimer = null;
  }
}

// Boot: start schedule evaluator
migrateAutomationContextFiles(LOOP_DATA_DIR);
startScheduleEvaluator();

// ── Quick Timer (standalone, no schedule needed) ──

const _quickTimers = new Map(); // timerId → { timeoutId, templateId, templateName, firesAt, minutes, profile, model, effort, tools, platform, usesBrowser, createdAt }

function launchQuickTimer(timerId, templateId, context) {
  const templates = readLoopTemplates();
  const template = templates.find(t => t.id === templateId);
  if (!template) {
    console.warn(`[quick-timer] Template ${templateId} not found`);
    broadcastSync({ type: 'quick-timer:failed', timerId, reason: 'template_missing' });
    return;
  }
  const timerData = _quickTimers.get(timerId) || {};
  const fakeSchedule = {
    id: `qt-${timerId}`,
    name: `Quick: ${template.name}`,
    templateId,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    dayThemes: {},
    profile: timerData.profile || undefined,
    model: timerData.model || undefined,
    contextMode: timerData.contextMode || undefined,
    effort: timerData.effort || undefined,
    tools: storedToolList(timerData, toolListOptions()),
    platform: timerData.platform,
    codexAccountId: timerData.codexAccountId || undefined,
    usesBrowser: timerData.usesBrowser,
    // Synthetic schedule (not persisted) — must bypass the queue's stillDue and
    // disabled/deleted guards, both of which key off persisted schedule state.
    _forced: true,
    _quickTimer: true,
  };
  console.log(`[quick-timer] Firing "${template.name}" (timer ${timerId}) profile=${fakeSchedule.profile || 'default'} model=${fakeSchedule.model || 'default'}`);
  _scheduleQueue.push(fakeSchedule);
  processScheduleQueue();
  broadcastSync({ type: 'quick-timer:fired', timerId, templateName: template.name });
}

// POST /api/quick-timer — fire a template after N minutes (standalone, no schedule)
app.post('/api/quick-timer', async (req, res) => {
  try {
    const { templateId, minutes, context, profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId } = req.body;
    const mins = Number(minutes);
    if (!templateId?.trim()) return res.status(400).json({ error: 'templateId is required' });
    if (!mins || mins < 1 || mins > 1440) return res.status(400).json({ error: 'minutes must be 1–1440' });

    const templates = readLoopTemplates();
    const template = templates.find(t => t.id === templateId);
    if (!template) return res.status(400).json({ error: 'Template not found' });

    const timerId = randomBytes(8).toString('hex');
    const firesAt = new Date(Date.now() + mins * 60_000).toISOString();
    const timerProfile = profile || 'claude-code';
    const selection = normalizeAutomationSelection(timerProfile, model, contextMode);
    if (!validAutomationContextMode(timerProfile, selection.contextMode)) return res.status(400).json({ error: `Invalid context mode: ${selection.contextMode}` });
    const timerModel = selection.model;
    const timerContextMode = selection.contextMode || 'default';
    const timerEffort = effort || null;
    const timerTools = launchToolList({ tools }, { provider: timerProfile, usesBrowser: usesBrowser ?? template.usesBrowser }).items;
    const timerCodexAccountId = timerProfile === 'codex' ? (codexAccountId || 'default') : null;
    const timerCodexAccount = timerProfile === 'codex' ? findCodexAccount(timerCodexAccountId) : null;
    if (timerProfile === 'codex' && !timerCodexAccount) return res.status(400).json({ error: `Codex account not found: ${timerCodexAccountId}` });
    try { await resolveAutomationLaunchChoice(timerProfile, timerModel, timerContextMode, timerCodexAccount?.home); }
    catch (error) { return res.status(400).json({ error: error.message }); }
    const timerUsesBrowser = usesBrowser !== undefined ? !!usesBrowser : !!template.usesBrowser;

    const timeoutId = setTimeout(() => {
      launchQuickTimer(timerId, templateId, context);
      _quickTimers.delete(timerId);
    }, mins * 60_000);

    _quickTimers.set(timerId, { timeoutId, templateId, templateName: template.name, firesAt, minutes: mins, profile: timerProfile, model: timerModel, contextMode: timerContextMode, effort: timerEffort, tools: timerTools, platform: automationPlatform({ platform }, null, template), codexAccountId: timerCodexAccountId, usesBrowser: timerUsesBrowser, createdAt: new Date().toISOString() });
    console.log(`[quick-timer] Set: "${template.name}" fires in ${mins}m at ${firesAt} (${timerProfile}/${timerModel || 'default'}${timerEffort ? '/' + timerEffort : ''}${'/tools:' + serializeToolList(timerTools)})`);
    broadcastSync({ type: 'quick-timer:set', timerId, templateName: template.name, firesAt, minutes: mins, profile: timerProfile, model: timerModel, contextMode: timerContextMode, effort: timerEffort, tools: timerTools, platform: automationPlatform({ platform }, null, template), usesBrowser: timerUsesBrowser });
    res.json({ ok: true, timerId, templateName: template.name, firesAt, minutes: mins, profile: timerProfile, model: timerModel, contextMode: timerContextMode, effort: timerEffort, tools: timerTools, platform: automationPlatform({ platform }, null, template), usesBrowser: timerUsesBrowser });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// GET /api/quick-timers — list active quick timers
app.get('/api/quick-timers', (_req, res) => {
  const timers = [];
  for (const [id, t] of _quickTimers) {
    timers.push({ id, templateId: t.templateId, templateName: t.templateName, firesAt: t.firesAt, minutes: t.minutes, profile: t.profile, model: t.model, contextMode: t.contextMode, effort: t.effort, tools: storedToolList(t, toolListOptions()), usesBrowser: t.usesBrowser, createdAt: t.createdAt });
  }
  res.json(timers);
});

// DELETE /api/quick-timers/:id — cancel a quick timer
app.delete('/api/quick-timers/:id', (req, res) => {
  const timer = _quickTimers.get(req.params.id);
  if (!timer) return res.status(404).json({ error: 'Timer not found' });
  clearTimeout(timer.timeoutId);
  _quickTimers.delete(req.params.id);
  console.log(`[quick-timer] Cancelled timer ${req.params.id}`);
  broadcastSync({ type: 'quick-timer:cancelled', timerId: req.params.id });
  res.json({ ok: true });
});

// POST /api/quick-timer/now — fire a template immediately (same pipeline as scheduled, for debugging)
app.post('/api/quick-timer/now', async (req, res) => {
  try {
    const {
      templateId, profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId,
      sidepanelWindowId, sidepanelClaimToken,
    } = req.body;
    if (!templateId?.trim()) return res.status(400).json({ error: 'templateId is required' });

    const templates = readLoopTemplates();
    const template = templates.find(t => t.id === templateId);
    if (!template) return res.status(400).json({ error: 'Template not found' });

    const timerProfile = profile || 'claude-code';
    const selection = normalizeAutomationSelection(timerProfile, model, contextMode);
    if (!validAutomationContextMode(timerProfile, selection.contextMode)) return res.status(400).json({ error: `Invalid context mode: ${selection.contextMode}` });
    const timerModel = selection.model;
    const timerContextMode = selection.contextMode || 'default';
    const timerEffort = effort || null;
    const timerTools = launchToolList({ tools }, { provider: timerProfile, usesBrowser: usesBrowser ?? template.usesBrowser }).items;
    const timerCodexAccountId = timerProfile === 'codex' ? (codexAccountId || 'default') : null;
    const timerCodexAccount = timerProfile === 'codex' ? findCodexAccount(timerCodexAccountId) : null;
    if (timerProfile === 'codex' && !timerCodexAccount) return res.status(400).json({ error: `Codex account not found: ${timerCodexAccountId}` });
    try { await resolveAutomationLaunchChoice(timerProfile, timerModel, timerContextMode, timerCodexAccount?.home); }
    catch (error) { return res.status(400).json({ error: error.message }); }
    const timerUsesBrowser = usesBrowser !== undefined ? !!usesBrowser : !!template.usesBrowser;

    const fakeSchedule = {
      id: `qt-now-${randomBytes(4).toString('hex')}`,
      name: `Now: ${template.name}`,
      templateId,
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      dayThemes: {},
      profile: timerProfile,
      model: timerModel,
      contextMode: timerContextMode,
      effort: timerEffort,
      tools: timerTools, platform: automationPlatform({ platform }, null, template),
      codexAccountId: timerCodexAccountId || undefined,
      usesBrowser: timerUsesBrowser,
      // Synthetic schedule (not persisted) — must bypass the queue's stillDue and
      // disabled/deleted guards, both of which key off persisted schedule state.
      _forced: true,
      _quickTimer: true,
      _sidepanelLaunch: createScheduleSidepanelIntent({ sidepanelWindowId, sidepanelClaimToken }),
    };

    console.log(`[quick-timer] Firing NOW "${template.name}" profile=${timerProfile} model=${timerModel || 'default'}${timerEffort ? ' effort=' + timerEffort : ''}${' tools=' + serializeToolList(timerTools)}`);
    _scheduleQueue.push(fakeSchedule);
    processScheduleQueue();

    broadcastSync({ type: 'quick-timer:fired-now', templateName: template.name, profile: timerProfile, model: timerModel, contextMode: timerContextMode, effort: timerEffort, tools: timerTools });
    res.json({ ok: true, templateName: template.name, profile: timerProfile, model: timerModel, contextMode: timerContextMode, effort: timerEffort, tools: timerTools, platform: automationPlatform({ platform }, null, template), usesBrowser: timerUsesBrowser });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// ── Schedule Group REST API ──

app.get('/api/schedule-groups', (_req, res) => {
  res.json(loadScheduleGroups());
});

app.post('/api/schedule-groups', (req, res) => {
  try {
    const { name, color, icon, collapsed, mutualExclusion, profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId } = req.body || {};
    if (unknownAutomationContextMode(contextMode)) return res.status(400).json({ error: `Invalid context mode: ${contextMode}` });
    if (!name?.trim()) return res.status(400).json({ error: 'name is required' });

    const groups = loadScheduleGroups();
    const group = {
      id: `sg_${randomBytes(6).toString('hex')}`,
      name: name.trim(),
      color: color || null,
      icon: icon || null,
      order: groups.length,
      collapsed: !!collapsed,
      mutualExclusion: !!mutualExclusion,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    applyScheduleLaunchOverrides(group, { profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId });
    groups.push(group);
    saveScheduleGroups(groups);
    broadcastSync({ type: 'schedule-group:created', group });
    res.json(group);
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

app.put('/api/schedule-groups/:id', (req, res) => {
  try {
    const store = loadScheduleStore();
    const groups = store.groups;
    const idx = groups.findIndex(g => g.id === req.params.id);
    if (idx === -1) return res.status(404).json({ error: 'Group not found' });

    const { name, color, icon, collapsed, order, mutualExclusion, profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId } = req.body || {};
    if (unknownAutomationContextMode(contextMode)) return res.status(400).json({ error: `Invalid context mode: ${contextMode}` });
    if (name !== undefined) {
      if (!name.trim()) return res.status(400).json({ error: 'name is required' });
      groups[idx].name = name.trim();
    }
    if (color !== undefined) groups[idx].color = color || null;
    if (icon !== undefined) groups[idx].icon = icon || null;
    if (collapsed !== undefined) groups[idx].collapsed = !!collapsed;
    if (order !== undefined && typeof order === 'number') groups[idx].order = order;
    if (mutualExclusion !== undefined) groups[idx].mutualExclusion = !!mutualExclusion;
    // Snapshot the group's prior launch values BEFORE mutating it, so we can tell
    // which launch fields the user actually CHANGED in this save.
    const prevGroupLaunch = {
      profile: groups[idx].profile,
      model: groups[idx].model,
      contextMode: groups[idx].contextMode,
      effort: groups[idx].effort,
      tools: groups[idx].tools,
      usesBrowser: groups[idx].usesBrowser,
      codexAccountId: groups[idx].codexAccountId,
    };
    applyScheduleLaunchOverrides(groups[idx], { profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId });
    groups[idx].updatedAt = new Date().toISOString();

    // Write-through: a launch override deliberately CHANGED in the group window is
    // pushed onto every schedule in that group. Critically, propagate ONLY the fields
    // the user actually changed (incoming differs from the group's prior value). The
    // Studio always sends every launch field, so without this diff a plain name/color/
    // mutex save — or just re-opening and saving the group — would clobber each
    // schedule's own model/profile back to the group's value. Per-schedule overrides
    // win at launch (cliModel = schedule.model || group.model || template.model), so
    // they must survive unrelated group saves.
    const normLaunch = (v) => (v === '' || v === undefined ? null : v);
    const propagation = {};
    for (const [field, value] of [
      ['profile', profile], ['model', model], ['contextMode', contextMode], ['effort', effort],
      ['tools', tools], ['usesBrowser', usesBrowser], ['codexAccountId', codexAccountId],
    ]) {
      if (value === undefined) continue; // field absent from this request
      if (JSON.stringify(normLaunch(value)) === JSON.stringify(normLaunch(prevGroupLaunch[field]))) continue; // unchanged — don't touch schedules
      propagation[field] = value;
    }
    const changedSchedules = [];
    if (Object.keys(propagation).length) {
      const now = new Date().toISOString();
      for (const schedule of store.schedules) {
        if (schedule.groupId !== req.params.id) continue;
        applyScheduleLaunchOverrides(schedule, propagation);
        schedule.updatedAt = now;
        changedSchedules.push(schedule);
      }
    }

    saveScheduleStore(store);
    broadcastSync({ type: 'schedule-group:updated', group: groups[idx] });
    for (const schedule of changedSchedules) {
      broadcastSync({ type: 'schedule:updated', schedule });
    }
    res.json(groups[idx]);
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

app.delete('/api/schedule-groups/:id', (req, res) => {
  try {
    const groups = loadScheduleGroups();
    const idx = groups.findIndex(g => g.id === req.params.id);
    if (idx === -1) return res.status(404).json({ error: 'Group not found' });
    groups.splice(idx, 1);

    const schedules = loadSchedules();
    let unassigned = 0;
    for (const schedule of schedules) {
      if (schedule.groupId === req.params.id) {
        schedule.groupId = null;
        schedule.updatedAt = new Date().toISOString();
        unassigned++;
      }
    }

    saveScheduleStore({ schedules, groups });
    broadcastSync({ type: 'schedule-group:deleted', groupId: req.params.id, schedulesUnassigned: unassigned });
    res.json({ ok: true, id: req.params.id, schedulesUnassigned: unassigned });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

app.post('/api/schedule-groups/reorder', (req, res) => {
  try {
    const { orderedIds } = req.body || {};
    if (!Array.isArray(orderedIds)) return res.status(400).json({ error: 'orderedIds array required' });

    const groups = loadScheduleGroups();
    const byId = new Map(groups.map(g => [g.id, g]));
    let order = 0;
    for (const id of orderedIds) {
      const group = byId.get(id);
      if (group) {
        group.order = order++;
        group.updatedAt = new Date().toISOString();
      }
    }
    for (const group of groups) {
      if (!orderedIds.includes(group.id)) group.order = order++;
    }
    saveScheduleGroups(groups);
    broadcastSync({ type: 'schedule-group:reordered', groups });
    res.json({ ok: true });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// GET /api/schedules/mutex-status — diagnostic: check mutex state
app.get('/api/schedules/mutex-status', (_req, res) => {
  try {
    const activeGroupIds = getActiveLoopGroupIds();
    const groups = loadScheduleGroups();
    const loopFiles = [];
    for (const { file: f, data } of readLoopStateFiles()) {
      try {
        loopFiles.push({
          file: f,
          active: data.active,
          pending: data.pending,
          scheduledBy: data.scheduledBy,
          terminalSessionId: data.terminalSessionId,
          terminalAlive: data.terminalSessionId ? isLoopRuntimeAlive(data) : null,
          runtimeType: data.runtimeType || 'pty',
          startedAt: data.startedAt,
          elapsedMin: data.startedAt ? Math.round((Date.now() - new Date(data.startedAt).getTime()) / 60000) : null,
        });
      } catch { /* skip */ }
    }
    res.json({
      activeGroupIds: [...activeGroupIds],
      mutexGroups: groups.filter(g => g.mutualExclusion).map(g => ({ id: g.id, name: g.name })),
      deferredCount: _deferredMutexSchedules.length,
      deferred: _deferredMutexSchedules.map(d => ({ id: d.schedule.id, name: d.schedule.name, deferredAt: new Date(d.deferredAt).toISOString() })),
      loopFiles,
    });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// GET /api/schedules/queue — live queue state for the Schedule Queue window
app.get('/api/schedules/queue', (_req, res) => {
  try {
    const allSchedules = loadSchedules();
    const groups = loadScheduleGroups();
    const groupById = new Map(groups.map(g => [g.id, g]));

    const running = [];
    for (const { file: f, data } of readLoopStateFiles()) {
      try {
        if (!data?.active) continue;
        const elapsed = Date.now() - new Date(data.startedAt).getTime();
        const maxMs = ((data.maxMinutes || 30) + 5) * 60 * 1000;
        if (elapsed >= maxMs) continue;
        if (data.terminalSessionId && !isLoopRuntimeAlive(data)) continue;
        const sched = data.scheduledBy ? allSchedules.find(s => s.id === data.scheduledBy) : null;
        const group = sched?.groupId ? groupById.get(sched.groupId) : null;
        running.push({
          sessionId: f.replace('.json', ''),
          scheduleName: sched?.name || data.task?.slice(0, 60) || 'Unknown',
          scheduleId: data.scheduledBy || null,
          groupId: group?.id || null,
          groupName: group?.name || null,
          groupColor: group?.color || null,
          mutex: !!group?.mutualExclusion,
          startedAt: data.startedAt,
          elapsedMin: Math.round(elapsed / 60000),
          maxMinutes: data.maxMinutes || 30,
          iteration: data.currentIteration || 0,
          totalIterations: data.totalIterations || 0,
        });
      } catch { /* skip */ }
    }

    const queued = _scheduleQueue.map(s => {
      const group = s.groupId ? groupById.get(s.groupId) : null;
      return { id: s.id, name: s.name, groupName: group?.name || null, groupColor: group?.color || null };
    });

    // One active-group scan for ALL deferred entries — this used to rescan
    // the loop dir once per deferred schedule.
    const activeGroupIds = _deferredMutexSchedules.length ? getActiveLoopGroupIds() : null;
    const deferred = _deferredMutexSchedules.map(d => {
      const group = d.schedule.groupId ? groupById.get(d.schedule.groupId) : null;
      const blockedByGroups = groups.filter(g => g.mutualExclusion && g.id !== d.schedule.groupId);
      const blockedBy = blockedByGroups.filter(g => activeGroupIds.has(g.id)).map(g => g.name);
      return {
        id: d.schedule.id, name: d.schedule.name,
        groupName: group?.name || null, groupColor: group?.color || null,
        deferredAt: new Date(d.deferredAt).toISOString(),
        deferredMin: Math.round((Date.now() - d.deferredAt) / 60000),
        blockedBy,
      };
    });

    const nowISO = new Date();
    const upcoming = allSchedules
      .filter(s => s.enabled && s.nextRun)
      .map(s => {
        const group = s.groupId ? groupById.get(s.groupId) : null;
        let nr = s.nextRun;
        if (new Date(nr) < nowISO) nr = getNextCronRun(s.cron, s.timezone) || nr;
        return {
          id: s.id, name: s.name, cron: s.cron,
          groupName: group?.name || null, groupColor: group?.color || null,
          mutex: !!group?.mutualExclusion,
          nextRun: nr,
        };
      })
      .filter(s => new Date(s.nextRun) > nowISO)
      .sort((a, b) => new Date(a.nextRun) - new Date(b.nextRun))
      .slice(0, 8);

    res.json({ running, queued, deferred, upcoming });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// ── Schedule REST API ──

// GET /api/schedules — list all schedules
app.get('/api/schedules', (_req, res) => {
  res.json(loadSchedules());
});

// GET /api/schedules/timers — list all active timers (must be before :id routes)
app.get('/api/schedules/timers', (_req, res) => {
  const timers = {};
  for (const [id, t] of _scheduleTimers) {
    timers[id] = { firesAt: t.firesAt, minutes: t.minutes };
  }
  res.json(timers);
});

// POST /api/schedules — create a new schedule
app.post('/api/schedules', (req, res) => {
  try {
    const { name, templateId, cron, timezone, enabled, dayThemes, overrides, groupId, profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId } = req.body;
    if (unknownAutomationContextMode(contextMode)) return res.status(400).json({ error: `Invalid context mode: ${contextMode}` });
    if (!name?.trim()) return res.status(400).json({ error: 'name is required' });
    if (!templateId?.trim()) return res.status(400).json({ error: 'templateId is required' });
    if (!cron?.trim()) return res.status(400).json({ error: 'cron is required' });
    if (cron.trim().split(/\s+/).length !== 5) return res.status(400).json({ error: 'cron must be a 5-field expression' });

    const templates = readLoopTemplates();
    if (!templates.find(t => t.id === templateId)) return res.status(400).json({ error: 'Template not found' });
    const normalizedGroupId = validateScheduleGroupId(groupId);
    if (normalizedGroupId === false) return res.status(400).json({ error: 'Group not found' });

    const tz = timezone || Intl.DateTimeFormat().resolvedOptions().timeZone;
    const schedule = {
      id: randomBytes(12).toString('hex'),
      name: name.trim(),
      templateId,
      cron: cron.trim(),
      timezone: tz,
      enabled: enabled !== false,
      groupId: normalizedGroupId,
      dayThemes: dayThemes || {},
      overrides: overrides || {},
      lastRun: null,
      lastRunResult: null,
      nextRun: getNextCronRun(cron.trim(), tz),
      runCount: 0,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    applyScheduleLaunchOverrides(schedule, { profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId });

    const schedules = loadSchedules();
    schedules.push(schedule);
    saveSchedules(schedules);

    broadcastSync({ type: 'schedule:created', schedule });
    res.json(schedule);
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// GET /api/schedules/:id — get a single schedule
app.get('/api/schedules/:id', (req, res) => {
  const schedules = loadSchedules();
  const schedule = schedules.find(s => s.id === req.params.id);
  if (!schedule) return res.status(404).json({ error: 'Schedule not found' });
  res.json(schedule);
});

// PUT /api/schedules/:id — update a schedule
app.put('/api/schedules/:id', (req, res) => {
  try {
    const schedules = loadSchedules();
    const idx = schedules.findIndex(s => s.id === req.params.id);
    if (idx === -1) return res.status(404).json({ error: 'Schedule not found' });

    const { name, templateId, cron, timezone, enabled, dayThemes, overrides, groupId, profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId } = req.body;
    if (unknownAutomationContextMode(contextMode)) return res.status(400).json({ error: `Invalid context mode: ${contextMode}` });
    if (name !== undefined) schedules[idx].name = name.trim();
    if (templateId !== undefined) {
      const templates = readLoopTemplates();
      if (!templates.find(t => t.id === templateId)) return res.status(400).json({ error: 'Template not found' });
      schedules[idx].templateId = templateId;
    }
    if (cron !== undefined) {
      if (cron.trim().split(/\s+/).length !== 5) return res.status(400).json({ error: 'cron must be a 5-field expression' });
      schedules[idx].cron = cron.trim();
    }
    if (timezone !== undefined) schedules[idx].timezone = timezone;
    if (typeof enabled === 'boolean') schedules[idx].enabled = enabled;
    if (dayThemes !== undefined) schedules[idx].dayThemes = dayThemes;
    if (overrides !== undefined) schedules[idx].overrides = overrides;
    if (groupId !== undefined) {
      const normalizedGroupId = validateScheduleGroupId(groupId);
      if (normalizedGroupId === false) return res.status(400).json({ error: 'Group not found' });
      schedules[idx].groupId = normalizedGroupId;
    }
    applyScheduleLaunchOverrides(schedules[idx], { profile, model, contextMode, effort, tools, platform, usesBrowser, codexAccountId });

    schedules[idx].updatedAt = new Date().toISOString();
    schedules[idx].nextRun = getNextCronRun(schedules[idx].cron, schedules[idx].timezone);
    saveSchedules(schedules);

    broadcastSync({ type: 'schedule:updated', schedule: schedules[idx] });
    res.json(schedules[idx]);
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// DELETE /api/schedules/:id — delete a schedule
app.delete('/api/schedules/:id', (req, res) => {
  try {
    const schedules = loadSchedules();
    const idx = schedules.findIndex(s => s.id === req.params.id);
    if (idx === -1) return res.status(404).json({ error: 'Schedule not found' });
    const removed = schedules.splice(idx, 1)[0];
    saveSchedules(schedules);
    // Cancel any pending timer
    if (_scheduleTimers.has(removed.id)) {
      clearTimeout(_scheduleTimers.get(removed.id).timeoutId);
      _scheduleTimers.delete(removed.id);
    }
    broadcastSync({ type: 'schedule:deleted', scheduleId: removed.id });
    res.json({ ok: true, id: removed.id });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// POST /api/schedules/:id/test — fire a schedule immediately for testing
app.post('/api/schedules/:id/test', async (req, res) => {
  try {
    const schedules = loadSchedules();
    const schedule = schedules.find(s => s.id === req.params.id);
    if (!schedule) return res.status(404).json({ error: 'Schedule not found' });
    // Forced: the user explicitly clicked "Run now". A manual fire is by definition
    // "not due yet" (nextRun is in the future, the current minute doesn't match cron),
    // so it must bypass the queue's stillDue duplicate-launch guard or it gets dropped.
    _scheduleQueue.push({
      ...schedule,
      _forced: true,
      _sidepanelLaunch: createScheduleSidepanelIntent(req.body),
    });
    processScheduleQueue();
    res.json({ ok: true, message: 'Schedule queued for immediate fire' });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// POST /api/schedules/:id/timer — fire a schedule after N minutes
app.post('/api/schedules/:id/timer', (req, res) => {
  try {
    const { minutes } = req.body;
    const mins = Number(minutes);
    if (!mins || mins < 1 || mins > 1440) return res.status(400).json({ error: 'minutes must be 1–1440' });

    const schedules = loadSchedules();
    const schedule = schedules.find(s => s.id === req.params.id);
    if (!schedule) return res.status(404).json({ error: 'Schedule not found' });

    // Cancel existing timer for this schedule if any
    if (_scheduleTimers.has(schedule.id)) {
      clearTimeout(_scheduleTimers.get(schedule.id).timeoutId);
      _scheduleTimers.delete(schedule.id);
    }

    const firesAt = new Date(Date.now() + mins * 60_000).toISOString();
    const timeoutId = setTimeout(() => {
      console.log(`[schedule] Timer fired for "${schedule.name}" after ${mins}m`);
      _scheduleTimers.delete(schedule.id);
      // Re-read schedule in case it was updated/deleted since timer was set
      const current = loadSchedules().find(s => s.id === schedule.id);
      if (current) {
        // Forced: the user set a one-off timer to fire this now; it is not "due" by
        // cron, so it must bypass the queue's stillDue duplicate-launch guard.
        _scheduleQueue.push({ ...current, _forced: true });
        processScheduleQueue();
      }
      broadcastSync({ type: 'schedule:timer-fired', scheduleId: schedule.id, scheduleName: schedule.name });
    }, mins * 60_000);

    _scheduleTimers.set(schedule.id, { timeoutId, firesAt, minutes: mins });
    console.log(`[schedule] Timer set: "${schedule.name}" fires in ${mins}m at ${firesAt}`);
    broadcastSync({ type: 'schedule:timer-set', scheduleId: schedule.id, scheduleName: schedule.name, firesAt, minutes: mins });
    res.json({ ok: true, firesAt, minutes: mins });
  } catch (err) {
    res.status(err.status || 500).json({ error: err.message, ...(err.code ? { code: err.code, problems: err.problems } : {}) });
  }
});

// DELETE /api/schedules/:id/timer — cancel a pending timer
app.delete('/api/schedules/:id/timer', (req, res) => {
  const timer = _scheduleTimers.get(req.params.id);
  if (!timer) return res.status(404).json({ error: 'No active timer for this schedule' });
  clearTimeout(timer.timeoutId);
  _scheduleTimers.delete(req.params.id);
  console.log(`[schedule] Timer cancelled for schedule ${req.params.id}`);
  broadcastSync({ type: 'schedule:timer-cancelled', scheduleId: req.params.id });
  res.json({ ok: true });
});


// ═══════════════════════════════════════════════════════════════
// ISOLATED AGENTS — spawn Claude Code as fully isolated child processes
// Uses --print --output-format stream-json for clean JSON streaming.
// Supports both fully isolated mode and SynaBun-integrated mode.
// Loop mode: fresh process per iteration (anti-brain-rot).
// ═══════════════════════════════════════════════════════════════

const agentRegistry = new Map(); // agentId → agent object
const AGENT_IS_WIN = process.platform === 'win32';

/**
 * Build the MCP config JSON for an agent.
 * withSynabun controls the pinned SynaBun entry. External grants come only from the captured task list.
 */
function buildAgentMcpConfig(withSynabun, browserSessionId, browserTabId, terminalSessionId, tools = [], cwd = PACKAGE_ROOT) {
  const mcpPreload = resolve(PACKAGE_ROOT, 'mcp-server', 'dist', 'preload.js');
  const dotenvPath = resolve(DATA_HOME, '.env');
  const env = { DOTENV_PATH: dotenvPath, SYNABUN_DATA_HOME: DATA_HOME, MEMORY_DATA_DIR: resolve(DATA_HOME, 'mcp-data') };
  if (browserSessionId) env.SYNABUN_BROWSER_SESSION = browserSessionId;
  if (browserTabId) env.SYNABUN_BROWSER_TAB = browserTabId;
  // Stable per-agent routing identity so the MCP child's X-Synabun-Terminal header
  // matches this agent's _tabOwners key on the server (tab-less calls route to the
  // agent's own dedicated tab instead of the shared activeTab).
  if (terminalSessionId) env.SYNABUN_TERMINAL_SESSION = terminalSessionId;
  // Agents run with --strict-mcp-config, so they see only what this file lists.
  // External servers come from the captured list and owner switches; SynaBun is added last
  // so its per-agent pins always win over a same-named registry entry.
  const inventory = externalInventory('claude-code', cwd);
  const scope = selectExternalServers(tools, inventory);
  const mcpServers = Object.fromEntries(scope.names.map(name => [name, inventory.definitionFor(name)]));
  if (withSynabun) mcpServers.SynaBun = { type: 'stdio', command: 'node', args: [mcpPreload], env };
  return JSON.stringify({ mcpServers });
}

/**
 * Spawn a single Claude Code agent process.
 * Returns a Promise that resolves when the process exits.
 * The agent object is updated in-place with output, status, etc.
 */
function spawnAgentProcess(agent, prompt, extraEnv = {}) {
  return new Promise((resolveAgentExit) => {
    const claudeBin = getClaudeBin();
    // Reuse the agent's persistent session-id for conversation continuity.
    // The controller rotates agent._activeSessionId every N iterations to avoid context overflow.
    const sessionId = agent._activeSessionId || agent.sessionId;

    const serverMap = JSON.parse(agent._mcpConfig).mcpServers;
    const mcpValues = Object.values(serverMap).flatMap(entry => [...Object.values(entry.env || {}), ...Object.values(entry.headers || {}), ...(entry.args || []), ...(entry.url ? [entry.url] : [])]).filter(value => typeof value === 'string' && value);
    const mcpConfigPath = writePrivateMcpConfig(resolve(DATA_HOME, 'data', 'agents', agent.id, 'mcp.json'), serverMap);
    const args = [
      '--print',
      '--output-format', 'stream-json',
      '--verbose',
      '--session-id', sessionId,
      '--strict-mcp-config',
      '--mcp-config', mcpConfigPath,
      '--permission-mode', 'bypassPermissions',
    ];
    // Resume the session when continuing an existing conversation (not the first use of this session-id)
    if (agent._resumableSessionId === sessionId) {
      args.push('--resume');
    }
    agent._resumableSessionId = sessionId; // Mark this session-id as resumable for next iteration

    if (agent.model && agent.model !== 'default') args.push('--model', toCliModelName(agent.model));
    if (agent.effort && CLAUDE_EFFORT_LEVELS.includes(agent.effort)) args.push('--effort', agent.effort);
    if (agent._maxTurns) args.push('--max-turns', String(agent._maxTurns));
    if (agent._systemPrompt) args.push('--system-prompt', agent._systemPrompt);
    if (agent._allowedTools?.length) args.push('--allowedTools', ...agent._allowedTools);
    // Spend/mutation guard — see MCP_SERVER_WRITE_TOOLS. Takes precedence over --allowedTools.
    const disallowedTools = buildAgentDisallowedTools(agent._mcpConfig);
    if (disallowedTools.length) args.push('--disallowedTools', ...disallowedTools);
    if (agent._addDirs?.length) {
      for (const dir of agent._addDirs) args.push('--add-dir', dir);
    }
    args.push('-p', prompt);

    const cleanEnv = Object.fromEntries(
      Object.entries(process.env).filter(([k]) =>
        !k.startsWith('VSCODE_') && k !== 'TERM_PROGRAM' && k !== 'TERM_PROGRAM_VERSION'
      )
    );

    console.log(`[agent] ${agent.id} spawn: ${claudeBin} ${args.map(a => a.length > 80 ? a.slice(0, 80) + '…' : a).join(' ')}`);

    const child = spawn(shellCommand(claudeBin, AGENT_IS_WIN), args, {
      cwd: agent.cwd,
      env: claudeChildEnv({ ...cleanEnv, FORCE_COLOR: '0', NO_COLOR: '1', TERM: 'dumb', ...extraEnv }),
      stdio: ['ignore', 'pipe', 'pipe'],
      shell: AGENT_IS_WIN,
      windowsHide: true,
    });

    agent.process = child;
    agent._lineBuffer = '';
    let stderrBuf = '';
    let stderrLineBuffer = '';

    child.stdout.on('data', (chunk) => {
      agent._lineBuffer += chunk.toString();
      const lines = agent._lineBuffer.split('\n');
      agent._lineBuffer = lines.pop();

      for (const line of lines) {
        if (!line.trim()) continue;
        try {
          const event = redactMcpValues(JSON.parse(line), mcpValues);
          agent.output.push(event);
          if (event.type === 'assistant' && event.message?.content) {
            for (const block of event.message.content) {
              if (block.type === 'text') agent.textOutput += block.text;
              else if (block.type === 'tool_use') {
                agent.toolUses.push({
                  tool: block.name,
                  input: typeof block.input === 'string' ? block.input.slice(0, 200) : JSON.stringify(block.input).slice(0, 200),
                });
                console.log(`[agent] ${agent.id} tool_use: ${block.name}`);
              }
            }
          }
          if (event.type === 'result') {
            if (event.cost_usd != null) agent.costUsd = (agent.costUsd || 0) + event.cost_usd;
            if (event.total_cost_usd != null) agent.costUsd = event.total_cost_usd;
          }
          broadcastSync({ type: 'agent:output', agentId: agent.id, event });
        } catch { /* partial JSON */ }
      }
    });

    child.stderr.on('data', (chunk) => {
      const text = chunk.toString();
      stderrBuf = redactMcpValues(stderrBuf + text, mcpValues);
      if (stderrBuf.length > 8192) stderrBuf = stderrBuf.slice(-4096);
      // Log MCP and error lines in real-time for diagnostics
      stderrLineBuffer += text;
      const lines = stderrLineBuffer.split('\n'); stderrLineBuffer = lines.pop() || '';
      if (stderrLineBuffer.length > 65536) stderrLineBuffer = '';
      for (const line of lines) {
        const t = redactMcpValues(line, mcpValues).trim();
        if (t && (t.includes('error') || t.includes('Error') || t.includes('MCP') || t.includes('mcp') || t.includes('ENOENT') || t.includes('refused'))) {
          console.warn(`[agent] ${agent.id} stderr: ${t.slice(0, 200)}`);
        }
      }
    });

    child.on('error', (err) => {
      console.error(`[agent] ${agent.id} spawn error:`, err.message);
      resolveAgentExit({ code: -1, error: err.message });
    });

    child.on('close', (code) => {
      if (agent._lineBuffer.trim()) {
        try {
          const event = redactMcpValues(JSON.parse(agent._lineBuffer), mcpValues);
          agent.output.push(event);
          if (event.type === 'result') {
            if (event.cost_usd != null) agent.costUsd = (agent.costUsd || 0) + event.cost_usd;
            if (event.total_cost_usd != null) agent.costUsd = event.total_cost_usd;
          }
        } catch {}
      }
      agent._lineBuffer = '';
      if (stderrBuf.trim()) {
        console.log(`[agent] ${agent.id} stderr dump (exit ${code}):\n${stderrBuf.trim().slice(-1000)}`);
      }
      console.log(`[agent] ${agent.id} close: code=${code}, tools=${agent.toolUses.length}, textLen=${agent.textOutput.length}`);
      resolveAgentExit({ code, error: code !== 0 ? (stderrBuf.trim().slice(-500) || `Exit code ${code}`) : null });
    });
  });
}

/**
 * Launch an agent. Supports two modes:
 * - single: one-shot task (spawn once)
 * - loop: iterating task (spawn per iteration, inject progress)
 */
async function launchAgentController(opts) {
  const {
    task, model, effort, cwd, allowedTools, addDirs, systemPrompt, maxTurns,
    withSynabun = false, browserSessionId = null, browserTabId = null,
    agentId: providedAgentId = null,
    mode = 'single', iterations = 1, maxMinutes = 30, context = null,
  } = opts;

  const agentId = providedAgentId || randomUUID();
  const agentTerminalId = `agent:${agentId}`;
  const agentTools = requireToolList(resolveToolList(opts.tools ?? [], { source: 'runtime' })).items;
  const mcpConfig = buildAgentMcpConfig(withSynabun, browserSessionId, browserTabId, agentTerminalId, agentTools, cwd || PACKAGE_ROOT);
  const agentCwd = cwd || PACKAGE_ROOT;

  // Build default system prompt for agents — overrides the boot sequence in the agent's instructions
  // so the agent goes straight to the task instead of greeting/recalling
  const defaultAgentPrompt = withSynabun
    ? [
        'You are an autonomous agent executing a task. CRITICAL RULES:',
        '',
        '## Boot',
        '1. SKIP every boot sequence in your instructions (CLAUDE.md, rules files) — no greeting, no recall, no communication style lookup. Go straight to the task.',
        '2. DO NOT output pleasantries, status summaries, or explanatory text. Execute using tools immediately.',
        '',
        '## Tools',
        '3. Your SynaBun MCP tools are deferred. On your FIRST response, batch-fetch ALL schemas in ONE ToolSearch call:',
        '   ToolSearch("select:browser_navigate,browser_click,browser_type,browser_fill,browser_snapshot,browser_scroll,browser_screenshot,browser_console,browser_press,browser_select,browser_hover,browser_evaluate,browser_wait,browser_content,browser_extract_tweets,browser_extract_ig_feed,browser_extract_ig_profile,browser_extract_ig_post,browser_extract_ig_reels,browser_extract_ig_search,browser_extract_li_feed,browser_extract_li_profile,browser_extract_li_post,browser_extract_tiktok_videos,browser_extract_tiktok_search,browser_extract_tiktok_profile,browser_extract_fb_posts,browser_go_back,browser_go_forward,browser_reload,browser_session,browser_upload,bluesky_session,bluesky_timeline,bluesky_author_feed,bluesky_thread,bluesky_profile,bluesky_search_posts,bluesky_search_actors,bluesky_notifications,bluesky_graph,bluesky_likes,bluesky_feed,bluesky_post,bluesky_action,bluesky_resolve,bluesky_dm,remember,recall,reflect,forget,restore,memories,category,sync")',
        '   Then IMMEDIATELY call your first actual tool in the SAME response. A text-only response terminates the session.',
        '4. EVERY response MUST contain at least one tool_use call. Text-only responses terminate --print mode and waste the iteration.',
        '5. Chain multiple tool calls in a single response when they are independent (e.g., ToolSearch + browser_navigate).',
        '',
        '## Focus',
        '6. Stay laser-focused on the task. Do not drift into unrelated actions.',
        '7. Be autonomous. Do not ask for confirmation. Do not wait. Execute the full task using all available turns.',
        '8. If a tool call fails, try an alternative approach immediately. Do not output explanatory text without a tool call.',
        '9. If the browser shows a login wall, CAPTCHA, or 2FA — STOP and output the blocker in your handoff. Do not try to bypass it.',
        '',
        '## Iteration Handoff',
        '10. At the END of each iteration (when you have exhausted your task or turns), output a structured handoff:',
        '   ## Handoff',
        '   - Done: [concrete accomplishments this iteration]',
        '   - Next: [specific next steps for the following iteration]',
        '   - State: [current browser URL, login status, any critical state]',
        '   This handoff is injected into the next iteration for continuity. Be specific and actionable.',
        '',
        '## Memory',
        '11. SynaBun memory tools are available. Use them ONLY when the task prompt explicitly asks, or every 10 iterations when instructed.',
        '12. Do NOT call recall/remember/reflect unless directly relevant to the task. Memory operations waste turns.',
      ].join('\n')
    : null;

  const agent = {
    id: agentId,
    sessionId: randomUUID(),
    task,
    model: model || 'default',
    effort: effort || null,
    cwd: agentCwd,
    status: 'running',
    mode,
    process: null,
    output: [],
    textOutput: '',
    toolUses: [],
    startedAt: new Date().toISOString(),
    endedAt: null,
    exitCode: null,
    error: null,
    costUsd: null,
    // Loop state
    currentIteration: 0,
    totalIterations: iterations,
    maxMinutes,
    journal: [],
    browserSessionId: browserSessionId || null,
    browserTabId: browserTabId || null,
    withSynabun,
    // Internal
    _agentTerminalId: agentTerminalId,
    tools: agentTools,
    _mcpConfig: mcpConfig,
    _maxTurns: maxTurns || 200,
    _systemPrompt: systemPrompt || defaultAgentPrompt,
    _allowedTools: allowedTools || null,
    _addDirs: addDirs || null,
    _lineBuffer: '',
    _stopped: false,
    _activeSessionId: null, // set per-iteration
    _usesBrowser: !!browserSessionId, // true if loop uses browser automation
    _iterOutputStart: 0, // tracks where each iteration's output starts in textOutput
    _iterToolStart: 0, // tracks where each iteration's tools start in toolUses
  };

  agentRegistry.set(agentId, agent);

  console.log(`[agent] Launching ${mode} agent ${agentId} (synabun=${withSynabun}, browser=${browserSessionId || 'none'})`);
  console.log(`[agent] Task: ${task.slice(0, 100)}${task.length > 100 ? '...' : ''}`);

  broadcastSync({
    type: 'agent:launched',
    agentId, task: agent.task, model: agent.model,
    cwd: agent.cwd, mode, iterations, browserSessionId,
    startedAt: agent.startedAt,
  });

  // Run in background — don't block the API response
  (async () => {
    // When this launch started: the loop prompt says how much of maxMinutes is left.
    const startTime = Date.now();
    // Mark the initial browser session as agent-owned (prevents grace timer / context-close from killing it).
    // A Set, not a scalar: concurrent agents in the shared persistent browser
    // must not overwrite each other's ownership (premature grace-reap).
    if (agent._usesBrowser && agent.browserSessionId) {
      const initBs = browserSessions.get(agent.browserSessionId);
      if (initBs) (initBs._agentOwnedSet ||= new Set()).add(agentId);
    }

    for (let i = 1; i <= iterations; i++) {
      if (agent._stopped) break;

      agent.currentIteration = i;
      agent._iterOutputStart = agent.textOutput.length;
      agent._iterToolStart = agent.toolUses.length;

      // Fresh Claude session EVERY iteration — prevents context bloat and compaction.
      agent._activeSessionId = randomUUID();
      agent._resumableSessionId = null; // ensure --resume is never used

      // ── Per-iteration browser tab: fresh OWNED TAB for every iteration ──
      // Release just this agent's tab (NOT the whole browser — other loops/agents may
      // share it under the persistent profile) then acquire a fresh dedicated tab.
      // This keeps the "fresh per iteration" intent without nuking co-owners' tabs.
      if (agent._usesBrowser && i > 1) {
        if (agent.browserSessionId) {
          await releaseSharedBrowserTab(agent.browserSessionId, agent._agentTerminalId).catch(e =>
            console.warn(`[agent] ${agentId} tab release: ${e.message}`)
          );
          agent.browserSessionId = null;
          agent.browserTabId = null;
        }
        for (let attempt = 1; attempt <= 3; attempt++) {
          const acq = await acquireSharedBrowserTab({ ownerKey: agent._agentTerminalId, ownerType: 'interactive', logTag: 'agent:browser' });
          if (!acq.error) {
            agent.browserSessionId = acq.browserSessionId;
            agent.browserTabId = acq.browserTabId;
            const bs = browserSessions.get(acq.browserSessionId);
            if (bs) (bs._agentOwnedSet ||= new Set()).add(agentId);
            agent._mcpConfig = buildAgentMcpConfig(agent.withSynabun, agent.browserSessionId, agent.browserTabId, agent._agentTerminalId, agent.tools, agent.cwd);
            console.log(`[agent] ${agentId} fresh tab ${agent.browserTabId} in ${agent.browserSessionId} for iteration ${i}`);
            break;
          }
          console.warn(`[agent] ${agentId} tab acquire attempt ${attempt}/3: ${acq.error}`);
          if (attempt < 3) await new Promise(r => setTimeout(r, 2000));
          else {
            console.error(`[agent] ${agentId} all tab acquire attempts failed for iteration ${i}`);
            // Update MCP config without browser so agent doesn't reference a dead session
            agent._mcpConfig = buildAgentMcpConfig(agent.withSynabun, null, null, agent._agentTerminalId, agent.tools, agent.cwd);
          }
        }
      }

      if (i > 1) console.log(`[agent] ${agentId} fresh session for iteration ${i}`);

      broadcastSync({ type: 'agent:iteration', agentId, iteration: i, total: iterations });

      // Build iteration prompt — always inject full task + journal (fresh session each time)
      let prompt;
      if (mode === 'loop') {
        const parts = [];
        const elapsed = Math.floor((Date.now() - startTime) / 60000);
        const remaining = maxMinutes - elapsed;

        if (i === 1) {
          parts.push(task);
          if (context) parts.push(`\nContext: ${context}`);
        } else {
          // Every iteration after the first: re-inject full task + journal
          parts.push(`[Iteration ${i}/${iterations}] Continue the task:`);
          parts.push(task);
          if (context) parts.push(`Context: ${context}`);
          const recentJournal = agent.journal.slice(-10);
          if (recentJournal.length > 0) {
            parts.push('\n--- PREVIOUS ITERATIONS ---');
            for (const entry of recentJournal) {
              const fields = [];
              if (entry.done) fields.push(`Done: ${entry.done}`);
              if (entry.next) fields.push(`Next: ${entry.next}`);
              if (entry.state) fields.push(`State: ${entry.state}`);
              const detail = fields.length > 0 ? fields.join(' | ') : entry.summary;
              parts.push(`  Iteration ${entry.iteration}: ${detail}`);
            }
            parts.push('--- END PREVIOUS ---');
          }
        }

        parts.push(`\nIteration ${i}/${iterations}. ${remaining}min remaining. Execute this iteration now.`);
        // Memory enforcement every 10 iterations (if SynaBun enabled)
        if (withSynabun && i > 1 && i % 10 === 0) {
          parts.push('\nMANDATORY: Call `remember` to store your progress from the last 10 iterations before proceeding.');
        }
        prompt = parts.join('\n');
      } else {
        prompt = task;
      }

      console.log(`[agent] ${agentId} iteration ${i}/${iterations}`);

      // Retry logic: if the agent produces zero tool calls (wasted iteration in --print mode),
      // retry once with a more forceful prompt before advancing
      let result = await spawnAgentProcess(agent, prompt);
      const iterToolCount = agent.toolUses.length - agent._iterToolStart;

      if (mode === 'loop' && iterToolCount === 0 && result.code === 0 && !agent._stopped) {
        console.warn(`[agent] ${agentId} iteration ${i} produced 0 tool calls — retrying with forceful prompt`);
        agent._activeSessionId = randomUUID();
        agent._resumableSessionId = null;
        const retryPrompt = [
          `CRITICAL: Your previous attempt produced NO tool calls and was wasted.`,
          `You MUST call tools immediately. Do NOT output text without tool calls.`,
          `\n${prompt}`,
        ].join('\n');
        result = await spawnAgentProcess(agent, retryPrompt);
      }

      // Extract iteration summary for the journal.
      // Prefer structured ## Handoff block if the agent produced one; fall back to tail text.
      if (mode === 'loop') {
        const iterText = agent.textOutput.slice(agent._iterOutputStart);
        let summary = '';
        let done = '';
        let next = '';
        let state = '';

        // Try to parse structured handoff
        const handoffMatch = iterText.match(/## Handoff\s*\n([\s\S]*?)(?:\n##|\n---|\s*$)/i);
        if (handoffMatch) {
          const block = handoffMatch[1];
          done = (block.match(/[-*]\s*Done:\s*(.+)/i) || [])[1]?.trim() || '';
          next = (block.match(/[-*]\s*Next:\s*(.+)/i) || [])[1]?.trim() || '';
          state = (block.match(/[-*]\s*State:\s*(.+)/i) || [])[1]?.trim() || '';
          summary = [done && `Done: ${done}`, next && `Next: ${next}`].filter(Boolean).join(' | ');
        }

        // Fallback: last 300 chars of this iteration's output
        if (!summary) {
          summary = iterText.slice(-300).slice(0, 200).replace(/\n/g, ' ').trim() || 'Completed';
        }

        const journalEntry = { iteration: i, summary, timestamp: new Date().toISOString() };
        if (done) journalEntry.done = done;
        if (next) journalEntry.next = next;
        if (state) journalEntry.state = state;
        journalEntry.toolCount = agent.toolUses.length - (agent._iterToolStart || 0);

        agent.journal.push(journalEntry);
        // Keep journal bounded
        if (agent.journal.length > 30) agent.journal = agent.journal.slice(-20);

        broadcastSync({
          type: 'agent:iteration-complete', agentId, iteration: i,
          summary, done, next, state, toolCount: journalEntry.toolCount,
        });

        console.log(`[agent] ${agentId} iteration ${i} complete: ${journalEntry.toolCount} tools, exit=${result.code}`);
      }

      if (result.code !== 0 && !agent._stopped) {
        agent.error = result.error;
        if (mode !== 'loop') break;
        // For loops: log and continue — transient failures shouldn't kill the loop
        console.warn(`[agent] ${agentId} iteration ${i} exited with code ${result.code}, continuing...`);
        // Small delay before retry to let any transient issues settle
        await new Promise(r => setTimeout(r, 2000));
      }

      // Small stabilization delay between iterations (let MCP server settle)
      if (mode === 'loop' && !agent._stopped && i < iterations) {
        await new Promise(r => setTimeout(r, 1000));
      }
    }

    // Clean up the agent's tab when the loop ends — release just this agent's tab and
    // clear its ownership markers. The shared browser is left for co-owners (the grace
    // timer reaps it once no loop/interactive/agent owner remains).
    if (agent._usesBrowser && agent.browserSessionId) {
      const finalBs = browserSessions.get(agent.browserSessionId);
      finalBs?._agentOwnedSet?.delete(agentId);
      await releaseSharedBrowserTab(agent.browserSessionId, agent._agentTerminalId).catch(() => {});
      agent.browserSessionId = null;
      agent.browserTabId = null;
    }

    agent.endedAt = new Date().toISOString();
    agent.exitCode = agent._stopped ? null : 0;
    agent.status = agent._stopped ? 'stopped' : (agent.error && mode !== 'loop') ? 'failed' : 'completed';
    agent.process = null;

    console.log(`[agent] ${agentId} finished: status=${agent.status}, iterations=${agent.currentIteration}/${iterations}`);
    broadcastSync({ type: 'agent:status', agentId, status: agent.status, exitCode: agent.exitCode });
  })().catch(async (err) => {
    // A failure in the background run ends this launch, not the server (an
    // unhandled rejection exits the process): it is logged, the agent's tab is
    // released as at a normal end, and the agent is reported failed.
    const message = err?.message || String(err);
    console.error(`[agent] ${agentId} failed in iteration ${agent.currentIteration}/${iterations}: ${message}`);
    try {
      if (agent._usesBrowser && agent.browserSessionId) {
        browserSessions.get(agent.browserSessionId)?._agentOwnedSet?.delete(agentId);
        await releaseSharedBrowserTab(agent.browserSessionId, agent._agentTerminalId).catch(() => {});
        agent.browserSessionId = null;
        agent.browserTabId = null;
      }
    } catch {}
    agent.error = message;
    agent.endedAt = new Date().toISOString();
    agent.exitCode = -1;
    agent.status = 'failed';
    agent.process = null;
    try { broadcastSync({ type: 'agent:status', agentId, status: agent.status, exitCode: agent.exitCode }); } catch {}
  });

  return agent;
}

// POST /api/agents/launch — spawn a new agent (single or loop, isolated or with SynaBun)
app.post('/api/agents/launch', async (req, res) => {
  try {
    const {
      task, model, contextMode, effort, cwd, allowedTools, addDirs, systemPrompt, maxTurns,
      withSynabun, browserProfile,
      mode, iterations, maxMinutes, context,
    } = req.body;
    if (!task?.trim()) return res.status(400).json({ error: 'task is required' });
    if (req.body.tools !== undefined && !Array.isArray(req.body.tools)) throw Object.assign(new Error('tools must be an array'), { code: 'TOOLS_INVALID', status: 400 });
    const tools = requireToolList(resolveToolList(req.body.tools ?? [], { source: 'runtime' })).items;
    selectExternalServers(tools, externalInventory('claude-code', cwd || PACKAGE_ROOT));
    let launchChoice;
    try { launchChoice = await resolveAutomationLaunchChoice('claude-code', model, contextMode); }
    catch (error) { return res.status(400).json({ error: error.message }); }

    // Pre-acquire a DEDICATED TAB in the one shared browser when SynaBun is enabled.
    // Under a persistent profile only one Chromium can run, so agents must share it —
    // each gets its own tab (registered in _tabOwners under `agent:<id>`) instead of a
    // second browser (which would throw "profile is locked"). We mint the agentId here
    // so the ownerKey + SYNABUN_TERMINAL_SESSION routing identity are stable.
    let browserSessionId = null;
    let browserTabId = null;
    const agentId = randomUUID();
    if (withSynabun) {
      const acq = await acquireSharedBrowserTab({ ownerKey: `agent:${agentId}`, ownerType: 'interactive', logTag: 'agent:browser' });
      if (acq.error) {
        console.warn(`[agent] Browser tab acquire failed: ${acq.error}`);
        return res.status(500).json({ error: `Could not start browser session for this automation: ${acq.error}` });
      }
      browserSessionId = acq.browserSessionId;
      browserTabId = acq.browserTabId;
      // Mark agent ownership — grace-timer/registry keep-alive checks it.
      const preOwned = browserSessions.get(browserSessionId);
      if (preOwned) (preOwned._agentOwnedSet ||= new Set()).add(agentId);
      console.log(`[agent] ${agentId} acquired shared browser ${browserSessionId} tab ${browserTabId}`);
    }

    // maxTurns: browser automation needs high headroom (navigate+snapshot+click+type per page).
    // Non-browser tasks need less. User-supplied value takes priority.
    const effectiveMaxTurns = maxTurns || (browserSessionId ? 200 : 100);

    const agent = await launchAgentController({
      task: task.trim(), model: launchChoice.contextMode === '1m' && launchChoice.model
        ? `${launchChoice.model}[1m]` : launchChoice.model,
      effort, cwd, allowedTools, addDirs, systemPrompt,
      maxTurns: effectiveMaxTurns,
      withSynabun: !!withSynabun,
      tools,
      agentId,
      browserSessionId,
      browserTabId,
      mode: mode || 'single',
      iterations: Math.min(Math.max(iterations || 1, 1), 200),
      maxMinutes: Math.min(Math.max(maxMinutes || 30, 1), 480),
      context: context || null,
    });

    res.json({
      ok: true,
      agentId: agent.id,
      sessionId: agent.sessionId,
      status: agent.status,
      browserSessionId,
      mode: agent.mode,
    });
  } catch (err) {
    console.error('POST /api/agents/launch error:', err.message);
    res.status(err.status || 500).json({ error: err.message, code: err.code, problems: err.problems });
  }
});

// GET /api/agents — list all agents (active + recent)
app.get('/api/agents', (req, res) => {
  const agents = [];
  for (const [id, agent] of agentRegistry) {
    agents.push({
      id,
      task: agent.task,
      model: agent.model,
      cwd: agent.cwd,
      status: agent.status,
      mode: agent.mode,
      currentIteration: agent.currentIteration,
      totalIterations: agent.totalIterations,
      startedAt: agent.startedAt,
      endedAt: agent.endedAt,
      exitCode: agent.exitCode,
      error: agent.error,
      costUsd: agent.costUsd,
      textLength: agent.textOutput.length,
      toolUseCount: agent.toolUses.length,
      eventCount: agent.output.length,
      browserSessionId: agent.browserSessionId,
      withSynabun: agent.withSynabun,
      journal: agent.journal,
      // Last 5 tool uses for live feed
      recentTools: agent.toolUses.slice(-5).map(t => t.tool),
    });
  }
  res.json({ agents });
});

// GET /api/agents/:id — get full agent details including output
app.get('/api/agents/:id', (req, res) => {
  const agent = agentRegistry.get(req.params.id);
  if (!agent) return res.status(404).json({ error: 'Agent not found' });

  res.json({
    id: agent.id,
    sessionId: agent.sessionId,
    task: agent.task,
    model: agent.model,
    cwd: agent.cwd,
    status: agent.status,
    mode: agent.mode,
    currentIteration: agent.currentIteration,
    totalIterations: agent.totalIterations,
    startedAt: agent.startedAt,
    endedAt: agent.endedAt,
    exitCode: agent.exitCode,
    error: agent.error,
    costUsd: agent.costUsd,
    textOutput: agent.textOutput,
    toolUses: agent.toolUses,
    journal: agent.journal,
    eventCount: agent.output.length,
    browserSessionId: agent.browserSessionId,
    withSynabun: agent.withSynabun,
  });
});

// POST /api/agents/:id/stop — kill a running agent
app.post('/api/agents/:id/stop', (req, res) => {
  const agent = agentRegistry.get(req.params.id);
  if (!agent) return res.status(404).json({ error: 'Agent not found' });
  if (agent.status !== 'running') return res.json({ ok: true, status: agent.status, message: 'Already finished' });

  agent._stopped = true;
  agent.status = 'stopped';
  try {
    if (agent.process) {
      if (AGENT_IS_WIN) {
        spawn('taskkill', ['/pid', String(agent.process.pid), '/T', '/F'], { shell: true, windowsHide: true });
      } else {
        try { process.kill(-agent.process.pid, 'SIGTERM'); } catch { agent.process.kill('SIGTERM'); }
      }
    }
  } catch (err) {
    console.warn(`[agent] ${agent.id} kill error:`, err.message);
  }
  res.json({ ok: true, status: 'stopped' });
});

// DELETE /api/agents/:id — remove agent from registry
app.delete('/api/agents/:id', (req, res) => {
  const agent = agentRegistry.get(req.params.id);
  if (!agent) return res.status(404).json({ error: 'Agent not found' });

  if (agent.status === 'running') {
    agent._stopped = true;
    agent.status = 'stopped';
    try { if (agent.process) agent.process.kill('SIGTERM'); } catch {}
  }

  agentRegistry.delete(req.params.id);
  broadcastSync({ type: 'agent:removed', agentId: req.params.id });
  res.json({ ok: true });
});

// POST /api/search/memories — category-filtered semantic search
app.post('/api/search/memories', async (req, res) => {
  try {
    const { query, category, limit = 15 } = req.body;
    if (!query) return res.status(400).json({ error: 'query required' });

    const embedding = await getEmbedding(query);
    const results = dbSearchMemories(embedding, Math.min(limit, 50), { category, scoreThreshold: 0.3 });

    res.json({
      results: results.map(r => ({
        id: r.id,
        score: r.score,
        payload: { content: r.content, category: r.category, subcategory: r.subcategory, project: r.project, tags: r.tags, importance: r.importance, source: r.source, created_at: r.created_at, updated_at: r.updated_at, accessed_at: r.accessed_at, access_count: r.access_count, related_files: r.related_files, related_memory_ids: r.related_memory_ids, trashed_at: r.trashed_at },
      })),
      query,
      category,
    });
  } catch (err) {
    console.error('POST /api/search/memories error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// ═══════════════════════════════════════════
// SYNABUN UPDATE CHECK (NPM + GITHUB RELEASES)
// ═══════════════════════════════════════════
//
// Checks both the npm registry AND the project's GitHub releases. Alerts
// when EITHER source is newer than the installed version (catches one-sided
// publishes — e.g. release tagged on GitHub before npm publish completes).

let _synabunUpdateCache = {
  current: null,
  installedChannel: 'stable',    // 'stable' | 'prerelease'
  npmLatestStable: null,         // dist-tags.latest
  npmLatestBeta: null,           // dist-tags.beta (or null if absent)
  npmLatestTag: null,            // dist-tag of npmLatest (informational; the install is pinned to a version)
  npmLatest: null,               // chosen target for installed channel
  gitLatest: null,               // tag_name from GitHub release matching channel
  gitLatestRaw: null,            // original GitHub tag, preserving leading v
  latest: null,                  // newer of (npmLatest, gitLatest): the target shown and installed
  npmUpdateAvailable: false,
  gitUpdateAvailable: false,
  updateAvailable: false,        // npmUpdateAvailable || gitUpdateAvailable
  source: null,                  // 'npm' | 'github' | 'both' | null
  installPlan: null,             // server-owned npm/GitHub action target for click-to-update
  checkedAt: null,
  npmError: null,
  gitError: null,
};

const SYNABUN_GITHUB_REPO_URL = 'https://github.com/danilokhury/Synabun';

function isSynabunGitHubRemote(remoteText) {
  return /github\.com[:/]danilokhury\/Synabun(?:\.git)?(?:[\s)]|$)/i.test(String(remoteText || ''));
}

function detectSynabunInstallSource() {
  if (PACKAGED_RUNTIME) return { kind: 'packaged-app' };
  const normalizedRoot = PACKAGE_ROOT.replace(/\\/g, '/');
  if (/\/node_modules\/synabun$/i.test(normalizedRoot)) {
    return { kind: 'npm-global' };
  }

  try {
    // Run as reads (lib/git-read.js): the app's own checkout is a folder like any other, and can be a registered
    // project. What git could not say is an empty answer.
    const git = (args) => {
      const result = spawnGitRead(args, { cwd: PACKAGE_ROOT, timeout: 2000 });
      return result.status === 0 ? result.stdout.toString().trim() : '';
    };
    if (git(['rev-parse', '--is-inside-work-tree']) === 'true') {
      const remote = git(['remote', 'get-url', 'origin']);
      const remotes = git(['remote', '-v']);
      if (isSynabunGitHubRemote(`${remote}\n${remotes}`)) {
        const firstRemote = remote || remotes.split(/\s+/).find(part => isSynabunGitHubRemote(part)) || null;
        return { kind: 'github-clone', remote: firstRemote };
      }
      return { kind: 'git-clone', remote: remote || null };
    }
  } catch {}

  return { kind: 'local' };
}

// The selection (which version is the target) and the install plan (what
// click-to-update runs: an exact pinned version, never a dist-tag) are pure and
// live in lib/synabun-update-plan.js.

async function checkSynabunUpdate() {
  let current = _synabunUpdateCache.current;
  try {
    const pkg = JSON.parse(readFileSync(resolve(PACKAGE_ROOT, 'package.json'), 'utf-8'));
    current = pkg.version;
  } catch { /* keep prior current if package.json read fails */ }

  // Any suffix on a semver-era version is a prerelease (`2.0.0-1`,
  // `2.0.0-beta.1`). Only the old date-style iterations (`2026.4.26-1`) were
  // stable releases with a suffix.
  const installedChannel = synabunReleaseChannel(current);

  // The desktop app updates itself (packaging/desktop: its window's update function, fed by the GitHub
  // releases' desktop files). Nothing here offers it an npm or GitHub update; there is nothing to check.
  if (PACKAGED_RUNTIME?.shell) {
    _synabunUpdateCache = {
      ..._synabunUpdateCache,
      current, installedChannel, latest: null, npmUpdateAvailable: false, gitUpdateAvailable: false, updateAvailable: false,
      source: null, installPlan: null, checkedAt: new Date().toISOString(), npmError: null, gitError: null, desktopManaged: true,
    };
    console.log(`  Updates:   from the SynaBun app (v${current})`);
    return;
  }

  const fetchJsonWithTimeout = async (url, ms = 5000) => {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), ms);
    try {
      const res = await fetch(url, {
        signal: controller.signal,
        headers: { 'Accept': 'application/json', 'User-Agent': 'synabun-update-check' },
      });
      if (!res.ok) throw new Error(`${url} returned ${res.status}`);
      return await res.json();
    } finally {
      clearTimeout(timeout);
    }
  };

  // npm: fetch the FULL registry document so we can read every dist-tag
  // (latest + beta + any future channel). The /latest shorthand only
  // surfaces dist-tags.latest, which made beta installs invisible.
  // github: when installed is a prerelease, /releases/latest is wrong
  // because it skips prereleases — fetch the full list and pick newest.
  const npmUrl = 'https://registry.npmjs.org/synabun';
  const githubUrl = installedChannel === 'prerelease'
    ? 'https://api.github.com/repos/danilokhury/Synabun/releases?per_page=20'
    : 'https://api.github.com/repos/danilokhury/Synabun/releases/latest';

  const [npmRes, gitRes] = await Promise.allSettled([
    fetchJsonWithTimeout(npmUrl),
    fetchJsonWithTimeout(githubUrl),
  ]);

  const npmError = npmRes.status === 'fulfilled' ? null : (npmRes.reason?.message || 'npm fetch failed');
  const gitError = gitRes.status === 'fulfilled' ? null : (gitRes.reason?.message || 'github fetch failed');

  const found = selectSynabunUpdate({
    current,
    npmDocument: npmRes.status === 'fulfilled' ? npmRes.value : null,
    githubReleases: gitRes.status === 'fulfilled' ? gitRes.value : null,
  });
  const { latest, updateAvailable, source } = found;

  // The plan installs exactly `latest`: pinned when npm has that version, a
  // manual update when it exists only as a GitHub release.
  const installPlan = buildSynabunInstallPlan({
    ...found,
    current,
    installSource: updateAvailable ? detectSynabunInstallSource() : null,
    repoUrl: SYNABUN_GITHUB_REPO_URL,
  });

  _synabunUpdateCache = {
    current,
    installedChannel: found.installedChannel,
    npmLatestStable: found.npmLatestStable,
    npmLatestBeta: found.npmLatestBeta,
    npmLatestTag: found.npmLatestTag,
    npmLatest: found.npmLatest,
    gitLatest: found.gitLatest,
    gitLatestRaw: found.gitLatestRaw,
    latest,
    npmUpdateAvailable: found.npmUpdateAvailable,
    gitUpdateAvailable: found.gitUpdateAvailable,
    updateAvailable,
    source,
    installPlan,
    checkedAt: new Date().toISOString(),
    npmError,
    gitError,
  };

  if (updateAvailable) {
    console.log(`  Updates:   v${current} → v${latest} (${source}; channel: ${installedChannel})`);
  } else if (npmError && gitError) {
    console.log(`  Updates:   check failed (npm: ${npmError}; github: ${gitError})`);
  } else if (npmError) {
    console.log(`  Updates:   up to date (v${current}; npm check failed: ${npmError})`);
  } else if (gitError) {
    console.log(`  Updates:   up to date (v${current}; github check failed: ${gitError})`);
  } else {
    console.log(`  Updates:   up to date (v${current}; channel: ${installedChannel})`);
  }
}

app.get('/api/system/version', async (req, res) => {
  // Settings > App: with automatic updates off the server looks only when the user asks (?force=1). A page's own
  // timer or a drawer that refreshes itself says `passive=1`, and never makes it look then.
  const auto = automaticUpdateCheck();
  const force = req.query.force === '1' && (auto || req.query.passive !== '1');
  if (force || (auto && !_synabunUpdateCache.checkedAt)) {
    try { await checkSynabunUpdate(); } catch {}
  } else if (auto) {
    const age = Date.now() - new Date(_synabunUpdateCache.checkedAt).getTime();
    if (age > 60 * 60 * 1000) {
      checkSynabunUpdate().catch(() => {});
    }
  }
  res.json({ ..._synabunUpdateCache, current: _synabunUpdateCache.current || installedSynabunVersion(), autoCheck: auto });
});

// ── Settings > App (lib/app-controls-api.js): automatic update checks, start at login, the data and logs folders ──
// The desktop app keeps its own (packaging/desktop/src/app-prefs.mjs): there this only says so.
const appSettings = createAppSettingsStore({ path: join(DATA_HOME, 'data', 'app-settings.json') });
/** Does the server look for updates by itself (at start, and when the page asks without ?force=1)? */
function automaticUpdateCheck() {
  if (PACKAGED_RUNTIME?.shell) return true;
  try { return appSettings.get().autoUpdateCheck !== false; } catch { return true; }
}
function installedSynabunVersion() {
  try { return JSON.parse(readFileSync(resolve(PACKAGE_ROOT, 'package.json'), 'utf-8')).version || null; } catch { return null; }
}
const loginStart = createLoginStart({
  packageRoot: PACKAGE_ROOT,
  home: os.homedir(),
  dataHome: DATA_HOME,
  entry: PACKAGED_RUNTIME && !PACKAGED_RUNTIME.shell ? durableEntry(PACKAGED_RUNTIME) : null,
  desktopShell: !!PACKAGED_RUNTIME?.shell,
  // Never from a test run or a throwaway data folder (the same rule as the synabun:// handler).
  allowed: () => launcherRegistrationAllowed({ env: process.env, dataHome: DATA_HOME }),
  log: (line) => console.log(`[app] ${line}`),
});
app.use('/api/system/app', createAppControlsApi({
  store: appSettings,
  loginStart,
  folders: { data: DATA_HOME, logs: join(DATA_HOME, 'data') },
  install: PACKAGED_RUNTIME?.shell ? 'desktop' : INSTALL_KIND,
  isGuestRequest,
  port: () => PORT,
  log: (line) => console.warn(line),
}));

// The notice after an automatic restart (lib/crash-notice-api.js): the crash the supervisor recovered from, which
// the owner's pages show once (public/shared/ui-crash-notice.js); dismissed in one page, gone from every page.
app.use('/api/system/crash-notice', createCrashNoticeApi({
  dataHome: DATA_HOME,
  guard: ownerRouteGuard({ isGuestRequest, port: PORT, allowedOrigins: publicWebOrigins, refuseCrossSite: true, ownOriginsOnly: true, requireOrigin: true }),
  // The dismissal carries this boot's page secret, as Skills Studio's owner writes do (lib/page-session.js).
  pageSession: _pageSession,
  broadcast: (message) => broadcastSync(message),
  // A public address the crashed server's cloudflared may still hold open (sweepLeftoverTunnels).
  leftovers: () => tunnelLeftovers(),
  log: (line) => console.log(line),
}));

// GET /api/system/about — Settings → About (lib/system-about.js): the app, the runtime, the project's links and
// every dependency of the product's packages with the version installed, read from the files on disk on the first
// request and kept for the life of the process. No environment, no token, no setting. Owner only (/api/system is
// in ADMIN_ONLY_PREFIXES).
const systemAbout = createSystemAbout({
  packageRoot: PACKAGE_ROOT,
  dataHome: DATA_HOME,
  port: PORT,
  install: PACKAGED_RUNTIME?.shell ? 'desktop' : INSTALL_KIND,
  // The WhatsApp connector is installed on demand, into the data folder (lib/whatsapp/paths.js runtimeDir).
  installDirs: { 'whatsapp-connector': [join(DATA_HOME, 'runtime', 'whatsapp')] },
  vendorDir: join(__dirname, 'public', 'vendor'),
});
app.get('/api/system/about', (req, res) => {
  res.set('Cache-Control', 'no-store');
  try {
    res.json(systemAbout.get());
  } catch (err) {
    res.status(500).json({ error: 'about_failed', detail: String(err?.message || err).slice(0, 200) });
  }
});

// GET /api/system/activity — whether anything runs that a restart would end. The
// desktop app installs a downloaded update only while this says idle
// (packaging/desktop/src/updater/controller.mjs); lib/system-activity.js adds the
// counters up, and one that throws makes the answer "not idle". Terminals are not
// counted: nothing here can tell a command that runs from a shell that waits.
function systemActivitySources() {
  const nativeRuns = () => _nativeLoopRuntime?.list?.({ activeOnly: true }) || [];
  return {
    assistant: () => {
      const runtime = _assistantRuntime;
      const sessions = runtime?._internals?.sessions;
      const brains = sessions ? countWhere(sessions.keys(), (id) => runtime.isBusy(id)) : 0;
      const runs = _assistantDispatcher ? _assistantDispatcher.list({ activeOnly: true, limit: 500 }).length : 0;
      const agents = countWhere(agentRegistry, (agent) => agent?.status === 'running');
      return brains + runs + agents;
    },
    'claude-panel': () => _claudeBridge?.panelSessionsWorking?.() || 0,
    'codex-panel': () => countWhere(_codexLiveConnections, (connection) => !!connection?.busy?.())
      + countWhere(_codexOrphanedProcs, (orphan) => orphan?.isIdle?.() !== true),
    'opencode-panel': () => {
      const blockers = getOpenCodeHistoryBlockers();
      return blockers.activeTurns + blockers.startingTurns;
    },
    'claude-cli': () => recentCliSessions(sessionRegistry),
    loop: () => {
      // A dispatched worker also runs in the native runtime: it is counted under assistant.
      const native = countWhere(nativeRuns(), (run) => run?.runMode !== 'task' && run?.source !== 'assistant');
      const files = countWhere(readLoopStateFiles(), ({ data }) => !!data?.active && (!data.terminalSessionId || isLoopRuntimeAlive(data)));
      const terminals = countWhere(terminalSessions, (session) => !!session?._loopTerminalSessionId);
      return Math.max(native + terminals, files);
    },
    schedule: () => _scheduleQueue.length + (_scheduleQueueRunning ? 1 : 0),
    backup: () => (_backupOperationActive ? 1 : 0) + (_autoBackupPromise ? 1 : 0),
    maintenance: () => (_reindexJob?.running ? 1 : 0) + (_indexingJob && !_indexingJob.done ? 1 : 0)
      + countWhere(Object.values(cliInstaller.jobs()), (job) => job?.state === 'running')
      + (_projectStorageClearInProgress ? 1 : 0) + (_ocpHistoryClearInProgress ? 1 : 0),
  };
}

app.get('/api/system/activity', (req, res) => {
  res.set('Cache-Control', 'no-store');
  res.json(collectActivity(systemActivitySources(), { log: (line) => console.warn(`[activity] ${line}`) }));
});

// ═══════════════════════════════════════════
// EXTERNAL CLI TOOL VERSION CHECK
// ═══════════════════════════════════════════

const TOOL_DEFS = [
  { key: 'claude-code', cmd: 'claude',   versionArg: '--version', npm: '@anthropic-ai/claude-code' },
  { key: 'codex',       cmd: 'codex',    versionArg: '--version', npm: '@openai/codex' },
  { key: 'gemini',      cmd: 'gemini',   versionArg: '--version', npm: '@google/gemini-cli' },
  // npm's opencode-ai is OpenCode 1: OpenCode 2's newer version is what Homebrew says (a brew install) or what OpenCode
  // itself announces in its own interface.
  { key: 'opencode',    cmd: 'opencode', versionArg: '--version' },
];

let _toolVersionCache = { checkedAt: null, tools: {} };
let _toolVersionGeneration = 0;

// Backwards-compat helper — returns a "MAJOR.MINOR.PATCH" string (no pre).
// Kept because legacy callers expect a string for display purposes only.
// Comparison logic must use semverNewer (lib/synabun-version.js) to handle
// prerelease/iteration suffixes correctly.
function parseVersion(raw) {
  // Keep any prerelease/iteration suffix. Truncating it made a user on
  // 2.1.0-beta.3 record as 2.1.0, so semverNewer('2.1.0','2.1.0') was false
  // and a stable release never produced a badge. The leading (\d+\.\d+\.\d+)
  // still tolerates surrounding noise like "codex-cli 0.147.0" and
  // "2.1.224 (Claude Code)" — the suffix group only matches a real
  // `-prerelease` tag, never the " (Claude Code)" trailer.
  const m = String(raw ?? '').match(/(\d+)\.(\d+)\.(\d+)(-[0-9A-Za-z.-]+)?/);
  return m ? `${m[1]}.${m[2]}.${m[3]}${m[4] || ''}` : null;
}

// parseSemver / compareSemver / semverNewer live in lib/synabun-version.js, with
// the rules that order SynaBun's own date-style and semver-era releases.

// Where each CLI is: lib/cli-resolver.js (cliResolver, near getClaudeBin).

// detectInstallSource / buildUpdateCommand / NPM_PKGS now live in
// ./lib/cli-update-planner.js so they can be unit tested away from this file.
// See the module header for the rule that decides self-updater vs package
// manager: a self-updater cannot replace a brew-managed binary, because
// brew's symlink in /opt/homebrew/bin still wins PATH.

// Ask Homebrew what it could actually upgrade. One subprocess covers every
// tool, and unlike the formulae.brew.sh API it is tap-aware — OpenCode ships
// from a third-party tap whose version differs from homebrew/core's.
// HOMEBREW_NO_AUTO_UPDATE keeps this fast: brew refreshes its own API cache
// during normal use, so the data is current without us blocking on a fetch.
async function probeBrewOutdated(env) {
  try {
    const { stdout } = await execAsync('brew outdated --json=v2', {
      encoding: 'utf-8',
      timeout: 15000,
      env: { ...env, HOMEBREW_NO_AUTO_UPDATE: '1' },
      windowsHide: true,
      maxBuffer: 4 * 1024 * 1024,
    });
    return parseBrewOutdated(stdout);
  } catch {
    // brew missing or errored — callers fail closed (latest = installed)
    // rather than falling back to npm, which would resurrect the stuck badge.
    return null;
  }
}

// Resolve SynaBun's own install roots so we can reject any tool binary that
// lives inside our bundled node_modules — bulletproof guard for the recurring
// phantom-version bug (e.g. stale @anthropic-ai/claude-code left over from
// prior SynaBun installs that shipped it as a dependency, which `npm install`
// does not auto-prune when removed from package.json).
const SYNABUN_ROOTS = (() => {
  const roots = new Set();
  try { roots.add(realpathSync(__dirname).replace(/\\/g, '/').toLowerCase()); } catch {}
  try { roots.add(realpathSync(resolve(__dirname, '..')).replace(/\\/g, '/').toLowerCase()); } catch {}
  // A packaged application: everything it ships, its own Node and npm included.
  if (PACKAGED_RUNTIME?.resources) {
    try { roots.add(realpathSync(PACKAGED_RUNTIME.resources).replace(/\\/g, '/').toLowerCase()); } catch {}
  }
  return [...roots];
})();

function isInsideSynabun(binPath) {
  if (!binPath) return false;
  try {
    const resolved = realpathSync(binPath).replace(/\\/g, '/').toLowerCase();
    return SYNABUN_ROOTS.some(root => resolved.startsWith(root + '/'));
  } catch {
    const norm = binPath.replace(/\\/g, '/').toLowerCase();
    return SYNABUN_ROOTS.some(root => norm.startsWith(root + '/'));
  }
}

// Remove any external tool that ended up in our own node_modules: Claude Code,
// Codex, OpenCode and Gemini CLI are installed by the user, never by SynaBun,
// and the agent SDKs are installed without the executables they would carry
// (the list and the reasons: lib/external-tools.js at the package root).
// Idempotent, runs on every startup, and touches nothing when there is nothing
// to remove — a packaged application ships without them and is never written to.
// Catches what `npm install` leaves behind: packages an older SynaBun depended
// on, and payloads a regenerated lockfile brought back. Logs each removal so a
// user can see the prune fire on their machine.
function pruneBundledCliTools() {
  const moduleRoots = [
    join(__dirname, 'node_modules'),
    join(__dirname, '..', 'node_modules'),
  ];
  for (const root of moduleRoots) {
    const result = pruneExternalTools(root);
    for (const item of result.removed) console.log(`  Removed ${item.name} from SynaBun's own node_modules (${item.tool} is installed separately): ${item.path}`);
  }
}

async function checkToolVersions({ force = false } = {}) {
  const generation = ++_toolVersionGeneration;
  // Every CLI exactly as the panels and launchers find it (lib/cli-resolver.js):
  // the path in Settings first, then PATH with the OS PATH read afresh, then the
  // known install folders; installed (with its version), missing, or broken
  // (found, but `--version` failed: the real error). Never a copy inside
  // SynaBun, so the badge reflects the CLI the user would run in a terminal.
  // `force` is Re-check: the OS PATH is read again and every --version asked again.
  const statuses = await cliResolver.resolveAll(TOOL_DEFS.map((tool) => tool.key), { force });
  const cleanEnv = withPathEnv(process.env, getAugmentedPath());

  // Only pay for the brew probe when a brew-managed tool is actually present.
  const brewOutdated = Object.values(statuses).some((status) => status.state === 'installed' && isBrewSource(status.installSource))
    ? await probeBrewOutdated(cleanEnv)
    : null;

  const checkOneTool = async (tool) => {
    const status = statuses[tool.key];
    const installed = status.state === 'installed' ? status.version : null;

    // Upstream (npm) version. For a brew install this is NOT the yardstick —
    // Homebrew routinely trails npm by a few releases, so comparing against it
    // produced a badge that lit up while `brew upgrade` answered "already
    // installed". Reported as upstreamLatest purely for diagnostics.
    let upstreamLatest = null;
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 5000);
      if (tool.npm) {
        const res = await fetch(`https://registry.npmjs.org/${tool.npm}/latest`, { signal: controller.signal });
        clearTimeout(timeout);
        if (res.ok) { const d = await res.json(); upstreamLatest = d.version; }
      } else if (tool.github) {
        const res = await fetch(`https://api.github.com/repos/${tool.github}/releases/latest`, { signal: controller.signal });
        clearTimeout(timeout);
        if (res.ok) { const d = await res.json(); upstreamLatest = parseVersion(d.tag_name || ''); }
      }
    } catch { /* network error */ }

    const installSource = status.installSource;
    const brewToken = isBrewSource(installSource) ? resolveBrewToken(tool.key, status.realPath || status.path) : null;
    const latest = resolveLatest({
      installSource,
      brewToken,
      brewOutdated,
      npmLatest: upstreamLatest,
      installed,
    });
    // A self-updater is started by the path found, so the update reaches this
    // very installation even where a terminal's PATH does not name its folder.
    const updateCommand = installed
      ? buildUpdateCommand(tool.key, installSource, { brewToken, binPath: status.path, platform: process.platform })
      : null;

    return [tool.key, {
      installed,
      latest,
      upstreamLatest,
      updateAvailable: !!(installed && latest && semverNewer(installed, latest)),
      installSource,
      brewToken,
      binPath: status.path,
      updateCommand,
      canUpdate: !!updateCommand,
      state: status.state,
      version: status.version,
      error: status.error,
      foundBy: status.foundBy,
      realPath: status.realPath,
      launchPath: status.launchPath,
      configured: status.configured,
      checked: status.candidates,
      guideUrl: CLI_INSTALL_GUIDES[tool.key] || null,
      install: cliInstaller.describe(tool.key),
      pathStatus: cliPathManager.inspect(status),
    }];
  };

  const entries = await Promise.all(TOOL_DEFS.map((tool) => checkOneTool(tool)));
  const results = Object.fromEntries(entries);

  // Tell a missing tool's install banner the command that fits this machine:
  // the vendor's own installer for this system (Anthropic's native installer
  // for Claude Code always), unless the CLIs that ARE installed show a package
  // manager this machine uses (Homebrew, bun, pnpm …), which is kept to, so
  // that the manual command never creates a second, conflicting install.
  const siblingSources = Object.values(results)
    .filter((v) => v.state === 'installed')
    .map((v) => v.installSource)
    .filter((s) => s && s !== 'unknown' && s !== 'other');
  const dominantSource = siblingSources
    .sort((a, b) =>
      siblingSources.filter((s) => s === b).length - siblingSources.filter((s) => s === a).length)[0]
    || 'unknown';
  for (const [key, info] of Object.entries(results)) {
    const source = info.installed ? info.installSource : dominantSource;
    info.installCommand = buildInstallCommand(key, source, { platform: process.platform });
  }

  // A check started before a newer refresh must never publish its stale answer.
  if (generation !== _toolVersionGeneration) return;
  _toolVersionCache = { checkedAt: new Date().toISOString(), tools: results };

  const updates = Object.entries(results).filter(([, v]) => v.updateAvailable);
  const broken = Object.entries(results).filter(([, v]) => v.state === 'broken');
  if (updates.length) {
    console.log(`  CLI Tools: ${updates.map(([k, v]) => `${k} v${v.installed}→v${v.latest}`).join(', ')}`);
  } else {
    console.log('  CLI Tools: all up to date');
  }
  for (const [key, info] of broken) console.warn(`  CLI Tools: ${key} at ${info.binPath} does not start: ${info.error}`);
}

// Single-flight: concurrent requests share one refresh instead of each
// spawning their own set of subprocess probes.
let _toolVersionInFlight = null;
let _toolVersionForced = null;
function refreshToolVersions({ force = false, fresh = false } = {}) {
  // A Re-check never takes the answer of a plain check already under way: it
  // reads the OS PATH and asks every --version again.
  if (force) {
    if (fresh || !_toolVersionForced) {
      const refresh = checkToolVersions({ force: true })
        .catch(() => {})
        .finally(() => { if (_toolVersionForced === refresh) _toolVersionForced = null; });
      _toolVersionForced = refresh;
    }
    return _toolVersionForced;
  }
  if (_toolVersionForced) return _toolVersionForced;
  if (!_toolVersionInFlight) {
    _toolVersionInFlight = checkToolVersions()
      .catch(() => {})
      .finally(() => { _toolVersionInFlight = null; });
  }
  return _toolVersionInFlight;
}

app.get('/api/system/tool-versions', async (req, res) => {
  const force = req.query.force === '1';
  if (force || !_toolVersionCache.checkedAt) {
    // force=1 (Re-check, the post-update badge refresh, the panels' poll while
    // a CLI is missing) needs fresh data: await it.
    await refreshToolVersions({ force });
  } else {
    const age = Date.now() - new Date(_toolVersionCache.checkedAt).getTime();
    // Stale-while-revalidate: serve the cached value now, refresh in background.
    if (age > 15 * 60 * 1000) refreshToolVersions();
  }
  res.json(_toolVersionCache);
});

// ── One-click install of a missing CLI (lib/cli-install.js, lib/cli-install-api.js) ──
// The side panels' Install button: the vendor's official installer for this
// system (or OpenCode's release archive on Windows), never a source a request
// names, guarded like the other local mutating endpoints, its progress streamed
// as NDJSON. Its last step is the resolver looking again (force); the tool
// versions are then refreshed, so every panel's next check shows the CLI.
const cliPathManager = createCliPathManager({
  onChanged: () => { _toolVersionCache = { ..._toolVersionCache, checkedAt: null }; },
});
app.use('/api/cli/path', createCliPathApi({
  pathManager: cliPathManager, resolver: cliResolver, isGuestRequest, port: () => PORT,
  diagnostics: async () => {
    const fresh = await freshTerminalPath();
    const statuses = await cliResolver.resolveAll(['claude-code', 'codex', 'opencode']);
    return { platform: process.platform, pathKey: Object.keys(fresh.env).find(key => key.toUpperCase() === 'PATH'),
      entries: fresh.entries, os: fresh.os, pathext: fresh.env.PATHEXT || fresh.env.PathExt || null,
      tools: Object.fromEntries(Object.entries(statuses).map(([tool, status]) => [tool, { path: status.path, launchPath: status.launchPath, ...cliPathManager.inspect(status) }])) };
  },
}));
const cliInstaller = createCliInstaller({
  resolver: cliResolver,
  addToPath: status => cliPathManager.add(status),
  readOsPath: async () => (await osPath.refresh({ force: true })).entries,
  onFinished: () => {
    _toolVersionCache = { ..._toolVersionCache, checkedAt: null };
    // The install changes the disk: even a Re-check already running predates it.
    refreshToolVersions({ force: true, fresh: true });
  },
  log: (line) => console.log(line),
});
app.use('/api/cli/install', createCliInstallApi({ installer: cliInstaller, isGuestRequest, port: () => PORT, log: (line) => console.warn(line) }));
// Settings beside the CLIs: the Git Bash Claude Code gets on Windows, its download and a new look (lib/git-bash/).
app.use('/api/cli/git-bash', createGitBashApi({ manager: gitBash, isGuestRequest, port: () => PORT, onRecheck: async () => { syncGitBashSettings(); } }));

// ═══════════════════════════════════════════
// FULL SYSTEM BACKUP & RESTORE
// ═══════════════════════════════════════════

// GET /api/system/backup — Download full system backup as ZIP
app.get('/api/system/backup', async (req, res) => {
  try {
    const manualDir = resolve(DATA_HOME, 'backups', 'manual-staging');
    const pkg = JSON.parse(readFileSync(resolve(PACKAGE_ROOT, 'package.json'), 'utf-8'));
    const backup = await serializeBackupOperation(() => createVerifiedBackup({
      dataHome: DATA_HOME,
      databasePath: getDbPath(),
      folderPath: manualDir,
      kind: 'manual',
      appVersion: pkg.version || null,
      additionalEntries: getBackupAdditionalEntries(),
    }));
    res.download(backup.path, backup.name, error => {
      try { if (existsSync(backup.path)) unlinkSync(backup.path); } catch {}
      if (error && !res.headersSent) res.status(500).json({ error: error.message });
    });
    return;

  } catch (err) {
    console.error('GET /api/system/backup error:', err.message);
    if (!res.headersSent) res.status(500).json({ error: err.message });
  }
});

// Restore uploads stream to disk: a data home can pass the old 1 GB body cap,
// and a ZIP over 2 GiB cannot be read into a Buffer at all.
const RESTORE_STAGING_DIR = resolve(DATA_HOME, 'backups', 'restore-staging');

// POST /api/system/restore/preview — Read manifest from uploaded ZIP without applying
app.post('/api/system/restore/preview', async (req, res) => {
  let upload = null;
  let zip = null;
  try {
    upload = await saveRestoreUpload(req, RESTORE_STAGING_DIR);
    if (upload.sizeBytes === 0) {
      return res.status(400).json({ error: 'No data received' });
    }
    zip = await openZipArchive(upload.path);
    const found = await readBackupManifest(zip);
    if (!found) {
      return res.status(400).json({ error: 'Invalid backup: manifest.json not found' });
    }
    res.json({ ok: true, manifest: found.manifest });
  } catch (err) {
    console.error('POST /api/system/restore/preview error:', err.message);
    if (!res.headersSent) res.status(500).json({ error: err.message });
  } finally {
    await zip?.close().catch(() => {});
    removeRestoreUpload(upload);
  }
});

// POST /api/system/restore — Apply a full system backup from uploaded ZIP
app.post('/api/system/restore', async (req, res) => {
  let upload = null;
  let zip = null;
  try {
    upload = await saveRestoreUpload(req, RESTORE_STAGING_DIR);
    if (upload.sizeBytes === 0) {
      return res.status(400).json({ error: 'No backup data received' });
    }

    const mode = req.query.mode || 'full';

    zip = await openZipArchive(upload.path);

    // Find and validate manifest
    const found = await readBackupManifest(zip);
    if (!found) {
      return res.status(400).json({ error: 'Invalid backup: manifest.json not found' });
    }
    const { manifest, prefix } = found;
    if (![1, 2, 3].includes(manifest.version)) {
      return res.status(400).json({ error: `Unsupported backup version: ${manifest.version}` });
    }

    // v3 archives are published only after checksum verification. Recheck on
    // restore so a damaged or edited snapshot cannot partially replace state.
    if (manifest.version >= 3) {
      try { await verifyBackupChecksums(zip, { prefix, manifest, label: 'Invalid backup' }); }
      catch (error) { return res.status(400).json({ error: error.message }); }
    }

    const entryAt = rel => zip.getEntry(`${prefix}/${rel}`);
    const results = { files: [], snapshots: [], errors: [] };

    // Restore config files
    if (mode === 'full' || mode === 'config-only') {
      // Every target must stay inside its root. Plan all writes first so a
      // crafted entry (../../) rejects the archive before anything is written.
      const home = process.env.USERPROFILE || process.env.HOME || '';
      const { writes, unsafe } = planRestoreWrites(zip, prefix, {
        data: resolve(DATA_HOME, 'data'),
        mcpData: CATEGORIES_DATA_DIR,
        globalSkills: getGlobalSkillsDir(),
        globalAgents: getGlobalAgentsDir(),
        bundledSkills: SKILLS_SOURCE_DIR,
        skins: join(__dirname, 'skins'),
        claudeSettings: home ? join(home, '.claude', 'settings.json') : null,
      });
      if (unsafe.length) {
        return res.status(400).json({ error: `Invalid backup: unsafe path ${unsafe[0]}` });
      }

      // .env
      const envEntry = entryAt('env.bak');
      if (envEntry) {
        await extractZipEntry(zip, envEntry, ENV_PATH);
        results.files.push('.env');
      }

      // data/ files
      const dataDir = resolve(DATA_HOME, 'data');
      mkdirSync(dataDir, { recursive: true });
      for (const subdir of ['pending-remember', 'pending-compact', 'loop', 'plans']) {
        mkdirSync(resolve(dataDir, subdir), { recursive: true });
      }

      // Per-user MCP data (~/.synabun/mcp-data by default)
      mkdirSync(CATEGORIES_DATA_DIR, { recursive: true });

      // data/, mcp-data/, global skills/agents (~/.claude), bundled skills,
      // installed skins and ~/.claude/settings.json.
      for (const { entry, rel, target } of writes) {
        await extractZipEntry(zip, entry, target);
        results.files.push(rel);
      }
    }

    // Normalize SQLITE_DB_PATH from restored .env to local default
    // (backup may contain paths from a different OS, e.g. J:\Sites\... from Windows)
    if (mode === 'full' || mode === 'config-only') {
      const localDefaultDbPath = resolve(CATEGORIES_DATA_DIR, 'memory.db');
      const vars = parseEnvFile(ENV_PATH);
      const restoredPath = vars['SQLITE_DB_PATH'] || '';
      // If the restored path doesn't exist on this OS, reset to local default
      if (restoredPath && !existsSync(dirname(restoredPath))) {
        vars['SQLITE_DB_PATH'] = localDefaultDbPath;
        writeEnvFile(ENV_PATH, vars);
        process.env['SQLITE_DB_PATH'] = localDefaultDbPath;
        results.files.push('(normalized SQLITE_DB_PATH to local default)');
      }
      reloadConfig();
    }

    // Restore SQLite database
    if (mode === 'full' || mode === 'snapshots-only') {
      const dbEntry = entryAt('database/memory.db');
      if (dbEntry) {
        try {
          // Close existing database connection before replacing
          closeDb();
          // Always restore to local default path, ignoring any cross-OS path from .env
          const dbPath = resolve(CATEGORIES_DATA_DIR, 'memory.db');
          // Update .env and runtime to point here
          const vars = parseEnvFile(ENV_PATH);
          vars['SQLITE_DB_PATH'] = dbPath;
          writeEnvFile(ENV_PATH, vars);
          process.env['SQLITE_DB_PATH'] = dbPath;
          const dbDir = dirname(dbPath);
          mkdirSync(dbDir, { recursive: true });
          await extractZipEntry(zip, dbEntry, dbPath);
          // Remove WAL/SHM files if they exist
          try { if (existsSync(dbPath + '-wal')) unlinkSync(dbPath + '-wal'); } catch {}
          try { if (existsSync(dbPath + '-shm')) unlinkSync(dbPath + '-shm'); } catch {}
          results.files.push('database/memory.db');
        } catch (err) {
          results.errors.push(`Failed to restore database: ${err.message}`);
        }
      } else if (manifest.connections && Object.keys(manifest.connections).length > 0) {
        // Old Qdrant-format backup detected
        results.errors.push('This backup contains Qdrant snapshots (old format). Run the migration script to convert to SQLite first.');
      }
    }

    // Post-restore: ensure MCP server is built (critical for fresh installs + restore). Built means dist/index.js
    // and every module it imports (lib/mcp-dist.js).
    if (!mcpDistBuilt(PACKAGE_ROOT)) {
      try {
        // TypeScript is a devDependency of the package root (a development checkout also has it in mcp-server/).
        const mcpDir = resolve(PACKAGE_ROOT, 'mcp-server');
        if (!mcpCompiler(PACKAGE_ROOT)) {
          const npm = npmCommand(npmInvocation(), fallbackInstallArgs({ includeDev: true }));
          await execFileAsync(npm.file, npm.args, { cwd: PACKAGE_ROOT, timeout: 600_000, maxBuffer: 16 * 1024 * 1024, shell: npm.shell, windowsHide: true, env: withPackagedPathLast(fallbackInstallEnv({ ...process.env, NODE_ENV: 'development' })) });
        }
        await execFileAsync(process.execPath, [mcpCompiler(PACKAGE_ROOT), '-p', mcpDir], { cwd: mcpDir, timeout: 120_000, maxBuffer: 16 * 1024 * 1024, windowsHide: true });
        results.files.push('(auto-built MCP server)');
      } catch (buildErr) {
        results.errors.push(`MCP server auto-build failed: ${buildErr.message}`);
      }
    }

    res.json({ ok: true, message: 'Backup restored successfully', results });
  } catch (err) {
    console.error('POST /api/system/restore error:', err.message);
    if (!res.headersSent) res.status(500).json({ error: err.message });
  } finally {
    await zip?.close().catch(() => {});
    removeRestoreUpload(upload);
  }
});

// ═══════════════════════════════════════════
// AUTO-BACKUP SYSTEM
// ═══════════════════════════════════════════

const AUTO_BACKUP_CONFIG_PATH = resolve(DATA_HOME, 'data', 'auto-backup-config.json');

function loadAutoBackupConfig() {
  return loadBackupConfigFile(AUTO_BACKUP_CONFIG_PATH);
}

function saveAutoBackupConfig(cfg) {
  return saveBackupConfigFile(AUTO_BACKUP_CONFIG_PATH, cfg);
}

let _autoBackupTimer = null;
let _autoBackupPromise = null;
let _backupOperationTail = Promise.resolve();
let _backupOperationActive = false;
let _autoBackupLastAttemptMs = 0;

function trySaveAutoBackupConfig(cfg, context) {
  try {
    saveAutoBackupConfig(cfg);
    return true;
  } catch (error) {
    console.error(`[auto-backup] Could not persist ${context}: ${error.message}`);
    return false;
  }
}

function serializeBackupOperation(operation) {
  const run = _backupOperationTail
    .catch(() => {})
    .then(async () => {
      _backupOperationActive = true;
      try { return await operation(); }
      finally { _backupOperationActive = false; }
    });
  _backupOperationTail = run.catch(() => {});
  return run;
}

function getBackupAdditionalEntries() {
  const entries = [];
  const add = (archivePath, diskPath) => {
    if (diskPath && existsSync(diskPath)) entries.push({ archivePath, diskPath });
  };
  add('global-skills', getGlobalSkillsDir());
  add('global-agents', getGlobalAgentsDir());
  add('bundled-skills', SKILLS_SOURCE_DIR);
  add('skins', join(__dirname, 'skins'));
  const home = process.env.USERPROFILE || process.env.HOME || '';
  if (home) add('claude-settings.json', join(home, '.claude', 'settings.json'));
  return entries;
}

function backupConfigResponse(cfg = loadAutoBackupConfig()) {
  const snapshots = cfg.folderPath ? listBackupSnapshots(cfg.folderPath) : [];
  const health = getBackupHealth(cfg, { snapshots });
  if (_backupOperationActive || _autoBackupPromise) {
    health.status = 'running';
    health.reason = 'A backup is currently being created and verified.';
  }
  return {
    ...cfg,
    health,
    snapshots: snapshots.slice(0, 100),
  };
}

async function runAutoBackup({ force = false, kind = 'scheduled', folderPath = null } = {}) {
  if (_autoBackupPromise) return _autoBackupPromise;
  _autoBackupPromise = (async () => {
    const cfg = loadAutoBackupConfig();
    const destination = folderPath || cfg.folderPath;
    if ((!cfg.enabled && !force) || !destination) return { skipped: true, reason: 'disabled-or-unconfigured' };

    cfg.lastAttemptAt = new Date().toISOString();
    _autoBackupLastAttemptMs = Date.parse(cfg.lastAttemptAt) || Date.now();
    if (!trySaveAutoBackupConfig(cfg, 'backup attempt state')) {
      const error = 'Backup skipped because its attempt state could not be persisted.';
      console.error(`[auto-backup] Failed: ${error}`);
      return { error };
    }
    try {
      const pkg = JSON.parse(readFileSync(resolve(PACKAGE_ROOT, 'package.json'), 'utf-8'));
      let preRetention = null;
      const backup = await serializeBackupOperation(async () => {
        if (kind === 'scheduled') {
          preRetention = applyBackupRetention({
            folderPath: destination,
            retention: cfg.retention,
            incomingBytes: cfg.lastBackupSize,
          });
        }
        return createVerifiedBackup({
          dataHome: DATA_HOME,
          databasePath: getDbPath(),
          folderPath: destination,
          kind,
          appVersion: pkg.version || null,
          additionalEntries: getBackupAdditionalEntries(),
          expectedArchiveBytes: cfg.lastBackupSize,
        });
      });
      const retention = applyBackupRetention({ folderPath: destination, retention: cfg.retention });
      cfg.lastVerifiedBackup = backup.createdAt;
      cfg.lastBackup = backup.createdAt; // backward compatibility
      cfg.lastBackupPath = backup.path;
      cfg.lastBackupSize = backup.sizeBytes;
      cfg.lastBackupError = null;
      cfg.retentionWarning = retention.capExceeded
        ? 'Backup retention cap is exceeded by pinned/protected snapshots.'
        : null;
      const configPersisted = trySaveAutoBackupConfig(cfg, 'verified backup state');
      console.log(`[auto-backup] Verified ${(backup.sizeBytes / 1024 / 1024).toFixed(1)} MB → ${backup.path}`);
      return { backup, preRetention, retention, configPersisted };
    } catch (err) {
      cfg.lastBackupError = err.message;
      trySaveAutoBackupConfig(cfg, 'backup failure state');
      console.error(`[auto-backup] Failed: ${err.message}`);
      return { error: err.message };
    }
  })();
  try { return await _autoBackupPromise; }
  finally { _autoBackupPromise = null; }
}

function startAutoBackupScheduler() {
  stopAutoBackupScheduler();
  const cfg = loadAutoBackupConfig();
  if (!cfg.enabled || !cfg.folderPath || !cfg.intervalMinutes) return;
  // Shared with getBackupHealth so the Settings "next due" matches the timer.
  const nextDue = nextBackupDueMs(cfg, { lastAttemptMs: _autoBackupLastAttemptMs });
  const delay = Math.max(0, Math.min(2_147_000_000, nextDue - Date.now()));
  _autoBackupTimer = setTimeout(async () => {
    try { await runAutoBackup(); }
    catch (error) { console.error(`[auto-backup] Scheduler failed safely: ${error.message}`); }
    finally { startAutoBackupScheduler(); }
  }, delay);
  console.log(`[auto-backup] Scheduler started: next ${new Date(Date.now() + delay).toISOString()} → ${cfg.folderPath}`);
}

function stopAutoBackupScheduler() {
  if (_autoBackupTimer) {
    clearInterval(_autoBackupTimer);
    _autoBackupTimer = null;
  }
}

// Boot: start scheduler if enabled
startAutoBackupScheduler();

// GET /api/system/auto-backup — Get auto-backup config
app.get('/api/system/auto-backup', (req, res) => {
  res.json(backupConfigResponse());
});

// PUT /api/system/auto-backup — Update auto-backup config
app.put('/api/system/auto-backup', (req, res) => {
  try {
    const current = loadAutoBackupConfig();
    const { enabled, intervalMinutes, folderPath, retention } = req.body;

    if (typeof enabled === 'boolean') current.enabled = enabled;
    if (typeof intervalMinutes === 'number' && intervalMinutes >= 1) current.intervalMinutes = intervalMinutes;
    if (typeof folderPath === 'string') current.folderPath = folderPath.trim();
    if (retention && typeof retention === 'object') current.retention = normalizeBackupConfig({ retention }).retention;

    saveAutoBackupConfig(current);

    // Restart scheduler with new config
    if (current.enabled && current.folderPath) {
      startAutoBackupScheduler();
    } else {
      stopAutoBackupScheduler();
    }

    res.json({ ok: true, config: backupConfigResponse(current) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/system/auto-backup/trigger — Run auto-backup now
app.post('/api/system/auto-backup/trigger', async (req, res) => {
  try {
    const cfg = loadAutoBackupConfig();
    if (!cfg.folderPath) return res.status(400).json({ error: 'No backup folder configured' });
    const result = await runAutoBackup({ force: true });
    if (result?.error) return res.status(500).json({ error: result.error, ...backupConfigResponse() });
    res.json(backupConfigResponse());
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/system/backups — verified/runtime backup history for Settings.
app.get('/api/system/backups', (req, res) => {
  try {
    const cfg = loadAutoBackupConfig();
    const snapshots = cfg.folderPath ? listBackupSnapshots(cfg.folderPath) : [];
    res.json({ ok: true, snapshots, health: getBackupHealth(cfg, { snapshots }), retention: cfg.retention });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/projects — List registered projects for file explorer selector
// `capabilities` tells the File Explorer, in the request it makes anyway, that this server has its routes
// (/api/explorer, lib/file-explorer-api.js): a page loaded against an older server finds none and asks for none.
app.get('/api/projects', (req, res) => {
  const projects = loadHookProjects();
  res.json({ ok: true, projects: projects.map(p => ({ path: p.path, label: p.label || basename(p.path) })), capabilities: [...EXPLORER_CAPABILITIES] });
});

// ── Path validation helper (reused by project-files, file-content) ──
// The roots a file path may be under: folders, and single files allowed by their exact path.
function allowedFileRoots() {
  const registeredProjects = loadHookProjects();
  const claudePlansDir = resolve(join(process.env.USERPROFILE || process.env.HOME || '', '.claude', 'plans'));
  const localPlansDir = resolve(join(DATA_HOME, 'data', 'plans'));
  // OpenCode's global configuration documents (the "Open config" link of Settings → OpenCode).
  const opencodeConfigFiles = ['opencode.json', 'opencode.jsonc'].map((name) => resolve(getOpencodeConfigDir(), name));
  return {
    dirs: [resolve(DATA_HOME), ...registeredProjects.map(p => resolve(p.path)), localPlansDir, claudePlansDir],
    files: opencodeConfigFiles,
  };
}

function validateProjectPath(filePath) {
  const normalized = resolve(filePath);
  const { dirs, files } = allowedFileRoots();
  const matched = [...dirs, ...files].find(r => normalized === r || normalized.startsWith(r + sep));
  return matched ? normalized : null;
}

// ── Code editor (File Explorer): file routes and preferences ──
// lib/editor-files-api.js: GET / POST / DELETE /api/file-content, POST /api/file-mkdir,
// POST /api/file-stat, GET /api/editor/capabilities. lib/editor-config.js: GET / PUT /api/editor/config.
// lib/editor-completion.js: the routes under /api/editor/complete (AI autocomplete).
// lib/editor-git-api.js: GET /api/file-head (a file as the last commit has it; git is only ever read).
const editorConfigStore = createEditorConfigStore({
  path: resolve(DATA_HOME, 'data', 'editor-config.json'),
  log: (tag, message) => console.error(`[${tag}] ${message}`),
});
// AI autocomplete (lib/editor-completion.js): POST /api/editor/complete, /test and /feedback, GET /models and
// /usage. OpenCode models are asked through a serve of their own (lib/editor-completion-opencode.js: started on
// the first request, stopped after ten idle minutes and at shutdown, never the shared serve), or a
// user-configured endpoint is, whose key is SYNABUN_EDITOR_AI_KEY in the data home's .env.
const editorEndpointKey = createEndpointKeyStore({ envPath: ENV_PATH, parseEnvFile, writeEnvFile });
// The completion serve's process → its record (trackOpencodeServe), from its spawn until it has ended.
const editorCompletionServeTracks = new WeakMap();
const editorCompletionServe = createOpencodeCompletionEngine({
  dataDir: resolve(DATA_HOME, 'data', 'editor-complete'),
  system: COMPLETION_SYSTEM,
  // The user's global configuration (opencode.json, then opencode.jsonc over it).
  readUserConfig: () => readOpencodeGlobalConfig().config,
  // A provider's {file:./key} is relative to that configuration: it is written whole for the serve's own folder.
  userConfigDir: () => getOpencodeConfigDir(),
  // What an earlier SynaBun left running goes first (lib/opencode-serve-records.js), then a port is picked.
  allocPort: async () => { await sweepLeftoverOpencodeServes(); return allocOpencodeIsoPort(); },
  // On record from its spawn (spawnServe), its record gone with its process: a crash of SynaBun does not leave it
  // running. Once something answers on its port: is it this start's own serve ('foreign': another server took the
  // port, which the engine leaves running while it tries another)?
  trackServe: ({ proc }) => editorCompletionServeTracks.get(proc)?.answering(),
  // As the isolated serves are started (opencodeServeLaunch): the CLI the resolver found, through the login shell,
  // with the password OpenCode prints privately for this start; its start waits its turn among every serve SynaBun starts
  // (one OpenCode database cannot be opened by two serves at once).
  detectOpencode: () => detectOpencode(),
  startOneAtATime: oneOpencodeStartAtATime,
  passwordFrom: 'stdout',
  checkServer: checkOpencodeServer,
  spawnServe: ({ port, env, cwd }) => {
    const token = opencodeServeRecords.newToken();
    const launch = opencodeServeLaunch(port, { env: { ...env, [SERVE_TOKEN_ENV]: token }, passwordFrom: 'stdout' });
    const proc = spawn(launch.command, launch.args, { stdio: ['ignore', 'pipe', 'pipe'], ...launch.options, cwd, detached: false, shell: false, windowsHide: true });
    editorCompletionServeTracks.set(proc, trackOpencodeServe(proc, { kind: 'completion', id: 'editor-complete', port, token, nativeWebSocketSafe: launch.nativeWebSocketSafe }));
    const outLog = createServeLogRedactor(line => console.log(`[editor-complete:out] ${line.trim().slice(0, 500)}`));
    const errLog = createServeLogRedactor(line => console.log(`[editor-complete:err] ${line.trim().slice(0, 500)}`));
    proc.stdout?.on('data', d => outLog.push(d));
    proc.stderr?.on('data', d => errLog.push(d));
    proc.stdout?.on('end', () => outLog.flush());
    proc.stderr?.on('end', () => errLog.flush());
    proc.on('close', () => { outLog.flush(); errLog.flush(); });
    return proc;
  },
  // SIGTERM to stop it; SIGKILL, through its handle, for a failed start's process that did not end (Windows: taskkill /T /F).
  killServe: (proc, signal = 'SIGTERM') => {
    try {
      if (IS_WIN && proc.pid) spawn('taskkill', ['/pid', String(proc.pid), '/T', '/F'], { shell: true, windowsHide: true, stdio: 'ignore' });
      else proc.kill(signal);
    } catch { /* already gone */ }
  },
  createClient: opencodeV2Client.createClientInstance,
  log: (tag, message) => console.log(`[${tag}] ${message}`),
});
const editorCompletion = createEditorCompletionService({
  readConfig: editorConfigStore.read,
  engines: { opencode: editorCompletionServe, endpoint: createEndpointCompletionEngine() },
  getEndpointKey: editorEndpointKey.get,
  // The model list comes from the shared serve while it runs: listing models starts nothing.
  sharedProviders: async () => {
    if (!_ocpReady) return null;
    // The connected providers, from the kept list (the same read as the pickers').
    try { return (await readOpencodeProviders('compact')).compact; } catch { return null; }
  },
  isHiddenModel: (id) => opencodeHiddenModels.has(id),
  usage: createUsageStore({
    path: resolve(DATA_HOME, 'data', 'editor-ai-usage.json'),
    log: (tag, message) => console.error(`[${tag}] ${message}`),
  }),
  log: (tag, message) => console.warn(`[${tag}] ${message}`),
});
app.use(createEditorFilesRouter({ fileRoots: allowedFileRoots, guard: editorOwnerGuard, capabilities: () => [...EDITOR_CONFIG_CAPABILITIES, ...EDITOR_COMPLETION_CAPABILITIES, ...EDITOR_BACKUP_CAPABILITIES, ...EDITOR_GIT_CAPABILITIES] }));
app.use(createEditorGitRouter({ fileRoots: allowedFileRoots, guard: editorOwnerGuard }));
app.use('/api/editor/config', createEditorConfigRouter({
  store: editorConfigStore,
  guard: editorOwnerGuard,
  broadcastSync,
  hasEndpointKey: editorEndpointKey.has,
  setEndpointKey: editorEndpointKey.set,
}));
app.use('/api/editor/complete', createEditorCompletionRouter({ service: editorCompletion, guard: editorOwnerGuard }));

// The File Explorer's own routes (lib/file-explorer-api.js, docs/file-explorer.md): one folder, search, the git
// state of a project, the watcher's event stream, and what is done to files (new, rename, move, copy, delete to
// the system's Trash, upload, reveal, the bytes of an image). The same guard as the editor's routes.
// The guard looks at the Origin of a write only; the router refuses a read from another site's page as well (a
// watch is a session of which there are sixteen), by the same origins.
app.use('/api/explorer', createFileExplorerRouter({ fileRoots: allowedFileRoots, guard: editorOwnerGuard, origins: { port: PORT, allowedOrigins: publicWebOrigins } }));

// GET /api/latest-plan — Find most recently modified plan file (data/plans/YYYY-MM-DD/ preferred, flat fallback)
app.get('/api/latest-plan', (req, res) => {
  try {
    const localPlansDir = join(DATA_HOME, 'data', 'plans');
    const legacyPlansDir = join(process.env.USERPROFILE || process.env.HOME || '', '.claude', 'plans');
    const maxAge = 24 * 60 * 60 * 1000; // 24 hours
    const now = Date.now();
    const files = [];

    // Primary: scan localPlansDir — date subdirectories (YYYY-MM-DD/) and legacy flat files
    if (existsSync(localPlansDir)) {
      for (const entry of readdirSync(localPlansDir)) {
        if (entry.startsWith('.')) continue;
        const entryPath = join(localPlansDir, entry);
        const entryStat = statSync(entryPath);
        if (entryStat.isDirectory() && /^\d{4}-\d{2}-\d{2}$/.test(entry)) {
          for (const f of readdirSync(entryPath).filter(f => f.endsWith('.md'))) {
            const fullPath = join(entryPath, f);
            const st = statSync(fullPath);
            if ((now - st.mtimeMs) < maxAge) {
              files.push({ name: f, path: fullPath.replace(/\\/g, '/'), mtime: st.mtimeMs });
            }
          }
        } else if (entry.endsWith('.md')) {
          if ((now - entryStat.mtimeMs) < maxAge) {
            files.push({ name: entry, path: entryPath.replace(/\\/g, '/'), mtime: entryStat.mtimeMs });
          }
        }
      }
    }

    // Fallback: ~/.claude/plans/ (flat only)
    if (existsSync(legacyPlansDir)) {
      for (const f of readdirSync(legacyPlansDir).filter(f => f.endsWith('.md'))) {
        if (files.some(r => r.name === f)) continue;
        const fullPath = join(legacyPlansDir, f);
        const st = statSync(fullPath);
        if ((now - st.mtimeMs) < maxAge) {
          files.push({ name: f, path: fullPath.replace(/\\/g, '/'), mtime: st.mtimeMs });
        }
      }
    }

    files.sort((a, b) => b.mtime - a.mtime);

    if (!files.length) return res.json({ ok: true, found: false });
    res.json({ ok: true, found: true, path: files[0].path, name: files[0].name, mtime: files[0].mtime });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

function cleanupMatchingRootPlan(cwd, content) {
  if (!cwd || typeof cwd !== 'string' || typeof content !== 'string') return false;
  try {
    const rootPlan = resolve(cwd, 'PLAN.md');
    if (!validateProjectPath(rootPlan) || !existsSync(rootPlan) || !statSync(rootPlan).isFile()) return false;
    // PLAN.md arrived with the project's repository: it is read as a regular
    // file really inside the folder, and no more of it than a plan can be
    // (lib/confined-fs.js). Anything else is not this plan, and stays.
    const existing = readConfinedFile(resolve(cwd), rootPlan, { maxBytes: 2 * 1024 * 1024, encoding: 'utf-8' }).replace(/\r\n/g, '\n').trim();
    const next = content.replace(/\r\n/g, '\n').trim();
    if (!existing || existing !== next) return false;
    unlinkSync(rootPlan);
    return true;
  } catch {
    return false;
  }
}

const _NARRATION_PREFIX = /^(thought\b|›|thinking[:\s]|let me\b|i'?ll\b|i will\b|i (have|see|need|found|checked)\b|i'?ve (found|checked|seen|got)\b|now i (have|see|understand|need)\b|here'?s\b|looking at\b|based on (the|my|your)\b|okay,?\s|alright,?\s|so\s+(i|we)\s+(need|should|can)|the user (wants|asked|is asking|needs)|the recent\b|found it\b)/i;

function writePlanFile(content, opts = {}) {
  if (!content || typeof content !== 'string') return { ok: false, status: 400, error: 'Missing content' };
  const h1 = content.match(/^#\s+(.+)$/m);
  if (!h1) {
    const firstLine = (content.split('\n').find(l => l.trim()) || '').trim();
    if (_NARRATION_PREFIX.test(firstLine)) {
      return { ok: false, status: 422, error: 'Plan content looks like thinking/preamble, not a plan (no H1, starts with narration marker)' };
    }
  }
  const d = new Date();
  const ymd = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  const plansDir = join(DATA_HOME, 'data', 'plans', ymd);
  if (!existsSync(plansDir)) mkdirSync(plansDir, { recursive: true });
  const title = h1 ? h1[1].trim() : (content.split('\n').find(l => l.trim()) || 'untitled').trim();
  const slug = (title || 'untitled')
    .toLowerCase()
    .replace(/^plan[:\s]+/i, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60) || 'untitled';
  // Idempotent: same-slug + identical content returns existing path so the
  // server hook and a UI retry don't race into slug-2.md duplicates.
  const sameContent = (path) => {
    try { return readFileSync(path, 'utf-8') === content; } catch { return false; }
  };
  let name = `${slug}.md`;
  let fullPath = join(plansDir, name);
  if (existsSync(fullPath)) {
    if (sameContent(fullPath)) return { ok: true, path: fullPath.replace(/\\/g, '/'), name, idempotent: true };
    let n = 2;
    while (existsSync(join(plansDir, `${slug}-${n}.md`))) {
      const candidate = join(plansDir, `${slug}-${n}.md`);
      if (sameContent(candidate)) return { ok: true, path: candidate.replace(/\\/g, '/'), name: `${slug}-${n}.md`, idempotent: true };
      n++;
    }
    name = `${slug}-${n}.md`;
    fullPath = join(plansDir, name);
  }
  writeFileSync(fullPath, content, 'utf-8');
  const cleanedRootPlan = cleanupMatchingRootPlan(opts.projectPath || opts.cwd || '', content);
  return { ok: true, path: fullPath.replace(/\\/g, '/'), name, cleanedRootPlan };
}

// POST /api/create-plan — Materialize plan content into a file in data/plans/YYYY-MM-DD/slug.md
app.post('/api/create-plan', (req, res) => {
  try {
    const { content, cwd, projectPath } = req.body;
    const result = writePlanFile(content, { cwd, projectPath });
    if (!result.ok) return res.status(result.status || 500).json({ error: result.error });
    res.json(result);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/project-files — List ALL files (incl. dotfiles) for file explorer sidebar
// The owner's, like the file routes: the names of a project's files are not an invited guest's to list.
app.get('/api/project-files', editorOwnerGuard, async (req, res) => {
  try {
    const root = DATA_HOME;
    let dir = req.query.path ? resolve(req.query.path) : root;
    const search = (req.query.search || '').trim();
    const recursive = req.query.recursive === '1' || req.query.recursive === 'true';
    const filesOnly = req.query.filesOnly === '1' || req.query.filesOnly === 'true';

    // Security: allow paths within any registered project root
    const normalizedDir = resolve(dir);
    const registeredProjects = loadHookProjects();
    const allowedRoots = [resolve(root), ...registeredProjects.map(p => resolve(p.path))];
    const normalizedRoot = allowedRoots.find(r => normalizedDir === r || normalizedDir.startsWith(r + sep));
    if (!normalizedRoot) {
      return res.status(403).json({ error: 'Path outside registered project roots' });
    }
    if (!existsSync(normalizedDir) || !statSync(normalizedDir).isDirectory()) {
      return res.status(400).json({ error: 'Not a valid directory' });
    }
    // Judged as the disk resolves it too: a link that leads out of its project is not listed.
    if (!isInsideReal(normalizedRoot, normalizedDir, { allowRoot: true })) {
      return res.status(403).json({ error: 'Path outside registered project roots' });
    }

    // Git info for status badges
    const git = getGitInfo(normalizedDir);

    if (recursive || (search && search.length > 2)) {
      // Recursive search mode
      const SKIP = new Set(['.git', 'node_modules', '__pycache__', '.next', 'dist', '.cache']);
      const MAX_RESULTS = 100;
      const MAX_VISITED = 20000;   // bound the walk on huge trees with few matches
      const results = [];
      let visited = 0;
      const lowerSearch = search.toLowerCase();

      function walkSearch(d) {
        if (results.length >= MAX_RESULTS || visited >= MAX_VISITED) return;
        let entries;
        try { entries = readdirSync(d, { withFileTypes: true }); } catch { return; }
        for (const e of entries) {
          if (results.length >= MAX_RESULTS || visited >= MAX_VISITED) break;
          visited++;
          if (SKIP.has(e.name)) continue;
          const full = join(d, e.name);
          const relativePath = full.substring(normalizedDir.length).replace(/^[\\/]+/, '').replace(/\\/g, '/');
          if ((!lowerSearch || relativePath.toLowerCase().includes(lowerSearch)) && (!filesOnly || e.isFile())) {
            const rel = full.substring(normalizedRoot.length).replace(/\\/g, '/');
            const item = { name: e.name, type: e.isDirectory() ? 'dir' : 'file', path: rel, relativePath };
            if (e.isFile()) {
              try {
                const s = statSync(full);
                item.size = s.size;
                item.mtime = s.mtimeMs;
              } catch {}
            }
            results.push(item);
          }
          if (e.isDirectory()) walkSearch(full);
        }
      }

      walkSearch(normalizedDir);
      return res.json({ path: normalizedDir.replace(/\\/g, '/'), items: results, search: true, branch: git?.branch || null });
    }

    // Normal directory listing — async so a directory with thousands of entries
    // doesn't block the event loop on readdir + a per-file statSync loop.
    let entries = await fsp.readdir(normalizedDir, { withFileTypes: true });

    // Cap very large directories so the stat fan-out, response payload, and client
    // render stay bounded. Sort dirs-first + alpha BEFORE slicing so the kept slice
    // is stable and useful rather than filesystem-order.
    const LISTING_CAP = 2000;
    const total = entries.length;
    let truncated = false;
    if (total > LISTING_CAP) {
      entries.sort((a, b) => {
        const ad = a.isDirectory(), bd = b.isDirectory();
        if (ad !== bd) return ad ? -1 : 1;
        return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
      });
      entries = entries.slice(0, LISTING_CAP);
      truncated = true;
    }

    // Stat files in parallel (directories need no stat). Bounded by LISTING_CAP.
    const items = await Promise.all(entries.map(async (e) => {
      const item = { name: e.name, type: e.isDirectory() ? 'dir' : 'file' };
      if (e.isFile()) {
        try {
          const s = await fsp.stat(join(normalizedDir, e.name));
          item.size = s.size;
          item.mtime = s.mtimeMs;
        } catch {}
      }
      if (git?.statuses?.has(e.name)) {
        item.git = git.statuses.get(e.name);
      }
      return item;
    }));

    // Sort: dirs first, then alphabetical
    items.sort((a, b) => {
      if (a.type !== b.type) return a.type === 'dir' ? -1 : 1;
      return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
    });

    const parent = normalizedDir !== normalizedRoot
      ? resolve(normalizedDir, '..').replace(/\\/g, '/')
      : null;

    res.json({
      path: normalizedDir.replace(/\\/g, '/'),
      items,
      branch: git?.branch || null,
      parent,
      total,
      truncated
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/browse-directory — List directories at a given path for folder picker UI
app.get('/api/browse-directory', (req, res) => {
  try {
    let dir = req.query.path || '';
    // Default to common roots on Windows / Unix
    if (!dir) {
      const home = process.env.USERPROFILE || process.env.HOME || '/';
      dir = home;
    }
    dir = resolve(dir);
    if (!existsSync(dir) || !statSync(dir).isDirectory()) {
      return res.status(400).json({ error: 'Not a valid directory' });
    }
    const entries = readdirSync(dir, { withFileTypes: true });
    const dirs = entries
      .filter(e => e.isDirectory() && !e.name.startsWith('.'))
      .map(e => e.name)
      .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
    // Parent directory (unless at root)
    const parent = resolve(dir, '..');
    res.json({ ok: true, current: dir, parent: parent !== dir ? parent : null, directories: dirs });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/browse-folder — Open native OS folder picker dialog
// Async exec: the dialog stays open for up to 60s — execSync here froze the
// entire server (every WS stream, every request) until the user dismissed it.
// The dialog opens on the owner's machine: the owner's route. Its prompt is handed to the picker as an argument
// (lib/file-explorer-system.js), never as part of a command line: a request cannot make it run anything.
app.post('/api/browse-folder', editorOwnerGuard, async (req, res) => {
  try {
    const { description } = req.body || {};
    const picker = folderPickerCommand(process.platform, typeof description === 'string' ? description : '', { scriptPath: resolve(__dirname, 'lib', 'folder-picker.ps1') });
    const { stdout } = await execFileAsync(picker.file, picker.args, { encoding: 'utf8', timeout: 60000, windowsHide: true });
    const result = stdout.trim();
    if (result) {
      res.json({ path: result.replace(/\\/g, '/') });
    } else {
      res.json({ path: null, cancelled: true });
    }
  } catch {
    res.json({ path: null, cancelled: true });
  }
});

