// ── "Both": register MoreLogin's OWN MCP server into installed agent configs ──
const MORELOGIN_MCP_KEY = 'MoreLogin';

// Normalize a pasted MoreLogin MCP block into { command, args, env, url, type }.
// Accepts a bare entry, a { mcpServers: { name: {...} } }, or { mcp: { name: {...} } }.
function _normalizeMcpEntry(input) {
  if (!input || typeof input !== 'object') return null;
  let entry = input;
  if (input.mcpServers && typeof input.mcpServers === 'object') {
    const k = Object.keys(input.mcpServers); if (k.length) entry = input.mcpServers[k[0]];
  } else if (input.mcp && typeof input.mcp === 'object') {
    const k = Object.keys(input.mcp); if (k.length) entry = input.mcp[k[0]];
  }
  if (!entry || typeof entry !== 'object') return null;
  let command = entry.command;
  let args = Array.isArray(entry.args) ? entry.args.slice() : [];
  if (Array.isArray(command)) { args = [...command.slice(1), ...args]; command = command[0]; } // opencode array form
  const env = entry.env || entry.environment || undefined;
  const url = entry.url || undefined;
  const type = entry.type || (url ? 'http' : (command ? 'stdio' : undefined));
  return { command, args, env, url, type };
}

function _writeMoreLoginMcpToAgents(entry) {
  const targets = [];
  const home = getHomePath();
  try { // Claude Code (~/.claude.json)
    const p = join(home, '.claude.json');
    if (existsSync(p)) {
      const data = JSON.parse(readFileSync(p, 'utf8') || '{}');
      if (!data.mcpServers) data.mcpServers = {};
      data.mcpServers[MORELOGIN_MCP_KEY] = entry.url
        ? { type: entry.type || 'http', url: entry.url }
        : { command: entry.command, args: entry.args || [], ...(entry.env ? { env: entry.env } : {}) };
      writeFileSync(p, JSON.stringify(data, null, 2), 'utf8');
      targets.push('Claude Code');
    }
  } catch (e) { console.warn('[morelogin] Claude register failed:', e.message); }
  try { // Gemini (~/.gemini/settings.json)
    const p = join(home, '.gemini', 'settings.json');
    if (existsSync(p)) {
      const data = JSON.parse(readFileSync(p, 'utf8') || '{}');
      if (!data.mcpServers) data.mcpServers = {};
      data.mcpServers[MORELOGIN_MCP_KEY] = entry.url
        ? { url: entry.url, trust: true }
        : { command: entry.command, args: entry.args || [], ...(entry.env ? { env: entry.env } : {}), trust: true };
      writeFileSync(p, JSON.stringify(data, null, 2) + '\n', 'utf8');
      targets.push('Gemini');
    }
  } catch (e) { console.warn('[morelogin] Gemini register failed:', e.message); }
  try { // Codex (~/.codex/config.toml) — stdio only
    const p = join(home, '.codex', 'config.toml');
    if (existsSync(p) && entry.command) {
      let content = readFileSync(p, 'utf8');
      content = tomlUpsertSection(content, `mcp_servers.${MORELOGIN_MCP_KEY}`, {
        command: entry.command, args: entry.args || [], ...(entry.env ? { env: entry.env } : {}),
      });
      writeFileSync(p, content, 'utf8');
      targets.push('Codex');
    }
  } catch (e) { console.warn('[morelogin] Codex register failed:', e.message); }
  try { // OpenCode (its global opencode.json, mcp.servers)
    if (existsSync(getOpencodeConfigDir()) && (entry.command || entry.url)) {
      persistMcpToOpencodeConfig(MORELOGIN_MCP_KEY, entry.url
        ? { url: entry.url }
        : { command: entry.command, args: entry.args || [], env: entry.env });
      targets.push('OpenCode');
    }
  } catch (e) { console.warn('[morelogin] OpenCode register failed:', e.message); }
  return targets;
}

function _removeMoreLoginMcpFromAgents() {
  const targets = [];
  const home = getHomePath();
  try {
    const p = join(home, '.claude.json');
    if (existsSync(p)) {
      const data = JSON.parse(readFileSync(p, 'utf8') || '{}');
      if (data.mcpServers && data.mcpServers[MORELOGIN_MCP_KEY]) {
        delete data.mcpServers[MORELOGIN_MCP_KEY];
        writeFileSync(p, JSON.stringify(data, null, 2), 'utf8');
        targets.push('Claude Code');
      }
    }
  } catch {}
  try {
    const p = join(home, '.gemini', 'settings.json');
    if (existsSync(p)) {
      const data = JSON.parse(readFileSync(p, 'utf8') || '{}');
      if (data.mcpServers && data.mcpServers[MORELOGIN_MCP_KEY]) {
        delete data.mcpServers[MORELOGIN_MCP_KEY];
        writeFileSync(p, JSON.stringify(data, null, 2) + '\n', 'utf8');
        targets.push('Gemini');
      }
    }
  } catch {}
  try {
    const p = join(home, '.codex', 'config.toml');
    if (existsSync(p)) {
      let content = readFileSync(p, 'utf8');
      if (tomlHasSection(content, `mcp_servers.${MORELOGIN_MCP_KEY}`)) {
        content = tomlRemoveSection(content, `mcp_servers.${MORELOGIN_MCP_KEY}`);
        writeFileSync(p, content, 'utf8');
        targets.push('Codex');
      }
    }
  } catch {}
  try {
    if (mcpServersOf(readOpencodeConfigDocument(getOpencodeConfigPath()).config)[MORELOGIN_MCP_KEY]) {
      updateOpencodeConfigFile(getOpencodeConfigDir(), (cfg) => removeMcpServer(cfg, MORELOGIN_MCP_KEY));
      targets.push('OpenCode');
    }
  } catch {}
  return targets;
}

// POST /api/morelogin/register-mcp — add MoreLogin's own MCP server to installed agents.
// Body: { config } = the JSON block MoreLogin gives you (Settings → API & MCP → MCP).
app.post('/api/morelogin/register-mcp', (req, res) => {
  try {
    const entry = _normalizeMcpEntry(req.body && req.body.config);
    if (!entry || (!entry.command && !entry.url)) {
      return res.status(400).json({ ok: false, error: 'Paste the MCP config block from MoreLogin (Settings → API & MCP → MCP). It must contain a command or url.' });
    }
    res.json({ ok: true, targets: _writeMoreLoginMcpToAgents(entry) });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// DELETE /api/morelogin/register-mcp — remove MoreLogin's MCP server from installed agents
app.delete('/api/morelogin/register-mcp', (req, res) => {
  try {
    res.json({ ok: true, targets: _removeMoreLoginMcpFromAgents() });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

