// ── Memory-tool permission auto-injection ──
// On MCP enable for any provider, force-allow the 7 SynaBun memory tools
// (recall/remember/reflect/forget/memories/restore/sync) so PTY/CLI sessions
// can use SynaBun memory without per-call permission prompts. Inject-only,
// never overwrites existing entries. Falls back to project-scoped settings
// when the user has no global settings file.
function getMemoryToolKeys() {
  const cat = SYNABUN_TOOL_CATEGORIES.find(c => c.id === 'memory');
  return cat ? cat.tools.map(t => t.key) : [];
}

function getOpenCodeCoreMcpToolKeys() {
  return [...getMemoryToolKeys(), 'mcp__SynaBun__tool_groups']
    .map((key) => key.replace(/^mcp__([^_]+)__/, '$1_'));
}

// An `allow` rule (OpenCode 2's `permissions`) for each SynaBun memory tool the config does not decide itself.
// An explicit user deny/ask stays the user's. Missing rules inherit OpenCode's permissive default, but writing
// allow here makes unattended profile routing resilient under restrictive wildcard policies.
function ensureOpenCodeCoreMcpPermissions(config) {
  return allowActions(config, getOpenCodeCoreMcpToolKeys());
}

function injectClaudeMemoryPerms() {
  const keys = getMemoryToolKeys();
  const globalPath = getGlobalClaudeSettingsPath();

  if (existsSync(globalPath)) {
    const settings = readClaudeSettingsForWrite(globalPath);
    if (!settings.permissions) settings.permissions = {};
    if (!Array.isArray(settings.permissions.allow)) settings.permissions.allow = [];
    const set = new Set(settings.permissions.allow);
    for (const k of keys) set.add(k);
    settings.permissions.allow = [...set];
    writeClaudeSettings(globalPath, settings);
    return { scope: 'global', paths: [globalPath] };
  }

  const projects = loadHookProjects();
  const written = [];
  for (const p of projects) {
    if (!p?.path) continue;
    const projPath = getClaudeSettingsPath(p.path);
    const s = readClaudeSettingsForWrite(projPath);
    if (!s.permissions) s.permissions = {};
    if (!Array.isArray(s.permissions.allow)) s.permissions.allow = [];
    const set = new Set(s.permissions.allow);
    for (const k of keys) set.add(k);
    s.permissions.allow = [...set];
    writeClaudeSettings(projPath, s);
    written.push(projPath);
  }
  return { scope: 'project', paths: written };
}

function injectCodexMemoryPerms() {
  try {
    const configPath = join(CODEX_DEFAULT_HOME, 'config.toml');
    if (!existsSync(configPath)) return { scope: 'none', paths: [] };
    let content = readFileSync(configPath, 'utf-8');
    if (!tomlHasSection(content, 'mcp_servers.SynaBun')) return { scope: 'none', paths: [] };
    for (const k of getMemoryToolKeys()) {
      const shortName = k.replace('mcp__SynaBun__', '');
      const section = `mcp_servers.SynaBun.tools.${shortName}`;
      if (!tomlHasSection(content, section)) {
        content = tomlUpsertSection(content, section, { approval_mode: 'approve' });
      }
    }
    writeFileSync(configPath, content, 'utf-8');
    return { scope: 'global', paths: [configPath] };
  } catch (err) {
    console.error('[memory-perms] Codex inject failed:', err.message);
    return { scope: 'error', paths: [] };
  }
}

function injectOpenCodeMemoryPerms() {
  try {
    const configPath = getOpencodeConfigPath();
    if (!existsSync(configPath)) return { scope: 'none', paths: [] };
    updateOpencodeConfigFile(getOpencodeConfigDir(), (cfg) => ensureOpenCodeCoreMcpPermissions(cfg));
    return { scope: 'global', paths: [configPath] };
  } catch (err) {
    console.error('[memory-perms] OpenCode inject failed:', err.message);
    return { scope: 'error', paths: [] };
  }
}

function addHookToSettings(settings, onlyEvent, targetProjectPath) {
  if (!settings) settings = {};
  if (!settings.hooks) settings.hooks = {};

  // Enforce SynaBun env defaults and tool permissions alongside hooks
  ensureSynaBunEnv(settings);
  ensureHookRoot(settings, targetProjectPath);
  ensureSynaBunPermissions(settings);

  const defs = hookDefinitionsForEvent(onlyEvent);
  for (const def of defs) {
    if (!settings.hooks[def.event]) settings.hooks[def.event] = [];
    const cmd = hookCommandString(def.script, targetProjectPath);
    // Self-healing sweep: drop EVERY existing entry that points at this hook
    // script in any command-string form — relative, absolute, or a stale
    // cross-OS path (e.g. a Windows "J:/..." left in a settings.json synced to
    // macOS) — then add exactly one canonical entry for this machine. This both
    // dedups the legacy relative+absolute duplication and repairs broken paths
    // that would otherwise crash the CLI with MODULE_NOT_FOUND on every event.
    settings.hooks[def.event] = settings.hooks[def.event].flatMap(entry => {
      const hooks = (entry.hooks || []).filter(h => !isSynaBunHookCommand(h.command, def.script));
      return hooks.length ? [{ ...entry, hooks }] : [];
    });
    settings.hooks[def.event].push({
      matcher: def.matcher || '',
      hooks: [{ type: 'command', command: cmd, timeout: def.timeout }],
    });
  }
  return settings;
}

// Canonicalize across settings scopes, preserving unrelated handlers.
function dedupeAllSettingsHooks() {
  const stats = { files: 0, removed: 0, repaired: 0, matchers: 0 };
  const sweep = (settings, targetProjectPath) => sweepSettingsHooks(settings, targetProjectPath, stats);
  try {
    const globalPath = getGlobalClaudeSettingsPath();
    const globalSettings = readClaudeSettings(globalPath);
    if (globalSettings && sweep(globalSettings, undefined)) {
      writeClaudeSettings(globalPath, globalSettings);
      stats.files++;
    }
  } catch { /* ok */ }
  try {
    const projects = loadHookProjects();
    for (const p of projects) {
      try {
        for (const name of ['settings.json', 'settings.local.json']) {
          const projPath = join(p.path, '.claude', name);
          const projSettings = readClaudeSettings(projPath);
          if (projSettings && sweep(projSettings, p.path)) {
            writeClaudeSettings(projPath, projSettings);
            stats.files++;
          }
        }
      } catch { /* skip */ }
    }
  } catch { /* ok */ }
  return stats;
}

function removeHookFromSettings(settings, onlyEvent, targetProjectPath) {
  if (!settings?.hooks) return settings;
  const defs = hookDefinitionsForEvent(onlyEvent);
  for (const def of defs) {
    if (!settings.hooks[def.event]) continue;
    settings.hooks[def.event] = settings.hooks[def.event].flatMap(entry => {
      const hooks = (entry.hooks || []).filter(h => !isSynaBunHookCommand(h.command, def.script));
      return hooks.length ? [{ ...entry, hooks }] : [];
    });
    if (!settings.hooks[def.event].length) delete settings.hooks[def.event];
  }
  if (!Object.keys(settings.hooks).length) delete settings.hooks;
  return settings;
}

// Persistent list of project paths the user has registered
const HOOK_PROJECTS_PATH = resolve(DATA_HOME, 'data', 'claude-code-projects.json');

function loadHookProjects() {
  try {
    if (!existsSync(HOOK_PROJECTS_PATH)) return [];
    return JSON.parse(readFileSync(HOOK_PROJECTS_PATH, 'utf-8'));
  } catch { return []; }
}

/**
 * The registered code projects an Assistant task run's test runners may run in besides its own project (the browser
 * policy's `roots`, lib/browser-policy-roots.js: never ~/Downloads). Read as the run starts; a project registered while
 * it runs counts from the next run.
 */
function taskBrowserPolicyRoots(state) {
  if (state?.runMode !== 'task') return [];
  try { return browserPolicyRoots(loadHookProjects()); } catch { return []; }
}

function saveHookProjects(projects) {
  const dir = dirname(HOOK_PROJECTS_PATH);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  writeFileSync(HOOK_PROJECTS_PATH, JSON.stringify(projects, null, 2), 'utf-8');
}

// ── Combined project storage scanner / cleanup ──

const PROJECT_STORAGE_SCAN_TTL_MS = 10 * 60 * 1000;
const PROJECT_STORAGE_CACHE_MS = 30 * 1000;
const PROJECT_STORAGE_MAX_SELECTION = 500;
const _projectStorageScans = new Map();
let _latestProjectStorageScan = null;
let _projectStorageScanPromise = null;
let _projectStorageClearInProgress = false;

function projectStorageRuntimeProtectedPaths() {
  return [
    resolve(PACKAGE_ROOT, 'node_modules'),
    resolve(PACKAGE_ROOT, 'neural-interface', 'node_modules'),
    resolve(PACKAGE_ROOT, 'mcp-server', 'node_modules'),
    resolve(PACKAGE_ROOT, 'mcp-server', 'dist'),
  ];
}

function activeProjectStorageCwds() {
  const active = new Set();
  for (const session of terminalSessions.values()) {
    if (session?.cwd) active.add(resolve(session.cwd));
  }
  for (const run of (_nativeLoopRuntime?.list?.({ activeOnly: true }) || [])) {
    if (run?.cwd) active.add(resolve(run.cwd));
  }
  return [...active];
}

function projectStorageProjectIsActive(projectPath, activeCwds = activeProjectStorageCwds()) {
  return activeCwds.some((cwd) => pathIsWithin(cwd, projectPath));
}

function purgeProjectStorageScans(now = Date.now()) {
  for (const [scanId, record] of _projectStorageScans) {
    if (record.expiresAtMs <= now) _projectStorageScans.delete(scanId);
  }
  if (_latestProjectStorageScan?.expiresAtMs <= now) _latestProjectStorageScan = null;
  if (_projectStorageScans.size > 20) {
    const oldest = [..._projectStorageScans.values()]
      .sort((a, b) => a.createdAtMs - b.createdAtMs)
      .slice(0, _projectStorageScans.size - 20);
    oldest.forEach((record) => _projectStorageScans.delete(record.scanId));
  }
}

function publicProjectStorageItem(item, projectActive = false) {
  return {
    id: item.id,
    scope: item.scope,
    name: item.name,
    provider: item.provider || null,
    displayPath: item.displayPath,
    category: item.category,
    risk: item.risk,
    originalRisk: item.originalRisk,
    bytes: item.bytes,
    fileCount: item.fileCount,
    incomplete: !!item.incomplete,
    protected: !!item.protected,
    protectionReason: item.protectionReason || null,
    blocked: projectActive,
    blockerReason: projectActive ? 'A terminal or unattended run is currently using this project.' : null,
    defaultSelected: !projectActive && !!item.defaultSelected,
  };
}

function summarizePublicProjectStorage(items) {
  return items.reduce((totals, item) => {
    totals.bytes += Number(item.bytes) || 0;
    totals.fileCount += Number(item.fileCount) || 0;
    totals.itemCount += 1;
    if (!item.protected && !item.blocked) {
      totals.reclaimableBytes += Number(item.bytes) || 0;
      totals.reclaimableItemCount += 1;
    }
    if (item.defaultSelected) {
      totals.selectedBytes += Number(item.bytes) || 0;
      totals.selectedItemCount += 1;
    }
    if (item.protected) totals.protectedItemCount += 1;
    if (item.blocked) totals.blockedItemCount += 1;
    if (!item.protected && !item.blocked && item.originalRisk === 'dependency') totals.dependencyItemCount += 1;
    return totals;
  }, {
    bytes: 0,
    fileCount: 0,
    itemCount: 0,
    reclaimableBytes: 0,
    reclaimableItemCount: 0,
    selectedBytes: 0,
    selectedItemCount: 0,
    protectedItemCount: 0,
    blockedItemCount: 0,
    dependencyItemCount: 0,
  });
}

function serializeProjectStorageScan(record) {
  const activeCwds = activeProjectStorageCwds();
  const projects = record.scan.projects.map((group) => {
    const active = projectStorageProjectIsActive(group.path, activeCwds);
    const items = group.items.map((item) => publicProjectStorageItem(item, active));
    return {
      projectKey: group.projectKey,
      label: group.label,
      path: group.path,
      active,
      items,
      totals: summarizePublicProjectStorage(items),
    };
  });
  const sharedItems = record.scan.shared.items.map((item) => publicProjectStorageItem(item, false));
  const allItems = [...projects.flatMap((group) => group.items), ...sharedItems];
  return {
    ok: true,
    scanId: record.scanId,
    scannedAt: record.scan.scannedAt,
    expiresAt: new Date(record.expiresAtMs).toISOString(),
    busy: _projectStorageClearInProgress,
    totals: summarizePublicProjectStorage(allItems),
    projects,
    shared: {
      label: record.scan.shared.label,
      items: sharedItems,
      totals: summarizePublicProjectStorage(sharedItems),
    },
    warnings: record.scan.warnings || [],
    confirmations: {
      safe: PROJECT_STORAGE_SAFE_CONFIRMATION,
      dependency: PROJECT_STORAGE_DEPENDENCY_CONFIRMATION,
    },
  };
}

async function createProjectStorageScan() {
  if (_projectStorageScanPromise) return _projectStorageScanPromise;
  _projectStorageScanPromise = (async () => {
    const projects = loadHookProjects()
      .filter((project) => project?.path)
      .map((project) => ({ path: resolve(project.path), label: project.label || basename(project.path) }));
    const scan = await scanProjectStorageInWorker({
      projects,
      packageRoot: PACKAGE_ROOT,
      runtimeProtectedPaths: projectStorageRuntimeProtectedPaths(),
    });
    const createdAtMs = Date.now();
    const record = {
      scanId: randomUUID(),
      createdAtMs,
      expiresAtMs: createdAtMs + PROJECT_STORAGE_SCAN_TTL_MS,
      scan,
    };
    _projectStorageScans.set(record.scanId, record);
    _latestProjectStorageScan = record;
    purgeProjectStorageScans(createdAtMs);
    return record;
  })();
  try { return await _projectStorageScanPromise; }
  finally { _projectStorageScanPromise = null; }
}

app.get('/api/settings/project-storage', async (req, res) => {
  try {
    const refresh = req.query.refresh === '1' || req.query.refresh === 'true';
    purgeProjectStorageScans();
    if (refresh && _projectStorageClearInProgress) {
      return res.status(409).json({ error: 'Cleanup is still running.', code: 'CLEANUP_BUSY' });
    }
    const cached = !refresh && _latestProjectStorageScan
      && Date.now() - _latestProjectStorageScan.createdAtMs < PROJECT_STORAGE_CACHE_MS
      ? _latestProjectStorageScan
      : null;
    const record = cached || await createProjectStorageScan();
    res.json(serializeProjectStorageScan(record));
  } catch (error) {
    console.error('[project-storage] Scan failed:', error);
    res.status(500).json({ error: error?.message || 'Project storage scan failed.', code: error?.code || 'SCAN_FAILED' });
  }
});

app.post('/api/settings/project-storage/clear', async (req, res) => {
  if (_projectStorageClearInProgress) {
    return res.status(409).json({ error: 'Another cleanup is already running.', code: 'CLEANUP_BUSY' });
  }
  try {
    purgeProjectStorageScans();
    const scanId = typeof req.body?.scanId === 'string' ? req.body.scanId : '';
    const itemIds = Array.isArray(req.body?.itemIds) ? [...new Set(req.body.itemIds)] : [];
    if (!scanId || !itemIds.length || itemIds.length > PROJECT_STORAGE_MAX_SELECTION || itemIds.some((id) => typeof id !== 'string')) {
      return res.status(400).json({ error: 'A valid scan and selection are required.', code: 'INVALID_SELECTION' });
    }
    const record = _projectStorageScans.get(scanId);
    if (!record || record.expiresAtMs <= Date.now()) {
      return res.status(409).json({ error: 'This storage scan has expired. Refresh and review the selection again.', code: 'SCAN_EXPIRED' });
    }
    const itemMap = new Map(record.scan.items.map((item) => [item.id, item]));
    const selectedItems = itemIds.map((id) => itemMap.get(id));
    if (selectedItems.some((item) => !item)) {
      return res.status(409).json({ error: 'The selection no longer matches this scan. Refresh and try again.', code: 'SCAN_MISMATCH' });
    }
    const blocked = selectedItems.filter((item) => item.scope === 'project' && projectStorageProjectIsActive(item.projectPath));
    if (blocked.length) {
      return res.status(409).json({
        error: 'Close active terminals or unattended runs for the selected projects, then refresh.',
        code: 'PROJECT_ACTIVE',
        itemIds: blocked.map((item) => item.id),
      });
    }
    if (selectedItems.some((item) => item.protected || item.risk === 'protected')) {
      return res.status(400).json({ error: 'Protected items cannot be selected.', code: 'PROTECTED_SELECTION' });
    }
    const includesDependencies = selectedItems.some((item) => item.originalRisk === 'dependency');
    const expectedConfirmation = includesDependencies
      ? PROJECT_STORAGE_DEPENDENCY_CONFIRMATION
      : PROJECT_STORAGE_SAFE_CONFIRMATION;
    if (req.body?.confirmation !== expectedConfirmation) {
      return res.status(400).json({
        error: includesDependencies
          ? `Type ${PROJECT_STORAGE_DEPENDENCY_CONFIRMATION} to remove dependency downloads.`
          : 'Cleanup confirmation was missing.',
        code: 'CONFIRMATION_REQUIRED',
        requiredConfirmation: expectedConfirmation,
      });
    }

    _projectStorageClearInProgress = true;
    const result = await clearProjectStorageInWorker({
      items: selectedItems,
      projects: record.scan.projects.map((group) => ({ path: group.path, label: group.label })),
      packageRoot: PACKAGE_ROOT,
      runtimeProtectedPaths: projectStorageRuntimeProtectedPaths(),
    });
    _projectStorageScans.clear();
    _latestProjectStorageScan = null;
    res.json({ ...result, requiresRescan: true });
  } catch (error) {
    const validationError = error instanceof ProjectStorageValidationError || error?.code === 'VALIDATION_FAILED';
    console.error('[project-storage] Cleanup failed:', error);
    res.status(validationError ? 409 : 500).json({
      error: error?.message || 'Project storage cleanup failed.',
      code: error?.code || 'CLEANUP_FAILED',
      details: error?.details || [],
      requiresRescan: validationError,
    });
  } finally {
    _projectStorageClearInProgress = false;
  }
});

// ── Claude session index helpers ──

/** Extract metadata from a .jsonl session file by reading its first user message.
 *  Reads line-by-line (stops at first `type: user`) to avoid loading the whole file. */
async function extractSessionMeta(filePath) {
  let fh = null;
  try {
    fh = await fsp.open(filePath, 'r');
    const CHUNK = 65536;      // 64KB per read
    const MAX_READ = 1048576; // 1MB max total
    const fileSize = (await fh.stat()).size;
    const buf = Buffer.alloc(CHUNK);
    let pending = '';
    let offset = 0;

    while (offset < Math.min(fileSize, MAX_READ)) {
      const readSize = Math.min(CHUNK, fileSize - offset);
      const { bytesRead } = await fh.read(buf, 0, readSize, offset);
      if (bytesRead === 0) break;
      pending += buf.toString('utf-8', 0, bytesRead);
      offset += bytesRead;

      // Process complete lines (terminated by \n)
      let nlIdx;
      while ((nlIdx = pending.indexOf('\n')) !== -1) {
        const line = pending.slice(0, nlIdx).trim();
        pending = pending.slice(nlIdx + 1);
        if (!line) continue;
        try {
          const obj = JSON.parse(line);
          if (obj.type === 'user' && obj.message) {
            const txt = obj.message.content;
            const prompt = Array.isArray(txt)
              ? (txt.find(b => b.type === 'text')?.text || '')
              : (txt || '');
            return {
              sessionId: obj.sessionId || basename(filePath, '.jsonl'),
              firstPrompt: prompt.slice(0, 200),
              gitBranch: obj.gitBranch || null,
              isSidechain: !!obj.isSidechain,
              cwd: obj.cwd || null,
            };
          }
        } catch { /* incomplete or malformed line */ }
      }
    }

    return null; // no user message found
  } catch { return null; }
  finally { try { await fh?.close(); } catch {} }
}

const _MSG_TYPE_MARKERS = ['"type":"user"', '"type":"assistant"', '"type": "user"', '"type": "assistant"'];
function _lineHasMessageMarker(line) {
  return _MSG_TYPE_MARKERS.some(m => line.includes(m));
}

/** Count user + assistant messages in a JSONL session file from a byte offset.
 *  Fast string scan — no JSON parsing, async reads in 64KB chunks. Starting at
 *  a previously-recorded EOF lets pollers count only appended bytes instead of
 *  re-reading the whole (multi-MB, still-growing) transcript every time. */
async function countSessionMessagesFrom(filePath, startOffset = 0) {
  let fh = null;
  try {
    fh = await fsp.open(filePath, 'r');
    const CHUNK = 65536;
    const fileSize = (await fh.stat()).size;
    const buf = Buffer.alloc(CHUNK);
    let pending = '', offset = Math.max(0, startOffset), count = 0;

    while (offset < fileSize) {
      const readSize = Math.min(CHUNK, fileSize - offset);
      const { bytesRead } = await fh.read(buf, 0, readSize, offset);
      if (bytesRead === 0) break;
      pending += buf.toString('utf-8', 0, bytesRead);
      offset += bytesRead;

      let nlIdx;
      while ((nlIdx = pending.indexOf('\n')) !== -1) {
        const line = pending.slice(0, nlIdx);
        pending = pending.slice(nlIdx + 1);
        if (_lineHasMessageMarker(line)) count++;
      }
    }
    if (pending.length > 0 && _lineHasMessageMarker(pending)) count++;
    return count;
  } catch { return 0; }
  finally { try { await fh?.close(); } catch {} }
}

// ── Session metadata cache ──
// Persists discovered session metadata so entries survive even after
// Claude Code deletes old JSONL files from disk.
const SESSION_CACHE_DIR = resolve(DATA_HOME, 'data');
const _sessionCacheMap = new Map(); // projDir → Map(sessionId → entry)

function getSessionCachePath(projDir) {
  const key = basename(projDir).replace(/[^a-zA-Z0-9_-]/g, '_');
  return join(SESSION_CACHE_DIR, `sessions-cache-${key}.json`);
}

function loadSessionCache(projDir) {
  if (_sessionCacheMap.has(projDir)) return _sessionCacheMap.get(projDir);
  const cache = new Map();
  try {
    const data = JSON.parse(readFileSync(getSessionCachePath(projDir), 'utf-8'));
    for (const e of data) cache.set(e.sessionId, e);
  } catch { /* no cache yet */ }
  _sessionCacheMap.set(projDir, cache);
  return cache;
}

// Debounced async cache persistence — a sync write used to fire on every poll
// that observed growth (i.e. constantly while any session streams).
const _sessionCacheSaveTimers = new Map(); // projDir → timeout
function saveSessionCache(projDir, cache) {
  if (_sessionCacheSaveTimers.has(projDir)) return;
  const t = setTimeout(async () => {
    _sessionCacheSaveTimers.delete(projDir);
    try {
      if (!existsSync(SESSION_CACHE_DIR)) mkdirSync(SESSION_CACHE_DIR, { recursive: true });
      await fsp.writeFile(getSessionCachePath(projDir), JSON.stringify([...cache.values()]), 'utf-8');
    } catch { /* write error */ }
  }, 1000);
  t.unref?.();
  _sessionCacheSaveTimers.set(projDir, t);
}

/** Build a complete session list for a project dir by scanning JSONL files,
 *  counting messages (with smart caching by fileSize), and preserving
 *  cached entries for sessions whose files have been deleted. Fully async —
 *  this runs behind a polled endpoint while sessions stream. */
async function buildSessionEntries(projDir) {
  const cache = loadSessionCache(projDir);
  let cacheChanged = false;

  // 1. Scan ALL JSONL files with stat info
  let allFiles;
  try { allFiles = await fsp.readdir(projDir); } catch { allFiles = []; }

  const jsonlFiles = allFiles.filter(f => f.endsWith('.jsonl'));
  const jsonlIds = new Set(jsonlFiles.map(f => f.replace('.jsonl', '')));

  const filesWithStat = (await asyncPool(8, jsonlFiles, async (f) => {
    try {
      const stat = await fsp.stat(join(projDir, f));
      return { file: f, mtime: stat.mtime, size: stat.size };
    } catch { return null; }
  })).filter(Boolean).sort((a, b) => b.mtime - a.mtime);

  // 2. Partition into unchanged / changed (smart: skip counting if fileSize unchanged)
  const changedFiles = [];
  for (const { file, mtime, size } of filesWithStat) {
    const sid = file.replace('.jsonl', '');
    const cached = cache.get(sid);

    if (cached && cached.fileSize === size && cached.fileSize !== undefined) {
      // File unchanged — update modified timestamp if needed
      if (mtime.toISOString() > cached.modified) {
        cache.set(sid, { ...cached, modified: mtime.toISOString() });
        cacheChanged = true;
      }
      continue;
    }
    changedFiles.push({ file, mtime, size, sid, cached });
  }

  // 3. Extract metadata + count messages for changed files.
  await asyncPool(8, changedFiles, async ({ file, mtime, size, sid, cached }) => {
    const filePath = join(projDir, file);
    // Append-only growth: the first user message never changes, so reuse the
    // cached meta and count ONLY the appended bytes. While N sessions stream,
    // their JSONLs grow every turn — this turns each poll's cost from
    // O(total file size) into O(bytes appended since last poll). Count drift
    // on a mid-write tail line is at most ±1 and self-corrects on the next
    // full recount (truncation or refresh=true).
    const grew = cached && cached.fileSize !== undefined && size > cached.fileSize
      && cached.firstPrompt !== undefined;
    let meta, messageCount;
    if (grew) {
      meta = {
        sessionId: cached.sessionId || sid,
        firstPrompt: cached.firstPrompt,
        gitBranch: cached.gitBranch,
        isSidechain: cached.isSidechain,
        cwd: cached.projectPath,
      };
      messageCount = (cached.messageCount || 0) + await countSessionMessagesFrom(filePath, cached.fileSize);
    } else {
      meta = await extractSessionMeta(filePath);
      if (!meta) return;
      messageCount = await countSessionMessagesFrom(filePath, 0);
    }

    const entry = {
      sessionId: meta.sessionId,
      firstPrompt: meta.firstPrompt,
      messageCount,
      fileSize: size,
      created: cached?.created || mtime.toISOString(),
      modified: mtime.toISOString(),
      gitBranch: meta.gitBranch,
      isSidechain: meta.isSidechain,
      projectPath: meta.cwd,
    };

    cache.set(sid, cached ? { ...cached, ...entry } : entry);
    cacheChanged = true;
  });

  // Mark cached entries whose files are gone (still returned, but not resumable)
  for (const [sid, entry] of cache) {
    const wasLive = jsonlIds.has(sid);
    if (!wasLive && !entry._deleted) {
      entry._deleted = true;
      cacheChanged = true;
    } else if (wasLive && entry._deleted) {
      entry._deleted = false;
      cacheChanged = true;
    }
  }

  if (cacheChanged) saveSessionCache(projDir, cache);

  return [...cache.values()];
}

// Route-level memo: one entry list per project dir, invalidated by fs.watch on
// the JSONL dir (TTL backstop for dropped FSEvents). Polling windows share one
// rebuild via memoCache's single-flight.
const _sessionEntriesCaches = new Map(); // projDir → memoCache
function getSessionEntriesCache(projDir) {
  let mc = _sessionEntriesCaches.get(projDir);
  if (!mc) {
    mc = memoCache(() => buildSessionEntries(projDir), {
      ttlMs: 5000,
      watchDirs: [projDir],
      watchFilter: (f) => f.endsWith('.jsonl'),
    });
    _sessionEntriesCaches.set(projDir, mc);
  }
  return mc;
}

// Keep filesystem reconciliation off the dropdown's request path. Registered
// projects can contain thousands of multi-MB transcripts, while the persistent
// metadata cache is small enough to return immediately. Refresh projects one at
// a time in the background to avoid turning a menu open into a burst of disk I/O.
let _sessionEntriesRefreshQueue = Promise.resolve();
const _sessionEntriesRefreshQueued = new Set();
function scheduleSessionEntriesRefresh(projDir) {
  if (_sessionEntriesRefreshQueued.has(projDir)) return;
  _sessionEntriesRefreshQueued.add(projDir);
  _sessionEntriesRefreshQueue = _sessionEntriesRefreshQueue
    .catch(() => {})
    .then(() => getSessionEntriesCache(projDir).get())
    .catch((err) => console.warn(`[sessions] Background refresh failed for ${projDir}:`, err.message))
    .finally(() => _sessionEntriesRefreshQueued.delete(projDir));
}

async function getSessionEntriesForRequest(projDir, { forceRefresh = false } = {}) {
  const memo = getSessionEntriesCache(projDir);
  if (forceRefresh) return memo.get();

  const inMemory = memo.peek();
  if (inMemory) {
    scheduleSessionEntriesRefresh(projDir);
    return inMemory;
  }

  const persisted = [...loadSessionCache(projDir).values()];
  if (persisted.length > 0) {
    scheduleSessionEntriesRefresh(projDir);
    return persisted;
  }

  // A newly registered project has no stale value to show, so its first request
  // must build the metadata cache once.
  return memo.get();
}

let _codexSessionCatalogRefresh = null;
function getCodexSessionCatalogRefresh() {
  if (!_codexSessionCatalogRefresh) {
    _codexSessionCatalogRefresh = memoCache(() => rebuildCodexCache({
      accounts: loadCodexAccounts().accounts,
      projects: loadHookProjects(),
    }), { ttlMs: 15000 });
  }
  return _codexSessionCatalogRefresh;
}

async function refreshCodexSessionCatalog({ force = false } = {}) {
  const memo = getCodexSessionCatalogRefresh();
  if (force) memo.invalidate();
  return memo.get();
}

function normalizeCodexSessionEntry(entry) {
  if (!entry) return null;
  const sessionId = String(entry.session_id || entry.sessionId || entry.id || '').trim();
  if (!sessionId) return null;
  return {
    sessionId,
    firstPrompt: String(entry.first_prompt || entry.firstPrompt || entry.title || '').trim(),
    messageCount: Number(entry.message_count ?? entry.messageCount ?? 0) || 0,
    created: entry.created || entry.createdAt || null,
    modified: entry.modified || entry.modifiedAt || null,
    gitBranch: entry.git_branch || entry.gitBranch || null,
    source: entry.source || null,
    cwd: entry.cwd || entry.project_path || entry.projectPath || null,
    projectPath: entry.project_path || entry.projectPath || null,
    accountId: entry.account_id || entry.accountId || null,
    accountLabel: entry.account_label || entry.accountLabel || null,
    deleted: !!(entry.deleted || entry._deleted),
    resumable: entry.resumable !== false,
  };
}

function groupCodexSessionsByProject(projects, rawEntries, { targetProject, search, limit, offset } = {}) {
  const projectRows = (Array.isArray(projects) ? projects : []).map((proj) => ({
    path: proj.path,
    label: proj.label || basename(proj.path),
    total: 0,
    sessions: [],
  }));
  const buckets = new Map(projectRows.map((proj) => [resolve(proj.path), []]));
  const targetResolved = targetProject ? resolve(targetProject) : null;
  const query = String(search || '').toLowerCase().trim();
  const pageLimit = Math.min(Math.max(parseInt(limit) || 30, 1), 100);
  const pageOffset = Math.max(parseInt(offset) || 0, 0);

  for (const raw of (Array.isArray(rawEntries) ? rawEntries : [])) {
    const entry = normalizeCodexSessionEntry(raw);
    if (!entry || entry.deleted || !entry.projectPath) continue;
    if (query) {
      const searchable = [
        entry.firstPrompt,
        entry.sessionId,
        entry.gitBranch,
        entry.accountLabel,
      ].some((value) => String(value || '').toLowerCase().includes(query));
      if (!searchable) continue;
    }

    const project = (Array.isArray(projects) ? projects : []).find((proj) =>
      proj?.path && pathIsWithin(entry.projectPath, proj.path),
    );
    if (!project) continue;
    if (targetResolved && !samePath(project.path, targetResolved)) continue;

    const bucket = buckets.get(resolve(project.path));
    if (bucket) bucket.push(entry);
  }

  return projectRows
    .filter((proj) => !targetResolved || samePath(proj.path, targetResolved))
    .map((proj) => {
      const entries = (buckets.get(resolve(proj.path)) || [])
        .sort((a, b) => new Date(b.modified || 0) - new Date(a.modified || 0));
      const total = entries.length;
      const sessions = entries.slice(pageOffset, pageOffset + pageLimit).map((entry) => ({
        sessionId: entry.sessionId,
        firstPrompt: entry.firstPrompt,
        messageCount: entry.messageCount || 0,
        created: entry.created,
        modified: entry.modified,
        gitBranch: entry.gitBranch || null,
        source: entry.source || null,
        cwd: entry.cwd || entry.projectPath || null,
        accountId: entry.accountId || null,
        accountLabel: entry.accountLabel || null,
        archived: false,
        resumable: true,
      }));
      return {
        path: proj.path,
        label: proj.label,
        total,
        sessions,
      };
    });
}

async function getCodexSessionsResponse({ targetProject, limit, offset, search, forceRefresh = false } = {}) {
  const cachedEntries = listSessionCache('codex', { limit: 100000 });
  const hasCache = cachedEntries.some((entry) => !entry?.deleted);
  if (forceRefresh) {
    await refreshCodexSessionCatalog({ force: true });
    return groupCodexSessionsByProject(loadHookProjects(), listSessionCache('codex', { limit: 100000 }), {
      targetProject, limit, offset, search,
    });
  }

  if (hasCache) {
    void refreshCodexSessionCatalog().catch((err) => {
      console.warn('[codex-sessions] Background refresh failed:', err.message);
    });
    return groupCodexSessionsByProject(loadHookProjects(), cachedEntries, {
      targetProject, limit, offset, search,
    });
  }

  try {
    await refreshCodexSessionCatalog();
  } catch (err) {
    console.warn('[codex-sessions] Refresh failed, falling back to live scan:', err.message);
  }

  const refreshedEntries = listSessionCache('codex', { limit: 100000 });
  if (refreshedEntries.some((entry) => !entry?.deleted)) {
    return groupCodexSessionsByProject(loadHookProjects(), refreshedEntries, {
      targetProject, limit, offset, search,
    });
  }

  const projects = loadHookProjects();
  const accounts = loadCodexAccounts().accounts.map((account) => ({
    ...account,
    home: account.home || getCodexAccountHome(account.id),
  }));
  const liveCatalog = listCodexSessionsFromAccounts(accounts, {
    projects,
    includeArchived: false,
    maxRows: 10000,
    onError(account, err) {
      console.warn(`[codex-sessions] Failed to read account ${account?.id || 'unknown'}:`, err.message);
    },
  });
  return groupCodexSessionsByProject(projects, liveCatalog, {
    targetProject, limit, offset, search,
  });
}

// GET /api/claude-code/sessions — browse past Claude Code sessions across registered projects
app.get('/api/claude-code/sessions', async (req, res) => {
  try {
    // A tab under a named Claude account keeps its transcripts in that account's
    // own config directory. The list below and its caches (keyed by the project
    // folder's name, which every account shares) are the default account's. For
    // a named account the route answers the one thing the panel asks it: which
    // registered project holds this session (`search` is its id), looked up in
    // that account's catalogue. An account that is no longer set up is an
    // error, never the default account's list in its place.
    const wantedAccount = typeof req.query.account === 'string' ? req.query.account : '';
    if (wantedAccount && wantedAccount !== 'default') {
      if (isGuestRequest(req)) return res.status(403).json({ error: 'Admin only' });
      try {
        const accountHome = panelAccountHome(wantedAccount);
        const sessionId = String(req.query.search || '').trim();
        const registered = loadHookProjects().filter(p => p?.path);
        const owners = new Set(sessionProjects({ sessionId, projects: registered, projectsDir: join(accountHome, 'projects'), pathToKey: pathToClaudeKey }));
        const only = typeof req.query.project === 'string' && req.query.project ? resolve(req.query.project) : '';
        const row = { sessionId, firstPrompt: '', messageCount: 0, created: null, modified: null, gitBranch: null, isSidechain: false, deleted: false, title: '', tag: '' };
        return res.json({
          account: wantedAccount,
          projects: registered.filter(p => !only || resolve(p.path) === only).map(p => ({
            path: p.path, label: p.label || basename(p.path), total: owners.has(p.path) ? 1 : 0, sessions: owners.has(p.path) ? [{ ...row }] : [],
          })),
        });
      } catch (err) {
        return res.status(err?.status || 500).json({ error: err.message, ...(err?.code ? { code: err.code } : {}) });
      }
    }

    // Force full re-scan when refresh requested — nuke both in-memory and persistent cache
    if (req.query.refresh === 'true') {
      _sessionCacheMap.clear();
      for (const mc of _sessionEntriesCaches.values()) mc.invalidate();
      try {
        const cacheFiles = readdirSync(SESSION_CACHE_DIR)
          .filter(f => f.startsWith('sessions-cache-') && f.endsWith('.json'));
        for (const f of cacheFiles) { try { unlinkSync(join(SESSION_CACHE_DIR, f)); } catch {} }
      } catch {}
    }

    const forceRefresh = req.query.refresh === 'true';
    if (forceRefresh) claudeSessionOverlay.invalidate();
    const projects = loadHookProjects();
    const targetProject = req.query.project;
    const limit = Math.min(parseInt(req.query.limit) || 30, 100);
    const offset = parseInt(req.query.offset) || 0;
    const search = (req.query.search || '').toLowerCase().trim();
    const tagFilter = typeof req.query.tag === 'string' ? req.query.tag.trim().slice(0, 60) : '';

    const homeDir = process.env.USERPROFILE || process.env.HOME;
    const claudeProjectsDir = join(homeDir, '.claude', 'projects');

    const result = [];

    for (const proj of projects) {
      if (targetProject && resolve(proj.path) !== resolve(targetProject)) continue;

      // Convert project path to Claude's directory name format
      // "D:\Projects\MyApp" -> "d--Projects-MyApp"
      // Try both lowercase and uppercase drive letter (Claude is inconsistent)
      const projKeyLower = pathToClaudeKey(proj.path).replace(/^([A-Z])/, (m) => m.toLowerCase());
      const projKeyUpper = pathToClaudeKey(proj.path);

      let projDir = join(claudeProjectsDir, projKeyLower);
      if (!existsSync(projDir)) projDir = join(claudeProjectsDir, projKeyUpper);
      if (!existsSync(projDir)) {
        result.push({ path: proj.path, label: proj.label || basename(proj.path), total: 0, sessions: [] });
        continue;
      }

      // Ordinary menu opens use stale-while-revalidate so cached metadata is
      // returned immediately. Only the explicit refresh action blocks on a scan.
      let entries = await getSessionEntriesForRequest(projDir, { forceRefresh });

      // Filter out sidechains by default, sort by modified descending
      entries = entries.filter(e => !e.isSidechain);
      entries.sort((a, b) => new Date(b.modified) - new Date(a.modified));

      // What the CLI itself keeps per session (a title set with /rename or in the
      // terminal, the summary, the tag), laid over this list. Cached and never
      // fatal: without it the list is what it was. See lib/claude-session-list.js.
      const meta = await claudeSessionOverlay.forProject(proj.path);
      entries = overlaySessions(entries, meta);

      // Apply the text and tag filters (the title and the tag are searchable too)
      if (search || tagFilter) entries = entries.filter(e => matchesSessionFilter(e, { search, tag: tagFilter }));

      const total = entries.length;
      const paginated = entries.slice(offset, offset + limit);

      result.push({
        path: proj.path,
        label: proj.label || basename(proj.path),
        total,
        sessions: paginated.map(e => ({
          sessionId: e.sessionId,
          firstPrompt: (e.firstPrompt || '').slice(0, 200),
          messageCount: e.messageCount || 0,
          created: e.created,
          modified: e.modified,
          gitBranch: e.gitBranch || null,
          isSidechain: e.isSidechain || false,
          deleted: e._deleted || false,
          title: e.title || '',
          tag: e.tag || '',
        })),
      });
    }

    res.json({ projects: result });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/codex/sessions — browse past Codex CLI sessions across registered projects
app.get('/api/codex/sessions', async (req, res) => {
  try {
    const targetProject = req.query.project;
    const limit = Math.min(parseInt(req.query.limit) || 30, 100);
    const offset = parseInt(req.query.offset) || 0;
    const search = (req.query.search || '').toLowerCase().trim();
    const result = await getCodexSessionsResponse({ targetProject, limit, offset, search });
    res.json({ projects: result });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/opencode/sessions — browse past OpenCode sessions across registered projects
app.get('/api/opencode/sessions', (req, res) => {
  try {
    const db = getOpencodeDb();
    const projects = loadHookProjects();
    const targetProject = req.query.project;
    const limit = Math.min(parseInt(req.query.limit) || 30, 100);
    const offset = parseInt(req.query.offset) || 0;
    const search = (req.query.search || '').toLowerCase().trim();

    if (!db) return res.json({ projects: projects.map(p => ({ path: p.path, label: p.label || basename(p.path), total: 0, sessions: [] })) });

    let rows;
    try {
      // OpenCode 2's tables (lib/opencode-db-schema.js); a file without them lists nothing.
      if (!hasOpencodeSessionTables(db)) throw new Error('no OpenCode 2 session tables');
      const tables = OPENCODE_SESSION_TABLES;
      const stmt = db.prepare(`
        SELECT s.id, s.title, s.directory, s.time_created, s.time_updated,
               p.worktree as project_worktree,
               ${tables.messageCount} as message_count
        FROM ${tables.session} s
        LEFT JOIN project p ON s.project_id = p.id
        WHERE s.time_archived IS NULL
        ORDER BY s.time_updated DESC
      `);
      rows = stmt.all();
    } catch { rows = []; }

    // Group by registered project
    const sessionsByProject = new Map();
    for (const proj of projects) sessionsByProject.set(resolve(proj.path), []);

    for (const row of rows) {
      // OpenCode's project.worktree is the actual project path
      const projWorktree = row.project_worktree ? resolve(row.project_worktree) : null;
      const dir = row.directory ? resolve(row.directory) : null;
      const matchDir = projWorktree || dir;
      if (!matchDir) continue;
      const projPath = [...sessionsByProject.keys()].find(pp => matchDir.startsWith(pp));
      if (!projPath) continue;
      if (targetProject && projPath !== resolve(targetProject)) continue;

      sessionsByProject.get(projPath).push({
        sessionId: row.id,
        firstPrompt: row.title || '',
        messageCount: row.message_count || 0,
        created: row.time_created ? new Date(row.time_created).toISOString() : null,
        modified: row.time_updated ? new Date(row.time_updated).toISOString() : null,
        gitBranch: null,
      });
    }

    const result = [];
    for (const proj of projects) {
      if (targetProject && resolve(proj.path) !== resolve(targetProject)) continue;
      let entries = sessionsByProject.get(resolve(proj.path)) || [];
      entries.sort((a, b) => new Date(b.modified) - new Date(a.modified));
      if (search) {
        entries = entries.filter(e =>
          (e.firstPrompt || '').toLowerCase().includes(search) ||
          (e.sessionId || '').toLowerCase().includes(search)
        );
      }
      const total = entries.length;
      result.push({
        path: proj.path,
        label: proj.label || basename(proj.path),
        total,
        sessions: entries.slice(offset, offset + limit),
      });
    }
    res.json({ projects: result });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

