app.put('/api/cli/config', (req, res) => {
  try {
    if (!req.body || typeof req.body !== 'object') {
      return res.status(400).json({ ok: false, error: 'Body must be a JSON object' });
    }
    const config = loadCliConfig();
    for (const [key, val] of Object.entries(req.body)) {
      if (CLI_DEFAULTS[key] && val && typeof val === 'object') {
        const command = (val.command || '').trim();
        config[key] = { command: command || CLI_DEFAULTS[key].command };
      }
    }
    saveCliConfig(config);
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Settings > Terminal > Detect: what is installed, whatever Settings says now
// (the button fills the field with it), found the way every launcher finds it
// (lib/cli-resolver.js), with the OS PATH read afresh.
app.post('/api/cli/detect/:profileId', async (req, res) => {
  try {
    const { profileId } = req.params;
    if (!['claude-code', 'codex', 'gemini', 'opencode'].includes(profileId)) return res.status(400).json({ ok: false, error: 'Unknown profile' });
    const status = await cliResolver.resolve(profileId, { force: true, configured: null });
    res.json({
      ok: true,
      found: status.state !== 'missing',
      path: status.path,
      version: status.version,
      state: status.state,
      foundBy: status.foundBy,
      pathStatus: cliPathManager.inspect(status),
      installSource: status.installSource,
      error: status.error,
      // OpenCode: whether SynaBun drives the one found (OpenCode 2 only), in the shape of /api/opencode/status `installed`.
      ...(profileId === 'opencode' && status.path ? { support: opencodeInstallStateOf({ ...opencodeSupportFor(status.version, { path: status.path }), path: status.path }) } : {}),
    });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// ═══════════════════════════════════════════
// TERMINAL LINKS — Relay/Mediator between PTY sessions
// ═══════════════════════════════════════════

const terminalLinks = new Map(); // linkId → LinkState

/**
 * Strip ANSI escape sequences from raw PTY output for relay purposes.
 * Covers CSI, OSC, DCS, charset designators, and C0 control chars.
 * Keeps \n and \t for readable text.
 */
function stripAnsi(str) {
  return str
    .replace(/\x1b\[[\x20-\x3f]*[\x40-\x7e]/g, '')              // CSI sequences
    .replace(/\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g, '')          // OSC sequences (BEL or ST terminated)
    .replace(/\x1b[P^_][\s\S]*?(?:\x1b\\|\x07)/g, '')           // DCS/PM/APC strings
    .replace(/\x1b[()][AB012]/g, '')                              // Charset designators
    .replace(/\x1b[=><78HMNOZcn]/g, '')                          // Simple ESC sequences
    .replace(/\x1b./g, '')                                        // Stray ESC + char
    .replace(/[^\n]*\r(?!\n)/g, '')                               // CR overwrite cleanup
    .replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, '');          // Control chars (keep \n \t)
}

// ── Sidecar CLI config — non-interactive args for each profile ──
// Spawns headless CLI processes for clean text relay (sidecar mode).
//
// stdin: true  — message piped to stdin (flag is a boolean mode switch)
// stdin: false — message appended as the last CLI arg (flag takes a value)
const CLI_SIDECAR_CONFIG = {
  'claude-code': { args: ['-p', '--verbose'], stdin: true },   // -p = non-interactive mode; reads prompt from stdin
  'gemini':      { args: ['-p'],              stdin: false },   // -p <value>; PowerShell passes correctly on Windows
  'codex':       { args: ['-q'],              stdin: false },   // -q <msg>; flag takes a value
  'shell':       null,
};

// ── Live PTY config — inject messages into the actual TUI terminal ──
// User sees messages typed and agents responding in real-time.
// Response captured from PTY output stream, ANSI-stripped, then relayed.
const CLI_LIVE_CONFIG = {
  'claude-code': {
    promptPatterns: [/>\s*$/m],             // ">" at end of stripped output
    idleMs: 3000,                           // 3s of no output → check prompt
    maxIdleMs: 120000,                      // 2 min absolute max wait
    useBracketedPaste: true,
  },
  'gemini': {
    promptPatterns: [/>\s*$/m, /\u276F\s*$/m],
    idleMs: 3000,
    maxIdleMs: 120000,
    useBracketedPaste: true,
  },
  'codex': {
    promptPatterns: [/>\s*$/m],
    idleMs: 3000,
    maxIdleMs: 120000,
    useBracketedPaste: true,
  },
  'shell': null,
};

const LIVE_CAPTURE_SETTLE_MS = 500; // delay after injection before starting capture

const LINK_SIDECAR_TIMEOUT_MS = 5 * 60 * 1000; // 5 min max per sidecar process

/**
 * Create a terminal link (relay/mediator session between agents).
 * mode: 'sidecar' (headless CLI processes) or 'live' (inject into TUI PTY).
 */
function createTerminalLink(sessionIds, config = {}) {
  for (const sid of sessionIds) {
    if (!terminalSessions.has(sid)) throw new Error(`Session ${sid} not found`);
  }
  for (const sid of sessionIds) {
    for (const [, link] of terminalLinks) {
      if (link.sessions.includes(sid)) throw new Error(`Session ${sid} is already linked`);
    }
  }

  const mode = config.mode || 'sidecar';

  // Validate live mode profiles
  if (mode === 'live') {
    for (const sid of sessionIds) {
      const s = terminalSessions.get(sid);
      if (!s || !CLI_LIVE_CONFIG[s.profile]) {
        throw new Error(`Profile "${s?.profile}" does not support live mode`);
      }
    }
  }

  const linkId = randomBytes(16).toString('hex');
  const link = {
    id: linkId,
    sessions: sessionIds,
    status: 'idle',           // idle | running | paused
    activeAgent: 0,           // index into sessions[]
    history: [],              // { role, sessionId, content, timestamp }
    mode,                     // 'sidecar' | 'live'
    config: {
      autoContinue: config.autoContinue !== false,
      maxTurns: config.maxTurns || 0,
      turnCount: 0,
    },
    // Sidecar-mode state
    _sidecarProcess: null,
    _sidecarSessionId: null,
    // Live-mode state
    _captureBuffer: '',
    _captureVTerm: null,           // VTermBuffer for clean text extraction
    _captureSessionId: null,
    _idleTimer: null,
    _maxIdleTimer: null,
    _injectionEcho: '',
    createdAt: Date.now(),
  };

  terminalLinks.set(linkId, link);
  return linkId;
}

/**
 * Destroy a terminal link — kill sidecar, remove from map.
 */
function destroyTerminalLink(linkId) {
  const link = terminalLinks.get(linkId);
  if (!link) return false;

  // Clean up sidecar mode
  if (link._sidecarProcess) {
    try { link._sidecarProcess.kill('SIGTERM'); } catch {}
    link._sidecarProcess = null;
  }

  // Clean up live mode
  if (link._idleTimer) clearTimeout(link._idleTimer);
  if (link._maxIdleTimer) clearTimeout(link._maxIdleTimer);
  if (link._captureSessionId) {
    const capSession = terminalSessions.get(link._captureSessionId);
    if (capSession) capSession._linkCaptureCallback = null;
  }
  link._captureVTerm = null;

  terminalLinks.delete(linkId);
  return true;
}

/**
 * Spawn a non-interactive sidecar CLI process for a linked agent.
 * Instead of injecting into the TUI PTY, we spawn a separate headless
 * process (e.g. `claude -p "message"`) and capture its clean stdout.
 */
function spawnSidecarProcess(linkId, sessionId, message) {
  const link = terminalLinks.get(linkId);
  if (!link) throw new Error('Link not found');

  const session = terminalSessions.get(sessionId);
  if (!session) throw new Error('Session not found');

  const profile = session.profile;
  const sidecarConfig = CLI_SIDECAR_CONFIG[profile];
  if (!sidecarConfig) throw new Error(`No sidecar config for profile: ${profile}`);

  // Get the CLI command from config (e.g. 'claude', 'gemini', 'codex')
  const cliConfig = loadCliConfig();
  const command = (cliConfig[profile]?.command || '').trim();
  if (!command) throw new Error(`No CLI command configured for ${profile}`);

  // Named by its plain name in Settings: the CLI the panels use (lib/cli-resolver.js), a program started
  // without a shell; otherwise the Settings value as written.
  const found = CLI_DEFAULTS[profile] && command === CLI_DEFAULTS[profile].command ? cliResolver.launcher(profile) : null;
  const direct = found?.spec?.kind === 'direct' ? found.launchPath : null;
  let spawnCmd = direct || command;
  // Codex: the Windows sandbox the Admin sandbox setting allows, before its flag (a bare value: no quote for a shell to lose).
  const leadArgs = profile === 'codex' ? ['-c', `windows.sandbox=${codexWindowsSandbox(adminSandboxOn())}`] : [];
  let spawnArgs = [...leadArgs, ...sidecarConfig.args];
  let useShell = IS_WIN && !direct;
  let tmpFile = null;

  if (sidecarConfig.stdin) {
    // stdin-based: args are fixed, message piped after spawn (e.g. Claude Code)
  } else if (IS_WIN) {
    // Windows: cmd.exe shell quoting mangles multi-word args (splits by spaces),
    // causing CLIs like Gemini to misparse -p "hello world" as -p + positional "hello" "world".
    // Use PowerShell which correctly passes $msg as a single argument value.
    tmpFile = join(os.tmpdir(), `synabun-relay-${randomBytes(4).toString('hex')}.txt`);
    writeFileSync(tmpFile, message, 'utf-8');
    const flag = sidecarConfig.args[0]; // e.g. '-p', '-q'
    const lead = leadArgs.map((word) => ` '${word}'`).join('');
    spawnCmd = 'powershell.exe';
    spawnArgs = ['-NoProfile', '-NonInteractive', '-Command',
      `$msg = Get-Content -Raw '${tmpFile}'; & '${String(direct || command).replace(/'/g, "''")}'${lead} ${flag} $msg`];
    useShell = false;
  } else {
    // Unix: pass directly as the flag's value arg (no shell quoting issues)
    spawnArgs.push(message);
  }

  console.log(`[link-sidecar] Spawning: ${spawnCmd} ${spawnArgs.join(' ').slice(0, 200)}... (${profile}, cwd: ${session.cwd || process.cwd()})`);

  const child = spawn(spawnCmd, spawnArgs, {
    cwd: session.cwd || process.cwd(),
    env: { ...withPathEnv(process.env, getAugmentedPath()), FORCE_COLOR: '0', NO_COLOR: '1' },
    stdio: ['pipe', 'pipe', 'pipe'],
    shell: useShell,
    timeout: LINK_SIDECAR_TIMEOUT_MS,
    windowsHide: true,
  });

  // Pipe message to stdin for CLIs that support it (e.g. Claude Code). A CLI
  // that ends before reading it fails the pipe (EPIPE) after write() returned:
  // its exit says what happened, and the error must not end the server.
  child.stdin.on('error', () => {});
  if (sidecarConfig.stdin) {
    child.stdin.write(message);
  }
  child.stdin.end();

  // Track on link state
  link._sidecarProcess = child;
  link._sidecarSessionId = sessionId;

  let fullOutput = '';

  child.stdout.on('data', (chunk) => {
    const text = chunk.toString();
    fullOutput += text;

    // Broadcast streaming chunk to clients
    broadcastSync({
      type: 'link:chunk',
      linkId,
      sessionId,
      profile,
      content: text,
    });
  });

  let stderrOutput = '';
  child.stderr.on('data', (chunk) => {
    const text = chunk.toString();
    stderrOutput += text;
    console.log(`[link-sidecar] ${profile} stderr: ${text.slice(0, 500)}`);
  });

  child.on('close', (code) => {
    link._sidecarProcess = null;
    link._sidecarSessionId = null;
    if (tmpFile) { try { unlinkSync(tmpFile); } catch {} }

    const cleanOutput = fullOutput.trim();

    if (code !== 0 && code !== null) {
      console.error(`[link-sidecar] ${profile} exited with code ${code}${stderrOutput ? ': ' + stderrOutput.slice(0, 500) : ''}`);
      if (!cleanOutput) {
        const errDetail = stderrOutput.trim().slice(0, 200) || `exited with code ${code}`;
        broadcastSync({ type: 'link:error', linkId, error: `${profile}: ${errDetail}` });
        link.status = 'idle';
        return;
      }
    }

    if (cleanOutput) {
      onSidecarFinished(linkId, sessionId, cleanOutput);
    } else {
      link.status = 'idle';
      broadcastSync({ type: 'link:agent-finished', linkId, sessionId, profile });
    }
  });

  child.on('error', (err) => {
    link._sidecarProcess = null;
    link._sidecarSessionId = null;
    console.error(`[link-sidecar] ${profile} spawn error:`, err.message);
    broadcastSync({ type: 'link:error', linkId, error: `Failed to start ${profile}: ${err.message}` });
    link.status = 'idle';
  });

  return child;
}

/**
 * Called when a sidecar process finishes with output.
 * Output is already clean text — no ANSI stripping needed.
 */
function onSidecarFinished(linkId, sessionId, cleanOutput) {
  const link = terminalLinks.get(linkId);
  if (!link) return;

  const session = terminalSessions.get(sessionId);
  const profile = session?.profile || 'unknown';

  // Add to history
  const entry = { role: profile, sessionId, content: cleanOutput, timestamp: Date.now() };
  link.history.push(entry);

  broadcastSync({ type: 'link:agent-finished', linkId, sessionId, profile });
  broadcastSync({ type: 'link:message', linkId, ...entry, turnCount: link.config.turnCount });

  // Auto-continue to next agent?
  if (link.config.autoContinue && link.status === 'running') {
    link.config.turnCount++;
    if (link.config.maxTurns > 0 && link.config.turnCount >= link.config.maxTurns) {
      link.status = 'idle';
      broadcastSync({ type: 'link:paused', linkId, reason: 'max-turns' });
      return;
    }
    relayToNextAgent(linkId, cleanOutput);
  } else {
    link.status = 'idle';
  }
}

// ── Live PTY injection functions ──

/**
 * Inject a message into a live PTY terminal and capture the response.
 * The message is typed directly into the TUI CLI's input prompt.
 * Response is captured from PTY output, ANSI-stripped, and relayed.
 */
function injectIntoLivePty(linkId, sessionId, message) {
  const link = terminalLinks.get(linkId);
  if (!link) throw new Error('Link not found');
  if (link.mode !== 'live') throw new Error('Link is not in live mode');

  const session = terminalSessions.get(sessionId);
  if (!session) throw new Error('Session not found');

  const profile = session.profile;
  const liveConfig = CLI_LIVE_CONFIG[profile];
  if (!liveConfig) throw new Error(`No live config for profile: ${profile}`);

  if (session._linkCaptureCallback) {
    throw new Error(`Session ${sessionId.slice(0, 8)} already has a capture callback`);
  }

  console.log(`[link-live] Injecting into ${profile} (session ${sessionId.slice(0, 8)}), msg: ${message.slice(0, 200)}...`);

  // Set up link capture state
  link._captureBuffer = '';
  link._captureSessionId = sessionId;
  link._injectionEcho = message;

  // Create VTermBuffer matching the session's PTY dimensions for clean text extraction.
  // Unlike regex stripAnsi(), this properly handles TUI cursor positioning, spinners,
  // and screen overwrites — only the final visual state is retained.
  const ptyCols = session.pty.cols || 120;
  const ptyRows = session.pty.rows || 30;
  link._captureVTerm = new VTermBuffer(ptyCols, ptyRows);

  broadcastSync({ type: 'link:agent-started', linkId, sessionId, profile });

  // Inject message into PTY — send text first, then Enter after a short delay.
  // TUI frameworks (Ink) process input per-frame; Enter must arrive as a separate
  // keystroke or it gets swallowed when bundled with the text in one write.
  const pty = session.pty;
  const ENTER_DELAY_MS = 80;

  if (liveConfig.useBracketedPaste && message.includes('\n')) {
    pty.write('\x1b[200~' + message + '\x1b[201~');
  } else {
    pty.write(message);
  }
  // Send Enter separately after delay
  setTimeout(() => pty.write('\r'), ENTER_DELAY_MS);

  // Wait for settle delay, then start capturing output
  setTimeout(() => {
    if (!terminalLinks.has(linkId)) return;
    if (link._captureSessionId !== sessionId) return;

    // Output reaches this process only while tapped; the tap switches itself
    // off once no consumer (link capture / loop driver) is left.
    terminalHost.setTap(sessionId, true);
    session._linkCaptureCallback = (data) => {
      link._captureBuffer += data;

      // Feed raw data into VTermBuffer for proper terminal emulation
      if (link._captureVTerm) {
        try { link._captureVTerm.write(data); } catch {}
      }

      // Broadcast streaming chunk (ANSI-stripped for display)
      const cleanChunk = stripAnsi(data);
      if (cleanChunk.trim()) {
        broadcastSync({
          type: 'link:chunk',
          linkId,
          sessionId,
          profile,
          content: cleanChunk,
        });
      }

      // Reset idle timer on each output chunk
      if (link._idleTimer) clearTimeout(link._idleTimer);
      link._idleTimer = setTimeout(() => {
        _checkLiveCaptureComplete(linkId, sessionId);
      }, liveConfig.idleMs);
    };

    // Absolute max wait safety net
    link._maxIdleTimer = setTimeout(() => {
      console.log(`[link-live] Max idle timeout for ${profile}`);
      _finalizeLiveCapture(linkId, sessionId, 'max-idle-timeout');
    }, liveConfig.maxIdleMs);

  }, LIVE_CAPTURE_SETTLE_MS);
}

/**
 * Called after idle timeout — check if the CLI prompt has reappeared.
 */
function _checkLiveCaptureComplete(linkId, sessionId) {
  const link = terminalLinks.get(linkId);
  if (!link || link._captureSessionId !== sessionId) return;

  const session = terminalSessions.get(sessionId);
  if (!session) {
    _finalizeLiveCapture(linkId, sessionId, 'session-gone');
    return;
  }

  const profile = session.profile;
  const liveConfig = CLI_LIVE_CONFIG[profile];
  if (!liveConfig) {
    _finalizeLiveCapture(linkId, sessionId, 'no-config');
    return;
  }

  // Check last 5 lines of ANSI-stripped output for prompt patterns
  const stripped = stripAnsi(link._captureBuffer);
  const lastLines = stripped.split('\n').slice(-5).join('\n');
  const promptFound = liveConfig.promptPatterns.some(p => p.test(lastLines));

  if (promptFound) {
    console.log(`[link-live] Prompt detected for ${profile}, finalizing`);
    _finalizeLiveCapture(linkId, sessionId, 'prompt-detected');
  } else {
    // No prompt found — set a short follow-up timer, then force finalize.
    // The idle timeout already means no output for idleMs; if still nothing
    // after another idleMs, the response is almost certainly done.
    console.log(`[link-live] Idle but no prompt for ${profile}, will finalize in ${liveConfig.idleMs}ms`);
    link._idleTimer = setTimeout(() => {
      _finalizeLiveCapture(linkId, sessionId, 'idle-no-prompt');
    }, liveConfig.idleMs);
  }
}

/**
 * Finalize a live PTY capture — strip ANSI, clean up, and relay.
 * Reuses onSidecarFinished() for history and auto-continue logic.
 */
function _finalizeLiveCapture(linkId, sessionId, reason) {
  const link = terminalLinks.get(linkId);
  if (!link) return;

  const session = terminalSessions.get(sessionId);
  const profile = session?.profile || 'unknown';

  console.log(`[link-live] Finalizing capture for ${profile}: ${reason}`);

  // Remove capture callback
  if (session) session._linkCaptureCallback = null;

  // Clear timers
  if (link._idleTimer) { clearTimeout(link._idleTimer); link._idleTimer = null; }
  if (link._maxIdleTimer) { clearTimeout(link._maxIdleTimer); link._maxIdleTimer = null; }

  // Extract clean text from VTermBuffer (proper terminal emulation).
  // Unlike regex stripAnsi(), VTermBuffer correctly handles cursor positioning,
  // spinner overwrites, and screen repaints — only the final visual state remains.
  let cleanOutput = '';
  const vterm = link._captureVTerm;
  if (vterm) {
    const sb = vterm.scrollbackLength;
    const totalRows = sb + vterm.rows;
    // Get all text: scrollback + visible screen
    cleanOutput = vterm.getText(0, 0, totalRows - 1, vterm.cols - 1);
    // Collapse excessive blank lines (TUI apps leave lots of empty rows)
    cleanOutput = cleanOutput.replace(/\n{3,}/g, '\n\n').trim();
  }

  // Fallback to regex stripping if VTermBuffer produced nothing
  if (!cleanOutput) {
    cleanOutput = stripAnsi(link._captureBuffer).trim();
  }

  console.log(`[link-live] Extracted text (${cleanOutput.length} chars, via ${vterm ? 'vterm' : 'regex'}): ${cleanOutput.slice(0, 300)}...`);

  // Strip injected echo — TUI CLIs echo back what was typed
  if (link._injectionEcho) {
    const echoText = link._injectionEcho.trim();
    // Strategy 1: prefix match
    if (cleanOutput.startsWith(echoText)) {
      cleanOutput = cleanOutput.slice(echoText.length).trim();
    } else {
      // Strategy 2: line-by-line match
      const echoLines = echoText.split('\n');
      const outputLines = cleanOutput.split('\n');
      let matched = 0;
      while (matched < echoLines.length && matched < outputLines.length) {
        if (outputLines[matched].trim() === echoLines[matched].trim()) {
          matched++;
        } else break;
      }
      if (matched > 0) {
        cleanOutput = outputLines.slice(matched).join('\n').trim();
      }
    }
  }

  // Strip trailing prompt patterns
  const liveConfig = CLI_LIVE_CONFIG[profile];
  if (liveConfig) {
    for (const pattern of liveConfig.promptPatterns) {
      cleanOutput = cleanOutput.replace(pattern, '').trim();
    }
  }

  // Reset live capture state
  link._captureBuffer = '';
  link._captureVTerm = null;
  link._captureSessionId = null;
  link._injectionEcho = '';

  if (cleanOutput) {
    onSidecarFinished(linkId, sessionId, cleanOutput);
  } else {
    link.status = 'idle';
    broadcastSync({ type: 'link:agent-finished', linkId, sessionId, profile });
    if (reason === 'max-idle-timeout') {
      broadcastSync({ type: 'link:error', linkId, error: `${profile}: No response detected (timed out)` });
    }
  }
}

/**
 * Forward a message to the next agent in the link chain.
 * Dispatches to sidecar or live mode based on link.mode.
 */
function relayToNextAgent(linkId, message) {
  const link = terminalLinks.get(linkId);
  if (!link) return;

  // Advance to next agent (round-robin)
  link.activeAgent = (link.activeAgent + 1) % link.sessions.length;
  const nextSessionId = link.sessions[link.activeAgent];
  const session = terminalSessions.get(nextSessionId);
  if (!session) {
    link.status = 'idle';
    broadcastSync({ type: 'link:error', linkId, error: 'Target session not found' });
    return;
  }

  link.status = 'running';

  // Cap message length (16KB — more generous since it's a CLI arg, not PTY)
  const MAX_RELAY_LEN = 16 * 1024;
  let relayMsg = message;
  if (relayMsg.length > MAX_RELAY_LEN) {
    relayMsg = relayMsg.slice(0, MAX_RELAY_LEN) + '\n\n[... response truncated]';
  }

  try {
    if (link.mode === 'live') {
      injectIntoLivePty(linkId, nextSessionId, relayMsg);
    } else {
      broadcastSync({ type: 'link:agent-started', linkId, sessionId: nextSessionId, profile: session.profile });
      spawnSidecarProcess(linkId, nextSessionId, relayMsg);
    }
  } catch (err) {
    link.status = 'idle';
    broadcastSync({ type: 'link:error', linkId, error: err.message });
  }
}

/**
 * User-initiated send — spawns sidecar for the specified (or first) agent.
 */
function sendToLink(linkId, message, targetIdx) {
  const link = terminalLinks.get(linkId);
  if (!link) throw new Error('Link not found');

  // Kill any running sidecar / clean up live capture
  if (link._sidecarProcess) {
    try { link._sidecarProcess.kill('SIGTERM'); } catch {}
    link._sidecarProcess = null;
  }
  if (link._captureSessionId) {
    const capSession = terminalSessions.get(link._captureSessionId);
    if (capSession) capSession._linkCaptureCallback = null;
    if (link._idleTimer) { clearTimeout(link._idleTimer); link._idleTimer = null; }
    if (link._maxIdleTimer) { clearTimeout(link._maxIdleTimer); link._maxIdleTimer = null; }
    link._captureBuffer = '';
    link._captureVTerm = null;
    link._captureSessionId = null;
  }

  const agentIdx = (typeof targetIdx === 'number') ? targetIdx : link.activeAgent;
  const sessionId = link.sessions[agentIdx];
  const session = terminalSessions.get(sessionId);
  if (!session) throw new Error('Target session not found');

  // Record in history as user message
  const entry = { role: 'user', sessionId: null, content: message, timestamp: Date.now() };
  link.history.push(entry);
  broadcastSync({ type: 'link:message', linkId, ...entry, turnCount: link.config.turnCount });

  // Set link to running
  link.activeAgent = agentIdx;
  link.status = 'running';

  // Dispatch based on mode
  if (link.mode === 'live') {
    injectIntoLivePty(linkId, sessionId, message);
  } else {
    broadcastSync({ type: 'link:agent-started', linkId, sessionId, profile: session.profile });
    spawnSidecarProcess(linkId, sessionId, message);
  }
}

// ── Terminal Link REST endpoints ──

app.get('/api/terminal/links', (req, res) => {
  const links = [...terminalLinks.entries()].map(([id, l]) => ({
    id,
    sessions: l.sessions.map(sid => {
      const s = terminalSessions.get(sid);
      return { id: sid, profile: s?.profile || 'unknown', cwd: s?.cwd };
    }),
    status: l.status,
    activeAgent: l.activeAgent,
    historyCount: l.history.length,
    mode: l.mode,
    config: { autoContinue: l.config.autoContinue, maxTurns: l.config.maxTurns, turnCount: l.config.turnCount },
    createdAt: l.createdAt,
  }));
  res.json({ links });
});

app.get('/api/terminal/links/:id', (req, res) => {
  const link = terminalLinks.get(req.params.id);
  if (!link) return res.status(404).json({ error: 'Link not found' });
  res.json({
    id: link.id,
    sessions: link.sessions.map(sid => {
      const s = terminalSessions.get(sid);
      return { id: sid, profile: s?.profile || 'unknown', cwd: s?.cwd };
    }),
    status: link.status,
    activeAgent: link.activeAgent,
    mode: link.mode,
    history: link.history,
    config: { autoContinue: link.config.autoContinue, maxTurns: link.config.maxTurns, turnCount: link.config.turnCount },
    createdAt: link.createdAt,
  });
});

app.post('/api/terminal/links', (req, res) => {
  const { sessions, autoContinue, maxTurns, mode } = req.body;
  if (!Array.isArray(sessions) || sessions.length < 2) {
    return res.status(400).json({ error: 'At least 2 session IDs required' });
  }
  try {
    const linkId = createTerminalLink(sessions, { autoContinue, maxTurns, mode });
    broadcastSync({ type: 'link:created', linkId, sessions, mode: mode || 'sidecar' });
    res.json({ linkId });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.delete('/api/terminal/links/:id', (req, res) => {
  const link = terminalLinks.get(req.params.id);
  if (!link) return res.status(404).json({ error: 'Link not found' });
  const sessions = [...link.sessions];
  destroyTerminalLink(req.params.id);
  broadcastSync({ type: 'link:deleted', linkId: req.params.id, sessions });
  res.json({ ok: true });
});

app.patch('/api/terminal/links/:id', (req, res) => {
  const link = terminalLinks.get(req.params.id);
  if (!link) return res.status(404).json({ error: 'Link not found' });
  const { autoContinue, maxTurns } = req.body;
  if (typeof autoContinue === 'boolean') link.config.autoContinue = autoContinue;
  if (typeof maxTurns === 'number') link.config.maxTurns = maxTurns;
  res.json({ ok: true, config: link.config });
});

app.post('/api/terminal/links/:id/send', (req, res) => {
  const { message, targetIdx } = req.body;
  if (!message || typeof message !== 'string') {
    return res.status(400).json({ error: 'message is required' });
  }
  try {
    sendToLink(req.params.id, message, targetIdx);
    res.json({ ok: true });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.post('/api/terminal/links/:id/pause', (req, res) => {
  const link = terminalLinks.get(req.params.id);
  if (!link) return res.status(404).json({ error: 'Link not found' });
  link.status = 'idle';
  link.config.autoContinue = false;
  // Kill any running sidecar process
  if (link._sidecarProcess) {
    try { link._sidecarProcess.kill('SIGTERM'); } catch {}
    link._sidecarProcess = null;
    link._sidecarSessionId = null;
  }
  // Clean up live capture
  if (link._captureSessionId) {
    const capSession = terminalSessions.get(link._captureSessionId);
    if (capSession) capSession._linkCaptureCallback = null;
    if (link._idleTimer) { clearTimeout(link._idleTimer); link._idleTimer = null; }
    if (link._maxIdleTimer) { clearTimeout(link._maxIdleTimer); link._maxIdleTimer = null; }
    link._captureBuffer = '';
    link._captureVTerm = null;
    link._captureSessionId = null;
  }
  broadcastSync({ type: 'link:paused', linkId: req.params.id, reason: 'manual' });
  res.json({ ok: true });
});

app.post('/api/terminal/links/:id/resume', (req, res) => {
  const link = terminalLinks.get(req.params.id);
  if (!link) return res.status(404).json({ error: 'Link not found' });
  link.config.autoContinue = true;
  broadcastSync({ type: 'link:resumed', linkId: req.params.id });
  res.json({ ok: true });
});

app.post('/api/terminal/links/:id/nudge', (req, res) => {
  const link = terminalLinks.get(req.params.id);
  if (!link) return res.status(404).json({ error: 'Link not found' });

  // Kill current sidecar / clean up live capture
  if (link._sidecarProcess) {
    try { link._sidecarProcess.kill('SIGTERM'); } catch {}
    link._sidecarProcess = null;
    link._sidecarSessionId = null;
  }
  if (link._captureSessionId) {
    const capSession = terminalSessions.get(link._captureSessionId);
    if (capSession) capSession._linkCaptureCallback = null;
    if (link._idleTimer) { clearTimeout(link._idleTimer); link._idleTimer = null; }
    if (link._maxIdleTimer) { clearTimeout(link._maxIdleTimer); link._maxIdleTimer = null; }
    link._captureBuffer = '';
    link._captureVTerm = null;
    link._captureSessionId = null;
  }

  // Get last agent message from history (or a nudge placeholder)
  const lastAgentMsg = [...link.history].reverse().find(h => h.role !== 'user');
  const relayContent = lastAgentMsg?.content || '[nudge — no previous response]';

  link.status = 'running';
  link.config.autoContinue = true;
  relayToNextAgent(link.id, relayContent);
  res.json({ ok: true });
});


// ═══════════════════════════════════════════
// BROWSER — Playwright-core CDP Manager
// ═══════════════════════════════════════════
//
// Manages headless/headed Chromium instances via playwright-core.
// Streams viewport via CDP Page.screencastFrame over WebSocket.
// Exposes CDP endpoint so Claude Code's Playwright MCP can connect.

const browserSessions = new Map(); // sessionId → { browser, context, page, clients, cdpSession, screencastActive, ... }
const BROWSER_GRACE_PERIOD_MS = 5 * 60 * 1000; // 5 min before orphaned browser is killed

/** Check if a browser session is actively used by a running automation loop or agent.
 *  Uses in-memory ownership flags — no file I/O, no race conditions. */
function isSessionUsedByActiveLoop(sessionId) {
  const session = browserSessions.get(sessionId);
  if (!session) return false;
  // Check in-memory loop ownership (Set of terminalSessionIds)
  if (session._loopOwned?.size > 0) return true;
  // Check agent ownership (Set of agentIds)
  if (session._agentOwnedSet?.size > 0) return true;
  // Check agent registry for running agents targeting this session
  for (const agent of agentRegistry.values()) {
    if (agent.status === 'running' && agent.browserSessionId === sessionId) return true;
  }
  return false;
}

// Periodic reaper for browser sessions that go idle without ever having a
// watching WS client. The ws.on('close') path (below) only reaps sessions a
// client disconnected from — a session created for a loop/agent/headless MCP
// call that finishes (owners cleared) but never had a client attached would
// otherwise stay resident forever, holding ~1+ GB of Chromium on about:blank.
// A session must stay continuously idle (no clients, no owners) for the full
// window before it's killed; it is lazily recreated on the next browser call.
const BROWSER_IDLE_REAP_MS = 10 * 60 * 1000; // 10 min of continuous idleness
setInterval(() => {
  const now = Date.now();
  for (const [id, session] of browserSessions) {
    // Never reap an attach (CDP) session — it backs a live Chrome window the user is
    // using; reaping would disconnect it and a later call would spawn a 2nd debug Chrome.
    if (session._profileMode === 'cdp' || session._profileMode === 'morelogin') { session._idleSince = null; continue; }
    const idle = (session.clients?.size || 0) === 0
      && sessionOwnerCount(session) === 0
      && !isSessionUsedByActiveLoop(id);
    if (!idle) { session._idleSince = null; continue; }
    if (!session._idleSince) { session._idleSince = now; continue; }
    if (now - session._idleSince >= BROWSER_IDLE_REAP_MS) {
      console.log(`[browser] Reaping idle unwatched session ${id} (idle ${Math.round((now - session._idleSince) / 1000)}s)`);
      destroyBrowserSession(id).catch(() => {});
    }
  }
}, 60_000).unref?.();

// ── Default-browser policy for automation sessions ──
// While MoreLogin is the default browser, every loop / schedule / dispatched run
// must drive the default MoreLogin profile, localhost pages included.
function moreLoginDefaultEnvId(cfg) {
  return cfg?.moreloginEnvId || (cfg?.morelogin && cfg.morelogin.defaultEnvId) || null;
}

function sessionServesMoreLoginDefault(session, cfg) {
  if (!session || session._profileMode !== 'morelogin') return false;
  const envId = moreLoginDefaultEnvId(cfg);
  return !envId || String(session._mlEnvId || '') === String(envId);
}

function describeBrowserSessionForLog(session) {
  return {
    profileMode: session?._profileMode || null,
    envId: session?._mlEnvId || null,
  };
}

async function findReusableBrowserSession(opts = {}) {
  const { excludeAgentOwned = true, excludeLoopOwned = true } = opts;
  const cfg = loadBrowserConfig();
  // Don't reuse across connect modes: an attach (cdp) session and a mirror session
  // are not interchangeable. Protects in-flight loops when the mode is switched.
  // Use the same applicability test as session creation to avoid infinite re-spawn.
  const wantAttach = isAttachConfigActive(cfg);
  const wantMoreLogin = cfg.connectMode === 'morelogin';
  let selectedPath = cfg.userDataDir || '';
  if (selectedPath && !selectedPath.startsWith('/') && !(/^[A-Z]:/i.test(selectedPath))) {
    selectedPath = resolve(DATA_HOME, selectedPath);
  }
  const normalize = (p) => (p || '').replace(/[\\/]+$/, '').replace(/\\/g, '/').toLowerCase();
  const selectedNorm = normalize(selectedPath);
  for (const [id, session] of browserSessions) {
    if (excludeAgentOwned && session._agentOwnedSet?.size > 0) continue;
    if (excludeLoopOwned && session._loopOwned?.size > 0) continue;
    // Belt-and-suspenders: also check agent registry in case the ownership set
    // hasn't been set yet (race between session creation and ownership marking)
    if (excludeAgentOwned) {
      let agentClaimed = false;
      for (const agent of agentRegistry.values()) {
        if (agent.status === 'running' && agent.browserSessionId === id) { agentClaimed = true; break; }
      }
      if (agentClaimed) continue;
    }
    // MoreLogin sessions are keyed by env id (not a userDataDir). When either the
    // active config OR this session is MoreLogin-backed, both must be — and the env
    // id must line up exactly — otherwise they aren't interchangeable.
    if (wantMoreLogin || session._profileMode === 'morelogin') {
      if (!wantMoreLogin || !sessionServesMoreLoginDefault(session, cfg)) continue;
    } else {
      if (wantAttach && session._profileMode !== 'cdp') continue;
      if (!wantAttach && session._profileMode === 'cdp') continue;
      if (selectedNorm) {
        const sessionSelected = normalize(session._selectedProfilePath);
        const sessionRoot = normalize(session._launchUserDataDir);
        const sessionActiveProfile = normalize(resolve(session._launchUserDataDir || '', session._launchProfileDirectory || 'Default'));
        if (selectedNorm !== sessionSelected && selectedNorm !== sessionRoot && selectedNorm !== sessionActiveProfile) {
          continue;
        }
      } else if (session._profileMode !== 'clean') {
        continue;
      }
    }
    try {
      // Do not probe only the mutable `session.page` alias here. A renderer can
      // wedge or the final external MoreLogin tab can close while the browser
      // context remains perfectly capable of creating the next loop's fresh tab.
      // `context.pages()` is local Playwright state and cannot itself wait on a
      // wedged renderer. Actual viability is verified by createSessionTab below.
      if (session.browser?.isConnected?.() === false) throw new Error('browser disconnected');
      session.context.pages();
      return { id, session };
    } catch (error) {
      console.warn(`[browser] Existing session ${id} context is dead — destroying (${error.message})`);
      await destroyBrowserSession(id).catch(() => {});
    }
  }
  return null;
}

// Serializes shared-loop-browser acquisition so concurrent loop/cron launches
// don't each create a separate "shared" browser. Without this mutex, two launches
// in the same tick both see findReusableBrowserSession() === null (before either
// createBrowserSession() registers its session) and each spawns a browser —
// breaking the single-shared-browser model that tab isolation depends on.
let _loopBrowserAcquireChain = Promise.resolve();
function withLoopBrowserLock(fn) {
  const result = _loopBrowserAcquireChain.then(fn, fn);
  // Keep the chain from latching into a rejected state after a failed acquisition.
  _loopBrowserAcquireChain = result.then(() => {}, () => {});
  return result;
}

/**
 * Acquire (reuse-or-create) the ONE shared browser and create a dedicated tab for
 * the caller, recording ownerKey → tabId so getTargetPage() can route that caller's
 * tab-less calls back to its own tab. Serialized via withLoopBrowserLock so
 * concurrent launches share one browser and never collide during find-or-create.
 *
 * ownerType: 'loop' marks the session _loopOwned (active-automation semantics);
 * 'interactive' marks it _interactiveOwned (a non-loop CLI MCP process claiming a
 * dedicated tab in the shared browser instead of spawning a second profile-locked
 * browser). Both record into _tabOwners — the routing map is owner-type agnostic.
 *
 * Returns { browserSessionId, browserTabId } on success, or { error } on failure.
 */
async function acquireSharedBrowserTab({ requestedBrowserSessionId = null, ownerKey, ownerType = 'loop', logTag = 'launch:browser' }) {
  return withLoopBrowserLock(async () => {
    let browserSessionId = null;
    let browserTabId = null;
    const ownerProp = ownerType === 'interactive' ? '_interactiveOwned' : '_loopOwned';

    // Strategy 0: best-effort pin to the caller-provided browser session — only when
    // it is a browser this caller may run in. While MoreLogin is the default, that is
    // the default MoreLogin profile.
    const policyCfg = loadBrowserConfig();
    const moreLoginDefault = policyCfg.connectMode === 'morelogin';
    if (requestedBrowserSessionId) {
      const requested = browserSessions.get(requestedBrowserSessionId);
      const unfit = requested && moreLoginDefault && !sessionServesMoreLoginDefault(requested, policyCfg);
      if (unfit) {
        loopLog(ownerKey, logTag, 'strategy 0 skipped: requested browser is not the default browser profile', {
          requestedBrowserSessionId, ...describeBrowserSessionForLog(requested),
          wantMoreLoginEnvId: moreLoginDefault ? moreLoginDefaultEnvId(policyCfg) : null,
        });
      } else if (requested) {
        try {
          await requested.page.evaluate('1');
          browserSessionId = requestedBrowserSessionId;
          loopLog(ownerKey, logTag, 'strategy 0: pinned to requested browser', { browserSessionId });
        } catch (err) {
          loopLog(ownerKey, logTag, 'strategy 0 failed: requested browser unhealthy — destroying', { requestedBrowserSessionId, err: err.message });
          await destroyBrowserSession(requestedBrowserSessionId).catch(() => {});
        }
      } else {
        loopLog(ownerKey, logTag, 'strategy 0 skipped: requested browser not in registry', { requestedBrowserSessionId });
      }
    }

    // Strategy 1: reuse the existing shared browser session. Under a PERSISTENT profile
    // only one Chromium can run, so every owner type (loop/interactive/agent) must join
    // the same browser — do NOT exclude agent-owned, or a concurrent acquire would fall
    // to strategy 2 and throw "profile is locked". Under a clean profile each owner can
    // have its own browser, so keep agent-owned excluded to preserve per-agent isolation.
    if (!browserSessionId) {
      const persistentProfile = !!loadBrowserConfig().userDataDir;
      const reusable = await findReusableBrowserSession({ excludeAgentOwned: !persistentProfile, excludeLoopOwned: false });
      if (reusable) {
        browserSessionId = reusable.id;
        loopLog(ownerKey, logTag, 'strategy 1: reusing shared browser session', { browserSessionId });
      } else {
        loopLog(ownerKey, logTag, 'strategy 1: no reusable shared browser session found');
      }
    }

    // Strategy 2: no shared browser exists — create one using the selected profile.
    // createBrowserSession is strict: with MoreLogin as the default it either attaches
    // to MoreLogin (auto-launching the app) or throws — never a Chrome fallback.
    let createError = null;
    if (!browserSessionId) {
      try {
        const result = await createBrowserSession({ url: 'about:blank' });
        browserSessionId = result.sessionId;
        loopLog(ownerKey, logTag, 'strategy 2: created shared browser session', {
          browserSessionId, profileMode: result.profileMode, profileSource: result.profileSource,
        });
        broadcastSync({
          type: 'browser:session-created',
          sessionId: browserSessionId, url: 'about:blank',
          profileMode: result.profileMode, profileSource: result.profileSource,
        });
      } catch (err) {
        createError = err.message;
        loopLog(ownerKey, logTag, 'strategy 2 FAILED: createBrowserSession threw', { err: err.message, stack: err.stack?.slice(0, 600) });
      }
    }

    if (!browserSessionId) {
      // Carry the real reason (e.g. "MoreLogin connect failed: … unreachable") into the
      // run's log, lastRunResult and the schedule:failed toast.
      return {
        error: createError
          ? `Could not start the shared browser session: ${createError}`
          : 'Could not start the shared browser session. Open Browser Settings and verify the selected profile can launch.',
      };
    }

    // Invariant: never hand an automation a browser other than the default MoreLogin
    // profile while MoreLogin is the default (strategies 0–2 already enforce it).
    const chosenSession = browserSessions.get(browserSessionId);
    if (moreLoginDefault && chosenSession && !sessionServesMoreLoginDefault(chosenSession, policyCfg)) {
      loopLog(ownerKey, logTag, 'ABORT: acquired session is not the default MoreLogin profile', {
        browserSessionId, ...describeBrowserSessionForLog(chosenSession),
      });
      return {
        error: `Refusing browser session ${browserSessionId} (${chosenSession._profileMode || 'unknown'} mode): MoreLogin env ${moreLoginDefaultEnvId(policyCfg) || '(default)'} is the default browser, and automations never fall back to another browser.`,
      };
    }

    // Mark owned immediately (before the tab-creation await) so a concurrent launch
    // can't see this session as unowned. Clear any pending grace timer. Defensively
    // init the owner set — sessions created before this field existed may lack it.
    const claimedSession = browserSessions.get(browserSessionId);
    if (claimedSession) {
      if (!claimedSession[ownerProp]) claimedSession[ownerProp] = new Set();
      claimedSession[ownerProp].add(ownerKey);
    }
    if (claimedSession?.graceTimer) { clearTimeout(claimedSession.graceTimer); claimedSession.graceTimer = null; }

    if (!claimedSession) {
      return { error: 'Shared browser session vanished during acquisition.' };
    }

    // ALWAYS create a dedicated, registered tab for the new owner. The old
    // else-branch handed out activeTabId when the tabs map was empty — every
    // owner landing there mapped to the SAME tab (cross-automation collision).
    // createBrowserSession registers the first tab, so an empty/missing tabs
    // map only occurs on degenerate legacy sessions — create a real tab there too.
    if (!claimedSession.tabs) claimedSession.tabs = new Map();
    try {
      const newTab = await createSessionTab(claimedSession, browserSessionId, 'about:blank');
      browserTabId = newTab.tabId;
      // Do NOT _switchSessionTab here. Each owner pins its own tab via SYNABUN_BROWSER_TAB
      // (loops) or the returned tabId (interactive); switching the shared session's active
      // tab pollutes other concurrent owners.
      loopLog(ownerKey, logTag, `created new ${ownerType} tab in shared session`, { browserSessionId, browserTabId });
    } catch (err) {
      claimedSession?.[ownerProp]?.delete(ownerKey);
      loopLog(ownerKey, logTag, 'ABORT: could not create tab', { err: err.message, browserSessionId });
      return { error: `Could not create a new browser tab: ${err.message}` };
    }

    // Record ownerKey → tabId so getTargetPage() can route a tab-less call from this
    // owner back to its own tab instead of the shared activeTab.
    if (claimedSession && browserTabId) {
      if (!claimedSession._tabOwners) claimedSession._tabOwners = new Map();
      claimedSession._tabOwners.set(ownerKey, browserTabId);
    }

    return { browserSessionId, browserTabId };
  });
}

/**
 * Backward-compatible loop wrapper around acquireSharedBrowserTab. Existing callers
 * pass { terminalSessionId } and expect loop-owned semantics.
 */
async function acquireLoopBrowserAndTab({ requestedBrowserSessionId = null, terminalSessionId, logTag = 'launch:browser' }) {
  return acquireSharedBrowserTab({ requestedBrowserSessionId, ownerKey: terminalSessionId, ownerType: 'loop', logTag });
}

/**
 * Relinquish ONE owner's dedicated tab in a shared browser without destroying the
 * browser that other owners may still be using. Drops the ownership + routing entries
 * and closes the owned tab only when it is not the session's last tab (the grace timer
 * reaps the browser once no owners remain). Safe to call with any ownerKey/owner type.
 */
async function releaseSharedBrowserTab(sessionId, ownerKey) {
  const session = browserSessions.get(sessionId);
  if (!session) return;
  session._interactiveOwned?.delete(ownerKey);
  session._loopOwned?.delete(ownerKey);
  const tabId = session._tabOwners?.get(ownerKey);
  if (tabId) {
    session._tabOwners.delete(ownerKey);
    if (session.tabs?.size > 1 && session.tabs.has(tabId)) {
      await closeSessionTab(session, sessionId, tabId).catch(() => {});
    }
  }
}

// ── Real-time sync WebSocket (multi-client state broadcast) ──
const syncClients = new Set(); // Set<WebSocket>

function isDroppableSidepanelProviderEvent(message) {
  if (message?.type !== 'sidepanel:provider-event') return false;
  const payload = message.event;
  const event = payload?.event;
  if (payload?.provider === 'codex') return event?.type === 'item.updated';
  if (payload?.provider !== 'claude-code' && payload?.provider !== 'claude') return false;
  return event?.type === 'stream_event'
    && event.event?.type === 'content_block_delta'
    && (event.event?.delta?.type === 'text_delta' || event.event?.delta?.type === 'thinking_delta');
}

function broadcastSync(message, excludeWs = null) {
  const data = JSON.stringify(message);
  const messageType = String(message?.type || '');
  const ownerOnly = ['sidepanel:', 'schedule:', 'schedule-group:', 'quick-timer:', 'assistant:', 'whatsapp:', 'editor:', 'skills:', 'crash-notice:']
    .some((prefix) => messageType.startsWith(prefix));
  const dropUnderBackpressure = isDroppableSidepanelProviderEvent(message);
  let sent = 0;
  for (const client of syncClients) {
    if (dropUnderBackpressure && Number(client.bufferedAmount) > 1024 * 1024) continue;
    if (client !== excludeWs && client.readyState === 1 && (!ownerOnly || !client._isGuest)) {
      try {
        client.send(data);
        sent++;
      } catch {}
    }
  }
  if (syncClients.size > 0 && message?.type !== 'sidepanel:provider-event') {
    console.log(`[sync] broadcast "${message.type}" → ${sent}/${syncClients.size} clients`);
  }
}

// Relayable message types (client → server → other clients)
const RELAYABLE_TYPES = new Set([
  'card:opened', 'card:closed', 'card:moved', 'card:resized', 'card:compacted', 'card:expanded',
  'terminal:session-created', 'terminal:session-deleted',
  'browser:session-created', 'browser:session-deleted',
  'link:created', 'link:deleted', 'link:message', 'link:agent-started', 'link:agent-finished',
  'link:paused', 'link:resumed', 'link:error', 'link:chunk',
]);

// Permission required per relay type prefix
const RELAY_PERM_MAP = { 'card:': 'cards', 'terminal:': 'terminal', 'link:': 'terminal' };

function handleSyncWebSocket(ws, req) {
  const guest = isGuestRequest(req);
  ws._isGuest = guest;
  syncClients.add(ws);
  console.log(`[sync] Client connected (${guest ? 'guest' : 'owner'}), total: ${syncClients.size}`);

  // Send initial state with role + permissions
  ws.send(JSON.stringify({
    type: 'connected',
    clients: syncClients.size,
    isGuest: guest,
    permissions: { ...invitePermissions },
  }));
  broadcastSync({ type: 'clients', count: syncClients.size });

  // Bidirectional relay: client → server → other clients
  ws.on('message', (raw) => {
    try {
      const msg = JSON.parse(raw);
      if (!msg.type || !RELAYABLE_TYPES.has(msg.type)) return;
      // A socket the owner's powers are refused to (lib/owner-authority.js): it reads, it relays nothing.
      if (req?._synabunReadOnly) return;

      // Permission check for guest senders
      if (ws._isGuest) {
        const permKey = Object.entries(RELAY_PERM_MAP).find(([prefix]) => msg.type.startsWith(prefix));
        if (permKey && !invitePermissions[permKey[1]]) return; // silently drop
      }

      broadcastSync(msg, ws); // relay to everyone except sender
    } catch { /* ignore malformed */ }
  });

  ws.on('close', () => {
    syncClients.delete(ws);
    console.log(`[sync] Client disconnected (${ws._isGuest ? 'guest' : 'owner'}), total: ${syncClients.size}`);
    broadcastSync({ type: 'clients', count: syncClients.size });
  });
}

// ── Whiteboard WebSocket clients (Claude MCP integration) ──
// Each socket carries `_wbClient` = { clientId, viewport, focusActive, visible,
// lastSeen, protocol, isGuest }. The viewport used for MCP coordinate math and
// the window asked for screenshots is the PRIMARY client: owner before guest,
// focus-active + visible first, most recently active last. With no browser
// connected the built-in default applies and GET /api/whiteboard says so.
const whiteboardClients = new Set(); // Set<WebSocket>
const whiteboardPendingScreenshots = new Map(); // requestId → { resolve, reject, timer }

function getPrimaryWhiteboardClient() {
  let best = null;
  let bestScore = -1;
  for (const ws of whiteboardClients) {
    if (ws.readyState !== 1) continue;
    const c = ws._wbClient;
    if (!c || !c.viewport) continue;
    const score = (c.isGuest ? 0 : 4) + (c.focusActive && c.visible !== false ? 2 : 0) + (c.visible !== false ? 1 : 0);
    if (score > bestScore || (score === bestScore && c.lastSeen > (best._wbClient.lastSeen || 0))) {
      best = ws;
      bestScore = score;
    }
  }
  return best;
}

function getWhiteboardViewport() {
  const primary = getPrimaryWhiteboardClient();
  return primary ? { ...primary._wbClient.viewport } : { ...WB_DEFAULT_VIEWPORT };
}

function getWhiteboardConnection() {
  const primary = getPrimaryWhiteboardClient();
  let clients = 0;
  for (const ws of whiteboardClients) if (ws.readyState === 1) clients++;
  return {
    clients,
    focusActive: !!(primary && primary._wbClient.focusActive),
    primaryClientId: primary ? primary._wbClient.clientId : null,
    source: primary ? 'browser' : 'default',
  };
}

function broadcastToWhiteboard(message, excludeWs = null) {
  const data = JSON.stringify(message);
  for (const client of whiteboardClients) {
    if (client !== excludeWs && client.readyState === 1) client.send(data);
  }
}

/** Send a list of {op:'update'|'remove'|'add'} ops: protocol-2 clients (they
 *  sent a clientId) get ONE `batch` message (one undo step, one render); older
 *  client JS gets the legacy per-op messages. */
function broadcastWhiteboardOps(ops, excludeWs = null) {
  if (!ops.length) return;
  const batch = JSON.stringify({ type: 'batch', ops });
  for (const client of whiteboardClients) {
    if (client === excludeWs || client.readyState !== 1) continue;
    if (client._wbClient?.protocol >= 2) { client.send(batch); continue; }
    for (const op of ops) {
      if (op.op === 'update') client.send(JSON.stringify({ type: 'update', id: op.id, updates: op.updates }));
      else if (op.op === 'remove') client.send(JSON.stringify({ type: 'remove', id: op.id }));
      else if (op.op === 'add' && op.element) client.send(JSON.stringify({ type: 'add', elements: [op.element] }));
    }
  }
}

// ── Browser config ──

const BROWSER_CONFIG_PATH = resolve(DATA_HOME, 'data', 'browser-config.json');

// The text of the last config read or written successfully. A read that fails (a
// torn file, a parse error, an I/O error) returns it instead of {}: an empty config
// would silently switch MoreLogin mode off for whatever asked. Kept as text so every
// caller still gets its own object to mutate.
let _lastGoodBrowserConfigText = null;
let _browserConfigWarnedAt = 0;
// Marks the {} returned for a browser-config.json that exists but was never read
// well (no last good text either): it is not "unconfigured", so session creation
// refuses it (browserConfigUnreadable) instead of starting Chrome where MoreLogin
// may be set up. A missing file still means the defaults.
const BROWSER_CONFIG_UNREADABLE = Symbol('browserConfigUnreadable');

function loadBrowserConfig() {
  try {
    if (!existsSync(BROWSER_CONFIG_PATH)) return {};
    const text = readFileSync(BROWSER_CONFIG_PATH, 'utf-8');
    const config = JSON.parse(text);
    if (!config || typeof config !== 'object' || Array.isArray(config)) throw new Error('not a JSON object');
    _lastGoodBrowserConfigText = text;
    _browserConfigWarnedAt = 0;
    return config;
  } catch (err) {
    // Once per failure streak, then at most once a minute while it lasts.
    if (Date.now() - _browserConfigWarnedAt > 60_000) {
      _browserConfigWarnedAt = Date.now();
      console.warn(`[browser] ${BROWSER_CONFIG_PATH} is unreadable (${err.message}); ${_lastGoodBrowserConfigText ? 'using the last good browser settings' : 'no browser session starts until it is fixed in Settings → Browser'}`);
    }
    if (_lastGoodBrowserConfigText) return JSON.parse(_lastGoodBrowserConfigText);
    const unreadable = {};
    Object.defineProperty(unreadable, BROWSER_CONFIG_UNREADABLE, { value: err.message || String(err) });
    return unreadable;
  }
}

/** Why the browser settings could not be read at all (a config from loadBrowserConfig), else null. */
function browserConfigUnreadable(cfg) {
  return (cfg && cfg[BROWSER_CONFIG_UNREADABLE]) || null;
}

// The default browser as one string (connect mode and MoreLogin env). Every
// /api/browser response carries it (X-Synabun-Browser-Default) and MCP processes
// key their route caches on it, so a change of browser settings drops them.
function browserDefaultSignature(cfg = loadBrowserConfig()) {
  if (browserConfigUnreadable(cfg)) return 'unreadable';
  return cfg.connectMode === 'morelogin' ? `morelogin:${moreLoginDefaultEnvId(cfg) || ''}` : `other:${cfg.connectMode || 'mirror'}`;
}

// Atomic: a reader never sees a half-written file (temp file + rename).
function saveBrowserConfig(config) {
  const dir = dirname(BROWSER_CONFIG_PATH);
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
  const text = JSON.stringify(config, null, 2);
  const tmpPath = `${BROWSER_CONFIG_PATH}.tmp-${process.pid}-${randomBytes(4).toString('hex')}`;
  try {
    writeFileSync(tmpPath, text, 'utf-8');
    renameSync(tmpPath, BROWSER_CONFIG_PATH);
  } catch (err) {
    try { if (existsSync(tmpPath)) unlinkSync(tmpPath); } catch {}
    throw err;
  }
  _lastGoodBrowserConfigText = text;
}

/**
 * Find a usable Chromium/Chrome executable.
 * Priority: user-configured path > common system locations > playwright bundled.
 */
function findBrowserExecutable(preferredChannel) {
  const config = loadBrowserConfig();
  if (config.executablePath && existsSync(config.executablePath)) {
    return config.executablePath;
  }

  const channel = preferredChannel || config.channel || '';
  const prefersEdge = /edge/i.test(channel);

  // Common Chrome/Chromium/Edge locations per platform
  // Order: Edge-first when channel is msedge, Chrome-first otherwise
  const edgeWin = [
    join(process.env.LOCALAPPDATA || '', 'Microsoft', 'Edge', 'Application', 'msedge.exe'),
    join(process.env['ProgramFiles'] || '', 'Microsoft', 'Edge', 'Application', 'msedge.exe'),
    join(process.env['ProgramFiles(x86)'] || '', 'Microsoft', 'Edge', 'Application', 'msedge.exe'),
  ];
  const chromeWin = [
    join(process.env.LOCALAPPDATA || '', 'Google', 'Chrome', 'Application', 'chrome.exe'),
    join(process.env['ProgramFiles'] || '', 'Google', 'Chrome', 'Application', 'chrome.exe'),
    join(process.env['ProgramFiles(x86)'] || '', 'Google', 'Chrome', 'Application', 'chrome.exe'),
    join(process.env.LOCALAPPDATA || '', 'Chromium', 'Application', 'chrome.exe'),
  ];
  const edgeMac = [
    '/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge',
  ];
  const chromeMac = [
    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    join(process.env.HOME || '', 'Applications', 'Google Chrome.app', 'Contents', 'MacOS', 'Google Chrome'),
    '/Applications/Chromium.app/Contents/MacOS/Chromium',
  ];
  const edgeLinux = [
    '/usr/bin/microsoft-edge',
    '/usr/bin/microsoft-edge-stable',
  ];
  const chromeLinux = [
    '/usr/bin/google-chrome',
    '/usr/bin/google-chrome-stable',
    '/usr/bin/chromium',
    '/usr/bin/chromium-browser',
    '/snap/bin/chromium',
  ];

  const candidates = IS_WIN
    ? (prefersEdge ? [...edgeWin, ...chromeWin] : [...chromeWin, ...edgeWin])
    : process.platform === 'darwin'
    ? (prefersEdge ? [...edgeMac, ...chromeMac] : [...chromeMac, ...edgeMac])
    : (prefersEdge ? [...edgeLinux, ...chromeLinux] : [...chromeLinux, ...edgeLinux]);

  for (const p of candidates) {
    if (p && existsSync(p)) return p;
  }

  return null; // Will let playwright-core try its default
}

/**
 * Decrypt cookies from a Chrome/Edge/Chromium profile's Cookies SQLite database.
 * macOS only — Chrome encrypts cookie values with a key stored in the system Keychain.
 * Returns an array of cookies in Playwright's addCookies() format.
 * @param {string} profileDir - Path to the Chrome profile directory (e.g., mirror/Default/)
 * @param {string} browserType - 'chrome' | 'msedge' | 'chromium'
 * @returns {Array} Decrypted cookies in Playwright format, or empty array on failure
 */
function decryptChromeCookies(profileDir, browserType = 'chrome') {
  if (process.platform !== 'darwin') return []; // macOS-only encryption

  const cookiesDbPath = resolve(profileDir, 'Cookies');
  if (!existsSync(cookiesDbPath)) return [];

  // Get encryption password from macOS Keychain
  const serviceNames = { chrome: 'Chrome Safe Storage', msedge: 'Microsoft Edge Safe Storage', chromium: 'Chromium Safe Storage' };
  const accountNames = { chrome: 'Chrome', msedge: 'Microsoft Edge', chromium: 'Chromium' };
  const serviceName = serviceNames[browserType] || serviceNames.chrome;
  const accountName = accountNames[browserType] || accountNames.chrome;

  let keychainPassword;
  try {
    keychainPassword = execSync(
      `security find-generic-password -w -s "${serviceName}" -a "${accountName}"`,
      { encoding: 'utf-8', timeout: 5000 }
    ).trim();
  } catch (e) {
    console.warn(`[browser] Could not read Keychain (${serviceName}): ${e.message}`);
    return [];
  }

  // Derive AES-128-CBC key: PBKDF2-SHA1, salt "saltysalt", 1003 iterations, 16-byte key
  const key = pbkdf2Sync(keychainPassword, 'saltysalt', 1003, 16, 'sha1');
  const iv = Buffer.alloc(16, ' '); // 16 space characters

  // Read cookies from SQLite
  let db;
  try {
    const _require = createRequire(import.meta.url);
    const { DatabaseSync } = _require('node:sqlite');
    db = new DatabaseSync(cookiesDbPath, { readOnly: true });
  } catch (e) {
    console.warn(`[browser] Could not open Cookies DB: ${e.message}`);
    return [];
  }

  const sameSiteMap = { 0: 'None', 1: 'Lax', 2: 'Strict' };
  // Chrome epoch: microseconds since 1601-01-01. Unix epoch offset = 11644473600 seconds.
  const CHROME_EPOCH_OFFSET = 11644473600;
  const cookies = [];

  try {
    const rows = db.prepare(
      'SELECT host_key, name, value, encrypted_value, path, expires_utc, is_secure, is_httponly, samesite FROM cookies'
    ).all();

    for (const row of rows) {
      let cookieValue = row.value || '';

      // Decrypt v10-prefixed encrypted values (macOS Chrome encryption)
      if (row.encrypted_value && row.encrypted_value.length > 3) {
        const encBuf = Buffer.from(row.encrypted_value);
        if (encBuf.length > 3 && encBuf.slice(0, 3).toString('ascii') === 'v10') {
          try {
            const decipher = createDecipheriv('aes-128-cbc', key, iv);
            cookieValue = Buffer.concat([decipher.update(encBuf.slice(3)), decipher.final()]).toString('utf-8');
          } catch {
            continue; // Skip cookies that fail to decrypt
          }
        }
      }

      if (!cookieValue) continue;

      // Convert Chrome expires_utc (microseconds since 1601) to Unix epoch seconds
      const expiresUtc = Number(row.expires_utc || 0);
      const expires = expiresUtc > 0 ? (expiresUtc / 1000000) - CHROME_EPOCH_OFFSET : -1;

      // Skip already-expired cookies
      if (expires > 0 && expires < Date.now() / 1000) continue;

      cookies.push({
        name: row.name,
        value: cookieValue,
        domain: row.host_key,
        path: row.path || '/',
        expires,
        httpOnly: !!row.is_httponly,
        secure: !!row.is_secure,
        sameSite: sameSiteMap[row.samesite] || 'None',
      });
    }
  } catch (e) {
    console.warn(`[browser] Failed to read/decrypt cookies: ${e.message}`);
  } finally {
    try { db.close(); } catch {}
  }

  console.log(`[browser] Decrypted ${cookies.length} cookies from ${browserType} profile`);
  return cookies;
}

/**
 * Detect Chrome/Edge/Chromium profile directories on the system.
 * Scans common User Data locations and reads Preferences files to get
 * human-readable profile names.
 */
function detectChromeProfiles() {
  const home = process.env.HOME || process.env.USERPROFILE || '';
  const localAppData = process.env.LOCALAPPDATA || '';

  // Browser User Data root directories by platform
  const browserRoots = IS_WIN ? [
    { browser: 'Chrome', dir: join(localAppData, 'Google', 'Chrome', 'User Data') },
    { browser: 'Edge', dir: join(localAppData, 'Microsoft', 'Edge', 'User Data') },
    { browser: 'Chromium', dir: join(localAppData, 'Chromium', 'User Data') },
  ] : process.platform === 'darwin' ? [
    { browser: 'Chrome', dir: join(home, 'Library', 'Application Support', 'Google', 'Chrome') },
    { browser: 'Edge', dir: join(home, 'Library', 'Application Support', 'Microsoft Edge') },
    { browser: 'Chromium', dir: join(home, 'Library', 'Application Support', 'Chromium') },
  ] : [
    { browser: 'Chrome', dir: join(home, '.config', 'google-chrome') },
    { browser: 'Chromium', dir: join(home, '.config', 'chromium') },
    { browser: 'Edge', dir: join(home, '.config', 'microsoft-edge') },
  ];

  const profiles = [];

  for (const { browser, dir } of browserRoots) {
    if (!existsSync(dir)) continue;

    // Read Local State for authoritative profile names (Chrome updates names here, not in per-profile Preferences)
    let localStateNames = {};
    try {
      const lsPath = join(dir, 'Local State');
      if (existsSync(lsPath)) {
        const ls = JSON.parse(readFileSync(lsPath, 'utf-8'));
        const cache = ls?.profile?.info_cache || {};
        for (const [folder, info] of Object.entries(cache)) {
          if (info.name) localStateNames[folder] = info.name;
        }
      }
    } catch { /* Local State unavailable */ }

    let entries;
    try { entries = readdirSync(dir, { withFileTypes: true }); } catch { continue; }

    for (const entry of entries) {
      if (!entry.isDirectory()) continue;
      const folderName = entry.name;
      // Match "Default", "Profile 1", "Profile 2", etc.
      if (folderName !== 'Default' && !/^Profile \d+$/.test(folderName)) continue;

      const profileDir = join(dir, folderName);
      const prefsPath = join(profileDir, 'Preferences');
      if (!existsSync(prefsPath)) continue;

      // Prefer Local State name (authoritative after renames), fall back to per-profile Preferences
      let displayName = localStateNames[folderName] || folderName;
      if (!localStateNames[folderName]) {
        try {
          const prefs = JSON.parse(readFileSync(prefsPath, 'utf-8'));
          if (prefs.profile?.name) displayName = prefs.profile.name;
        } catch { /* use folder name */ }
      }

      profiles.push({
        browser,
        name: displayName,
        folder: folderName,
        path: profileDir.replace(/\\/g, '/'),
        isDefault: folderName === 'Default',
      });
    }
  }

  return profiles;
}

function lookupDetectedProfile(profilePath) {
  if (!profilePath) return null;
  const needle = profilePath.replace(/\\/g, '/').toLowerCase().replace(/\/+$/, '');
  return detectChromeProfiles().find(p => (
    p.path.replace(/\\/g, '/').toLowerCase().replace(/\/+$/, '') === needle
  )) || null;
}

function isBrowserProcessRunning(browserType = 'chrome') {
  try {
    if (IS_WIN) {
      const image = browserType === 'msedge' ? 'msedge.exe' : 'chrome.exe';
      const tasklist = execSync(`tasklist /FI "IMAGENAME eq ${image}" /NH`, { encoding: 'utf8', timeout: 3000 });
      return tasklist.toLowerCase().includes(image.toLowerCase());
    }
    if (process.platform === 'darwin') {
      const proc = browserType === 'msedge' ? 'Microsoft Edge' : browserType === 'chromium' ? 'Chromium' : 'Google Chrome';
      const pgrep = execSync(`pgrep -x "${proc}"`, { encoding: 'utf8', timeout: 3000 });
      return pgrep.trim().length > 0;
    }
    const primary = browserType === 'msedge' ? 'microsoft-edge' : browserType === 'chromium' ? 'chromium' : 'chrome';
    const fallback = browserType === 'msedge' ? 'microsoft-edge-stable' : browserType === 'chromium' ? 'chromium-browser' : 'google-chrome';
    const pgrep = execSync(`pgrep -x "${primary}" || pgrep -x "${fallback}"`, { encoding: 'utf8', timeout: 3000 });
    return pgrep.trim().length > 0;
  } catch {
    return false;
  }
}

function getManagedProfileRoot() {
  return resolve(DATA_HOME, 'data', 'chrome-profile');
}

// Dedicated, debug-enabled profile for "Attach to real Chrome" (CDP) mode. ONE
// fixed non-default dir the user adopts as their browser — non-default so Chrome
// 136+ still honors --remote-debugging-port (it ignores it on the default dir).
function getAttachProfileRoot() {
  return resolve(DATA_HOME, 'data', 'chrome-attach');
}

// Safety guard (B2): the CDP debug-launch path (ensureChromeDebuggable) KILLS and
// relaunches Chrome on the dir it's given. It must ONLY ever target the dedicated
// attach root — never a real Chrome profile or the managed dir — or it would close
// the user's daily browser. Throws on anything else.
function assertSafeDebugRoot(dir) {
  const norm = (p) => (p || '').replace(/[\\/]+$/, '').replace(/\\/g, '/').toLowerCase();
  if (norm(dir) !== norm(getAttachProfileRoot())) {
    throw new Error(`Refusing to enable remote debugging on a non-attach directory: ${dir}`);
  }
}

// True iff the saved config would make createBrowserSession use attach (CDP) mode:
// connectMode='attach' AND the selected profile is a real *system* Chrome root
// (attach is inert for clean/managed/custom). Mirrors the _selectedProfileKind
// detection in createBrowserSession so session reuse agrees with session creation.
function isAttachConfigActive(cfg) {
  if ((cfg?.connectMode || 'mirror') !== 'attach') return false;
  let udd = cfg.userDataDir || '';
  if (!udd) return false;
  if (!udd.startsWith('/') && !(/^[A-Z]:/i.test(udd))) udd = resolve(DATA_HOME, udd);
  const normalized = udd.replace(/[\\/]+$/, '').replace(/\\/g, '/').toLowerCase();
  const managedRoot = getManagedProfileRoot().replace(/\\/g, '/').toLowerCase();
  if (normalized === managedRoot || normalized.startsWith(managedRoot + '/')) return false;
  const _home = process.env.HOME || process.env.USERPROFILE || '';
  const roots = IS_WIN ? [
    (process.env.LOCALAPPDATA || '') + '/Google/Chrome/User Data',
    (process.env.LOCALAPPDATA || '') + '/Microsoft/Edge/User Data',
    (process.env.LOCALAPPDATA || '') + '/Chromium/User Data',
    (process.env['ProgramFiles'] || '') + '/Google/Chrome/User Data',
  ] : process.platform === 'darwin' ? [
    _home + '/Library/Application Support/Google/Chrome',
    _home + '/Library/Application Support/Microsoft Edge',
    _home + '/Library/Application Support/Chromium',
  ] : [
    _home + '/.config/google-chrome',
    _home + '/.config/chromium',
    _home + '/.config/microsoft-edge',
  ];
  for (const r of roots) {
    const root = (r || '').replace(/\\/g, '/').toLowerCase();
    if (!root) continue;
    if (normalized === root) return true;
    if (normalized.startsWith(root + '/')) {
      const remainder = normalized.slice(root.length + 1).replace(/\/+$/, '');
      if (/^(default|profile \d+)$/i.test(remainder)) return true;
    }
  }
  return false;
}

// Prepare the dedicated attach profile. Unlike prepareMirroredProfile (a hashed,
// throwaway copy per source), this is ONE persistent dir. When attachSeed==='real'
// it is seeded ONCE from the real profile so the user starts logged in; thereafter
// it owns its own state. 'fresh' starts empty. Copying a live profile corrupts
// Cookies/LevelDB, so seeding refuses while the source browser is running (B3).
function prepareAttachProfile(sourceRoot, profileDirectory, attachSeed, browserType = 'chrome') {
  const attachRoot = getAttachProfileRoot();
  assertSafeDebugRoot(attachRoot);
  const profileDir = profileDirectory || 'Default';
  const destProfileDir = resolve(attachRoot, profileDir);

  mkdirSync(attachRoot, { recursive: true });

  let seeded = existsSync(destProfileDir);
  if (attachSeed === 'real' && !seeded) {
    const sourceProfileDir = resolve(sourceRoot, profileDir);
    if (!existsSync(sourceProfileDir)) {
      throw new Error(`Selected profile directory not found: ${sourceProfileDir}`);
    }
    if (isBrowserProcessRunning(browserType)) {
      throw new Error('Close Chrome once so SynaBun can copy your profile into its attach window. After this one-time copy you can reopen Chrome and keep it open — SynaBun never closes your daily browser again.');
    }
    console.log(`[browser] Seeding attach profile from ${sourceProfileDir} -> ${destProfileDir}`);
    cpSync(sourceProfileDir, destProfileDir, { recursive: true });
    const localStateSrc = resolve(sourceRoot, 'Local State');
    if (existsSync(localStateSrc)) {
      try { copyFileSync(localStateSrc, resolve(attachRoot, 'Local State')); } catch {}
    }
    seeded = true;
  }

  // Always clear singleton/devtools markers so ensureChromeDebuggable relaunches cleanly.
  for (const stale of ['SingletonLock', 'SingletonSocket', 'SingletonCookie', 'DevToolsActivePort']) {
    try { const p = resolve(attachRoot, stale); if (existsSync(p)) unlinkSync(p); } catch {}
    try { const p = resolve(destProfileDir, stale); if (existsSync(p)) unlinkSync(p); } catch {}
  }

  return { attachRoot, profileDirectory: profileDir, seeded };
}

function prepareMirroredProfile(sourceRoot, profileDirectory, browserType = 'chrome') {
  const sourceProfileDir = resolve(sourceRoot, profileDirectory || 'Default');
  if (!existsSync(sourceProfileDir)) {
    throw new Error(`Selected profile directory not found: ${sourceProfileDir}`);
  }

  const mirrorKey = createHash('md5')
    .update(`${browserType}:${sourceRoot}:${profileDirectory || 'Default'}`)
    .digest('hex')
    .slice(0, 12);
  const mirrorRoot = resolve(DATA_HOME, 'data', 'browser-profiles', mirrorKey);
  const mirrorProfileDir = resolve(mirrorRoot, profileDirectory || 'Default');

  mkdirSync(mirrorRoot, { recursive: true });

  // Seed the mirror once from the selected profile; after that the mirror owns its state.
  if (!existsSync(mirrorProfileDir)) {
    console.log(`[browser] Seeding mirrored profile from ${sourceProfileDir} -> ${mirrorProfileDir}`);
    cpSync(sourceProfileDir, mirrorProfileDir, { recursive: true });
  }

  const localStateSrc = resolve(sourceRoot, 'Local State');
  const localStateDest = resolve(mirrorRoot, 'Local State');
  if (existsSync(localStateSrc)) {
    try { copyFileSync(localStateSrc, localStateDest); } catch {}
  }

  for (const stale of ['SingletonLock', 'SingletonSocket', 'SingletonCookie', 'DevToolsActivePort']) {
    try {
      const rootPath = resolve(mirrorRoot, stale);
      if (existsSync(rootPath)) unlinkSync(rootPath);
    } catch {}
    try {
      const profilePath = resolve(mirrorProfileDir, stale);
      if (existsSync(profilePath)) unlinkSync(profilePath);
    } catch {}
  }

  return { mirrorRoot, mirrorProfileDir };
}

// ── Shared system browser: one-time CDP setup ──
// Prefers port 9222 for compatibility, but can self-heal to a dynamic DevTools
// endpoint when 9222 isn't exposed in time.
const CDP_PORT = 9222;
const CDP_LAUNCH_TIMEOUT_MS = 20000;
let _chromeDebuggableReady = false;
let _chromeCdpEndpoint = null; // http://127.0.0.1:<port>
let _chromeDebugCacheKey = null;

function _cdpCacheKey(executablePath, userDataDir, profileDirectory) {
  const ep = (executablePath || '').replace(/\\/g, '/').toLowerCase();
  const udd = (userDataDir || '').replace(/[\\/]+$/, '').replace(/\\/g, '/').toLowerCase();
  const pd = (profileDirectory || '').toLowerCase();
  return `${ep}|${udd}|${pd}`;
}

function _toHttpEndpoint(endpointOrPort) {
  if (typeof endpointOrPort === 'number') return `http://127.0.0.1:${endpointOrPort}`;
  if (!endpointOrPort || typeof endpointOrPort !== 'string') return null;
  if (endpointOrPort.startsWith('http://') || endpointOrPort.startsWith('https://')) {
    return endpointOrPort.replace(/\/+$/, '');
  }
  if (endpointOrPort.startsWith('ws://') || endpointOrPort.startsWith('wss://')) {
    try {
      const u = new URL(endpointOrPort);
      return `http://${u.hostname}:${u.port}`;
    } catch {
      return null;
    }
  }
  return null;
}

async function probeCdpEndpoint(endpointOrPort) {
  const http = await import('node:http');
  const httpEndpoint = _toHttpEndpoint(endpointOrPort);
  if (!httpEndpoint) return { ok: false };

  return await new Promise((resolveP) => {
    const req = http.get(`${httpEndpoint}/json/version`, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (!res.statusCode || res.statusCode < 200 || res.statusCode >= 300) {
          return resolveP({ ok: false });
        }
        try {
          const parsed = JSON.parse(data || '{}');
          resolveP({
            ok: true,
            httpEndpoint,
            wsEndpoint: parsed.webSocketDebuggerUrl || null,
          });
        } catch {
          resolveP({ ok: true, httpEndpoint, wsEndpoint: null });
        }
      });
    });
    req.on('error', () => resolveP({ ok: false }));
    req.setTimeout(2000, () => { req.destroy(); resolveP({ ok: false }); });
  });
}

function _readDevToolsActivePort(userDataDir) {
  if (!userDataDir) return null;
  try {
    const fp = resolve(userDataDir, 'DevToolsActivePort');
    if (!existsSync(fp)) return null;
    const lines = readFileSync(fp, 'utf-8')
      .split(/\r?\n/)
      .map(s => s.trim())
      .filter(Boolean);
    if (lines.length === 0) return null;
    const parsedPort = parseInt(lines[0], 10);
    if (!Number.isFinite(parsedPort) || parsedPort <= 0) return null;
    const httpEndpoint = `http://127.0.0.1:${parsedPort}`;
    let wsEndpoint = null;
    if (lines[1]) {
      wsEndpoint = lines[1].startsWith('ws://') || lines[1].startsWith('wss://')
        ? lines[1]
        : `ws://127.0.0.1:${parsedPort}${lines[1].startsWith('/') ? '' : '/'}${lines[1]}`;
    }
    return { port: parsedPort, httpEndpoint, wsEndpoint };
  } catch {
    return null;
  }
}

function _stderrTail(lines, max = 8) {
  return lines.slice(-max).join(' | ');
}

async function _shutdownChromeForDebugRestart(execSyncCmd, userDataDir = null) {
  // ── Scoped shutdown (B1) ── When a dir is given (always, for attach mode), kill
  // ONLY the Chrome processes — including helpers — whose command line holds that
  // exact --user-data-dir. The user's daily Chrome (a different dir) is never touched.
  if (userDataDir) {
    try {
      const needle = `user-data-dir=${userDataDir}`;
      let pids = [];
      if (IS_WIN) {
        const psScript = `$root = $env:SYNABUN_KILL_ROOT; Get-CimInstance Win32_Process -Filter "Name='chrome.exe' OR Name='msedge.exe' OR Name='chromium.exe'" | Where-Object { $_.CommandLine -like "*user-data-dir=$root*" } | ForEach-Object { $_.ProcessId }`;
        const out = execSyncCmd(`powershell -NoProfile -NonInteractive -Command -`, {
          input: psScript, encoding: 'utf-8', timeout: 10000,
          env: { ...process.env, SYNABUN_KILL_ROOT: userDataDir }, windowsHide: true,
        }).trim();
        pids = out.split(/\s+/).filter(Boolean).map(p => parseInt(p, 10)).filter(p => p > 0 && p !== process.pid);
      } else {
        const out = execSyncCmd(`pgrep -f ${JSON.stringify(needle)} 2>/dev/null || true`, { encoding: 'utf-8' }).trim();
        pids = out.split(/\s+/).filter(Boolean).map(p => parseInt(p, 10)).filter(p => p > 0 && p !== process.pid);
      }
      for (const pid of pids) {
        try {
          if (IS_WIN) execSyncCmd(`taskkill /F /PID ${pid}`, { stdio: 'ignore', timeout: 5000, windowsHide: true });
          else process.kill(pid, 'SIGKILL');
        } catch {}
      }
      if (pids.length) {
        console.log(`[browser] Scoped-killed ${pids.length} Chrome process(es) holding attach dir: ${pids.join(',')}`);
        await new Promise(r => setTimeout(r, 300));
      }
    } catch (err) {
      console.warn(`[browser] Scoped Chrome shutdown failed: ${err.message}`);
    }
    return;
  }
  // ── Legacy global shutdown (null dir) ── retained for any non-attach caller.
  if (process.platform === 'darwin') {
    try { execSyncCmd('osascript -e \'tell application "Google Chrome" to quit\'', { timeout: 3000 }); } catch {}
    const quitStart = Date.now();
    while (Date.now() - quitStart < 8000) {
      try {
        execSyncCmd('pgrep -x "Google Chrome"', { timeout: 1000 });
        await new Promise(r => setTimeout(r, 500));
      } catch { break; }
    }
    for (const procName of ['Google Chrome', 'Google Chrome Helper', 'Google Chrome Helper (GPU)', 'Google Chrome Helper (Renderer)', 'Google Chrome Helper (Plugin)']) {
      try { execSyncCmd(`killall -9 "${procName}"`, { timeout: 3000 }); } catch {}
    }
  } else {
    try { execSyncCmd('pkill -9 -f "google-chrome|chromium|msedge"', { timeout: 3000 }); } catch {}
  }
}

async function _launchChromeAndWaitForCdp({
  chromeBin,
  chromeArgs,
  userDataDir,
  timeoutMs,
  allowPreferredPortProbe,
}) {
  const { spawn: spawnChild } = await import('node:child_process');
  const stderrLines = [];
  let stderrWsEndpoint = null;
  let spawnError = null;

  console.log(`[browser] Spawning: ${chromeBin} ${chromeArgs.join(' ')}`);
  const cp = spawnChild(chromeBin, chromeArgs, { stdio: ['ignore', 'ignore', 'pipe'], detached: true });
  cp.on('error', (err) => { spawnError = err; });
  cp.stderr?.on('data', (chunk) => {
    const text = String(chunk || '');
    for (const line of text.split(/\r?\n/).map(s => s.trim()).filter(Boolean)) {
      stderrLines.push(line);
      if (stderrLines.length > 80) stderrLines.shift();
      const m = line.match(/DevTools listening on (ws:\/\/\S+)/i);
      if (m && m[1]) stderrWsEndpoint = m[1];
    }
  });
  cp.unref();

  const startedAt = Date.now();
  while (Date.now() - startedAt < timeoutMs) {
    if (spawnError) {
      throw new Error(`Chrome spawn failed: ${spawnError.message}`);
    }

    if (stderrWsEndpoint) {
      const probed = await probeCdpEndpoint(stderrWsEndpoint);
      if (probed.ok) return { ...probed, source: 'stderr-devtools-endpoint' };
    }

    const fromFile = _readDevToolsActivePort(userDataDir);
    if (fromFile?.httpEndpoint) {
      const probed = await probeCdpEndpoint(fromFile.httpEndpoint);
      if (probed.ok) return { ...probed, source: 'DevToolsActivePort' };
    }

    if (allowPreferredPortProbe) {
      const preferred = await probeCdpEndpoint(CDP_PORT);
      if (preferred.ok) return { ...preferred, source: `port-${CDP_PORT}` };
    }

    await new Promise(r => setTimeout(r, 250));
  }

  const diag = _stderrTail(stderrLines) || 'no stderr output';
  throw new Error(`Chrome did not expose DevTools within ${Math.round(timeoutMs / 1000)}s (stderr: ${diag})`);
}

async function ensureChromeDebuggable(opts = {}) {
  const savedCfg = loadBrowserConfig();
  const {
    userDataDir: rawUserDataDir = savedCfg.userDataDir || null,
    profileDirectory: requestedProfileDir = null,
    executablePath: requestedExecutablePath = null,
    channel: requestedChannel = savedCfg.channel || null,
    viewport = savedCfg.viewport || {},
  } = opts;

  let userDataDir = rawUserDataDir || null;
  if (userDataDir && !userDataDir.startsWith('/') && !(/^[A-Z]:/i.test(userDataDir))) {
    userDataDir = resolve(DATA_HOME, userDataDir);
  }

  let profileDirectory = requestedProfileDir || null;
  if (!profileDirectory && userDataDir) {
    const parts = userDataDir.replace(/[\\/]+$/, '').replace(/\\/g, '/').split('/');
    const last = parts[parts.length - 1];
    if (/^(default|profile \d+)$/i.test(last)) {
      profileDirectory = last;
      userDataDir = parts.slice(0, -1).join('/');
    }
  }
  if (!profileDirectory) profileDirectory = 'Default';

  // B2: never debug-launch (kill+relaunch) anything but the dedicated attach dir.
  assertSafeDebugRoot(userDataDir);

  const chromeBin = [requestedExecutablePath, savedCfg.executablePath, findBrowserExecutable(requestedChannel)]
    .find(p => p && existsSync(p))
    || (process.platform === 'darwin' ? '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome' : null);
  if (!chromeBin || !existsSync(chromeBin)) {
    throw new Error(`Cannot find Chrome executable. Attempted: ${requestedExecutablePath || savedCfg.executablePath || requestedChannel || 'auto-detect'}`);
  }

  // Dir-scoped re-probe: if a debuggable Chrome is already live on THIS dir (e.g. it
  // survived a Neural Interface restart), adopt it without killing/relaunching.
  {
    const fromFile = _readDevToolsActivePort(userDataDir);
    if (fromFile?.httpEndpoint) {
      const probed = await probeCdpEndpoint(fromFile.httpEndpoint);
      if (probed.ok) {
        _chromeDebuggableReady = true;
        _chromeCdpEndpoint = probed.httpEndpoint;
        _chromeDebugCacheKey = _cdpCacheKey(chromeBin, userDataDir, profileDirectory);
        console.log(`[browser] Re-attached to existing debuggable Chrome at ${probed.httpEndpoint} (DevToolsActivePort)`);
        return { endpoint: probed.httpEndpoint, source: 'devtools-active-port-reprobe' };
      }
    }
  }

  const cacheKey = _cdpCacheKey(chromeBin, userDataDir, profileDirectory);
  if (_chromeDebuggableReady && _chromeCdpEndpoint && _chromeDebugCacheKey === cacheKey) {
    const cached = await probeCdpEndpoint(_chromeCdpEndpoint);
    if (cached.ok) return { endpoint: cached.httpEndpoint, source: 'cache' };
  }

  // Reuse preferred fixed-port endpoint only when profile+binary cache key matches.
  if (_chromeDebugCacheKey === cacheKey) {
    const preferred = await probeCdpEndpoint(CDP_PORT);
    if (preferred.ok) {
      _chromeDebuggableReady = true;
      _chromeCdpEndpoint = preferred.httpEndpoint;
      return { endpoint: preferred.httpEndpoint, source: `existing-port-${CDP_PORT}` };
    }
  }

  console.log(`[browser] Chrome not debuggable for cacheKey=${cacheKey} — restarting with debugging`);
  broadcastSync({ type: 'notification', level: 'info', message: `Restarting Chrome with remote debugging...` });

  const { execSync: execSyncCmd } = await import('node:child_process');
  await _shutdownChromeForDebugRestart(execSyncCmd, userDataDir);
  await new Promise(r => setTimeout(r, 1200));

  if (userDataDir) {
    for (const f of ['SingletonLock', 'DevToolsActivePort']) {
      try { const p = resolve(userDataDir, f); if (existsSync(p)) unlinkSync(p); } catch {}
    }
    const prefsFile = resolve(userDataDir, profileDirectory, 'Preferences');
    if (existsSync(prefsFile)) {
      try {
        const prefs = JSON.parse(readFileSync(prefsFile, 'utf-8'));
        if (prefs.profile) {
          prefs.profile.exit_type = 'Normal';
          prefs.profile.exited_cleanly = true;
          writeFileSync(prefsFile, JSON.stringify(prefs));
        }
      } catch {}
    }
  }

  const vpW = viewport?.width || 1280;
  const vpH = viewport?.height || 800;
  const baseArgs = [
    '--no-first-run',
    '--no-default-browser-check',
    '--disable-popup-blocking',
    `--window-size=${vpW},${vpH}`,
    '--disable-backgrounding-occluded-windows',
    '--disable-renderer-backgrounding',
    '--disable-background-timer-throttling',
    '--restore-last-session',
  ];
  if (userDataDir) baseArgs.push(`--user-data-dir=${userDataDir}`);
  if (profileDirectory) baseArgs.push(`--profile-directory=${profileDirectory}`);

  let ready;
  try {
    ready = await _launchChromeAndWaitForCdp({
      chromeBin,
      chromeArgs: [...baseArgs, `--remote-debugging-port=${CDP_PORT}`],
      userDataDir,
      timeoutMs: CDP_LAUNCH_TIMEOUT_MS,
      allowPreferredPortProbe: true,
    });
  } catch (primaryErr) {
    console.warn(`[browser] Fixed port ${CDP_PORT} debug launch failed, retrying with dynamic port: ${primaryErr.message}`);
    await _shutdownChromeForDebugRestart(execSyncCmd, userDataDir);
    await new Promise(r => setTimeout(r, 1000));

    if (userDataDir) {
      try {
        const devtoolsPortFile = resolve(userDataDir, 'DevToolsActivePort');
        if (existsSync(devtoolsPortFile)) unlinkSync(devtoolsPortFile);
      } catch {}
    }

    try {
      ready = await _launchChromeAndWaitForCdp({
        chromeBin,
        chromeArgs: [...baseArgs, '--remote-debugging-port=0'],
        userDataDir,
        timeoutMs: CDP_LAUNCH_TIMEOUT_MS,
        allowPreferredPortProbe: false,
      });
    } catch (fallbackErr) {
      throw new Error(`Primary debug launch failed (${primaryErr.message}); dynamic-port retry failed (${fallbackErr.message})`);
    }
  }

  _chromeDebuggableReady = true;
  _chromeCdpEndpoint = ready.httpEndpoint;
  _chromeDebugCacheKey = cacheKey;
  const cdpPort = (() => {
    try { return new URL(ready.httpEndpoint).port || 'unknown'; } catch { return 'unknown'; }
  })();
  console.log(`[browser] Chrome debuggable at ${ready.httpEndpoint} (source=${ready.source})`);
  broadcastSync({ type: 'notification', level: 'info', message: `Chrome ready with debugging on port ${cdpPort}` });
  return { endpoint: ready.httpEndpoint, source: ready.source };
}

// ── Money-safety guard (SynaBun posts ORGANICALLY only — never spend) ──────────
// SynaBun's Facebook automation is organic-only: native Page posts, group seeds,
// comment replies. The generic browser tools (navigate/click/fill/type/evaluate)
// are otherwise unrestricted, and Facebook renders a "Turbinar publicação" / "Boost
// post" button beside every Page post (PT-BR for this account) plus a post-publish
// boost upsell — one stray click can start a PAID campaign. These guards block the
// ad/boost/payment surfaces at the navigation, element, and network layers so no
// charge can ever originate from the automation. Defense-in-depth: any one layer
// catches the others' misses.

// URLs the agent must never navigate to (ad creation/management + billing). Does NOT
// match /professional_dashboard/ (the legit, read-only Page Insights surface).
const MONEY_URL_RE = /(?:^|\.)business\.facebook\.com|(?:^|\.)adsmanager\.facebook\.com|facebook\.com\/(?:ads\/(?:create|manage|manager|campaign|audience)|adsmanager|ads_manager|ad_center|payments|billing)|secure\.facebook\.com\/payments|\/payments\/(?:dialog|edit|orders)/i;

// Network requests to abort outright (hard money-stop): ad-account graph nodes and
// the boost/billing hosts. Deliberately EXCLUDES facebook.com/api/graphql/* used by
// ordinary posting — only the ad-account (act_<id>) node and ads/billing surfaces
// match, so organic posting is unaffected while any boost/charge request is killed.
const MONEY_NET_RE = /(?:business\.facebook\.com|adsmanager\.facebook\.com)|facebook\.com\/(?:ads\/(?:create|manage|manager|campaign|audience)|adsmanager|ads_manager|ad_center|payments|billing)|secure\.facebook\.com\/(?:payments|ads)|graph\.facebook\.com\/v?[0-9.]*\/?act_\d+/i;

// Visible button/link/field labels that mean "spend money". Tested against the SINGLE
// element the agent is about to act on (not page content), so it is safe to be
// aggressive. Multi-locale: this account's UI is PT-BR ("Turbinar"/"Impulsionar").
const MONEY_TEXT_RE = /\b(?:boost(?:\s+post)?|turbinar|impulsionar|promote(?:\s+post)?|promover|promocionar|promouvoir|bewerben|advertise|anuncie|criar an[úu]ncio|create ad|ads?\s+manager|gerenciador de an[úu]ncios|or[çc]amento(?:\s+di[áa]rio)?|daily budget|set\s+(?:a\s+)?budget|definir or[çc]amento|add\s+payment|payment method|forma de pagamento|m[ée]todo de pagamento|confirm(?:ar)?\s+(?:and pay|payment|pagamento)|spend limit)\b/i;

const MONEY_GUARD_MSG = 'SynaBun posts ORGANICALLY only and must never spend money. Do NOT retry — skip this and continue with the next organic action.';

// The guard is ON for every session by default, so SynaBun's autonomous organic loops
// (Page posts, group seeds, comment replies) can never wander into a Boost/pay control.
// A session opened for DELIBERATE ads work can opt out via
// POST /api/browser/sessions/:id/paid-surfaces {allow:true}. The exemption is per
// session and dies with it — there is no global kill switch, so one ads session can
// never silently disarm the loops running beside it.
function moneyGuardActive(session) {
  return !session?.allowPaidAdsSurfaces;
}

// Read the label of a resolved Playwright locator; return the offending phrase if it
// is a money/boost/payment control, else null. Failures fall through (the network
// guard is the backstop) rather than blocking legitimate actions.
async function moneyGuardLabel(target, session) {
  if (!moneyGuardActive(session)) return null;
  try {
    const label = await target.evaluate(el => {
      const get = (a) => (el.getAttribute && el.getAttribute(a)) || '';
      return [el.innerText || el.textContent || '', get('aria-label'), el.value || '', get('placeholder'), get('title')]
        .filter(Boolean).join(' ').replace(/\s+/g, ' ').trim().slice(0, 300);
    });
    if (label && MONEY_TEXT_RE.test(label)) return label.slice(0, 60);
  } catch { /* detached/cross-origin — network guard still covers it */ }
  return null;
}

// ── Safe auto-heal: permission, not intent ──
// One retry click on a plain navigation link, and only while a recorded
// browser-target benchmark vouches for the configuration that is running.
// `browserAssist.autoHealEnabled` is what the operator wants; this is whether
// it may happen right now, read fresh because a settings change or a new bench
// from another process must take effect on the very next click. Any failure
// reads as "no". TypeSafe is never called from here: this only reads config.
function browserAutoHealAllowed() {
  try {
    if (!typesafeEnabled()) return false;
    invalidateTypeSafeConfig();
    return autoHealGate(typesafeConfig()).mode === 'auto-heal';
  } catch { return false; }
}

// The money guard's view of a heal target, from the facts the collector read:
// a session that lifted the guard can never heal, and neither can anything the
// guard's own vocabulary or URL list would block. Returns a static code or null.
function autoHealServerVeto(session, facts) {
  if (!moneyGuardActive(session)) return 'paid_surfaces_session';
  if (facts?.hrefRaw && MONEY_URL_RE.test(facts.hrefRaw)) return 'money_url';
  if (MONEY_TEXT_RE.test(Object.values(facts?.names || {}).join(' '))) return 'money_label';
  return null;
}

// Abort every ad/boost/billing request in a context so no charge can land even if a
// click or evaluate() slips a boost through. Native Fetch patterns keep unrelated
// public requests and HTTP cache untouched; Playwright route matchers do not.
async function installMoneyGuardRoute(ctx) {
  if (!ctx || ctx.__moneyGuardInstalled) return;
  await setBrowserNetworkRule(ctx, 'money', {
    patterns: MONEY_PATTERNS,
    decide: request => MONEY_NET_RE.test(request.url) ? { abort: true } : null,
  });
  ctx.__moneyGuardInstalled = true;
}

// ── SynaBun's own OpenCode serves: never opened by the automation browser ──
// A serve's API changes a session's rules and moves it to another folder, and a page that knew a serve's password could
// use it (OpenCode 2 accepts any http://localhost:* and http://127.0.0.1:* origin), outside every sandbox a worker's
// shell is in. HTTP to live serve ports (any host, including redirect hops) is
// still aborted. Managed contexts also block WS through Playwright. MoreLogin
// retains native WS only behind the verified server authentication boundary and
// credentials confined to this server, never an environment, page or log.
function protectNativeServeContext(ctx) {
  return nativeServeBoundary.protect(ctx, {
    ports: liveOpencodeServePorts(),
    unverifiedRecords: opencodeServeRecords.list().filter(record =>
      !opencodeServeRecords.ownedHere(record) && opencodeServeRecords.verifySync(record) !== 'gone'),
  });
}

async function installServePortGuard(ctx) {
  if (!ctx || ctx.__servePortGuardInstalled) return;
  // routeWebSocket installs page bindings and replaces WebSocket on navigation,
  // even with an empty matcher. Native contexts rely on the verified server's
  // authentication; never silently route or drop protection for unknown serves.
  const native = usesNativeBrowserNetworkGuard(ctx);
  const release = native ? protectNativeServeContext(ctx) : null;
  const refused = (url) => { try { return !!browserServePortDenial(url?.href ?? url, liveOpencodeServePorts()); } catch { return false; } };
  try {
    await setBrowserNetworkRule(ctx, 'serve-port', {
      patterns: SERVE_PORT_PATTERNS,
      decide: request => refused(request.url) ? { abort: true } : null,
    });
    if (!native) {
      if (typeof ctx.routeWebSocket !== 'function') throw new Error('WebSocket routing is unavailable');
      await ctx.routeWebSocket(refused, ws => Promise.resolve(ws.close({ code: 1008, reason: 'SynaBun: not an address the browser opens' })).catch(() => {}));
    }
    ctx.__servePortGuardInstalled = true;
  } catch (error) {
    release?.();
    throw new Error(`Failed to install the OpenCode serve guard: ${error.message}`);
  }
}

// ── MoreLogin blocks ───────────────────────────────────────────────────────────
// MoreLogin redirects a navigation it refuses to its stop page, which otherwise
// looks like a normal page load. Two settings cause it:
//   • a profile's Port scan protection: a local port (localhost, 127.0.0.1) loads
//     only when it is listed under Edit profile → Advanced settings → Port scan
//     protection (allowed ports, read when the profile starts). Every other local
//     port lands on black_whiteList_stop_page_v2.html?blockedUrl=<url>.
//   • an account-level website blacklist/whitelist, enforced by the bundled
//     SBBackground extension (chrome.webRequest.onBeforeRequest, main and sub frames).
// Localhost pages open in MoreLogin like any other page; the block is reported,
// never worked around.
const LOOPBACK_HOSTS = new Set(['localhost', '127.0.0.1', '::1', '[::1]', '0.0.0.0']);
function isLoopbackUrl(url) {
  if (typeof url !== 'string' || !url) return false;
  try {
    const host = new URL(url).hostname.replace(/^\[|\]$/g, '').toLowerCase();
    return LOOPBACK_HOSTS.has(host) || host.endsWith('.localhost') || /^127\./.test(host);
  } catch { return false; }
}

// The page MoreLogin redirects a blocked navigation to: the remote stop page (v1
// for the website policy, _v2 for port scan protection) and the extension's local
// gate page.
const MORELOGIN_BLOCK_RE = /^https?:\/\/getip\.morelogin\.com\/black_whiteList_stop_page(?:_v\d+)?\.html|^chrome-extension:\/\/[a-p]+\/url-blocking\.html/i;

// Observed-block telemetry. MoreLogin's local API does not expose the website-limit
// config, so the UI reports what we actually saw rather than what is configured.
const moreLoginBlockStats = { count: 0, lastUrl: null, lastAt: null };

// The URL the stop page names (?blockedUrl=…), else the one the caller asked for.
function moreLoginBlockedUrl(requestedUrl, landedUrl) {
  try {
    const named = new URL(landedUrl).searchParams.get('blockedUrl');
    if (named && /^https?:$/.test(new URL(named).protocol)) return named;
  } catch {}
  return requestedUrl;
}

// Returns an actionable message when `landedUrl` is MoreLogin's stop page and the
// caller did not ask for it — i.e. MoreLogin silently swallowed the navigation.
// Returns null when nothing was blocked.
function moreLoginBlockError(session, requestedUrl, landedUrl) {
  if (session?._profileMode !== 'morelogin') return null;
  if (!MORELOGIN_BLOCK_RE.test(landedUrl || '')) return null;
  if (MORELOGIN_BLOCK_RE.test(requestedUrl || '')) return null;
  const blockedUrl = moreLoginBlockedUrl(requestedUrl, landedUrl);
  moreLoginBlockStats.count += 1;
  moreLoginBlockStats.lastUrl = blockedUrl;
  moreLoginBlockStats.lastAt = new Date().toISOString();
  console.warn(`[morelogin] blocked ${blockedUrl} → ${landedUrl}`);
  if (isLoopbackUrl(blockedUrl)) {
    const { port, protocol } = new URL(blockedUrl);
    const shown = port || (protocol === 'https:' ? '443' : '80');
    return `MoreLogin blocked localhost:${shown}. Most likely the profile's Port scan protection: add ${shown} to its Advanced settings → Port scan protection allowed ports in MoreLogin. `
      + `If a URL Access Restriction in MoreLogin's Security Center blocks localhost, remove localhost from that block policy. Then restart the profile.`;
  }
  return `MoreLogin blocked this navigation to ${blockedUrl}. Its website blacklist/whitelist `
    + `(MoreLogin → Settings → security/permissions, or your team super-admin's policy) does not allow `
    + `that host, so the tab was redirected to MoreLogin's stop page. Add the host to the whitelist, or `
    + `disable the website limit for env ${session._mlEnvId}.`;
}

/**
 * Launch a browser session. Returns sessionId + CDP WebSocket URL.
 * Merges saved browser-config.json with per-session overrides, clones
 * the real browser's fingerprint from Neural Interface request headers.
 */
async function createBrowserSession(options = {}) {
  const sessionId = randomBytes(16).toString('hex');
  const savedCfg = loadBrowserConfig();
  // Settings that exist but cannot be read are not "no settings": never fall back to Chrome.
  const unreadableCfg = browserConfigUnreadable(savedCfg);
  if (unreadableCfg) throw new Error(`browser-config.json is unreadable; fix it in Settings → Browser (${unreadableCfg})`);
  // Resolve browser selector → channel (when no explicit channel is set)
  if (!savedCfg.channel && savedCfg.browser && savedCfg.browser !== 'auto' && savedCfg.browser !== 'custom') {
    savedCfg.channel = savedCfg.browser; // chrome, msedge, chromium
  }
  const execPath = findBrowserExecutable(savedCfg.channel);

  // Merge: saved config is base, per-session options override
  const vpW = options.width || savedCfg.viewport?.width || 1280;
  const vpH = options.height || savedCfg.viewport?.height || 800;

  // Always headed — headless mode is forbidden
  const headlessVal = false;

  // ── Stealth args: strip all headless indicators ──
  const stealthArgs = [
    '--no-first-run',
    '--no-default-browser-check',
    '--disable-popup-blocking',
    `--window-size=${vpW},${vpH}`,
    '--disable-blink-features=AutomationControlled',
    '--disable-features=AutomationControlled',
    '--disable-infobars',
    '--disable-dev-shm-usage',
    '--enable-webgl',
    '--disable-session-crashed-bubble',
    '--hide-crash-restore-bubble',
    // Prevent Chrome from throttling rendering when the window loses OS focus.
    // Without these, CDP screencast freezes when the browser isn't the foreground app.
    '--disable-backgrounding-occluded-windows',
    '--disable-renderer-backgrounding',
    '--disable-background-timer-throttling',
  ];

  // Note: --use-gl=swiftshader removed — Playwright's new headless mode handles GPU
  // internally, and SwiftShader crashes with real Chrome profile data (incompatible
  // GPU caches). Let Playwright/Chromium pick the appropriate GL backend.

  // Platform-specific flags
  if (IS_WIN) {
    // Windows: sandbox can cause issues in some environments, GPU sandbox prevents GPU crashes
    stealthArgs.push('--no-sandbox', '--disable-gpu-sandbox');
  } else if (process.platform === 'linux') {
    // Linux: sandbox requires unprivileged user namespaces (not always available)
    stealthArgs.push('--no-sandbox');
  }
  // macOS: no --no-sandbox needed (sandbox works natively)

  // ── Resolve userDataDir ──
  // If the user selected a Chrome profile subfolder (e.g., Chrome/Profile 1), extract the
  // profile name and use the parent Chrome User Data root as userDataDir. Playwright's
  // launchPersistentContext needs --user-data-dir (the root), plus --profile-directory for
  // the specific profile. Without this split, Chrome creates a NEW Default profile inside
  // the subfolder instead of using the actual selected profile.
  let userDataDir = savedCfg.userDataDir || null;
  // Resolve relative paths to absolute against DATA_HOME (e.g. "data/chrome-profile" → full path)
  if (userDataDir && !userDataDir.startsWith('/') && !(/^[A-Z]:/i.test(userDataDir))) {
    userDataDir = resolve(DATA_HOME, userDataDir);
  }
  let _profileDirectory = null; // Chrome --profile-directory flag
  let _sourceProfilePath = null; // Original selected profile dir (for labels + cookie bootstrap)
  let _sourceBrowser = null; // 'chrome' | 'msedge' | 'chromium' — which browser owns this profile
  let _selectedProfileKind = userDataDir ? 'custom' : 'clean'; // clean | managed | system | custom

  if (userDataDir) {
    const normalized = userDataDir.replace(/[\\/]+$/, '').replace(/\\/g, '/').toLowerCase();
    const managedRoot = getManagedProfileRoot().replace(/\\/g, '/').toLowerCase();

    // Known Chrome/Edge/Chromium User Data root directories per platform
    const _home = process.env.HOME || process.env.USERPROFILE || '';
    const chromeRootDefs = IS_WIN ? [
      { root: ((process.env.LOCALAPPDATA || '') + '/Google/Chrome/User Data').replace(/\\/g, '/').toLowerCase(), browser: 'chrome' },
      { root: ((process.env.LOCALAPPDATA || '') + '/Microsoft/Edge/User Data').replace(/\\/g, '/').toLowerCase(), browser: 'msedge' },
      { root: ((process.env.LOCALAPPDATA || '') + '/Chromium/User Data').replace(/\\/g, '/').toLowerCase(), browser: 'chromium' },
      { root: ((process.env['ProgramFiles'] || '') + '/Google/Chrome/User Data').replace(/\\/g, '/').toLowerCase(), browser: 'chrome' },
    ] : process.platform === 'darwin' ? [
      { root: (_home + '/Library/Application Support/Google/Chrome').toLowerCase(), browser: 'chrome' },
      { root: (_home + '/Library/Application Support/Microsoft Edge').toLowerCase(), browser: 'msedge' },
      { root: (_home + '/Library/Application Support/Chromium').toLowerCase(), browser: 'chromium' },
    ] : [
      { root: (_home + '/.config/google-chrome').toLowerCase(), browser: 'chrome' },
      { root: (_home + '/.config/chromium').toLowerCase(), browser: 'chromium' },
      { root: (_home + '/.config/microsoft-edge').toLowerCase(), browser: 'msedge' },
    ];

    if (normalized === managedRoot || normalized.startsWith(managedRoot + '/')) {
      _selectedProfileKind = 'managed';
    }

    for (const { root, browser: rootBrowser } of chromeRootDefs.filter(d => d.root)) {
      if (normalized === root) {
        _selectedProfileKind = 'system';
        _sourceBrowser = rootBrowser;
        break;
      }
      if (normalized.startsWith(root + '/')) {
        const remainder = normalized.slice(root.length + 1).replace(/\/+$/, '');
        if (/^(default|profile \d+)$/i.test(remainder)) {
          _sourceProfilePath = userDataDir;
          const parts = userDataDir.replace(/\\/g, '/').replace(/\/+$/, '').split('/');
          _profileDirectory = parts.pop(); // "Profile 1", "Default", etc.
          userDataDir = parts.join('/');
          _selectedProfileKind = root === managedRoot ? 'managed' : 'system';
          _sourceBrowser = rootBrowser;
          console.log(`[browser] Detected ${rootBrowser} profile: --profile-directory=${_profileDirectory}`);
          console.log(`[browser] Using ${rootBrowser} User Data dir: ${userDataDir}`);
          break;
        }
      }
    }

    if (!_profileDirectory) {
      const parts = userDataDir.replace(/[\\/]+$/, '').replace(/\\/g, '/').split('/');
      const last = parts[parts.length - 1];
      if (/^(default|profile \d+)$/i.test(last)) {
        _profileDirectory = last;
        _sourceProfilePath = userDataDir;
        userDataDir = parts.slice(0, -1).join('/');
      }
    }

    if (!_sourceProfilePath && userDataDir) {
      _sourceProfilePath = resolve(userDataDir, _profileDirectory || 'Default');
    }
  }

  // Only disable extensions when NOT using a user profile (they'd want their extensions)
  if (!userDataDir) {
    stealthArgs.push('--disable-extensions');
  }

  // NOTE: --profile-directory is appended per launch target so direct and mirror modes can differ.

  // Append user's extra launch args from config
  if (savedCfg.extraArgs) {
    const extra = savedCfg.extraArgs.split(/\s+/).filter(Boolean);
    stealthArgs.push(...extra);
  }
  const launchOpts = { headless: headlessVal, args: stealthArgs, timeout: 45000 };
  // Priority: user-configured executablePath > channel > auto-detected executablePath.
  // User explicitly set executablePath = intentional override, always respect it.
  // Channel = let Playwright resolve the binary for that browser brand.
  // Auto-detected = fallback when nothing else is configured.
  const hasUserExecPath = savedCfg.executablePath && existsSync(savedCfg.executablePath);
  if (hasUserExecPath) {
    launchOpts.executablePath = savedCfg.executablePath;
  } else if (savedCfg.channel) {
    launchOpts.channel = savedCfg.channel;
  } else if (execPath) {
    launchOpts.executablePath = execPath;
  }
  if (savedCfg.slowMo) launchOpts.slowMo = savedCfg.slowMo;
  if (savedCfg.timeout) launchOpts.timeout = savedCfg.timeout;

  // Proxy at browser level
  if (savedCfg.proxy?.server) {
    launchOpts.proxy = {
      server: savedCfg.proxy.server,
      ...(savedCfg.proxy.bypass ? { bypass: savedCfg.proxy.bypass } : {}),
      ...(savedCfg.proxy.username ? { username: savedCfg.proxy.username } : {}),
      ...(savedCfg.proxy.password ? { password: savedCfg.proxy.password } : {}),
    };
  }

  // ── Browser fingerprint ──
  // Don't clone the UI browser's user-agent or sec-ch-ua into the automated browser.
  // When the Neural Interface is opened in Safari or a different Chrome version, cloning
  // creates a fingerprint mismatch (e.g., Chrome sending Safari's UA) that triggers bot
  // detection on sites like Twitter. Let the automated Chrome use its own default UA.
  const realHeaders = options._realHeaders || {};
  const userAgent = savedCfg.userAgent || undefined; // only override if explicitly configured
  const { locale, acceptLanguage, languages, warnings: languageWarnings } =
    resolveBrowserLanguage(savedCfg, realHeaders['accept-language']);
  for (const warning of languageWarnings) {
    console.warn(`[browser] Invalid ${warning.field}; using ${JSON.stringify(warning.value)}`);
  }

  // Build context options from saved config
  const contextOpts = {
    // Headed mode: viewport null lets the page render at the actual window size,
    // exactly like a real browser. --window-size controls initial dimensions.
    // Forcing a fixed viewport causes layout bugs on complex SPAs (Twitter, etc.)
    // because the page CSS is constrained to an emulated box, not the real window.
    viewport: null,
    ...(userAgent ? { userAgent } : {}), // omit entirely to let Chrome use its own default
    locale,
    timezoneId: savedCfg.timezoneId || options.timezone || undefined,
    screen: savedCfg.screen || { width: options.screenWidth || 1920, height: options.screenHeight || 1080 },
    // Don't force deviceScaleFactor — let Chrome use its native DPR (2x on Retina).
    // Forcing DPR 1 on a Retina display causes rendering differences vs real Chrome.
    isMobile: savedCfg.isMobile || false,
    hasTouch: savedCfg.hasTouch || false,
    javaScriptEnabled: savedCfg.javaScriptEnabled !== false,
    ignoreHTTPSErrors: savedCfg.ignoreHTTPSErrors || false,
    bypassCSP: savedCfg.bypassCSP || false,
    acceptDownloads: savedCfg.acceptDownloads !== false,
    strictSelectors: savedCfg.strictSelectors !== false,
    serviceWorkers: savedCfg.serviceWorkers || 'allow',
    offline: savedCfg.offline || false,
    // Extra HTTP headers: Accept-Language from config/UI + any user-configured extras
    // sec-ch-ua headers are NOT cloned — let Chrome generate its own consistent set
    extraHTTPHeaders: {
      'Accept-Language': acceptLanguage,
      ...(savedCfg.extraHTTPHeaders || {}),
    },
  };

  // Appearance
  if (savedCfg.colorScheme) contextOpts.colorScheme = savedCfg.colorScheme;
  if (savedCfg.reducedMotion) contextOpts.reducedMotion = savedCfg.reducedMotion;
  if (savedCfg.forcedColors) contextOpts.forcedColors = savedCfg.forcedColors;

  // Geolocation
  if (savedCfg.geolocation) contextOpts.geolocation = savedCfg.geolocation;

  // Permissions
  if (savedCfg.permissions?.length) contextOpts.permissions = savedCfg.permissions;

  // HTTP credentials
  if (savedCfg.httpCredentials?.username) contextOpts.httpCredentials = savedCfg.httpCredentials;

  // Navigation timeout
  if (savedCfg.navigationTimeout) contextOpts.navigationTimeout = savedCfg.navigationTimeout;

  // Recording: video
  if (savedCfg.recordVideo?.dir) contextOpts.recordVideo = savedCfg.recordVideo;

  // Recording: HAR
  if (savedCfg.recordHar?.path) contextOpts.recordHar = savedCfg.recordHar;

  // Storage state: per-profile scoping to prevent cookie cross-contamination between profiles
  const _baseStorageName = savedCfg.storageStatePath || 'data/browser-storage.json';
  const _profileKey = _sourceProfilePath || savedCfg.userDataDir || null;
  const STORAGE_STATE_PATH = _profileKey
    ? resolve(DATA_HOME, _baseStorageName.replace('.json', `-${createHash('md5').update(_profileKey).digest('hex').slice(0, 12)}.json`))
    : resolve(DATA_HOME, _baseStorageName);
  if (!userDataDir && savedCfg.persistStorage !== false && !savedCfg.clearStorageOnStart && existsSync(STORAGE_STATE_PATH)) {
    try {
      contextOpts.storageState = STORAGE_STATE_PATH;
    } catch (e) {
      console.warn('Failed to load storage state:', e.message);
    }
  }

  let browser, context, page;
  let _isPersistent = false;
  let _chromeProcess = null; // CDP mode: ref to spawned Chrome process
  let _profileMode = userDataDir ? (_selectedProfileKind === 'managed' ? 'managed' : 'direct') : 'clean';
  const _detectedSource = lookupDetectedProfile(_sourceProfilePath);
  let _profileSourceName = _selectedProfileKind === 'managed'
    ? 'SynaBun Profile'
    : (_detectedSource?.name || _profileDirectory || (userDataDir ? 'Default' : null));
  let _launchUserDataDir = userDataDir || null;
  let _launchProfileDirectory = _profileDirectory || (userDataDir ? 'Default' : null);

  // ── MoreLogin connect mode ──
  // When configured (Settings → Browser → MoreLogin, or an explicit per-session
  // moreloginEnvId), launch/attach a MoreLogin anti-detect profile and drive it
  // over CDP. MoreLogin's /api/env/start returns a debugPort — the exact same CDP
  // path as "attach" mode, so we reuse connectOverCDP + probeCdpEndpoint here.
  // STRICT: while MoreLogin is the configured backend, a failed connect FAILS the
  // session — never silently falls back to a plain Chrome profile. Identity-bound
  // automations (anti-detect accounts) must not leak into the default browser.
  let _mlEnvId = null;
  let _mlDebugPort = null;
  let _moreLoginConnected = false;
  // Localhost opens in MoreLogin like any other URL. A port missing from the
  // profile's Port scan protection list lands on the stop page, which the start
  // navigation below reports (moreLoginBlockError).
  const _wantMoreLogin = options.connectMode === 'morelogin'
    || !!options.moreloginEnvId
    || savedCfg.connectMode === 'morelogin';
  if (_wantMoreLogin) {
    try {
      if (!moreLogin.isMoreLoginInstalled().installed) {
        throw new Error('MoreLogin desktop app is not installed');
      }
      // Installed but possibly not running (e.g. an autonomous schedule fires with
      // nobody at the machine to open it) — auto-launch and wait for its local API
      // before giving up, the same self-healing pattern ensureChromeDebuggable()
      // already uses to relaunch system Chrome for CDP "attach" mode. 120s window:
      // MoreLogin is a heavy multi-process Electron app whose API port can accept
      // connections well before it actually serves (observed cold-boot timeouts
      // past the old 25s default).
      const running = await moreLogin.ensureMoreLoginRunning({ savedCfg, timeoutMs: 120000 });
      if (!running.running) {
        throw new Error(`MoreLogin app is not reachable (${running.launchError || running.error || 'unknown error'})`);
      }
      const mlOpts = { savedCfg };
      let envId = options.moreloginEnvId
        || savedCfg.moreloginEnvId
        || (savedCfg.morelogin && savedCfg.morelogin.defaultEnvId)
        || null;
      if (!envId) {
        const def = await moreLogin.ensureDefaultProfile(mlOpts);
        envId = def.id;
      }
      const { debugPort } = await moreLogin.startProfile(envId, mlOpts);
      // Wait for MoreLogin's Chromium DevTools endpoint to come up.
      let endpoint = null;
      for (let i = 0; i < 40; i++) {
        const probed = await probeCdpEndpoint(debugPort);
        if (probed.ok) { endpoint = probed.httpEndpoint; break; }
        await new Promise(r => setTimeout(r, 250));
      }
      if (!endpoint) endpoint = `http://127.0.0.1:${debugPort}`;

      const { browser: cdpBrowser, context: cdpContext, page: cdpPage } = await moreLogin.attachProfileBrowser(
        chromium, endpoint,
        (cdpBrowser, cdpContext) => newSessionPage({ browser: cdpBrowser, context: cdpContext, _profileMode: 'morelogin' }),
      ); // fresh tab in the real profile; never substitute an incognito context

      browser = cdpBrowser;
      context = cdpContext;
      page = cdpPage;
      _isPersistent = false;          // CDP-attached, not a Playwright-owned context
      _profileMode = 'morelogin';
      _chromeProcess = null;          // teardown disconnects; MoreLogin owns the Chromium
      _mlEnvId = String(envId);
      _mlDebugPort = debugPort;
      _profileSourceName = `MoreLogin · ${envId}`;
      _moreLoginConnected = true;
      console.log(`[browser] Connected to MoreLogin env ${envId} via CDP at ${endpoint}`);
    } catch (err) {
      const port = moreLogin.getMoreLoginPort(savedCfg);
      throw new Error(`MoreLogin connect failed: ${err.message}. Open the MoreLogin app (or check its Local API on :${port}) — sessions will not fall back to Chrome while MoreLogin is the default browser.`);
    }
  }

  if (_moreLoginConnected) {
    // browser/context/page already established via MoreLogin CDP above.
  } else if (userDataDir) {
    // ── Persistent context: uses a Chrome profile directory ──
    // launchPersistentContext returns a BrowserContext directly — no separate browser.newContext()
    _isPersistent = true;

    const _browserLabel = _sourceBrowser === 'msedge' ? 'Edge' : _sourceBrowser === 'chromium' ? 'Chromium' : 'Chrome';
    const launchPersistentProfile = async (launchRoot, launchProfileDir, launchMode) => {
      const launchArgs = [...stealthArgs];

      // Kill orphan Chrome processes holding this user-data-dir BEFORE removing locks.
      // Otherwise launchPersistentContext hangs indefinitely waiting for the singleton.
      try {
        const { execSync } = await import('node:child_process');
        let pids = [];
        if (IS_WIN) {
          // Windows: PowerShell Get-CimInstance filters by CommandLine substring.
          // Pass launchRoot via env var to avoid quoting hell.
          const psScript = `$root = $env:SYNABUN_KILL_ROOT; Get-CimInstance Win32_Process -Filter "Name='chrome.exe' OR Name='msedge.exe' OR Name='chromium.exe'" | Where-Object { $_.CommandLine -like "*user-data-dir=$root*" } | ForEach-Object { $_.ProcessId }`;
          const out = execSync(`powershell -NoProfile -NonInteractive -Command -`, {
            input: psScript,
            encoding: 'utf-8',
            timeout: 10000,
            env: { ...process.env, SYNABUN_KILL_ROOT: launchRoot },
            windowsHide: true,
          }).trim();
          pids = out.split(/\s+/).filter(Boolean).map(p => parseInt(p, 10)).filter(p => p > 0 && p !== process.pid);
        } else {
          const needle = `user-data-dir=${launchRoot}`;
          const out = execSync(`pgrep -f ${JSON.stringify(needle)} 2>/dev/null || true`, { encoding: 'utf-8' }).trim();
          pids = out.split(/\s+/).filter(Boolean).map(p => parseInt(p, 10)).filter(p => p > 0 && p !== process.pid);
        }
        if (pids.length) {
          console.log(`[browser] Killing ${pids.length} orphan Chrome process(es) holding ${launchMode} root: ${pids.join(',')}`);
          for (const pid of pids) {
            try {
              if (IS_WIN) {
                // process.kill on Windows only does SIGTERM-like; taskkill /F is reliable.
                execSync(`taskkill /F /PID ${pid}`, { stdio: 'ignore', timeout: 5000, windowsHide: true });
              } else {
                process.kill(pid, 'SIGKILL');
              }
            } catch {}
          }
          await new Promise(r => setTimeout(r, 300));
        }
      } catch (err) {
        console.warn(`[browser] Orphan kill scan failed: ${err.message}`);
      }

      for (const lockFile of ['SingletonLock', 'SingletonSocket', 'SingletonCookie', 'DevToolsActivePort']) {
        const lf = resolve(launchRoot, lockFile);
        try {
          if (existsSync(lf)) {
            unlinkSync(lf);
            console.log(`[browser] Removed stale ${lockFile} from ${launchMode} root`);
          }
        } catch {}
      }

      if (launchProfileDir) {
        launchArgs.push(`--profile-directory=${launchProfileDir}`);
        console.log(`[browser] Using --profile-directory=${launchProfileDir} (${launchMode})`);
      }

      const prefsFile = resolve(launchRoot, launchProfileDir || 'Default', 'Preferences');
      if (existsSync(prefsFile)) {
        try {
          const prefs = JSON.parse(readFileSync(prefsFile, 'utf-8'));
          if (prefs.profile) {
            prefs.profile.exit_type = 'Normal';
            prefs.profile.exited_cleanly = true;
            writeFileSync(prefsFile, JSON.stringify(prefs));
          }
        } catch {}
      }

      const persistentLaunchOpts = {
        ...launchOpts,
        args: launchArgs,
        ...contextOpts,
        ignoreDefaultArgs: [
          '--disable-extensions',
          '--disable-component-extensions-with-background-pages',
          '--disable-default-apps',
          '--enable-automation',
          '--disable-sync',
        ],
      };

      console.log(`[browser] Launching ${launchMode} persistent context at: ${launchRoot}${launchProfileDir ? ` (profile: ${launchProfileDir})` : ''}`);
      let launchContext;
      try {
        launchContext = await chromium.launchPersistentContext(launchRoot, persistentLaunchOpts);
      } catch (err) {
        const msg = err.message || '';
        if (msg.includes('ProcessSingleton') || msg.includes('already in use') || msg.includes('lock') || msg.includes('SingletonLock')) {
          throw new Error(`Browser profile is locked. Original error: ${msg}`);
        }
        throw err;
      }

      await new Promise(r => setTimeout(r, 500));
      let contextAlive = true;
      try {
        const testPages = launchContext.pages();
        if (testPages.length === 0) contextAlive = false;
      } catch { contextAlive = false; }
      if (!contextAlive) {
        throw new Error('Browser closed immediately after launch.');
      }

      const launchBrowser = launchContext;
      const existingPages = launchContext.pages();
      const launchPage = await launchContext.newPage();
      for (const existing of existingPages) {
        await existing.close().catch(() => {});
      }

      return { launchBrowser, launchContext, launchPage };
    };

    if (_selectedProfileKind === 'system') {
      const requestedProfileDir = _profileDirectory || 'Default';
      const connectMode = savedCfg.connectMode === 'attach' ? 'attach' : 'mirror';

      if (connectMode === 'attach') {
        // ── Attach (CDP): open tabs in a real, persistent Chrome window the user
        // controls. Uses a dedicated debug profile (Chrome 136+ ignores remote
        // debugging on the default dir), seeded once from the real profile.
        const attachSeed = savedCfg.attachSeed === 'fresh' ? 'fresh' : 'real';
        const { attachRoot, profileDirectory: attachProfileDir } =
          prepareAttachProfile(userDataDir, requestedProfileDir, attachSeed, _sourceBrowser || 'chrome');

        const { endpoint } = await ensureChromeDebuggable({
          userDataDir: attachRoot,
          profileDirectory: attachProfileDir,
          executablePath: hasUserExecPath ? savedCfg.executablePath : (execPath || null),
          channel: savedCfg.channel || null,
          viewport: { width: vpW, height: vpH },
        });

        const cdpBrowser = await chromium.connectOverCDP(endpoint);
        let cdpContext = cdpBrowser.contexts()[0];
        if (!cdpContext) cdpContext = await cdpBrowser.newContext(contextOpts);
        const cdpPage = await newSessionPage({ browser: cdpBrowser, context: cdpContext, _profileMode: 'cdp' }); // ALWAYS a fresh tab; never hijack a user tab

        browser = cdpBrowser;
        context = cdpContext;
        page = cdpPage;
        _isPersistent = false;       // CDP-attached, not a Playwright-owned persistent context
        _profileMode = 'cdp';
        _chromeProcess = null;       // teardown disconnects (leaves the user's Chrome alive)
        _launchUserDataDir = attachRoot;
        _launchProfileDirectory = attachProfileDir;
        // Keep _sourceProfilePath/_profileSourceName on the REAL profile so
        // findReusableBrowserSession matches and a 2nd open = new tab in this window.
        _profileSourceName = _profileSourceName || requestedProfileDir;
        console.log(`[browser] Attached to real Chrome via CDP at ${endpoint} (profile: ${attachProfileDir})`);
      } else {
        // ── Mirror (default): isolated copy. System profiles can't launch directly
        // from Chrome's real User Data dir while the user's browser may be running,
        // so launch an isolated mirror via Playwright's persistent-context path.
        const { mirrorRoot } = prepareMirroredProfile(userDataDir, requestedProfileDir, _sourceBrowser || 'chrome');

        try {
          const launched = await launchPersistentProfile(mirrorRoot, requestedProfileDir, 'mirror');
          browser = launched.launchBrowser;
          context = launched.launchContext;
          page = launched.launchPage;
          _profileMode = 'mirror';
          _launchUserDataDir = mirrorRoot;
          _launchProfileDirectory = requestedProfileDir;

          console.log(`[browser] Launched mirrored ${_profileSourceName || requestedProfileDir} profile`);
        } catch (mirrorErr) {
          throw new Error(
            `Could not launch mirrored ${_browserLabel} profile: ${mirrorErr.message}`
          );
        }
      }
    } else {
      const launchRoot = _selectedProfileKind === 'managed' ? getManagedProfileRoot() : userDataDir;
      const launchProfileDir = _profileDirectory || 'Default';
      if (_selectedProfileKind === 'managed') {
        try { if (!existsSync(launchRoot)) mkdirSync(launchRoot, { recursive: true }); } catch {}
        _profileSourceName = 'SynaBun Profile';
      }
      const launched = await launchPersistentProfile(launchRoot, launchProfileDir, _selectedProfileKind === 'managed' ? 'managed' : 'direct');
      browser = launched.launchBrowser;
      context = launched.launchContext;
      page = launched.launchPage;
      _profileMode = _selectedProfileKind === 'managed' ? 'managed' : 'direct';
      _launchUserDataDir = launchRoot;
      _launchProfileDirectory = launchProfileDir;
    }
  } else {
    // ── Standard: clean sandboxed browser ──
    browser = await chromium.launch(launchOpts);
    context = await browser.newContext(contextOpts);
    page = await context.newPage();
  }

  // ── Decrypt and inject cookies from Chrome profile (macOS) ──
  // Mirror mode may start from an isolated copy; bootstrap fresh auth from the
  // selected source profile's Cookies DB so the mirrored copy inherits logins.
  if (_isPersistent && _profileMode === 'mirror' && !savedCfg.clearStorageOnStart) {
    const decryptedCookies = decryptChromeCookies(_sourceProfilePath, _sourceBrowser || 'chrome');
    if (decryptedCookies.length > 0) {
      try {
        await context.addCookies(decryptedCookies);
        console.log(`[browser] Injected ${decryptedCookies.length} decrypted ${_sourceBrowser || 'chrome'} cookies`);
      } catch (e) {
        console.warn(`[browser] Failed to inject decrypted cookies: ${e.message}`);
      }
    }
  }

  // ── Stealth injections (if enabled) ──
  // B4: never inject stealth into a CDP-attached real Chrome — Playwright stealth
  // args + overriding window.chrome.runtime cause SIGSEGV crashes in system Chrome.
  // MoreLogin injects its own anti-detect fingerprint; never layer ours on top
  // (same rationale as cdp — Playwright stealth into an externally-owned Chromium).
  const doStealth = savedCfg.stealthFingerprint !== false && _profileMode !== 'cdp' && _profileMode !== 'morelogin';
  if (doStealth) {
    const cdpStealth = await page.context().newCDPSession(page);
    try {
      await cdpStealth.send('Page.addScriptToEvaluateOnNewDocument', {
        source: `
          Object.defineProperty(navigator, 'webdriver', { get: () => false });
          Object.defineProperty(navigator, 'plugins', {
            get: () => [
              { name: 'Chrome PDF Plugin', filename: 'internal-pdf-viewer', description: 'Portable Document Format' },
              { name: 'Chrome PDF Viewer', filename: 'mhjfbmdgcfjbbpaeojofohoefgiehjai', description: '' },
              { name: 'Native Client', filename: 'internal-nacl-plugin', description: '' },
            ],
          });
          Object.defineProperty(navigator, 'languages', {
            get: () => ${JSON.stringify(languages)},
          });
          const origQuery = window.Permissions.prototype.query;
          window.Permissions.prototype.query = function(params) {
            if (params.name === 'notifications') {
              return Promise.resolve({ state: 'default', onchange: null });
            }
            return origQuery.call(this, params);
          };
          if (!window.chrome) window.chrome = {};
          if (!window.chrome.runtime) window.chrome.runtime = { connect: () => {}, sendMessage: () => {} };
          delete window.cdc_adoQpoasnfa76pfcZLmcfl_;
          delete window.__playwright;
        `,
      });
    } catch (err) {
      console.warn('CDP stealth injection warning:', err.message);
    }
    await cdpStealth.detach().catch(() => {});
  }

  try {
    // browser_console reads what this tab logs from its first page on.
    attachConsoleBuffer(page);

    // Navigate to initial URL or blank
    const startUrl = options.url || 'about:blank';
    // Refuse a startUrl that resolves to one of SynaBun's own live OpenCode serve ports, and install the serve-port
    // guards and host-proof worker marker BEFORE the first navigation. MoreLogin
    // uses native URL patterns so other public traffic retains its native cache.
    const startServeDenial = browserServePortDenial(startUrl, liveOpencodeServePorts());
    if (startServeDenial) throw new Error(startServeDenial);
    await installMoneyGuardRoute(context);
    await installServePortGuard(context);
    if (typeof _pageSession !== 'undefined') {
      const marked = await _pageSession.markWorkerBrowserContext(context, { port: PORT, hostNames: machineNames.names() });
      if (!marked) throw new Error('Cannot protect browser owner authority: local worker marker failed');
    }
    const launchAborted = options.browserRequest && (options.browserRequest.signal.aborted || Date.now() >= options.browserRequest.deadline);
    if (!launchAborted) await page.goto(startUrl).catch((err) => {
      console.warn('Initial navigation warning:', err.message);
    });

    // Wait for page to be ready before attaching CDP
    await page.waitForLoadState('domcontentloaded').catch(() => {});

    // Get CDP session for screencast
    console.log('[browser] Creating CDP session... persistent:', !!_isPersistent, 'page url:', page.url());
    let cdpSession;
    try {
      cdpSession = await context.newCDPSession(page);
      console.log('[browser] CDP session created successfully via context');
    } catch (err) {
      console.error('[browser] CDP session creation failed:', err.message);
      throw new Error('Cannot create CDP session for screencast: ' + err.message);
    }

    // Generate first tab ID
    const firstTabId = randomBytes(4).toString('hex');

    const session = {
      browser,
      context,
      page,              // alias → active tab's page (backward compat)
      cdpSession,        // alias → active tab's CDP session (backward compat)
      _isPersistent,
      _profileMode: _profileMode || 'clean',
      _profileSourceName: _profileSourceName || null,
      _storageStatePath: STORAGE_STATE_PATH,
      _launchUserDataDir: _launchUserDataDir || null,
      _launchProfileDirectory: _launchProfileDirectory || null,
      _selectedProfilePath: _sourceProfilePath || null,
      _chromeProcess: _chromeProcess || null, // CDP mode: spawned Chrome process
      _mlEnvId: _mlEnvId || null,        // MoreLogin env id (morelogin mode)
      _mlDebugPort: _mlDebugPort || null,
      clients: new Set(),       // WebSocket connections for screencast
      screencastActive: false,
      createdAt: Date.now(),
      graceTimer: null,
      _loopOwned: new Set(),  // terminalSessionIds of loops using this session
      _interactiveOwned: new Set(),  // clientIds of interactive (non-loop) MCP processes owning a dedicated tab here
      _agentOwnedSet: new Set(),  // agentIds of automation-window agents using this session
      _tabOwners: new Map(),  // ownerKey (loop terminalSessionId | interactive clientId | agent terminal id | sidepanel owner key) → tabId (authoritative tab routing for tab-less calls)
      currentUrl: startUrl,
      title: await page.title().catch(() => ''),
      // ── Multi-tab support ──
      tabs: new Map(),          // tabId → { page, cdpSession, url, title }
      activeTabId: firstTabId,
    };

    // Register the first tab
    session.tabs.set(firstTabId, {
      page,
      cdpSession,
      url: startUrl,
      title: session.title,
    });

    // Wire page events for a tab (reusable for new tabs)
    function wireTabPageEvents(tabId, tabPage) {
      const isRegisteredPage = () => session.tabs.get(tabId)?.page === tabPage;
      attachConsoleBuffer(tabPage); // no-op when the tab's creator attached it already

      tabPage.on('framenavigated', async (frame) => {
        if (frame === tabPage.mainFrame()) {
          if (!isRegisteredPage()) return;
          const url = tabPage.url();
          const title = await tabPage.title().catch(() => '');
          if (!isRegisteredPage()) return;
          const tabEntry = session.tabs.get(tabId);
          if (tabEntry) { tabEntry.url = url; tabEntry.title = title; }
          // Only broadcast to clients if this is the active tab
          if (session.activeTabId === tabId) {
            session.currentUrl = url;
            session.title = title;
            const msg = JSON.stringify({ type: 'navigated', url, title });
            session.clients.forEach(ws => { if (ws.readyState === 1) ws.send(msg); });
          }
        }
      });

      tabPage.on('load', async () => {
        if (!isRegisteredPage()) return;
        const title = await tabPage.title().catch(() => '');
        if (!isRegisteredPage()) return;
        const tabEntry = session.tabs.get(tabId);
        if (tabEntry) { tabEntry.title = title; tabEntry.url = tabPage.url(); }
        if (session.activeTabId === tabId) {
          session.title = title;
          const msg = JSON.stringify({ type: 'loaded', url: tabPage.url(), title });
          session.clients.forEach(ws => { if (ws.readyState === 1) ws.send(msg); });
        }
      });

      tabPage.on('dialog', async (dialog) => {
        try {
          await dialog.accept();
        } catch {
          // Dialog already dismissed — race between page navigation and auto-accept
        }
      });

      tabPage.on('close', () => {
        try {
          // A wedge recovery can replace the Playwright Page while preserving the
          // public tabId. Ignore a late close event from the retired page so it
          // cannot delete the replacement from the registry.
          if (!isRegisteredPage()) return;
          console.log(`Browser tab ${tabId} page closed for session ${sessionId}`);
          session.tabs.delete(tabId);
          // The session is being closed and closes its own tabs (destroyBrowserSession): the tab only leaves the
          // registry. No other tab is switched to and nothing is announced but the session's end (browser:session-deleted).
          if (session._tearingDown) return;
          // If active tab closed, switch to another tab if available
          if (session.activeTabId === tabId) {
            const remaining = [...session.tabs.keys()];
            if (remaining.length > 0) {
              _switchSessionTab(session, sessionId, remaining[0]).catch(() => {});
            } else {
              session.activeTabId = null;
              session.page = null;
              session.cdpSession = null;
              session.currentUrl = 'about:blank';
              session.title = '';
              // No tabs left — notify clients
              session.clients.forEach(ws => {
                if (ws.readyState === 1) {
                  ws.send(JSON.stringify({ type: 'error', message: 'All tabs closed' }));
                  ws.close(1000, 'All tabs closed');
                }
              });
              session.clients.clear();
            }
          }
          broadcastSync({ type: 'browser:tab-closed', sessionId, tabId, remainingTabs: session.tabs.size });
        } finally {
          // The dialog listener stays alive through target retirement; once the
          // close event arrives the page can release every closure it retained.
          try { tabPage.removeAllListeners(); } catch {}
        }
      });
    }

    // Wire events for the first tab
    wireTabPageEvents(firstTabId, page);
    // Store the wiring function on the session for creating new tabs
    session._wireTabPageEvents = wireTabPageEvents;

    // ── Money-safety: block all ad/boost/billing network requests in this context ──
    // Applies to the first tab and every future tab (context-level route).
    await installMoneyGuardRoute(context);
    // ── SynaBun's own OpenCode serves: no request of this context reaches one ──
    await installServePortGuard(context);

    // Handle context close (browser quit / crash)
    context.on('close', () => {
      const orphanedLoops = session._loopOwned?.size > 0 ? [...session._loopOwned] : [];
      console.log(`Browser context closed for session ${sessionId}${session._agentOwnedSet?.size ? ` (agent-owned: ${[...session._agentOwnedSet].join(',')})` : ''}${orphanedLoops.length ? ` (orphaning loops: ${orphanedLoops.join(', ')})` : ''}`);
      session.screencastActive = false;
      detachScreencastFrameHandler(session);
      // Stop autosave interval
      if (session._autosaveInterval) { clearInterval(session._autosaveInterval); session._autosaveInterval = null; }
      session.clients.forEach(ws => {
        if (ws.readyState === 1) ws.close(1000, 'Browser closed');
      });
      session.clients.clear();
      // Always clean up from the map — the context is dead, tools will fail anyway.
      // Agent iteration loop and MCP resolveSession will create a fresh session on next call.
      browserSessions.delete(sessionId);
      broadcastSync({ type: 'browser:session-deleted', sessionId, orphanedLoops });
    });

    if (context.__browserNetworkGuardError) {
      throw new Error(`Browser network protection unavailable: ${context.__browserNetworkGuardError}`);
    }
    browserSessions.set(sessionId, session);
    // SynaBun's automation browser carries a marker for SynaBun's own origin (lib/page-session.js): a worker that opens
    // the app's pages here can read and click them, but its owner-only writes are refused.
    // (a test runs this function from the file's text without the page session: then nothing is marked)

    // ── Periodic cookie autosave (every 30s) ──
    // Protects against cookie loss when the user closes the window directly.
    if (savedCfg.persistStorage !== false && !_isPersistent && _profileMode !== 'cdp' && _profileMode !== 'morelogin') {
      session._autosaveInterval = setInterval(async () => {
        if (!session.context) { clearInterval(session._autosaveInterval); return; }
        try {
          const dir = dirname(STORAGE_STATE_PATH);
          if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
          await session.context.storageState({ path: STORAGE_STATE_PATH });
          session._lastStorageSave = Date.now();
        } catch {
          // Context is dead — stop autosaving
          clearInterval(session._autosaveInterval);
          session._autosaveInterval = null;
        }
      }, 30000);
    }
    return {
      sessionId,
      // CDP-attached + persistent contexts have no streamable wsEndpoint; cdp also
      // shows the real Chrome window directly, so the UI must not open a screencast.
      wsEndpoint: (_isPersistent || _profileMode === 'cdp' || _profileMode === 'morelogin') ? null : (browser.wsEndpoint?.() || null),
      profileMode: _profileMode || 'clean',
      profileSource: _profileSourceName || null,
      // A start URL MoreLogin refused (a localhost port missing from Port scan
      // protection, say): the session exists, parked on the stop page.
      moreLoginBlocked: moreLoginBlockError(session, startUrl, page.url()),
    };
  } catch (error) {
    if (_profileMode === 'morelogin') {
      // Includes failures AFTER guard installation (navigation setup, screencast
      // CDP, tab registration). Dispose even if Playwright cannot disconnect.
      browserSessions.delete(sessionId);
      try {
        await page.close().catch(() => {});
        await browser.close().catch(() => {});
      } finally {
        await disposeBrowserNetworkGuard(context);
      }
    }
    throw error;
  }
}

/**
 * Start CDP screencast — streams JPEG frames to all connected WebSocket clients.
 */
function detachScreencastFrameHandler(session) {
  const handler = session?._screencastFrameHandler;
  const cdp = session?._screencastFrameCdpSession || session?.cdpSession;
  if (!handler || !cdp) return;
  try {
    if (typeof cdp.off === 'function') cdp.off('Page.screencastFrame', handler);
    else if (typeof cdp.removeListener === 'function') cdp.removeListener('Page.screencastFrame', handler);
  } catch {}
  session._screencastFrameHandler = null;
  session._screencastFrameCdpSession = null;
}

async function startScreencast(session) {
  if (session.screencastActive &&
      session._screencastFrameHandler &&
      session._screencastFrameCdpSession === session.cdpSession) return;

  const scCfg = loadBrowserConfig().screencast || {};
  if (scCfg.disabled !== false) {
    console.log('[screencast] Stream disabled in browser config — skipping');
    return;
  }
  if (session._profileMode === 'cdp' || session._profileMode === 'morelogin') {
    // Attach (CDP) and MoreLogin modes show their own browser window directly —
    // never stream it.
    console.log(`[screencast] ${session._profileMode} mode — skipping screencast`);
    return;
  }

  session.screencastActive = true;

  console.log('[screencast] Starting screencast, CDP session exists:', !!session.cdpSession, 'persistent:', !!session._isPersistent);

  detachScreencastFrameHandler(session);
  const frameCdpSession = session.cdpSession;
  const onScreencastFrame = (params) => {
    // Bail out cheaply when no clients can receive frames. Still ack to keep
    // the CDP pipeline moving — otherwise Chromium stops sending frames.
    if (!session.clients || session.clients.size === 0) {
      frameCdpSession.send('Page.screencastFrameAck', { sessionId: params.sessionId }).catch(() => {});
      return;
    }

    // Send raw JPEG bytes as binary WebSocket message (no base64/JSON overhead).
    // First byte = 0x01 (frame marker) so clients distinguish binary frames
    // from JSON text messages (navigated, loaded, error, etc.).
    const jpegBuf = Buffer.from(params.data, 'base64');
    const bin = Buffer.allocUnsafe(1 + jpegBuf.length);
    bin[0] = 0x01; // frame marker
    jpegBuf.copy(bin, 1);
    session.clients.forEach(ws => {
      // Skip clients with congested write buffers to prevent frame backlog
      if (ws.readyState === 1 && ws.bufferedAmount < 512 * 1024) ws.send(bin);
    });

    // Fire-and-forget ACK — no await, removes ACK latency from the frame pipeline
    frameCdpSession.send('Page.screencastFrameAck', {
      sessionId: params.sessionId,
    }).catch(() => {});
  };
  session._screencastFrameHandler = onScreencastFrame;
  session._screencastFrameCdpSession = frameCdpSession;
  frameCdpSession.on('Page.screencastFrame', onScreencastFrame);

  try {
    await session.cdpSession.send('Page.startScreencast', {
      format: scCfg.format || 'jpeg',
      quality: scCfg.quality ?? 80,
      maxWidth: scCfg.maxWidth || 1280,
      maxHeight: scCfg.maxHeight || 800,
      // Default 2: client renderer caps at 30fps, so every-frame capture just
      // wastes decode + WS bandwidth on frames the client drops.
      everyNthFrame: scCfg.everyNthFrame || 2,
    });
    console.log('[screencast] Page.startScreencast sent successfully');
  } catch (err) {
    console.error('[screencast] Page.startScreencast FAILED:', err.message);
    session.screencastActive = false;
    detachScreencastFrameHandler(session);
    throw err;
  }
}

async function stopScreencast(session) {
  const wasActive = !!session.screencastActive;
  session.screencastActive = false;
  if (wasActive) {
    try {
      await session.cdpSession.send('Page.stopScreencast');
    } catch {}
  }
  detachScreencastFrameHandler(session);
}

// ── Multi-tab helpers ──

/**
 * The page of a new tab, for every tab SynaBun opens in a browser the user
 * shares with the runs (`_profileMode` morelogin or cdp): the first tab of a
 * session (createBrowserSession, which has no session object yet and passes
 * browser, context and mode), each further tab (createSessionTab) and the
 * replacement of a wedged tab (recoverSessionTabPage).
 *
 * openTabsInBackground: true in browser-config.json (only that; not set or
 * anything else, this is context.newPage() exactly as before) opens such a tab
 * behind the selected one: the window is neither restored nor brought forward,
 * and the tab is not the selected tab when it opens. It does not cover SynaBun's
 * own windows (managed, mirror, direct and clean sessions), tabs a page opens
 * itself, or what selects a tab afterwards (the user, or the selected tab
 * closing next to it). A browser that cannot gets a normal tab.
 *
 * Every page it returns is recorded in synabunOpenedPages: an explicit close
 * of such a session closes those, and only those (closeOwnTabsBeforeDisconnect).
 */
async function newSessionPage(session, { timeoutMs } = {}) {
  if (loadBrowserConfig().openTabsInBackground === true && (session._profileMode === 'morelogin' || session._profileMode === 'cdp')) {
    const page = await openBackgroundPage(session.browser, session.context, timeoutMs ? { timeoutMs } : undefined).catch(() => null);
    if (page) {
      synabunOpenedPages.add(page);
      return page;
    }
    console.warn('[browser] could not open the tab in the background; opening it as the selected tab');
  }
  const page = await session.context.newPage();
  synabunOpenedPages.add(page);
  return page;
}

// The pages newSessionPage opened. In a browser the user owns (MoreLogin, their Chrome over CDP) context.pages() is
// the whole browser: the user's tabs, other sessions' tabs and what pages opened. A page is SynaBun's to close only
// when it is in here; one that was open before SynaBun connected, or that someone else opened, never is.
const synabunOpenedPages = new WeakSet();

/**
 * Create a new tab (page) in an existing browser session.
 * Returns { tabId, url, title }.
 */
async function createSessionTab(session, sessionId, url = 'about:blank') {
  const tabId = randomBytes(4).toString('hex');
  const activeEntry = session.tabs?.get(session.activeTabId);
  const shouldAdoptAsActive = !activeEntry || activeEntry.page?.isClosed?.();
  const page = await newSessionPage(session);
  attachConsoleBuffer(page);
  if (url && url !== 'about:blank') {
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 15000 }).catch(() => {});
  }
  const cdpSession = await session.context.newCDPSession(page);
  const title = await page.title().catch(() => '');

  session.tabs.set(tabId, { page, cdpSession, url: page.url(), title });
  if (session._wireTabPageEvents) session._wireTabPageEvents(tabId, page);
  // Externally-owned contexts (especially MoreLogin) can remain connected after
  // their last page closes. Revive that zero-tab session instead of retaining a
  // stale activeTabId/page alias that makes the next loop destroy the browser.
  if (shouldAdoptAsActive) {
    session.activeTabId = tabId;
    session.page = page;
    session.cdpSession = cdpSession;
    session.currentUrl = page.url();
    session.title = title;
  }

  console.log(`[browser] New tab ${tabId} created in session ${sessionId} (total: ${session.tabs.size})`);
  broadcastSync({ type: 'browser:tab-created', sessionId, tabId, url: page.url(), title, tabCount: session.tabs.size });
  return { tabId, url: page.url(), title };
}

/**
 * Replace only a wedged Playwright Page while preserving its public tabId and
 * owner mapping. Loops can continue with the same injected pin on their next MCP
 * call; other tabs and the shared profile remain untouched.
 */
async function recoverSessionTabPage(session, sessionId, tabId, reason = 'page became unresponsive') {
  if (!session?.tabs?.has(tabId)) return { recovered: false, error: `Tab ${tabId} is no longer registered` };
  if (session._invalidating) {
    return { recovered: false, sessionInvalidated: true, error: `Browser session ${sessionId} is being replaced` };
  }
  // A session being closed closes its own tabs (destroyBrowserSession): a call that fails on one of them opens no new tab.
  if (session._tearingDown) {
    return { recovered: false, sessionInvalidated: true, error: `Browser session ${sessionId} is being closed` };
  }
  if (!session._tabRecoveries) session._tabRecoveries = new Map();
  const pending = session._tabRecoveries.get(tabId);
  if (pending) return pending;

  const recovery = (async () => {
    const oldEntry = session.tabs.get(tabId);
    const oldPage = oldEntry?.page;
    let replacementPage = null;
    let replacementCdp = null;
    let recoveryStage = 'creating replacement page';
    const reportLateCleanupError = (error) => {
      console.warn(`[browser] Late ${recoveryStage} cleanup failed for tab ${tabId}: ${error.message}`);
    };
    try {
      replacementPage = await withBrowserOperationDeadline(
        // A background attempt gets half of the step, so a normal tab still fits after it.
        newSessionPage(session, { timeoutMs: BROWSER_RECOVERY_STEP_DEADLINE_MS / 2 }),
        BROWSER_RECOVERY_STEP_DEADLINE_MS,
        'Creating replacement browser tab',
        {
          onLateResolve: async (latePage) => {
            try { latePage?.removeAllListeners?.(); } catch {}
            await latePage?.close?.({ runBeforeUnload: false });
          },
          onCleanupError: reportLateCleanupError,
        },
      );
      recoveryStage = 'attaching replacement CDP session';
      replacementCdp = await withBrowserOperationDeadline(
        session.context.newCDPSession(replacementPage),
        BROWSER_RECOVERY_STEP_DEADLINE_MS,
        'Attaching replacement browser tab',
        {
          onLateResolve: (lateCdp) => lateCdp?.detach?.(),
          onCleanupError: reportLateCleanupError,
        },
      );
      recoveryStage = 'verifying replacement page';
      await withBrowserOperationDeadline(
        replacementPage.evaluate('1'),
        BROWSER_RECOVERY_PROBE_DEADLINE_MS,
        'Verifying replacement browser tab',
      );
      if (session._invalidating || browserSessions.get(sessionId) !== session) {
        throw new Error(`Browser session ${sessionId} was retired during tab recovery`);
      }
      recoveryStage = 'installing replacement page';
      const title = ''; // context.newPage() starts at about:blank
      const wasActive = session.activeTabId === tabId;
      if (wasActive) {
        await withBrowserOperationDeadline(
          stopScreencast(session),
          BROWSER_RECOVERY_STEP_DEADLINE_MS,
          'Stopping stale tab screencast',
        ).catch(() => {});
      }

      // Keep the retired page's defensive dialog handler alive until its close
      // event. Identity guards prevent all of its other late events from touching
      // the replacement entry.
      session.tabs.set(tabId, {
        page: replacementPage,
        cdpSession: replacementCdp,
        url: 'about:blank',
        title,
        recoveredAt: Date.now(),
      });
      session._wireTabPageEvents?.(tabId, replacementPage);
      if (wasActive) {
        session.page = replacementPage;
        session.cdpSession = replacementCdp;
        session.currentUrl = 'about:blank';
        session.title = title;
        await withBrowserOperationDeadline(
          startScreencast(session),
          BROWSER_RECOVERY_STEP_DEADLINE_MS,
          'Starting replacement tab screencast',
        ).catch(() => {});
      }

      if (oldEntry?.cdpSession?.detach) {
        await withBrowserOperationDeadline(
          oldEntry.cdpSession.detach(),
          1_000,
          'Detaching wedged browser tab CDP session',
        ).catch(() => {});
      }
      if (oldPage && !oldPage.isClosed?.()) {
        await withBrowserOperationDeadline(
          oldPage.close({ runBeforeUnload: false }),
          1_000,
          'Closing wedged browser tab',
        ).catch(() => {});
      }
      console.warn(`[browser] Recovered wedged tab ${tabId} in session ${sessionId}: ${reason}`);
      broadcastSync({
        type: 'browser:tab-recovered', sessionId, tabId,
        url: 'about:blank', reason: String(reason).slice(0, 500),
      });
      return { recovered: true, url: 'about:blank' };
    } catch (error) {
      if (replacementCdp?.detach) {
        await withBrowserOperationDeadline(
          replacementCdp.detach(),
          1_000,
          'Cleaning replacement CDP session',
        ).catch(() => {});
      }
      if (replacementPage?.close) {
        await withBrowserOperationDeadline(
          replacementPage.close({ runBeforeUnload: false }),
          1_000,
          'Cleaning replacement browser tab',
        ).catch(() => {});
      }

      console.warn(`[browser] Failed during ${recoveryStage} for tab ${tabId} in session ${sessionId}: ${error.message}`);
      if (!session._invalidating) {
        session._invalidating = true;
        // destroyBrowserSession removes the registry entry synchronously before
        // its first await. The next pinned MCP call will therefore use the
        // existing /api/loop/recover-browser path instead of reusing this context.
        void destroyBrowserSession(sessionId).catch((destroyError) => {
          console.warn(`[browser] Failed to retire invalidated session ${sessionId}: ${destroyError.message}`);
        });
      }
      return { recovered: false, sessionInvalidated: true, error: error.message };
    }
  })().finally(() => session._tabRecoveries?.delete(tabId));

  session._tabRecoveries.set(tabId, recovery);
  return recovery;
}

const BROWSER_NAVIGATION_WEDGE_COOLDOWN_MS = 2 * 60_000;

function browserNavigationCircuitKey(tabId, url) {
  return `${tabId}\n${url}`;
}

function activeBrowserNavigationCircuit(session, tabId, url) {
  const key = browserNavigationCircuitKey(tabId, url);
  const entry = session._navigationWedges?.get(key);
  if (!entry) return null;
  const age = Date.now() - entry.at;
  if (age >= BROWSER_NAVIGATION_WEDGE_COOLDOWN_MS) {
    session._navigationWedges.delete(key);
    return null;
  }
  return { ...entry, remainingMs: BROWSER_NAVIGATION_WEDGE_COOLDOWN_MS - age };
}

function rememberBrowserNavigationWedge(session, tabId, url, error) {
  if (!session._navigationWedges) session._navigationWedges = new Map();
  session._navigationWedges.set(browserNavigationCircuitKey(tabId, url), {
    at: Date.now(), error: String(error?.message || error || '').slice(0, 500),
  });
}

function clearBrowserNavigationWedge(session, tabId, url) {
  session._navigationWedges?.delete(browserNavigationCircuitKey(tabId, url));
}

async function recoverBrowserRouteFailure(session, sessionId, routed, req, operation, error) {
  if (!routed?.tabId) return null;
  const disposition = classifyBrowserPageError(error);
  if (disposition === BrowserPageFailureDisposition.NONE) return null;

  let recoveryReason = `${operation}: ${error.message}`;
  if (disposition === BrowserPageFailureDisposition.PROBE) {
    try {
      await withBrowserOperationDeadline(
        routed.page.evaluate('1'),
        BROWSER_RECOVERY_PROBE_DEADLINE_MS,
        'Browser page liveness probe',
      );
      return null;
    } catch (probeError) {
      recoveryReason += `; liveness probe failed: ${probeError.message}`;
    }
  }

  const result = await recoverSessionTabPage(session, sessionId, routed.tabId, recoveryReason);
  if (result.recovered) {
    const owner = _paceTerminalId(req);
    if (owner) loopLog(owner, 'browser:tab-recovered', `${operation} reset wedged tab`, {
      browserSessionId: sessionId, browserTabId: routed.tabId, error: error.message,
    });
  }
  return result;
}

function browserRecoveryErrorMessage(error, recovery) {
  if (recovery?.recovered) {
    return `${error.message} The tab was automatically reset to about:blank and is ready for the next browser call; do not immediately retry the same URL.`;
  }
  if (recovery?.sessionInvalidated) {
    return `${error.message} The unhealthy browser session was retired and will be reacquired on the next browser call.`;
  }
  if (recovery?.error) return `${error.message} Automatic tab recovery failed: ${recovery.error}`;
  return error.message;
}

/**
 * Switch the active tab — stops screencast on old tab, starts on new one.
 * Updates backward-compat aliases (session.page, session.cdpSession).
 */
async function _switchSessionTab(session, sessionId, tabId) {
  const tabEntry = session.tabs.get(tabId);
  if (!tabEntry) throw new Error(`Tab ${tabId} not found`);
  if (session.activeTabId === tabId) return; // already active

  // Stop screencast on current tab
  await stopScreencast(session);
  // The tab may have left the session while that was awaited (closed, retired):
  // the aliases never take a page that is no longer registered.
  if (session.tabs.get(tabId) !== tabEntry) throw new Error(`Tab ${tabId} not found`);

  // Switch aliases
  session.activeTabId = tabId;
  session.page = tabEntry.page;
  session.cdpSession = tabEntry.cdpSession;
  session.currentUrl = tabEntry.url;
  session.title = tabEntry.title;

  // Start screencast on new tab
  await startScreencast(session);
  // Gone, or no longer the active tab, while that was awaited: nothing to announce.
  if (session.tabs.get(tabId) !== tabEntry || session.activeTabId !== tabId) return;

  // Notify clients of the switch
  const msg = JSON.stringify({
    type: 'tab-switched',
    tabId,
    url: session.currentUrl,
    title: session.title,
    tabCount: session.tabs.size,
  });
  session.clients.forEach(ws => { if (ws.readyState === 1) ws.send(msg); });

  console.log(`[browser] Switched to tab ${tabId} in session ${sessionId}`);
  broadcastSync({ type: 'browser:tab-switched', sessionId, tabId, url: session.currentUrl, title: session.title });
}

/**
 * Close a single tab in a session. If it's the last tab, destroys the whole session.
 */
async function closeSessionTab(session, sessionId, tabId) {
  const tabEntry = session.tabs.get(tabId);
  if (!tabEntry) return;

  session.tabs.delete(tabId);
  clearAiSnapshotCache(sessionId, tabId);

  if (session.tabs.size === 0) {
    // Last tab — destroy the whole session. In a browser the user owns, that teardown closes
    // this tab too: it has left the registry already, so it is handed over.
    await destroyBrowserSession(sessionId, { closeOwnTabs: true, closingPage: tabEntry.page });
    return;
  }

  // If closing the active tab, switch to another. The tab picked can itself be
  // closed while the switch is awaited (two closes in one turn, or during a
  // screencast stop): the switch then refuses it, because it never aliases a tab
  // that left the registry, and a tab that is still registered is picked instead.
  let switchError = null;
  if (session.activeTabId === tabId) {
    for (let picks = 0; picks < 8 && session.activeTabId === tabId && session.tabs.size > 0; picks += 1) {
      const nextTabId = session.tabs.keys().next().value;
      const nextEntry = session.tabs.get(nextTabId);
      try {
        await _switchSessionTab(session, sessionId, nextTabId);
      } catch (error) {
        // Gone meanwhile: pick again. Still registered: the switch itself failed, reported once the page is closed.
        if (session.tabs.get(nextTabId) === nextEntry) { switchError = error; break; }
      }
    }
    // No tab took over (every other one left meanwhile): no alias stays on the tab that is closing.
    if (session.activeTabId === tabId) {
      session.activeTabId = null;
      session.page = null;
      session.cdpSession = null;
      session.currentUrl = 'about:blank';
      session.title = '';
    }
  }

  // Close the page, whatever the switch did: the tab has left the registry already
  try { await tabEntry.page.close(); } catch {}
  console.log(`[browser] Tab ${tabId} closed in session ${sessionId} (remaining: ${session.tabs.size})`);
  if (switchError) throw switchError;
}

/**
 * Clean up a browser session.
 * `closeOwnTabs` marks an explicit close (DELETE /api/browser/sessions/:id, or
 * the session's last tab closed): in a browser the user owns (MoreLogin, or
 * their Chrome over CDP) the tabs SynaBun opened for the session are closed
 * before the disconnect, `closingPage` (a last tab that has left the registry
 * already) included. Every other connect mode closes its whole browser anyway
 * and is unchanged, and so is every other teardown (a dead or invalidated
 * session, an idle or grace reap).
 */
async function destroyBrowserSession(sessionId, { closeOwnTabs = false, closingPage = null } = {}) {
  const session = browserSessions.get(sessionId);
  if (!session) return;

  try {
    // Remove from Map immediately to prevent races (new sessions seeing zombie entries)
    browserSessions.delete(sessionId);
    clearAiSnapshotCache(sessionId);
    engagementScheduler.clear(sessionId);
    // From here on the tabs this close takes leave quietly: their close handlers switch to no
    // other tab and announce nothing, and a call that fails on one of them opens no replacement.
    if (closeOwnTabs && (session._profileMode === 'cdp' || session._profileMode === 'morelogin') && !session._chromeProcess) {
      session._tearingDown = true;
    }

    const savedCfg = loadBrowserConfig();
    if (savedCfg.persistStorage !== false && session.context && !session._chromeProcess && !session._isPersistent && session._profileMode !== 'cdp' && session._profileMode !== 'morelogin') {
      // Use per-profile storage path from session (set at creation), fall back to config default
      const storagePath = session._storageStatePath || resolve(DATA_HOME, savedCfg.storageStatePath || 'data/browser-storage.json');
      try {
        const dir = dirname(storagePath);
        if (!existsSync(dir)) mkdirSync(dir, { recursive: true });
        await session.context.storageState({ path: storagePath });
        session._lastStorageSave = Date.now();
        console.log(`  Storage state saved to ${storagePath}`);
      } catch (err) {
        console.warn('Failed to save storage state:', err.message);
      }
    }

    if (session._autosaveInterval) { clearInterval(session._autosaveInterval); session._autosaveInterval = null; }
    if (session.graceTimer) clearTimeout(session.graceTimer);
    try { await stopScreencast(session); } catch {}
    if ((session._profileMode === 'cdp' || session._profileMode === 'morelogin') && !session._chromeProcess) {
      // Connected to an externally-owned Chromium (real Chrome via CDP, or a MoreLogin
      // env). For connectOverCDP, Playwright's browser.close() closes only its CDP
      // transport; it does not terminate the externally-owned Chromium process, and
      // every tab stays open (MoreLogin reopens them all at the profile's next start).
      // An explicit close therefore first closes the tabs SynaBun opened for the session.
      if (session._tearingDown) await closeOwnTabsBeforeDisconnect(session, sessionId, closingPage);
      try { await session.browser.close(); } catch {}
    } else if (session._chromeProcess) {
      // Spawned Chrome process: disconnect Playwright, then kill Chrome
      try { await session.browser.close(); } catch {}
      try {
        if (!session._chromeProcess.killed) {
          session._chromeProcess.kill('SIGTERM');
          setTimeout(() => {
            try { if (!session._chromeProcess.killed) session._chromeProcess.kill('SIGKILL'); } catch {}
          }, 3000);
        }
      } catch {}
    } else if (session._isPersistent) {
      // Persistent context: close context kills browser
      try { await session.context.close(); } catch {}
    } else {
      try { await session.browser.close(); } catch {}
    }
    // Keep the defensive dialog listeners installed while Playwright retires the
    // targets. Removing them first makes DialogManager auto-close a beforeunload
    // dialog against an already-detached page. Release their session closures only
    // after disconnect/close has completed.
    if (session.tabs) {
      for (const entry of session.tabs.values()) {
        try { entry?.page?.removeAllListeners?.(); } catch { /* page already gone */ }
      }
    }
    if (session._isPersistent && session._launchUserDataDir) {
      const pp = resolve(session._launchUserDataDir, session._launchProfileDirectory || 'Default', 'Preferences');
      if (existsSync(pp)) {
        try {
          const prefs = JSON.parse(readFileSync(pp, 'utf-8'));
          if (prefs.profile) {
            prefs.profile.exit_type = 'Normal';
            prefs.profile.exited_cleanly = true;
          }
          writeFileSync(pp, JSON.stringify(prefs));
        } catch {}
      }
    }
    broadcastSync({ type: 'browser:session-deleted', sessionId });
  } finally {
    // Independent of Playwright disconnect, configuration or notification errors.
    await disposeBrowserNetworkGuard(session.context);
  }
}

// Explicit closes count a browser's pages one session at a time: two sessions closing together
// in one browser could each count the other's tab as the page that stays, and leave it with none.
let _ownTabsCloseChain = Promise.resolve();

/**
 * Before an explicit close disconnects from a browser the user owns, close the
 * tabs SynaBun opened for the session: its registered pages that are in
 * synabunOpenedPages, and `closingPage`. Never a page found by walking the
 * browser, which is the user's whole browser. When no other page of the browser
 * would stay open, one of them is emptied (about:blank) instead, so the browser
 * keeps its window. Each close skips beforeunload and is bounded (3 s) and
 * best-effort: a page that is gone or hung never holds the close up, and
 * nothing here throws.
 */
function closeOwnTabsBeforeDisconnect(session, sessionId, closingPage = null) {
  const work = async () => {
    try {
      const pages = [...(session.tabs?.values() || [])].map((entry) => entry?.page).concat(closingPage);
      const own = [...new Set(pages)].filter((page) => page && synabunOpenedPages.has(page) && !page.isClosed?.());
      if (own.length === 0) return;
      const keep = (await otherOpenPageCount(session, own)) > 0 ? null : own[0];
      await Promise.all(own.map((page) => withBrowserOperationDeadline(
        page === keep ? page.goto('about:blank') : page.close({ runBeforeUnload: false }),
        3_000,
        page === keep ? 'Emptying the last tab of the browser' : 'Closing a tab SynaBun opened',
      ).catch(() => {})));
      const closed = own.filter((page) => page !== keep && page.isClosed?.()).length;
      const open = own.length - closed - (keep ? 1 : 0);
      console.log(`[browser] Closed ${closed} tab(s) SynaBun opened in session ${sessionId} before disconnecting`
        + `${keep ? '; the last page of the browser was emptied (about:blank) instead' : ''}`
        + `${open ? `; ${open} not confirmed closed, may still be open` : ''}`);
    } catch (error) {
      console.warn(`[browser] Closing the tabs SynaBun opened in session ${sessionId} failed: ${error.message}`);
    }
  };
  const result = _ownTabsCloseChain.then(work, work);
  _ownTabsCloseChain = result.then(() => {}, () => {});
  return result;
}

/**
 * How many pages of the browser are open besides `own`, as the browser lists
 * them (Target.getTargets: this connection's own view of a tab another session
 * just closed can lag), else as this connection sees them. Prerenders,
 * extension and DevTools pages and the browser's own UI (tab search, side
 * panels) are not counted: a doubt keeps a tab rather than closing the
 * browser's last one.
 */
async function otherOpenPageCount(session, own) {
  const counts = (url) => !/^(?:chrome-extension|devtools):|^chrome(?:-untrusted)?:\/\/[^/]*\.top-chrome\b/i.test(url || '');
  let cdp = null;
  try {
    cdp = await withBrowserOperationDeadline(session.browser.newBrowserCDPSession(), 1_000, 'Opening a browser CDP session', {
      onLateResolve: (late) => late?.detach?.(),
    });
    const { targetInfos = [] } = await withBrowserOperationDeadline(cdp.send('Target.getTargets'), 1_000, 'Listing the pages of the browser');
    return targetInfos.filter((target) => target.type === 'page' && !target.subtype && counts(target.url)).length - own.length;
  } catch {
    try {
      return session.browser.contexts().flatMap((context) => context.pages())
        .filter((page) => !own.includes(page) && !page.isClosed() && counts(page.url())).length;
    } catch {
      return 0;
    }
  } finally {
    if (cdp) cdp.detach().catch(() => {});
  }
}

// ── Tab-level page routing (concurrent loop isolation) ──

/** Automation owners (loops, interactive MCP processes, agents) on a session. */
function sessionOwnerCount(session) {
  return (session._loopOwned?.size || 0)
    + (session._interactiveOwned?.size || 0)
    + (session._agentOwnedSet?.size || 0);
}

/** Route attribution: warn ONLY when an identity's resolved tab CHANGES —
 *  tab-hopping is the collision smoking gun; steady state logs nothing. */
function trackRoute(session, identityKey, tabId, source) {
  if (!session._routeLog) session._routeLog = new Map();
  const key = identityKey || 'anon';
  const prev = session._routeLog.get(key);
  if (prev && prev.tabId !== tabId) {
    console.warn(`[browser] route-change: id=${key} tab ${prev.tabId} (${prev.source}) → ${tabId} (${source})`);
  }
  session._routeLog.set(key, { tabId, source, count: (prev?.count || 0) + 1, lastSeen: Date.now() });
}

/**
 * Resolve the Playwright page for an API request.
 * If tabId is provided (body or query), targets that specific tab's page directly.
 * Otherwise routes by caller identity (X-Synabun-Terminal → _tabOwners), and
 * only serves ownership-free fallbacks when no automation owns the session —
 * a caller without identity must NEVER receive another automation's tab.
 */
function getTargetPage(session, req) {
  const terminalId = (req.get && req.get('X-Synabun-Terminal')) || req.headers?.['x-synabun-terminal'] || null;

  // 1. An explicit tab must still belong to this caller. Manual UI requests
  // carry no terminal header and may intentionally inspect any tab.
  const tabId = req.body?.tabId || req.query?.tabId;
  if (tabId) {
    const tab = session.tabs?.get(tabId);
    if (!tab) return null;
    if (terminalId) {
      const owned = session._tabOwners?.get(terminalId);
      const claimedByOther = [...(session._tabOwners || [])].some(([owner, id]) => id === tabId && owner !== terminalId);
      if ((owned && owned !== tabId) || claimedByOther) return null;
    }
    trackRoute(session, terminalId, tabId, 'explicit-tab');
    return { page: tab.page, cdpSession: tab.cdpSession, tabId };
  }

  // 2. No tabId — route by caller identity. The MCP child sends X-Synabun-Terminal
  // (its loop terminalSessionId, sidepanel owner key, or per-caller client id).
  // If that caller owns a tab here, use it — never the shared activeTab.
  if (terminalId && session._tabOwners?.has(terminalId)) {
    const ownedTabId = session._tabOwners.get(terminalId);
    const tab = session.tabs?.get(ownedTabId);
    if (tab) {
      trackRoute(session, terminalId, ownedTabId, 'owner-map');
      return { page: tab.page, cdpSession: tab.cdpSession, tabId: ownedTabId };
    }
    // Owned tab vanished — drop the stale mapping and fall through.
    session._tabOwners.delete(terminalId);
  }

  // Every SynaBun MCP caller ALWAYS sends X-Synabun-Terminal (per-caller
  // identity with a guaranteed clientId fallback). So a request that carries
  // the header but matched nothing above is an AUTOMATION whose pin is lost —
  // it must fail closed rather than inherit someone else's tab. A request with
  // NO header is the NI web UI (manual control) — it keeps legacy activeTab
  // semantics; manual takeover of an automation's session is a supervised
  // user action, not a cross-automation collision.
  const isAutomation = !!terminalId;

  // 3. Single-tab session — unambiguous for manual callers; for an automation
  // this means its own tab is gone (or never registered): fail closed so the
  // MCP-side recovery acquires it a fresh owned tab instead of hijacking the
  // lone tab another automation may own.
  if (session.tabs && session.tabs.size === 1) {
    const onlyTabId = session.tabs.keys().next().value;
    const only = session.tabs.get(onlyTabId);
    const tabClaimed = session._tabOwners ? [...session._tabOwners.values()].includes(onlyTabId) : false;
    if (only && (!isAutomation || (sessionOwnerCount(session) === 0 && !tabClaimed))) {
      trackRoute(session, terminalId, onlyTabId, 'single-tab');
      return { page: only.page, cdpSession: only.cdpSession, tabId: onlyTabId };
    }
    if (only) {
      console.warn(`[browser] tab-pin-missing:single: refusing lone tab for unmatched automation (id=${terminalId}, owners=${sessionOwnerCount(session)}, claimed=${tabClaimed}) — returning 404 to avoid cross-automation leak`);
      return null;
    }
  }

  // 4. Multi-tab session with a tab-less call and no resolvable identity: FAIL CLOSED
  // for everyone (pre-existing behavior). Falling back to the shared activeTab hands
  // the caller whatever tab another automation navigated last — the exact cause of
  // cross-automation website leaks. The NI UI drives multi-tab sessions via explicit
  // tab activation / CDP input, not tab-less REST calls.
  if (session.tabs && session.tabs.size > 1) {
    console.warn(`[browser] tab-pin-missing: refusing activeTab fallback (id=${terminalId || 'none'}, tabs=${session.tabs.size}, owners=${sessionOwnerCount(session)}, persistent=${!!session._isPersistent}) — returning 404 to avoid cross-automation leak`);
    return null;
  }

  // 5. Zero/uninitialized tabs — legacy single active-tab behavior (local UI
  // session). Automations with a lost pin fail closed here too.
  if (isAutomation && sessionOwnerCount(session) > 0) {
    console.warn(`[browser] tab-pin-missing:legacy: refusing activeTab on owner-held session (id=${terminalId}, owners=${sessionOwnerCount(session)}) — returning 404 to avoid cross-automation leak`);
    return null;
  }
  // No active page at all (the last tab closed or was retired): there is nothing to route to.
  if (!session.page) return null;
  trackRoute(session, terminalId, session.activeTabId, 'legacy');
  return { page: session.page, cdpSession: session.cdpSession, tabId: session.activeTabId };
}

/** Update session-level URL/title only when operating on the active tab. */
async function syncPageState(session, routed) {
  const url = routed.page.url();
  const title = await routed.page.title().catch(() => '');
  if (routed.tabId === session.activeTabId) { session.currentUrl = url; session.title = title; }
  return { url, title };
}

function syncPageStateCompact(session, routed) {
  const url = routed.page.url();
  if (routed.tabId === session.activeTabId) session.currentUrl = url;
  return { url, title: routed.tabId === session.activeTabId ? (session.title || '') : '' };
}

async function getBrowserActionState(session, routed, compact) {
  return compact ? syncPageStateCompact(session, routed) : syncPageState(session, routed);
}

// ── Browser REST endpoints ──

app.use('/api/browser', browserRequestMiddleware);
app.use('/api/browser', (req, res, next) => { res.setHeader('X-Synabun-Browser-Default', browserDefaultSignature()); next(); });
// Agents act on the default browser only. MCP callers (browser tools, platform
// tools, batches) send X-Synabun-Terminal; the Neural Interface's own UI does not.
// While MoreLogin is the default, an agent's request on a session of managed
// Chrome or of another MoreLogin env is refused before anything runs (any page
// action, a new tab, CDP). Closing it, or listing its tabs, stays allowed.
app.use('/api/browser/sessions/:id', (req, res, next) => {
  const protectedContext = browserSessions.get(req.params.id)?.context;
  const unsafe = protectedContext?.__browserNetworkGuardError;
  if (unsafe && req.method !== 'DELETE' && !(req.method === 'GET' && req.path === '/tabs')) {
    return res.status(503).json({ error: `Browser network protection unavailable: ${unsafe}`, networkGuard: true });
  }
  // Also cancel requests already waiting/probing when the protection disappears.
  // Cancellation prevents their next page action; an action that already began
  // retains the existing truthful "outcome uncertain" response semantics.
  if (req.method !== 'DELETE' && protectedContext?.on) {
    const cancel = reason => req.browserRequest?.cancelForProtection?.(reason);
    protectedContext.on('synabun-network-guard-fault', cancel);
    const release = () => protectedContext.removeListener('synabun-network-guard-fault', cancel);
    res.once('finish', release);
    res.once('close', release);
  }
  if (!req.get('X-Synabun-Terminal') || req.method === 'DELETE' || (req.method === 'GET' && req.path === '/tabs')) return next();
  const session = browserSessions.get(req.params.id);
  if (!session) return next();
  const cfg = loadBrowserConfig();
  if (cfg.connectMode !== 'morelogin' || sessionServesMoreLoginDefault(session, cfg)) return next();
  const envId = moreLoginDefaultEnvId(cfg);
  res.status(409).json({
    error: `Session ${req.params.id} is not the default browser (${session._profileMode || 'unknown'} mode${session._mlEnvId ? `, MoreLogin env ${session._mlEnvId}` : ''}; the default is MoreLogin${envId ? ` env ${envId}` : ''}), so SynaBun's browser tools do not act on it. Leave sessionId out: browser_navigate opens the page in the default browser.`,
    code: 'NOT_DEFAULT_BROWSER',
  });
});
// Read-only semantic context for the browser judgments (the judgments themselves run in the MCP layer).
app.use('/api/browser', createBrowserAssistRouter({ browserSessions, getTargetPage, normalizeSelector }));

app.get('/api/browser/sessions', (req, res) => {
  // The server decides which sessions may carry normal-page work: with MoreLogin as
  // the default, only a MoreLogin session on the default env does (MCP callers
  // require servesDefault). Every session serves the default in other setups.
  const policyCfg = loadBrowserConfig();
  const moreLoginDefault = policyCfg.connectMode === 'morelogin';
  const sessions = [...browserSessions.entries()].map(([id, s]) => ({
    id,
    url: s.currentUrl,
    title: s.title,
    createdAt: s.createdAt,
    clients: s.clients.size,
    persistent: !!s._isPersistent,
    profileMode: s._profileMode || 'clean',
    profileSource: s._profileSourceName || null,
    moreloginEnvId: s._mlEnvId || null,
    servesDefault: moreLoginDefault ? sessionServesMoreLoginDefault(s, policyCfg) : true,
    wsEndpoint: s._isPersistent ? null : (s.browser.wsEndpoint?.() || null),
    activeTabId: s.activeTabId || null,
    loopOwned: (s._loopOwned?.size || 0) > 0,
    interactiveOwned: (s._interactiveOwned?.size || 0) > 0,
    // Also check agent registry as fallback — covers the race window between
    // session creation and agent ownership being set
    agentOwned: (s._agentOwnedSet?.size || 0) > 0 || [...agentRegistry.values()].some(a => a.status === 'running' && a.browserSessionId === id),
    // Identity → tab attribution for collision debugging:
    // `curl :3344/api/browser/sessions` shows exactly who owns which tab.
    owners: {
      loops: [...(s._loopOwned || [])],
      interactive: [...(s._interactiveOwned || [])],
      agents: [...(s._agentOwnedSet || [])],
    },
    tabOwners: s._tabOwners ? Object.fromEntries(s._tabOwners) : {},
    tabs: s.tabs ? [...s.tabs.entries()].map(([tid, t]) => ({
      id: tid,
      url: t.url,
      title: t.title,
      active: tid === s.activeTabId,
    })) : [],
  }));
  res.json({
    sessions,
    defaultBrowser: moreLoginDefault
      ? { connectMode: 'morelogin', moreloginEnvId: moreLoginDefaultEnvId(policyCfg) }
      : { connectMode: policyCfg.connectMode || null },
  });
});

app.post('/api/browser/sessions', async (req, res) => {
  const { url, width, height, screenWidth, screenHeight, deviceScaleFactor, timezone, connectMode, moreloginEnvId } = req.body;
  // A create-session startUrl that points at one of SynaBun's own live OpenCode serve ports is refused up front, like
  // navigate and new-tab: the serve's API can change what a worker session may do, and createBrowserSession navigates
  // to the startUrl while the rest of the session is still being wired. (createBrowserSession enforces the same denial
  // and installs the serve-port guard before that first navigation, for callers that do not pass through this route.)
  const serveDenial = typeof url === 'string' ? browserServePortDenial(url, liveOpencodeServePorts()) : null;
  if (serveDenial) return res.status(403).json({ error: serveDenial, servePortGuard: true });
  try {
    // Pass accept-language from the UI browser for locale matching.
    // user-agent and sec-ch-ua are NOT cloned — the automated Chrome generates its own
    // to avoid fingerprint mismatches when the UI runs in Safari/Firefox/different Chrome.
    const _realHeaders = {
      'accept-language': req.headers['accept-language'],
    };
    const result = await createBrowserSession({
      url, width, height, screenWidth, screenHeight, deviceScaleFactor, timezone, _realHeaders,
      // Optional per-session override to target a specific MoreLogin env (multi-identity)
      ...(connectMode === 'morelogin' ? { connectMode } : {}),
      ...(moreloginEnvId ? { moreloginEnvId: String(moreloginEnvId) } : {}),
    });
    // Tab ownership for the creating automation. An MCP child sends its routing
    // identity in X-Synabun-Terminal; register it as the owner of this session's
    // active tab. Without this, a plain-created tab is "unowned" and the creator's
    // tab-less calls FAIL CLOSED (getTargetPage 404) the instant another automation
    // acquires a second tab in the same shared persistent browser — the root of the
    // sidepanel-vs-CLI "lost browser session" collision. Manual NI-UI creates send
    // no header → stay unowned (legacy activeTab semantics preserved).
    const creatorTerminalId = req.get('X-Synabun-Terminal') || req.headers['x-synabun-terminal'] || null;
    if (creatorTerminalId && /^[A-Za-z0-9_-]{1,128}$/.test(creatorTerminalId)) {
      const createdSession = browserSessions.get(result.sessionId);
      if (createdSession) {
        if (!createdSession._tabOwners) createdSession._tabOwners = new Map();
        createdSession._tabOwners.set(creatorTerminalId, createdSession.activeTabId);
      }
    }
    broadcastSync({ type: 'browser:session-created', sessionId: result.sessionId, url: url || 'about:blank', profileMode: result.profileMode, profileSource: result.profileSource });
    res.json({
      sessionId: result.sessionId, url: url || 'about:blank', wsEndpoint: result.wsEndpoint, profileMode: result.profileMode, profileSource: result.profileSource,
      ...(result.moreLoginBlocked && { moreLoginBlocked: true, notice: result.moreLoginBlocked }),
    });
  } catch (err) {
    console.error('Browser session create error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

app.delete('/api/browser/sessions/:id', async (req, res) => {
  try {
    // An explicit close (browser_session close, the UI): in MoreLogin or the user's Chrome, the tabs SynaBun opened for it close too.
    await destroyBrowserSession(req.params.id, { closeOwnTabs: true });
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/browser/acquire — interactive (non-loop) MCP process claims a dedicated
// tab in the ONE shared browser instead of launching a second browser on the same
// persistent profile (which fails with "Browser profile is locked"). The clientId is
// a stable per-MCP-process id; it becomes the routing key in _tabOwners so this
// caller's tab-less browser calls (carrying X-Synabun-Terminal: <clientId>) route to
// its own tab. Body: { clientId, url? }. Returns { ok, sessionId, tabId }.
app.post('/api/browser/acquire', async (req, res) => {
  try {
    const clientId = req.body?.clientId;
    if (!clientId) return res.status(400).json({ error: 'clientId is required' });
    const acq = await acquireSharedBrowserTab({ ownerKey: clientId, ownerType: 'interactive', logTag: 'acquire:interactive' });
    if (acq.error) return res.status(500).json({ error: acq.error });
    res.json({ ok: true, sessionId: acq.browserSessionId, tabId: acq.browserTabId || null });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/browser/release — interactive MCP process relinquishes its owned tab on
// exit. Closes the dedicated tab and drops the ownership/routing entries so the shared
// browser can be grace-reaped once no owners remain. Best-effort; body: { clientId }.
app.post('/api/browser/release', async (req, res) => {
  try {
    const clientId = req.body?.clientId;
    if (!clientId) return res.status(400).json({ error: 'clientId is required' });
    let released = 0;
    for (const [sessionId, session] of browserSessions) {
      if (!session._interactiveOwned?.has(clientId)) continue;
      await releaseSharedBrowserTab(sessionId, clientId);
      released++;
    }
    res.json({ ok: true, released });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

