// ── Human-like pacing for loop-owned (scheduled automation) browser actions ──
// X shadow-bans accounts whose actions fire in superhuman bursts. These helpers
// add randomized think-time before interactions and a hard minimum gap between
// engagement writes (post/reply/like/repost/follow). Scoped STRICTLY to loop-owned
// tabs: a request is loop-owned only when its X-Synabun-Terminal header is in
// session._loopOwned. Interactive MCP callers (_interactiveOwned) and the NI web UI
// (no header) are never delayed, so manual browsing stays instant.
// Set SYNABUN_HUMAN_PACING=0 to disable globally.
const engagementScheduler = createEngagementScheduler();
const _paceRand = (min, max) => min + Math.floor(Math.random() * (max - min + 1));

function _paceTerminalId(req) {
  return (req.get && req.get('X-Synabun-Terminal')) || req.headers?.['x-synabun-terminal'] || null;
}
function isLoopPaced(session, req) {
  if (process.env.SYNABUN_HUMAN_PACING === '0') return false;
  const tid = _paceTerminalId(req);
  return !!(tid && session?._loopOwned?.has(tid));
}
async function humanThink(session, req, nonWriting = false) {
  assertBrowserRequestActive(req);
  if (!isLoopPaced(session, req) || (nonWriting && browserV2Enabled())) return;
  await measureBrowserPhase('intentionalPacing', () => cancellableBrowserDelay(_paceRand(250, 1100), req));
}
function loopTypeDelay(session, req) {
  return isLoopPaced(session, req) ? _paceRand(35, 95) : undefined;
}
// The write-selector test lives in lib/browser-execution.js (isEngagementWriteSelector) so the
// auto-heal path refuses on exactly what this queue would hold.
async function rateLimitEngagement(session, req, selector, execute) {
  if (!isLoopPaced(session, req) || !isEngagementWriteSelector(selector)) return execute();
  return engagementScheduler.run(req.params.id, req, execute);
}

// ── X/Twitter compose-state probe + publish gate ──
// Deterministic read of the X composer so loops branch on structured state instead of
// eyeballing screenshots. Lives here (not the MCP server) because the publish hard-gate
// below needs it server-side; the browser_x_compose_state MCP tool forwards to the
// /x-compose-state endpoint. Read-only DOM inspection — never types or clicks.
// quoteCard.type is the crux: 'quote' = a real embedded tweet card rendered (safe to post a
// quote); 'link' = only a plain link-preview card (posting = a bare reply); 'none' = nothing.
const X_COMPOSE_STATE_SCRIPT = `
(() => {
  const vis = el => { if (!el) return false; const r = el.getBoundingClientRect(); const cs = getComputedStyle(el); return r.width > 4 && r.height > 4 && cs.visibility !== 'hidden' && cs.display !== 'none' && el.getAttribute('aria-hidden') !== 'true'; };
  const MAXLEN = 280;
  const tas = [...document.querySelectorAll('[data-testid="tweetTextarea_0"]')];
  const visTas = tas.filter(vis);
  // Prefer the textarea inside a modal dialog (active reply), else the first visible one.
  const ta = visTas.find(t => t.closest('[role="dialog"][aria-modal="true"]')) || visTas[0] || tas[0] || null;
  const composerOpen = !!ta;
  const composerText = ta ? (ta.innerText || ta.textContent || '').replace(/\\u200b/g, '').replace(/\\u00a0/g, ' ').trim() : '';
  const charCount = composerText.length;

  // Modal = a visible centered reply dialog that contains a composer.
  const dialog = [...document.querySelectorAll('[role="dialog"][aria-modal="true"]')].filter(vis).find(d => d.querySelector('[data-testid="tweetTextarea_0"]')) || null;
  const isModal = !!dialog;

  // Submit button: prefer inline (reply) then compose; scope to the dialog if modal.
  const scope = dialog || document;
  // When a modal dialog is open, the button MUST come from inside it — falling back to
  // document.querySelector would grab an unrelated button elsewhere on the page (e.g. the
  // home feed's own always-present inline composer sitting behind the compose overlay).
  const pick = sel => { const b = dialog ? dialog.querySelector(sel) : document.querySelector(sel); return (b && vis(b)) ? b : null; };
  const inlineBtn = pick('[data-testid="tweetButtonInline"]');
  const postBtn = pick('[data-testid="tweetButton"]');
  const sEl = inlineBtn || postBtn;
  const sTestid = inlineBtn ? 'tweetButtonInline' : (postBtn ? 'tweetButton' : null);
  const submitButton = sEl ? {
    testid: sTestid, present: true,
    enabled: sEl.getAttribute('aria-disabled') !== 'true' && !sEl.disabled,
    selector: '[data-testid="' + sTestid + '"]'
  } : { testid: null, present: false, enabled: false, selector: null };

  // Quote-card detection — scope to the composer's nearest [data-testid="attachments"] region
  // (walk up from the textarea so a feed tweet behind the composer is never matched).
  let att = null, node = ta;
  for (let i = 0; i < 8 && node; i++) {
    const a = node.querySelector && node.querySelector('[data-testid="attachments"]');
    if (a) { att = a; break; }
    node = node.parentElement;
  }
  const warnings = [];
  let quoteCard = { present: false, type: 'none', author: null, handle: null, text: null, url: null };
  if (att) {
    const embText = att.querySelector('[data-testid="tweetText"]');
    const embUser = att.querySelector('[data-testid="User-Name"]');
    const embTweet = att.querySelector('[data-testid="tweet"]');
    const statusLink = att.querySelector('a[href*="/status/"]');
    const linkCard = att.querySelector('[data-testid="card.wrapper"], [data-testid^="card.layout"]');
    const isEmbeddedTweet = !!(embTweet || (embUser && embText) || (att.querySelector('time') && statusLink));
    if (isEmbeddedTweet) {
      const lines = embUser ? embUser.innerText.split('\\n').filter(Boolean) : [];
      quoteCard = { present: true, type: 'quote', author: lines[0] || null, handle: lines.find(l => l.startsWith('@')) || null, text: embText ? embText.innerText : null, url: statusLink ? statusLink.href : null };
    } else if (linkCard) {
      quoteCard = { present: true, type: 'link', author: null, handle: null, text: null, url: (att.querySelector('a[href]') || {}).href || null };
    } else if (statusLink) {
      quoteCard = { present: true, type: 'quote', author: null, handle: null, text: null, url: statusLink.href };
      warnings.push('quote card matched by structural fallback (status link in attachments, no card testid) — verify before posting');
    }
  }

  const overLimit = charCount > MAXLEN;
  const _lines = composerText.split('\\n').map(s => s.trim()).filter(s => s.length > 8);
  const hasStaleDraft = _lines.length > 1 && new Set(_lines).size < _lines.length;

  let recommendedAction = 'unknown';
  if (!composerOpen) recommendedAction = 'open-composer';
  else if (quoteCard.type === 'link') recommendedAction = 'fix-quote-url';
  else if (overLimit) recommendedAction = 'trim-text';
  else if (!composerText) recommendedAction = 'type';
  else if (submitButton.present && submitButton.enabled) recommendedAction = 'submit';

  return { composerOpen, composerText: composerText.slice(0, 600), charCount, overLimit, quoteCard, submitButton, isModal, composerCount: tas.length, hasStaleDraft, recommendedAction, warnings };
})()
`.trim();

async function getXComposeState(page) {
  const r = await page.evaluate(X_COMPOSE_STATE_SCRIPT);
  return r === undefined ? null : r;
}

// Publish hard-gate for loop-owned tabs: block a tweetButton/tweetButtonInline click that
// would publish a broken post — a status URL in the body with no quoted-tweet card rendered
// (the documented "quote misfires into a bare reply" failure), or an empty/stale composer.
// A probe error blocks the click (inspect, then retry); no composer found lets it through.
// SYNABUN_X_GATE=0 disables it. Interactive/manual tabs are never gated (same scoping as
// the rate-limiter). xGateBypassRefusal() below closes the two paths around this gate.
const _X_STATUS_URL_RE = /https?:\/\/(?:x|twitter)\.com\/[^\s]+\/status\/\d+/i;
async function xPublishGate(session, req, routed, rawSelector) {
  if (process.env.SYNABUN_X_GATE === '0') return null;
  if (!isLoopPaced(session, req)) return null;
  if (!rawSelector || !/tweetButton/.test(rawSelector)) return null;
  let st;
  try { st = await runBrowserRequest(req, () => getXComposeState(routed.page)); } catch { return { error: 'Cannot verify composer state; inspect before publishing.', quoteGuard: true }; }
  if (!st || !st.composerOpen) return null;
  const body = (st.composerText || '').trim();
  if (_X_STATUS_URL_RE.test(body) && st.quoteCard && st.quoteCard.type !== 'quote') {
    loopLog(_paceTerminalId(req), 'browser:x-gate', `blocked quote misfire (quoteCard.type=${st.quoteCard.type})`, {});
    return { error: `Publish blocked: the composer body contains a status URL but no quoted-tweet card rendered (quoteCard.type="${st.quoteCard.type}"). Posting now would publish a bare reply/link, not a quote. Wait for the card to render, fix the status URL, or skip this target — do NOT retry the same click.`, quoteGuard: true, composeState: st };
  }
  if (!body) {
    loopLog(_paceTerminalId(req), 'browser:x-gate', 'blocked empty-composer publish', {});
    return { error: 'Publish blocked: the composer is empty (nothing typed, or a stale/cleared draft). Type your content first; if old text / a "Save draft?" prompt is stuck, discard it and reopen a fresh composer.', quoteGuard: true, composeState: st };
  }
  return null;
}

// Publishing on X must go through a tweetButton click so xPublishGate and the write
// queue see it. On loop-owned tabs, refuse the two ways around that: a Cmd/Ctrl+Enter
// press in the composer, and a browser_evaluate script that clicks a write control.
function xGateBypassRefusal(session, req, routed, kind, payload) {
  if (process.env.SYNABUN_X_GATE === '0' || !isLoopPaced(session, req)) return null;
  let url = '';
  try { url = routed.page.url(); } catch { return null; }
  const hit = kind === 'press' ? isXShortcutPublish(payload, url) : isXScriptedWrite(payload, url);
  if (!hit) return null;
  loopLog(_paceTerminalId(req), 'browser:x-gate', `refused ${kind === 'press' ? 'keyboard-shortcut publish' : 'scripted write click'}`, {});
  return {
    error: kind === 'press'
      ? 'Publish blocked: keyboard-shortcut publishing is disabled on automation tabs. Call browser_x_compose_state, then browser_click its submitButton.selector.'
      : 'Blocked: browser_evaluate may not click X publish, like, repost or follow controls on automation tabs. Use browser_click on the control (after browser_x_compose_state for posts).',
    quoteGuard: true,
  };
}

/**
 * Exempt ONE session from the money-safety guard, for deliberate ads work (reviewing a
 * paused campaign, setting Business Suite ad-account rules). The exemption is scoped to
 * this session and dies with it, so autonomous organic loops running alongside keep all
 * three guard layers. Re-arm with {allow:false}. See MONEY_GUARD_MSG.
 */
app.post('/api/browser/sessions/:id/paid-surfaces', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const allow = req.body?.allow === true;
  try {
    if (allow) {
      // Drop the context-level abort route; the per-call guards read the flag directly.
      if (session.context) await setBrowserNetworkRule(session.context, 'money', null);
      if (session.context) session.context.__moneyGuardInstalled = false;
    } else if (session.context) {
      await installMoneyGuardRoute(session.context);
    }
  } catch (e) {
    return res.status(500).json({ error: `Failed to ${allow ? 'lift' : 'restore'} the network guard: ${e.message}` });
  }
  session.allowPaidAdsSurfaces = allow;
  console.warn(`[money-guard] ${allow ? 'LIFTED (ads work)' : 'restored'} for session ${req.params.id}`);
  res.json({ ok: true, sessionId: req.params.id, allowPaidAdsSurfaces: allow });
});

app.post('/api/browser/sessions/:id/navigate', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const { url, returnSnapshot, snapshot, compact } = req.body;
  if (moneyGuardActive(session) && typeof url === 'string' && MONEY_URL_RE.test(url)) {
    return res.status(400).json({ error: `Blocked navigation to a paid Facebook ads/boost/billing surface (${url.slice(0, 80)}). ${MONEY_GUARD_MSG}`, moneyGuard: true });
  }
  const servePort = typeof url === 'string' ? browserServePortDenial(url, liveOpencodeServePorts()) : null;
  if (servePort) return res.status(403).json({ error: servePort, servePortGuard: true });

  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session` });
  const circuit = activeBrowserNavigationCircuit(session, routed.tabId, url);
  if (circuit) {
    return res.status(409).json({
      error: `Navigation temporarily blocked: this URL wedged tab ${routed.tabId} less than two minutes ago. Skip it or use an alternate route; retrying now would wedge the replacement page again.`,
      navigationCircuitOpen: true,
      retryAfterMs: circuit.remainingMs,
    });
  }
  try {
    await humanThink(session, req, true);
    markBrowserActionStarted(req);
    const response = await measureBrowserPhase('action', () => routed.page.goto(url, { waitUntil: 'domcontentloaded', timeout: browserActionTimeout(req, 15000) }));
    let httpStatus = null;
    try { httpStatus = response ? response.status() : null; } catch { httpStatus = null; }
    clearBrowserNavigationWedge(session, routed.tabId, url);
    const state = await getBrowserActionState(session, routed, compact);
    const blocked = moreLoginBlockError(session, url, state.url);
    if (blocked) return res.status(502).json({ error: blocked, moreLoginBlocked: true, landedUrl: state.url });
    const body = { ok: true, url: state.url, title: state.title };
    if (snapshot && snapshot !== 'none') {
      await settleAfterAction(routed.page);
      const snap = await buildSnapshotResponse(routed.page, {
        mode: 'ai',
        diff: snapshot === 'diff',
        maxChars: req.body.snapshotMaxChars || 12000,
        ...snapshotRequestOptions(req, res, req.params.id, routed),
      }).catch(err => ({ snapshotText: null, snapshotError: err.message }));
      Object.assign(body, snap);
    } else if (returnSnapshot) {
      const snap = await buildSnapshotResponse(routed.page, {
        scopeSel: returnSnapshot.selector ? normalizeSelector(returnSnapshot.selector) : null,
        mode: returnSnapshot.mode,
        viewport: returnSnapshot.viewport,
        ...snapshotRequestOptions(req, res, req.params.id, routed),
      }).catch(err => ({ snapshot: null, snapshotError: err.message }));
      Object.assign(body, snap);
    }
    // Bounded, value-free context for the page-state judgment, in the same round
    // trip. A plain DOM scan (never a snapshot, which would replace the refs just
    // delivered), time-boxed, and its failure never fails the navigation.
    if (req.body.semanticContext === true && req.get('X-Synabun-Batch') !== '1') {
      try {
        if (!(snapshot && snapshot !== 'none')) await settleAfterAction(routed.page);
        body.semanticContext = await runBrowserRequest(req, () => measureBrowserPhase('semanticContext',
          () => collectSemanticContext(routed.page, { purpose: 'navigation', httpStatus })), 1500);
      } catch { body.semanticContextError = 'unavailable'; }
    }
    res.json(body);
  } catch (err) {
    const recovery = await recoverBrowserRouteFailure(session, req.params.id, routed, req, 'navigate', err);
    if (recovery?.recovered) rememberBrowserNavigationWedge(session, routed.tabId, url, err);
    res.status(500).json({
      error: browserRecoveryErrorMessage(err, recovery),
      ...(recovery && { tabRecovered: !!recovery.recovered }),
      ...(recovery?.sessionInvalidated && { sessionInvalidated: true }),
    });
  }
});

