app.post('/api/browser/sessions/:id/press', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session` });
  const { key, compact } = req.body;
  if (!key) return res.status(400).json({ error: 'key required' });
  const xRefusal = xGateBypassRefusal(session, req, routed, 'press', key);
  if (xRefusal) return res.status(409).json(xRefusal);
  try {
    await humanThink(session, req);
    markBrowserActionStarted(req);
    await routed.page.keyboard.press(key);
    const state = await getBrowserActionState(session, routed, compact);
    res.json({ ok: true, url: state.url, title: state.title });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/browser/sessions/:id/evaluate', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session` });
  const { script } = req.body;
  if (!script) return res.status(400).json({ error: 'script required' });
  const xRefusal = xGateBypassRefusal(session, req, routed, 'evaluate', script);
  if (xRefusal) return res.status(409).json(xRefusal);
  try {
    markBrowserActionStarted(req);
    const result = await withBrowserOperationDeadline(
      routed.page.evaluate(script),
      BROWSER_EVALUATE_DEADLINE_MS,
      'browser_evaluate',
    );
    // Ensure result is JSON-serializable (undefined becomes null)
    res.json({ ok: true, result: result === undefined ? null : result });
  } catch (err) {
    const recovery = await recoverBrowserRouteFailure(session, req.params.id, routed, req, 'evaluate', err);
    res.status(500).json({
      error: browserRecoveryErrorMessage(err, recovery),
      ...(recovery && { tabRecovered: !!recovery.recovered }),
      ...(recovery?.sessionInvalidated && { sessionInvalidated: true }),
    });
  }
});

// Read-only structured state of the X/Twitter composer (text, quote card, submit button,
// modal, stale-draft). Backs the browser_x_compose_state MCP tool and shares its detection
// with the loop publish gate above. Same single source of truth — no duplicated script.
app.post('/api/browser/sessions/:id/x-compose-state', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session` });
  try {
    const result = await getXComposeState(routed.page);
    res.json({ ok: true, result });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Upload a local image file as a BlueSky blob. The MCP page context can't read
// local disk, so the upload happens here: read the file, pull the logged-in
// session token + PDS host from the bsky.app tab, and POST the bytes to
// com.atproto.repo.uploadBlob. Returns the AT Protocol blob ref for embedding.
app.post('/api/browser/sessions/:id/bluesky/upload-blob', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session` });
  const { filePath } = req.body || {};
  if (!filePath) return res.status(400).json({ error: 'filePath required' });
  try {
    if (!existsSync(filePath) || !statSync(filePath).isFile()) {
      return res.status(400).json({ error: `File not found: ${filePath}` });
    }
    // Read the BlueSky session token + PDS host from the logged-in page.
    const sess = await routed.page.evaluate(() => {
      try {
        const raw = localStorage.getItem('BSKY_STORAGE');
        if (!raw) return null;
        const j = JSON.parse(raw);
        const s = j.session || j;
        const a = s.currentAccount || (Array.isArray(s.accounts) && (s.accounts.find(x => x && x.active && x.accessJwt) || s.accounts[0]));
        if (!a || !a.accessJwt || !a.did) return null;
        const pdsUrl = String(a.pdsUrl || a.service || 'https://bsky.social').replace(/[/]+$/, '');
        return { accessJwt: a.accessJwt, did: a.did, pdsUrl };
      } catch (e) { return null; }
    });
    if (!sess) return res.status(400).json({ error: 'Not logged in to BlueSky on this tab (no session token). Open bsky.app and sign in.' });

    const bytes = readFileSync(filePath);
    const ext = (filePath.split('.').pop() || '').toLowerCase();
    const ctMap = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', gif: 'image/gif', webp: 'image/webp' };
    const contentType = ctMap[ext] || 'image/jpeg';

    const up = await fetch(`${sess.pdsUrl}/xrpc/com.atproto.repo.uploadBlob`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${sess.accessJwt}`, 'Content-Type': contentType },
      body: bytes,
    });
    const data = await up.json().catch(() => null);
    if (!up.ok) return res.status(502).json({ error: `uploadBlob failed (${up.status}): ${(data && data.error) || ''}` });
    if (!data || !data.blob) return res.status(502).json({ error: 'uploadBlob returned no blob' });
    res.json({ ok: true, blob: data.blob });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/browser/sessions/:id/snapshot', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.query?.tabId} not found in session` });
  try {
    // page.accessibility was removed in Playwright 1.50+
    let tree = null;
    if (routed.page.accessibility && typeof routed.page.accessibility.snapshot === 'function') {
      tree = await routed.page.accessibility.snapshot();
    } else {
      // Fallback: build a tree from ariaSnapshot text
      const ariaText = await routed.page.locator('body').ariaSnapshot({ timeout: 5000 }).catch(() => null);
      if (ariaText) {
        tree = parseAriaSnapshotText(ariaText);
      }
    }
    const state = await syncPageState(session, routed);
    res.json({ ok: true, url: state.url, title: state.title, snapshot: tree });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/browser/sessions/:id/snapshot', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session` });
  const { selector: rawSel, mode, viewport, depth, diff, force, maxChars, baselineId, includeFullText } = req.body || {};
  const scopeSel = rawSel ? normalizeSelector(rawSel) : null;
  try {
    const payload = await buildSnapshotResponse(routed.page, {
      scopeSel, mode, viewport, depth, diff, force, maxChars, baselineId, includeFullText: includeFullText === true,
      ...snapshotRequestOptions(req, res, req.params.id, routed),
    });
    const state = await syncPageState(session, routed);
    res.json({ ok: true, url: state.url, title: state.title, ...payload });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── AI ref-based snapshots ──
// Playwright keeps refs stable for unchanged elements in the latest captured scope.
// Caller, document, scope and budget must all match before reusing an observation.
const aiSnapshots = createAiSnapshotStore({ enabled: browserV2Enabled, measure: measureBrowserPhase });
// Single-use heal contexts minted by the click route after a confirmed pre-action failure.
const assistContexts = createAssistContextStore();

function aiSnapshotKey(sessionId, routed, req) {
  const caller = req.get?.('X-Synabun-Terminal') || req.headers?.['x-synabun-terminal'] || 'ui';
  return `${sessionId}:${routed?.tabId || 'main'}:${caller}`;
}

function snapshotRequestOptions(req, res, sessionId, routed) {
  return {
    aiCacheKey: aiSnapshotKey(sessionId, routed, req),
    baselineId: req.body?.snapshotBaselineId || req.body?.baselineId,
    assertActive: () => assertBrowserRequestActive(req),
    onDelivered: commit => res.once('finish', () => {
      if (res.statusCode < 400 && !req.aborted) commit();
    }),
  };
}

function clearAiSnapshotCache(sessionId, tabId) {
  aiSnapshots.clear(sessionId, tabId);
}

// Resolve an element ref minted by the latest AI snapshot of this tab.
async function resolveRefLocator(page, ref) {
  const clean = String(ref).trim().replace(/^(?:\[?ref=)/, '').replace(/\]$/, '');
  const loc = page.locator(`aria-ref=${clean}`);
  let count = 0;
  try { count = await loc.count(); } catch { count = 0; }
  if (count !== 1) {
    return { error: {
      error: `Ref ${clean} not found in the current page snapshot — the page changed. Call browser_snapshot to get fresh refs.`,
      staleRef: true,
    } };
  }
  return { target: loc, healed: false };
}

// Bounded settle before post-action snapshots: let handlers fire / navigation start,
// wait for DOM if a navigation did start, then flush a paint.
async function settleAfterAction(page, cap = 800) {
  return measureBrowserPhase('readiness', () => settleBrowserPage(page, { cap, v2: browserV2Enabled() }));
}

// Build snapshot payload shared between the snapshot endpoints and the combined
// action-and-snapshot endpoints. Honors mode (ai/full/interactive/landmarks) and viewport filter.
async function buildSnapshotResponse(page, opts = {}) {
  const { scopeSel, mode = 'full', viewport = false } = opts;

  // mode=ai: compact YAML with [ref=eN] element references (token-efficient default).
  if (mode === 'ai') {
    return aiSnapshots.build(page, opts);
  }

  // mode=interactive: skip the tree entirely — return a flat list of interactive elements.
  if (mode === 'interactive') {
    const interactive = await getInteractiveHints(page, { limit: 200, viewportOnly: !!viewport });
    return { snapshot: null, interactive, mode };
  }

  let tree = null;
  if (scopeSel) {
    const ariaText = await page.locator(scopeSel).ariaSnapshot({ timeout: 8000 }).catch(() => null);
    if (ariaText) tree = parseAriaSnapshotText(ariaText);
  } else if (page.accessibility && typeof page.accessibility.snapshot === 'function') {
    tree = await page.accessibility.snapshot();
  } else {
    const ariaText = await page.locator('body').ariaSnapshot({ timeout: 5000 }).catch(() => null);
    if (ariaText) tree = parseAriaSnapshotText(ariaText);
  }

  if (viewport && tree) {
    const nameBox = await getViewportNamedRects(page).catch(() => new Map());
    tree = filterTreeByViewport(tree, nameBox);
  }

  return { snapshot: tree, mode };
}

// Build a {lowercase-name → true} set of element names that are currently in-viewport.
// Used to drop ax-tree nodes whose name doesn't match any visible DOM element name.
async function getViewportNamedRects(page) {
  const names = await page.evaluate(() => {
    const out = new Set();
    const els = document.querySelectorAll(
      'button, a, input, textarea, select, [role], [aria-label], h1, h2, h3, h4, h5, h6'
    );
    for (const el of els) {
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) continue;
      if (r.top >= window.innerHeight || r.bottom <= 0) continue;
      const name = (el.getAttribute('aria-label') || el.innerText || '').trim();
      if (name) out.add(name.slice(0, 120).toLowerCase());
    }
    return Array.from(out);
  });
  return new Set(names);
}

function filterTreeByViewport(node, names) {
  if (!node || typeof node !== 'object') return node;
  const keep = !node.name || names.has(String(node.name).toLowerCase());
  const children = Array.isArray(node.children) ? node.children : [];
  const keptChildren = children.map(c => filterTreeByViewport(c, names)).filter(c => c && (c.name || (c.children && c.children.length)));
  if (keep || keptChildren.length > 0) {
    return { ...node, children: keptChildren };
  }
  return null;
}

// Parse Playwright's ariaSnapshot YAML-like text into a tree structure
function parseAriaSnapshotText(text) {
  if (!text) return null;
  const lines = text.split('\n').filter(l => l.trim());
  if (lines.length === 0) return null;

  const root = { role: 'document', name: '', children: [] };
  const stack = [{ node: root, indent: -1 }];

  for (const line of lines) {
    const stripped = line.replace(/^\s*- /, '');
    const indent = line.length - line.trimStart().length;

    // Parse "role "name"" or "role "name": value"
    const match = stripped.match(/^(\w+)(?:\s+"([^"]*)")?(?::\s*(.*))?$/);
    if (!match) continue;

    const node = {
      role: match[1] || 'generic',
      name: match[2] || '',
      children: [],
    };
    if (match[3]) node.value = match[3];

    while (stack.length > 1 && stack[stack.length - 1].indent >= indent) {
      stack.pop();
    }
    stack[stack.length - 1].node.children.push(node);
    stack.push({ node, indent });
  }

  return root.children.length === 1 ? root.children[0] : root;
}

app.post('/api/browser/sessions/:id/wait', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session` });
  const { selector, state, loadState, timeout, compact } = req.body;
  try {
    if (loadState) {
      const valid = ['load', 'domcontentloaded', 'networkidle'];
      if (!valid.includes(loadState)) return res.status(400).json({ error: `Invalid loadState. Use: ${valid.join(', ')}` });
      await routed.page.waitForLoadState(loadState, { timeout: timeout || 15000 });
      const ps = await getBrowserActionState(session, routed, compact);
      res.json({ ok: true, loadState, url: ps.url, title: ps.title });
    } else if (selector) {
      await routed.page.locator(selector).waitFor({
        state: state || 'visible',
        timeout: timeout || 10000,
      });
      res.json({ ok: true, selector, state: state || 'visible' });
    } else {
      await routed.page.waitForTimeout(timeout || 1000);
      const ps = await getBrowserActionState(session, routed, compact);
      res.json({ ok: true, url: ps.url, title: ps.title });
    }
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/browser/sessions/:id/extract', async (req, res) => {
  if (!browserV2Enabled()) return res.status(409).json({ error: 'Server-side extraction is disabled by SYNABUN_BROWSER_V2=0. Remove the override to restore the default browser engine.', actionStarted: false });
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found', actionStarted: false });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session`, actionStarted: false });
  const { script, ...opts } = req.body;
  if (typeof script !== 'string' || !script.trim()) return res.status(400).json({ error: 'script required', actionStarted: false });
  for (const name of ['scrolls', 'minItems', 'maxItems', 'maxChars', 'timeoutMs', 'settleMs']) {
    if (opts[name] !== undefined && (!Number.isInteger(opts[name]) || opts[name] < (name === 'scrolls' ? 0 : name === 'maxChars' ? 2 : 1))) {
      return res.status(400).json({ error: `${name} must be a ${name === 'scrolls' ? 'nonnegative' : 'positive'} integer`, actionStarted: false });
    }
  }
  for (const name of ['fields', 'dedupeKeys']) {
    if (opts[name] !== undefined && (!Array.isArray(opts[name]) || opts[name].some(key => typeof key !== 'string' || !key))) {
      return res.status(400).json({ error: `${name} must be an array of nonempty strings`, actionStarted: false });
    }
  }
  try {
    assertBrowserRequestActive(req);
    markBrowserActionStarted(req);
    const result = await runBrowserExtraction(routed.page, script, opts, {
      signal: req.browserRequest?.signal,
      deadline: req.browserRequest?.deadline,
      measure: measureBrowserPhase,
    });
    res.json({ ok: !result.error, url: routed.page.url(), ...result });
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

app.get('/api/browser/sessions/:id/content', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.query?.tabId} not found in session` });
  try {
    const state = await syncPageState(session, routed);
    let text = '';
    if (req.query?.selector) {
      const target = routed.page.locator(String(req.query.selector));
      if (await target.count() !== 1) return res.status(400).json({ error: 'Content selector must match exactly one element.' });
      text = await target.innerText({ timeout: 5000 });
    } else {
      try { text = await routed.page.innerText('body'); } catch { text = ''; }
    }
    const totalChars = text.length;
    const offset = Math.max(0, parseInt(req.query?.offset, 10) || 0);
    const maxChars = Math.max(1, parseInt(req.query?.maxChars, 10) || 50000);
    if (offset > 0 || totalChars > offset + maxChars) {
      const slice = text.slice(offset, offset + maxChars);
      const more = totalChars > offset + maxChars;
      text = slice + (more ? `\n... (truncated — ${totalChars} chars total, pass offset=${offset + maxChars} to continue)` : '');
    }
    res.json({ ok: true, url: state.url, title: state.title, text, totalChars, ...(req.query?.selector ? { selector: req.query.selector } : {}) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Shared NHM instance (reuse = 1.57x faster than turndown)
const nhm = new NodeHtmlMarkdown({
  preferNativeParser: false,
  codeFence: '```',
  bulletMarker: '-',
  codeBlockStyle: 'fenced',
  emDelimiter: '*',
  strongDelimiter: '**',
  maxConsecutiveNewlines: 2,
});

app.get('/api/browser/sessions/:id/markdown', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.query?.tabId} not found in session` });
  try {
    const state = await syncPageState(session, routed);

    // Extract main content HTML — strip nav, header, footer, sidebar, ads
    let html = '';
    if (req.query?.selector || browserV2Enabled()) {
      html = await readBrowserContentHtml(routed.page, req.query?.selector ? String(req.query.selector) : undefined);
    } else try {
      html = await routed.page.evaluate(() => {
        // Remove noise elements before extraction
        const removeSelectors = [
          'nav', 'header', 'footer', 'aside',
          '[role="navigation"]', '[role="banner"]', '[role="contentinfo"]', '[role="complementary"]',
          '.sidebar', '.nav', '.footer', '.header', '.advertisement', '.ad', '.ads',
          '[class*="cookie"]', '[class*="popup"]', '[class*="modal"]', '[class*="overlay"]',
          'script', 'style', 'noscript', 'iframe',
        ];
        // Clone body so we don't mutate the live page
        const clone = document.body.cloneNode(true);
        for (const sel of removeSelectors) {
          clone.querySelectorAll(sel).forEach(el => el.remove());
        }
        // Prefer <main> or <article> if they exist
        const main = clone.querySelector('main') || clone.querySelector('article') || clone.querySelector('[role="main"]');
        return (main || clone).innerHTML;
      });
    } catch { html = ''; }

    if (!html) {
      return res.json({ ok: true, url: state.url, title: state.title, markdown: '', tokens: 0 });
    }

    let markdown = nhm.translate(html);
    const totalChars = markdown.length;
    const estimatedTokens = Math.ceil(totalChars / 4); // ~4 chars per token estimate

    const offset = Math.max(0, parseInt(req.query?.offset, 10) || 0);
    const maxChars = Math.max(1, parseInt(req.query?.maxChars, 10) || 80000);
    if (offset > 0 || totalChars > offset + maxChars) {
      const slice = markdown.slice(offset, offset + maxChars);
      const more = totalChars > offset + maxChars;
      markdown = slice + (more ? `\n\n... (truncated — ${totalChars} chars total, pass offset=${offset + maxChars} to continue)` : '');
    }

    res.json({ ok: true, url: state.url, title: state.title, markdown, tokens: estimatedTokens, totalChars, ...(req.query?.selector ? { selector: req.query.selector } : {}) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/fetch-markdown', async (req, res) => {
  const { url, timeout } = req.body;
  if (!url) return res.status(400).json({ error: 'url is required' });
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout || 15000);

    const response = await fetch(url, {
      headers: {
        'Accept': 'text/markdown, text/html, */*',
        'User-Agent': 'SynaBun/1.0 (AI Agent; +https://synabun.ai)',
      },
      signal: controller.signal,
      redirect: 'follow',
    });
    clearTimeout(timer);

    const contentType = response.headers.get('content-type') || '';
    const markdownTokens = response.headers.get('x-markdown-tokens');
    const contentSignal = response.headers.get('content-signal');
    const body = await response.text();

    // If server returned markdown natively (content negotiation worked!)
    const isMarkdown = contentType.includes('text/markdown');

    let markdown;
    if (isMarkdown) {
      markdown = body;
    } else {
      // Convert HTML to markdown client-side
      markdown = nhm.translate(body);
    }

    const estimatedTokens = markdownTokens ? parseInt(markdownTokens, 10) : Math.ceil(markdown.length / 4);

    if (markdown.length > 80000) {
      markdown = markdown.slice(0, 80000) + '\n\n... (truncated at 80K chars)';
    }

    res.json({
      ok: true,
      url: response.url, // final URL after redirects
      markdown,
      tokens: estimatedTokens,
      negotiated: isMarkdown, // true = server returned markdown natively
      contentSignal: contentSignal || null,
      status: response.status,
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET …/screenshot-base64 — what browser_screenshot shows, plus breakpoint sizes
// (width / height), full page and saving to a file (lib/browser-screenshot.js).
// The capture, putting the tab back and the state read after it share one budget,
// the request deadline: the answer names the phase a capture stopped in and never
// waits past it. A tab whose own width, height and devicePixelRatio could not be
// confirmed when the capture answers is retired: out of routing at once, then
// closed, so no page — a MoreLogin profile's above all — keeps a size, DPR or
// mobile flag it never had. The result says so, and says "closed" only when the
// close was confirmed.
const SCREENSHOT_TAB_CLOSED = 'SynaBun could not confirm the tab was back at its own viewport size after the capture, so it closed the tab; the next browser call opens a fresh one.';
const SCREENSHOT_TAB_UNROUTED = 'SynaBun could not confirm the tab was back at its own viewport size after the capture, so it took the tab out of routing; closing it was not confirmed, so it may still be open in the browser window. The next browser call opens a fresh one.';
// What building and sending the answer may take, out of the request deadline (a quarter of a deadline under four times this).
const SCREENSHOT_ANSWER_MARGIN_MS = 500;
// The longest the title read after a capture may take; never past the budget.
const SCREENSHOT_STATE_READ_MS = 1000;

/**
 * Take a tab out of routing now, whatever becomes of its page: no later call
 * reaches it (getTargetPage answers 404, and the caller's next browser call
 * opens a fresh tab). What the page's close event does for a tab that closed,
 * done here because that event is ignored for a tab no longer registered. Only
 * while the tab id still names `page`: a wedged tab replaced meanwhile
 * (recoverSessionTabPage keeps the id) has a fresh page under it, which stays.
 *
 * The registry entry and every alias of the page (session.page, cdpSession,
 * activeTabId) go in the same tick, before anything is awaited or anyone is
 * told: the switch to another tab is asynchronous and re-validates its target,
 * so neither a second retirement in the same turn nor a screencast stop that
 * hangs can leave the session pointing at a retired page. A client that cannot
 * be told changes none of this. Announced as `browser:tab-retired`: the tab
 * left routing; `browser:tab-closed` follows only when the close is confirmed.
 */
function unrouteScreenshotTab(session, sessionId, tabId, page) {
  if (session.tabs?.get(tabId)?.page !== page) return;
  session.tabs.delete(tabId);
  const wasActive = session.activeTabId === tabId || session.page === page;
  if (wasActive) {
    session.activeTabId = null;
    session.page = null;
    session.cdpSession = null;
    session.currentUrl = 'about:blank';
    session.title = '';
  }
  // What follows only tells others; none of it may undo or skip the above.
  const quietly = (what, work) => { try { work(); } catch (error) { console.warn(`[browser] retiring tab ${tabId} of session ${sessionId}: ${what} failed: ${error.message}`); } };
  quietly('clearing its snapshot cache', () => clearAiSnapshotCache(sessionId, tabId));
  // The session moves on to a tab that is left, also when an earlier retirement in this turn left it without one.
  if (wasActive || session.activeTabId == null) {
    const next = session.tabs.keys().next().value;
    if (next !== undefined) {
      _switchSessionTab(session, sessionId, next).catch(() => {});
    } else {
      session.clients?.forEach((ws) => quietly('telling a client that all tabs closed', () => {
        if (ws.readyState === 1) {
          ws.send(JSON.stringify({ type: 'error', message: 'All tabs closed' }));
          ws.close(1000, 'All tabs closed');
        }
      }));
      quietly('forgetting the clients', () => session.clients?.clear());
    }
  }
  quietly('announcing it', () => broadcastSync({ type: 'browser:tab-retired', sessionId, tabId, remainingTabs: session.tabs.size }));
}
/**
 * Retire a tab after a screenshot: out of routing before anything is awaited,
 * then closed. `reason` is 'size' (its viewport could not be confirmed restored)
 * or 'pending' (a capture of it may still be pending for good). The close is
 * attempted whatever taking it out of routing and telling the clients did.
 * `closed` settles true only when the page reports itself closed, and only then
 * is `browser:tab-closed` announced; a close that fails, or never answers,
 * leaves it false or pending, and the log says which.
 */
function retireScreenshotTab(session, sessionId, routed, reason = 'size') {
  console.warn(`[browser] retiring tab ${routed.tabId} of session ${sessionId}: ${reason === 'pending'
    ? 'a screenshot of it got no answer and may still be pending (its CDP session was never confirmed detached)'
    : 'its viewport was not confirmed restored after a screenshot'}`);
  // A wedged tab replaced meanwhile keeps its id for a fresh page: that tab neither left routing nor closes.
  const registered = session.tabs?.get(routed.tabId)?.page === routed.page;
  try {
    unrouteScreenshotTab(session, sessionId, routed.tabId, routed.page);
  } catch (error) {
    console.warn(`[browser] taking retired tab ${routed.tabId} of session ${sessionId} out of routing failed part-way: ${error.message}`);
  }
  const closed = (async () => {
    try {
      await routed.page.close();
    } catch (error) {
      console.warn(`[browser] closing retired tab ${routed.tabId} of session ${sessionId} failed: ${error.message}`);
    }
    const confirmed = routed.page.isClosed?.() === true;
    if (confirmed) {
      console.log(`[browser] Retired tab ${routed.tabId} closed in session ${sessionId} (remaining: ${session.tabs.size})`);
      if (registered) try { broadcastSync({ type: 'browser:tab-closed', sessionId, tabId: routed.tabId, remainingTabs: session.tabs.size }); } catch { /* the tab is closed either way */ }
    } else {
      console.warn(`[browser] retired tab ${routed.tabId} of session ${sessionId} is out of routing but its close was not confirmed; it may still be open in the browser window`);
    }
    return confirmed;
  })();
  return { closed };
}
/**
 * One line per capture, success or failure, so what a capture depends on can be
 * read back later (docs/browser-v2.md, "Reading the screenshot log"): session
 * and tab, the window state CDP reported (for a failure the one read when it
 * stopped, with `windowAtStart` when the one read as the capture began was
 * another), whether the tab was the selected one as far as the server can tell
 * (selectedTabReading: inferred from the order tabs were opened in, not
 * measured), the outcome, the phase of a failure and the duration. A run's line
 * also goes to its own log file.
 */
function logScreenshotCapture(req, sessionId, tabId, selected, record) {
  const caller = (req.get && req.get('X-Synabun-Terminal')) || req.headers?.['x-synabun-terminal'] || null;
  // The id names the log file: anything but a plain id goes to the console only.
  const owner = typeof caller === 'string' && /^[\w-]{1,120}$/.test(caller) ? caller : null;
  loopLog(owner, 'browser:screenshot',
    `session=${sessionId} tab=${tabId} window=${record.windowState || 'unknown'} selected=${selected.reading} outcome=${record.outcome}${record.phase ? ` phase=${record.phase}` : ''} ms=${record.ms}`,
    {
      selectedBasis: selected.basis,
      ...(record.code && { code: record.code }),
      ...(record.windowAtStart !== record.windowState && { windowAtStart: record.windowAtStart || 'unknown' }),
      ...(record.tab !== 'untouched' && { tabAfter: record.tab }),
      ...(record.tab === 'retired' && { tabClosed: record.tabClosed === true }),
      ...(record.capturePending && { capturePending: true }),
    });
}
app.get('/api/browser/sessions/:id/screenshot-base64', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.query?.tabId} not found in session` });
  let options;
  try {
    options = parseScreenshotOptions(req.query);
    const refusal = options.path ? screenshotPathRefusal(options.path, { dataHome: DATA_HOME }) : null;
    if (refusal) return res.status(400).json({ error: refusal });
  } catch (err) {
    return res.status(err.status || 400).json({ error: err.message });
  }
  const started = Date.now();
  // One budget for the capture, putting the tab back and the state read: the
  // request deadline, less what sending the answer takes. The capture itself is
  // given up on earlier (lib), so this route says which phase stopped it; at the
  // deadline the caller would only see a bare timeout.
  const requestDeadline = req.browserRequest ? req.browserRequest.deadline : started + 60_000;
  const answerBy = requestDeadline - Math.min(SCREENSHOT_ANSWER_MARGIN_MS, Math.max(0, requestDeadline - started) / 4);
  // Read before the capture: what the tab was when it began.
  const selected = selectedTabReading(routed.page);
  const known = session.tabs?.get(routed.tabId)?.title || '';
  let record = null;
  // The log line is built and written once the answer is with the operating
  // system (or the client is gone), and guarded: a sink that throws or does not
  // return costs the line, never the answer, its status or its time.
  let logged = false;
  const logCapture = () => {
    if (logged || !record) return;
    logged = true;
    try {
      logScreenshotCapture(req, req.params.id, routed.tabId, selected, record);
    } catch (error) {
      try { console.warn(`[browser] screenshot log line not written: ${error.message}`); } catch { /* nothing left to tell */ }
    }
  };
  try {
    const shot = await captureScreenshot(routed.page, options, {
      deadline: answerBy,
      // Ends the capture early when the request is aborted; the deadline is the lib's.
      runBounded: (work) => runBrowserRequest(req, work, 120_000),
      retire: (reason) => retireScreenshotTab(session, req.params.id, routed, reason),
      onRecord: (entry) => { record = entry; },
    });
    const retired = shot.tab === 'retired';
    // The title read gets what is left of the budget; a retired tab is not asked.
    const url = routed.page.url();
    let title = known;
    if (!retired) {
      let timer;
      const read = await Promise.race([
        routed.page.title().catch(() => ''),
        new Promise((done) => { timer = setTimeout(() => done(null), Math.max(1, Math.min(SCREENSHOT_STATE_READ_MS, answerBy - Date.now()))); }),
      ]);
      clearTimeout(timer);
      if (read !== null) {
        title = read;
        if (routed.tabId === session.activeTabId) { session.currentUrl = url; session.title = title; }
      }
    }
    let savedPath = null;
    if (shot.fileData) {
      const target = options.path
        ? resolve(options.path)
        : defaultScreenshotPath({ dataHome: DATA_HOME, pageUrl: url, width: shot.width, height: shot.height, format: options.fileFormat });
      // Checked again as it is written: the capture may have taken a minute.
      savedPath = writeScreenshotFile(target, Buffer.from(shot.fileData, 'base64'), { dataHome: DATA_HOME });
    }
    res.json({
      ok: true, url, title,
      data: shot.data, mime: shot.mime,
      width: shot.width, height: shot.height, imageWidth: shot.imageWidth, imageHeight: shot.imageHeight,
      fullPage: shot.fullPage,
      ...(shot.truncated && { truncated: true }),
      ...(shot.emulated && { viewport: shot.emulated }),
      ...(savedPath && { savedPath, format: options.fileFormat }),
      ...(retired && { tabRetired: true, tabClosed: shot.tabClosed === true, notice: shot.tabClosed === true ? SCREENSHOT_TAB_CLOSED : SCREENSHOT_TAB_UNROUTED }),
    });
  } catch (err) {
    // A failure of the capture itself, not of what came after it (the file).
    const captureFailed = !!record && record.outcome !== 'ok';
    // What became of the tab is said either way: a capture that worked can have retired it too.
    const retired = record?.tab === 'retired';
    const closed = record?.tabClosed === true;
    const after = retired ? (closed ? SCREENSHOT_TAB_CLOSED : SCREENSHOT_TAB_UNROUTED) : captureFailed && record.tab === 'restored' ? 'The tab is back at its own size.' : '';
    res.status(err.status || 500).json({
      error: after ? `${err.message}${/[.!?]$/.test(err.message) ? '' : '.'} ${after}` : err.message,
      ...(err.code && { code: err.code }),
      ...(err.phase && { phase: err.phase }),
      // What the capture depends on, for a caller that reads fields: the window state CDP reported when the
      // capture stopped (with the one from when it began, when that was another) and the selected-tab reading.
      ...(captureFailed && { windowState: err.windowState ?? null, ...((err.windowAtStart ?? null) !== (err.windowState ?? null) && { windowAtStart: err.windowAtStart ?? null }), selectedTab: selected.reading }),
      ...(retired && { tabRetired: true, tabClosed: closed }),
      ...(err.capturePending && { capturePending: true }),
    });
  } finally {
    if (res.writableFinished || res.destroyed) logCapture();
    else { res.once('finish', logCapture); res.once('close', logCapture); }
  }
});

// GET …/console — the tab's buffered console messages and page errors
// (lib/browser-console.js). Query: level (all|error|warning|info|log, each with
// the more severe ones), since (ISO or epoch ms), limit, clear.
app.get('/api/browser/sessions/:id/console', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.query?.tabId} not found in session` });
  const since = parseConsoleSince(req.query?.since);
  if (Number.isNaN(since)) return res.status(400).json({ error: 'since must be an ISO timestamp or epoch milliseconds' });
  try {
    const read = readConsoleBuffer(routed.page, {
      level: String(req.query?.level || 'all').toLowerCase(),
      since,
      limit: req.query?.limit,
      clear: ['1', 'true', 'yes'].includes(String(req.query?.clear || '').toLowerCase()),
    });
    // A page registered before buffering existed: start now, so the next read has entries.
    if (!read.attached) attachConsoleBuffer(routed.page);
    const state = await syncPageState(session, routed);
    res.json({ ok: true, url: state.url, title: state.title, ...read });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.post('/api/browser/sessions/:id/scroll', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session` });
  const { direction = 'down', distance = 500, selector: rawSel, ref, returnSnapshot, snapshot, compact } = req.body;
  const deltaX = direction === 'right' ? distance : direction === 'left' ? -distance : 0;
  const deltaY = direction === 'down' ? distance : direction === 'up' ? -distance : 0;
  try {
    await humanThink(session, req, true);
    markBrowserActionStarted(req);
    if (ref) {
      const resolved = await resolveRefLocator(routed.page, ref);
      if (resolved.error) return res.status(400).json(resolved.error);
      await resolved.target.evaluate((el, { dx, dy }) => el.scrollBy(dx, dy), { dx: deltaX, dy: deltaY });
    } else if (rawSel) {
      await routed.page.locator(normalizeSelector(rawSel)).evaluate(
        (el, { dx, dy }) => el.scrollBy(dx, dy), { dx: deltaX, dy: deltaY }
      );
    } else {
      await routed.page.evaluate(({ dx, dy }) => window.scrollBy(dx, dy), { dx: deltaX, dy: deltaY });
    }
    if (browserV2Enabled()) await settleAfterAction(routed.page);
    else await cancellableBrowserDelay(300, req);
    const state = await getBrowserActionState(session, routed, compact);
    const body = { ok: true, url: state.url, title: state.title };
    if (snapshot && snapshot !== 'none') {
      const snap = await buildSnapshotResponse(routed.page, {
        mode: 'ai',
        diff: snapshot === 'diff',
        maxChars: req.body.snapshotMaxChars || 12000,
        ...snapshotRequestOptions(req, res, req.params.id, routed),
      }).catch(err => ({ snapshotText: null, snapshotError: err.message }));
      Object.assign(body, snap);
    } else if (returnSnapshot) {
      const snap = await buildSnapshotResponse(routed.page, {
        scopeSel: returnSnapshot.selector ? normalizeSelector(returnSnapshot.selector) : null,
        mode: returnSnapshot.mode,
        viewport: returnSnapshot.viewport,
        ...snapshotRequestOptions(req, res, req.params.id, routed),
      }).catch(err => ({ snapshot: null, snapshotError: err.message }));
      Object.assign(body, snap);
    }
    res.json(body);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/browser/sessions/:id/upload', async (req, res) => {
  const session = browserSessions.get(req.params.id);
  if (!session) return res.status(404).json({ error: 'Session not found' });
  const routed = getTargetPage(session, req);
  if (!routed) return res.status(404).json({ error: `Tab ${req.body?.tabId} not found in session` });
  const { selector: rawSel, ref, filePaths, nthMatch, compact } = req.body;
  if (!rawSel && !ref) return res.status(400).json({ error: 'selector or ref required' });
  if (!Array.isArray(filePaths) || !filePaths.length) return res.status(400).json({ error: 'filePaths must be a non-empty array' });
  try {
    let target;
    if (ref) {
      const resolved = await resolveRefLocator(routed.page, ref);
      if (resolved.error) return res.status(400).json(resolved.error);
      target = resolved.target;
    } else {
      const selector = normalizeSelector(rawSel);
      const loc = routed.page.locator(selector);
      const count = await loc.count().catch(() => -1);
      if (count === 0) {
        const hints = await getInteractiveHints(routed.page, { allowTransparent: true });
        const body = { error: `No elements match selector: ${selector}`, hints };
        if (assistRequested(req)) {
          // Advice only: a file control is never healed. The visible "add photo" button that reveals the input is what gets ranked.
          try { body.assist = (await buildAssist(routed.page, { kind: 'no_match', needle: assistNeedle(selector, req.body?.textHint), hints })).assist; } catch { /* hints alone */ }
        }
        return res.status(400).json(body);
      }
      if (count > 1 && nthMatch === undefined) {
        return res.status(400).json({ error: `Selector matches ${count} elements (must be unique). Use a more specific selector or pass nthMatch (0-indexed). Matched: ${selector}` });
      }
      target = (count > 1 && nthMatch !== undefined) ? loc.nth(nthMatch) : loc;
    }
    markBrowserActionStarted(req);
    await target.setInputFiles(filePaths, { timeout: browserActionTimeout(req, 10000) });
    if (!browserV2Enabled()) await cancellableBrowserDelay(500, req);
    const state = await getBrowserActionState(session, routed, compact);
    res.json({ ok: true, url: state.url, title: state.title });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Browser config endpoint
app.get('/api/browser/config', (req, res) => {
  const config = loadBrowserConfig();
  const detected = findBrowserExecutable();
  // Check if Chrome is currently running (informs profile mirroring warnings)
  let chromeRunning = false;
  try {
    if (IS_WIN) {
      const tasklist = execSync('tasklist /FI "IMAGENAME eq chrome.exe" /NH', { encoding: 'utf8', timeout: 3000 });
      chromeRunning = tasklist.includes('chrome.exe');
    } else if (process.platform === 'darwin') {
      const pgrep = execSync('pgrep -x "Google Chrome"', { encoding: 'utf8', timeout: 3000 });
      chromeRunning = pgrep.trim().length > 0;
    } else {
      const pgrep = execSync('pgrep -x chrome || pgrep -x chromium', { encoding: 'utf8', timeout: 3000 });
      chromeRunning = pgrep.trim().length > 0;
    }
  } catch { /* not running */ }
  // attachSeeded drives the Settings warning (whether the one-time seed copy is done).
  let attachSeeded = false;
  try { attachSeeded = existsSync(getAttachProfileRoot()); } catch {}
  let moreloginInstalled = false;
  try { moreloginInstalled = moreLogin.isMoreLoginInstalled().installed; } catch {}
  const unreadable = browserConfigUnreadable(config);
  res.json({ config, detectedPath: detected, chromeRunning, attachSeeded, moreloginInstalled, ...(unreadable && { configError: `browser-config.json is unreadable (${unreadable}); saving these settings replaces it` }) });
});

app.put('/api/browser/config', (req, res) => {
  try {
    // Full replacement — the frontend sends the complete config object
    const body = validateBrowserLanguageConfig(req.body || {});
    if (body.connectMode !== undefined) body.connectMode = ['attach', 'morelogin'].includes(body.connectMode) ? body.connectMode : 'mirror';
    if (body.attachSeed !== undefined) body.attachSeed = body.attachSeed === 'fresh' ? 'fresh' : 'real';
    if (body.moreloginEnvId !== undefined && body.moreloginEnvId !== null && body.moreloginEnvId !== '') body.moreloginEnvId = String(body.moreloginEnvId);
    // openTabsInBackground is not in the Settings form: a save from the form keeps
    // it. What it covers is said at newSessionPage, which reads it.
    const savedBackgroundTabs = loadBrowserConfig().openTabsInBackground;
    if (body.openTabsInBackground === undefined && typeof savedBackgroundTabs === 'boolean') body.openTabsInBackground = savedBackgroundTabs;
    saveBrowserConfig(body);
    // The in-process MCP drops its cached browser routes now; MCP processes of their
    // own do on their next /api/browser response (X-Synabun-Browser-Default).
    import(pathToFileURL(resolve(PACKAGE_ROOT, 'mcp-server', 'dist', 'services', 'neural-interface.js')).href)
      .then((mcp) => mcp.noteBrowserDefault?.(browserDefaultSignature(body)))
      .catch(() => {});
    res.json({ ok: true });
  } catch (err) {
    const invalidLanguage = err.status === 400 && ['locale', 'acceptLanguage'].includes(err.field);
    res.status(invalidLanguage ? 400 : 500).json({ error: err.message, ...(invalidLanguage && { field: err.field }) });
  }
});

// Detect Chrome/Edge/Chromium profiles on the system
app.get('/api/browser/detect-profiles', (req, res) => {
  try {
    const profiles = detectChromeProfiles();
    const synabunProfile = resolve(DATA_HOME, 'data', 'chrome-profile').replace(/\\/g, '/');
    const synabunExists = existsSync(synabunProfile);
    res.json({ profiles, synabunProfile, synabunProfileExists: synabunExists });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// List MoreLogin profiles (environments) for the Browser settings profile picker
app.get('/api/browser/morelogin-envs', async (req, res) => {
  try {
    const cfg = loadBrowserConfig();
    const installed = moreLogin.isMoreLoginInstalled().installed;
    const port = moreLogin.getMoreLoginPort(cfg);
    if (!installed) return res.json({ ok: true, installed: false, running: false, port, envs: [] });
    const probe = await moreLogin.probeMoreLoginApi({ savedCfg: cfg, port });
    if (!probe.running) return res.json({ ok: true, installed: true, running: false, port, envs: [], error: probe.error || null });
    const envs = await moreLogin.listProfiles({ savedCfg: cfg, port });
    res.json({
      ok: true, installed: true, running: true, port, envs,
      // Observed website-policy blocks — MoreLogin's local API never exposes the
      // blacklist/whitelist itself, so the picker reports what actually happened.
      blockedNavigations: moreLoginBlockStats.count,
      lastBlockedUrl: moreLoginBlockStats.lastUrl,
    });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Open native folder picker dialog (Windows: PowerShell, macOS: osascript, Linux: zenity)
app.post('/api/browser/browse-folder', async (req, res) => {
  try {
    let cmd;
    if (IS_WIN) {
      const pickerScript = resolve(__dirname, 'lib', 'folder-picker.ps1');
      cmd = `powershell -NoProfile -STA -WindowStyle Hidden -ExecutionPolicy Bypass -File "${pickerScript}" -Title "Select Chrome profile directory"`;
    } else if (process.platform === 'darwin') {
      cmd = "osascript -e 'POSIX path of (choose folder with prompt \"Select Chrome profile directory\")'";
    } else {
      cmd = 'zenity --file-selection --directory --title="Select Chrome profile directory" 2>/dev/null';
    }
    const result = execSync(cmd, { encoding: 'utf8', timeout: 60000, windowsHide: true }).trim();
    if (result) {
      res.json({ path: result.replace(/\\/g, '/') });
    } else {
      res.json({ path: null, cancelled: true });
    }
  } catch (err) {
    // User cancelled or dialog failed
    res.json({ path: null, cancelled: true });
  }
});

// Detect installed browser binaries on the system
app.get('/api/browser/detect-browsers', (req, res) => {
  const home = process.env.HOME || process.env.USERPROFILE || '';
  const localAppData = process.env.LOCALAPPDATA || '';

  const browserDefs = IS_WIN ? [
    { name: 'Google Chrome', channel: 'chrome', paths: [
      join(localAppData, 'Google', 'Chrome', 'Application', 'chrome.exe'),
      join(process.env['ProgramFiles'] || '', 'Google', 'Chrome', 'Application', 'chrome.exe'),
    ]},
    { name: 'Microsoft Edge', channel: 'msedge', paths: [
      join(localAppData, 'Microsoft', 'Edge', 'Application', 'msedge.exe'),
      join(process.env['ProgramFiles'] || '', 'Microsoft', 'Edge', 'Application', 'msedge.exe'),
    ]},
    { name: 'Chromium', channel: 'chromium', paths: [
      join(localAppData, 'Chromium', 'Application', 'chrome.exe'),
    ]},
  ] : process.platform === 'darwin' ? [
    { name: 'Google Chrome', channel: 'chrome', paths: [
      '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
      join(home, 'Applications', 'Google Chrome.app', 'Contents', 'MacOS', 'Google Chrome'),
    ]},
    { name: 'Microsoft Edge', channel: 'msedge', paths: [
      '/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge',
    ]},
    { name: 'Chromium', channel: 'chromium', paths: [
      '/Applications/Chromium.app/Contents/MacOS/Chromium',
    ]},
  ] : [
    { name: 'Google Chrome', channel: 'chrome', paths: ['/usr/bin/google-chrome', '/usr/bin/google-chrome-stable'] },
    { name: 'Microsoft Edge', channel: 'msedge', paths: ['/usr/bin/microsoft-edge', '/usr/bin/microsoft-edge-stable'] },
    { name: 'Chromium', channel: 'chromium', paths: ['/usr/bin/chromium', '/usr/bin/chromium-browser', '/snap/bin/chromium'] },
  ];

  const browsers = [];
  for (const def of browserDefs) {
    for (const p of def.paths) {
      if (p && existsSync(p)) {
        browsers.push({ name: def.name, channel: def.channel, path: p });
        break; // first found path per browser
      }
    }
  }
  res.json({ browsers });
});

// --- Launch warm-up ---
// After the server listens (never before it, and never in front of the first page), the slow lists the
// windows, menus and Settings wait for are read once in the background: one step at a time, a pause between
// two, so a first click finds them kept (lib/launch-cache.js) and nothing competes with the page. Every step
// is asynchronous: a CLI runs as a child process, never through a synchronous spawn. A step that is not ready
// yet (the Assistant still starting, OpenCode's serve not up) is skipped: its own ready event runs it again.
// scheduleLaunchRefresh(name) runs one step again after an event (an account switch, a provider connected,
// a serve restart), debounced, behind the same one-at-a-time queue.
const _launchQueue = createLimiter(1);
const _launchTimers = new Map();
const LAUNCH_STEP_GAP_MS = 250;
const LAUNCH_TASKS = {
  // Where git is: the lookup a first git call would otherwise run synchronously.
  'git-path': () => resolveGitPathInBackground(),
  // Claude Code's model list (one CLI start; the kept list answers meanwhile). Only where Claude Code is found.
  'claude-models': async () => { if (cliFoundForWarmup('claude-code')) await getClaudeModelsForClient(true); },
  // OpenCode's providers, once its serve answers (the serve's ready event runs this step again).
  'opencode-providers': async () => { if (_ocpReady) await readOpencodeProviders('compact', { refresh: true }); },
  // Every signed-in Codex account's model list (one app-server each, one after another).
  'codex-models': async () => {
    // Only where Codex is found: listing prepares the account's config.toml, which a machine without Codex never gets.
    if (!cliFoundForWarmup('codex')) return;
    let rows = [];
    try { rows = _codexAccounts().list().filter((row) => row?.signedIn !== false); } catch { rows = [{ id: 'default' }]; }
    for (const row of rows) {
      try { await _codexModelListCache.read(codexModelListKey(row.id), { refresh: true }); } catch { /* that account's list stays as kept */ }
    }
  },
  // The Assistant's catalog, from the lists above (every view the windows ask for is made from it).
  'assistant-catalog': async () => { await _assistantCatalog?.full?.({ force: true }); },
  // Subscription quotas the account menus show.
  'account-usage': async () => { await _assistantAccountUsage?.refresh?.(); },
  // The old Codex prompt / OpenCode command bridges proven SynaBun's move to native skill folders, once per start
  // (docs/skills-studio.md → The old bridges and their move). Not under a test run or a temporary data home.
  'skills-bridges': async () => {
    if (!skillsAutoMigrationAllowed()) return;
    const out = await skillsService.autoMigrateBridges();
    if (out.ran) console.log(`[skills] moved ${out.result?.results?.filter((r) => r.outcome === 'migrated').length || 0} old bridge file(s) to skill folders (${out.result?.journalId || 'no journal'})`);
    else if (out.reason && out.reason !== 'nothing') console.log(`[skills] old bridges not moved at start: ${out.reason}${out.error ? ` (${out.error})` : ''}`);
  },
  // What the Codex panel's settings and cog menu validate against (a Codex start per setting value, once per version).
  'codex-settings': async () => {
    const found = cliResolver.launcher('codex');
    const bin = found.launchPath || found.path;
    // A file the resolver checked (a bare command name or a command line has no binary identity to key on).
    if (found.state === 'installed' && bin && /[\\/]/.test(bin)) await readCodexSettingsSchema(bin).catch(() => null);
  },
};

/**
 * Whether the start-up move of the old bridges may run (lib/skills/migration.js autoMigrationAllowed): not under a test
 * run, never from a temporary data home (os.tmpdir(), TMPDIR, /tmp, /var/folders and their /private twins, by real
 * path: a dev or test boot with the real HOME must not move the owner's real bridges), not with the kill switch.
 */
function skillsAutoMigrationAllowed() {
  return autoMigrationAllowed({ env: process.env, dataHome: DATA_HOME });
}

// A CLI the resolver found (probed or not yet): the warm-up starts nothing for a tool that is not installed.
function cliFoundForWarmup(toolKey) {
  try {
    const found = cliResolver.launcher(toolKey);
    return !!found.path && found.state !== 'broken' && found.state !== 'missing';
  } catch { return false; }
}

function runLaunchStep(name) {
  const task = LAUNCH_TASKS[name];
  if (!task) return Promise.resolve();
  return _launchQueue(async () => {
    const started = Date.now();
    try { await task(); } catch (error) { console.warn(`[launch-cache] ${name}: ${error?.message || error}`); }
    const took = Date.now() - started;
    if (took > 2000) console.log(`[launch-cache] ${name} warmed in ${(took / 1000).toFixed(1)} s`);
    await new Promise((done) => { const timer = setTimeout(done, LAUNCH_STEP_GAP_MS); timer.unref?.(); });
  });
}

/** Run one warm-up step again soon (an event changed what it reads); bursts of events run it once. */
function scheduleLaunchRefresh(name, delayMs = 600) {
  if (!LAUNCH_TASKS[name] || _launchTimers.has(name)) return;
  const timer = setTimeout(() => { _launchTimers.delete(name); runLaunchStep(name); }, delayMs);
  timer.unref?.();
  _launchTimers.set(name, timer);
}

function startLaunchWarmup() {
  if (process.env.SYNABUN_LAUNCH_WARMUP === 'off') return;
  const timer = setTimeout(() => {
    for (const name of Object.keys(LAUNCH_TASKS)) runLaunchStep(name);
  }, 3000);
  timer.unref?.();
}

// --- Start ---
reloadConfig();

const httpServer = app.listen(PORT, async () => {
  console.log(`\n  Neural Memory Interface`);
  console.log(`  ──────────────────────`);
  console.log(`  Server:    http://localhost:${PORT}`);
  console.log(`  MCP:       http://localhost:${PORT}/mcp`);
  console.log(`  Storage:   SQLite (${getDbPath()})`);
  console.log(`  Embedding: local (${EMBEDDING_DIMS}d)`);
  console.log(`  Terminal:  WebSocket on ws://localhost:${PORT}/ws/terminal/*`);
  console.log(`  Browser:   WebSocket on ws://localhost:${PORT}/ws/browser/*`);
  console.log(`  Whiteboard: WebSocket on ws://localhost:${PORT}/ws/whiteboard`);
  console.log(`  Cards:      WebSocket on ws://localhost:${PORT}/ws/cards`);
  console.log(`  Sessions:   WebSocket on ws://localhost:${PORT}/ws/sessions\n`);

  // Write embedding model metadata so mismatch can be detected later
  try {
    setKvConfig('embedding_model', EMBEDDING_MODEL);
    setKvConfig('embedding_dims', String(EMBEDDING_DIMS));
  } catch {}

  // Keep the Start Server launcher (synabun://) pointing at this install even
  // when the server was started directly rather than through setup.js. Writes
  // only what differs; skipped for test runs and throwaway data homes.
  try {
    const launcher = registerStartLauncher({ packageRoot: PACKAGE_ROOT });
    _startLauncherState = launcher.state === 'skipped' ? startLauncherState({ packageRoot: PACKAGE_ROOT }) : launcher.state;
    if (launcher.changed) console.log('[server] Start Server launcher registered (synabun://)');
    else if (!launcher.ok) console.warn(`[server] Start Server launcher not registered: ${launcher.errors[0]}`);
  } catch {}

  // Start at login (Settings > App): while it is on, its entry starts this install (another Node, a moved
  // install). One that is off, or that the user turned off in the system, is left as it is.
  try {
    const healed = loginStart.heal();
    if (healed.changed) console.log('[server] start at login: the entry now starts this install');
  } catch (err) {
    console.warn(`[server] start at login: ${err.message}`);
  }

  // Auto-heal legacy synabun-symlink plugin state and reinstall via CC CLI
  try {
    const repair = pluginInstaller.repairSynabunPlugins();
    if (repair?.repaired?.length) console.log(`[plugins] repaired legacy installs: ${repair.repaired.map(r => r.marketplaceName).join(', ')}`);
    if (repair?.failed?.length) console.warn(`[plugins] repair failed for: ${repair.failed.map(r => r.marketplaceName + ' (' + r.error + ')').join(', ')}`);
  } catch (err) {
    console.warn('[plugins] repair on startup failed:', err.message);
  }

  // SQLite indexes are created in schema — no runtime index creation needed

  // Gated: an idle tick reads one kv row + one index probe instead of the
  // ~9-query maintenanceStatus() and a BEGIN IMMEDIATE (see lib/memory-timers.js).
  startGatedMemoryMaintenance();
  // The TypeSafe judge backfill runs only here: one runner per store, never in
  // the stdio MCP servers. It is inert until the Judgments tab starts it.
  startJudgeBackfill();
  startMemoryCapture();

  // Warm the embedding model + vector caches in the background so the first
  // recall/search doesn't pay the 2-5s Transformers.js model load or the
  // initial vector-matrix build.
  setTimeout(() => {
    warmupEmbeddings()
      .then(() => console.log('  Embeddings: model warmed up'))
      .catch((err) => console.warn('  Embeddings warmup failed:', err.message));
    try { memoryVectors.size(); } catch { /* cache builds lazily on failure */ }
  }, 500);

  // Detect MoreLogin (anti-detect browser) — DETECTION ONLY, never auto-activates.
  // Activation is an explicit user choice via Settings → Browser / the MoreLogin tab.
  setTimeout(async () => {
    try {
      if (!moreLogin.isMoreLoginInstalled().installed) return;
      const cfg = loadBrowserConfig();
      const port = moreLogin.getMoreLoginPort(cfg);
      const probe = await moreLogin.probeMoreLoginApi({ savedCfg: cfg, port });
      const isDefault = cfg.connectMode === 'morelogin';
      console.log(`  MoreLogin:  detected${probe.running ? ` · API on :${port} (${probe.count} profile(s))` : ' · app not running'}${isDefault ? ' · default AI browser' : ''}`);
    } catch { /* best-effort */ }
  }, 700);

  // Reclaim orphaned per-loop config dirs left by crashed/killed loops. At boot
  // no loop is live, so this is the safe choke point to drop multi-GB of stale
  // opencode-<sid> node_modules that never got their per-loop cleanup.
  setTimeout(() => { try { cleanupStaleLoopConfigs(); } catch {} }, 1500);

  // OpenCode serves an earlier SynaBun left running (it crashed, or was killed): found by their records alone and
  // stopped only when they are provably its own and nothing uses them (lib/opencode-serve-records.js). An
  // OpenCode start that comes earlier makes the same look first (and this one then finds nothing left).
  setTimeout(() => { sweepLeftoverOpencodeServes(); }, 1000);
  // The cloudflared a crashed server left running (lib/cloudflared/tunnel.js): at once, its old address points here.
  sweepLeftoverTunnels();

  // Compare the installed Claude CLI with the release the Agent SDK was built
  // against, once, so an older installation is named in the log before the
  // first session runs on it (checkClaudeCliSkew in lib/claude-model-catalog.js).
  setTimeout(() => { checkClaudeCliSkew(getClaudeBin()).catch(() => {}); }, 1000);

  // The lists windows, menus and Settings wait for, read once in the background (see LAUNCH_TASKS above).
  startLaunchWarmup();

  // Windows: the Git Bash every Claude Code gets (lib/git-bash/). Looked for now (the settings of the user's own
  // claude follow it); a PC with none, and an app that carries none, gets SynaBun's copy, fetched in the background.
  setTimeout(() => {
    try {
      gitBash.refresh();
      if (gitBash.status().state === 'missing') gitBash.ensure({ reason: 'first run' });
      // What an earlier run left in the data home (a stopped attempt's work folder, an older version), off the event loop.
      gitBash.housekeep().catch(() => {});
    } catch (err) { console.warn('[git-bash] start check failed:', err?.message || err); }
  }, 2500);

  // Warm the session_cache + session_fts tables so the hybrid search has data
  // on first keystroke. Each pass is synchronous and holds the main thread, so
  // they run one per tick (requests are answered in between), and each only
  // re-reads sessions that changed since the last start.
  setTimeout(() => {
    const passes = [
      () => {
        try {
          const claude = rebuildClaudeCache();
          if (claude.updated > 0) console.log(`  Session cache (claude): indexed ${claude.updated}/${claude.sessions}`);
        } catch (err) { console.warn('  Session cache (claude) error:', err.message); }
      },
      () => {
        try {
          const codex = rebuildCodexCache({
            accounts: loadCodexAccounts().accounts,
            projects: loadHookProjects(),
          });
          if (codex.updated > 0) console.log(`  Session cache (codex): indexed ${codex.updated}/${codex.sessions}`);
        } catch (err) { console.warn('  Session cache (codex) error:', err.message); }
      },
      () => {
        try {
          const oc = rebuildOpencodeCache({ getOpencodeDb });
          if (oc.updated > 0) console.log(`  Session cache (opencode): indexed ${oc.updated}/${oc.sessions}`);
        } catch (err) { console.warn('  Session cache (opencode) error:', err.message); }
      },
    ];
    const next = () => {
      const pass = passes.shift();
      if (!pass) return;
      pass();
      setImmediate(next);
    };
    next();
  }, 2000);

  // Auto-sync OpenClaw bridge if enabled
  try {
    const ocConfig = loadBridgeConfig('openclaw');
    if (ocConfig?.enabled) {
      const result = syncOpenClawBridge();
      console.log(`  OpenClaw bridge: ${result.nodes} nodes synced`);
    }
  } catch (err) {
    console.warn('  OpenClaw bridge sync warning:', err.message);
  }

  // Repair legacy hook duplication in settings.json files (global + registered
  // projects). Cleans up entries where the same script appears twice with
  // different command-string forms (relative + absolute). Future installs are
  // already self-healing via addHookToSettings; this catches damage from
  // previous versions of the install flow.
  try {
    const dedupStats = dedupeAllSettingsHooks();
    if (dedupStats.removed > 0 || dedupStats.repaired > 0 || dedupStats.matchers > 0) {
      const bits = [];
      if (dedupStats.removed > 0) bits.push(`deduped ${dedupStats.removed} stray entr${dedupStats.removed === 1 ? 'y' : 'ies'}`);
      if (dedupStats.repaired > 0) bits.push(`repaired ${dedupStats.repaired} stale path${dedupStats.repaired === 1 ? '' : 's'}`);
      if (dedupStats.matchers > 0) bits.push(`updated ${dedupStats.matchers} stale matcher${dedupStats.matchers === 1 ? '' : 's'}`);
      console.log(`  Hooks:     ${bits.join(' + ')} across ${dedupStats.files} settings file${dedupStats.files === 1 ? '' : 's'}`);
    }
  } catch (err) {
    console.warn('  Hook dedup warning:', err.message);
  }

  // Keep the installed SynaBun rules current: an untouched copy of an older
  // ruleset is rewritten (unless the user switched that off), an edited copy is
  // left alone, a deleted one counts as an opt-out. Never installs for a tool
  // the user was not asked about. A failure here must not stop the boot. This
  // is the listen callback and reconcile() is synchronous file checks; its one
  // wait is for the rules lock another SynaBun process on this data home may
  // hold (2 s at most: then the installer logs one line and this boot skips it).
  try {
    const rules = rulesetInstaller.reconcile();
    if (rules.updated.length) console.log(`  Rules:     updated to ${rules.notice?.to || 'the current version'} for ${rules.updated.join(', ')}`);
    if (rules.optedOut.length) console.log(`  Rules:     no longer managed for ${rules.optedOut.join(', ')} (the installed copy was removed)`);
  } catch (err) {
    console.warn('  Rules reconcile warning:', err.message);
  }

  // Clean up orphaned loop state files from previous server runs.
  // After a restart, PTY sessions are gone but loop files remain with awaitingNext: true.
  // No terminal session exists to drive them, so delete them to prevent ghost loops.
  try {
    if (existsSync(LOOP_DIR)) {
      const loopFiles = readdirSync(LOOP_DIR).filter(f => f.endsWith('.json'));
      let cleaned = 0;
      for (const f of loopFiles) {
        const fp = resolve(LOOP_DIR, f);
        try {
          const data = JSON.parse(readFileSync(fp, 'utf-8'));
          if (!data.active && !data.pending) {
            // Inactive — safe to delete
            unlinkSync(fp);
            cleaned++;
          } else if (data.terminalSessionId && !isLoopRuntimeAlive(data)) {
            // Active/pending but provider runtime is dead (server restarted) — orphaned
            console.log(`[startup] Cleaning orphaned loop ${f} (runtime ${data.terminalSessionId} gone)`);
            unlinkSync(fp);
            cleaned++;
          }
        } catch { /* skip corrupt files */ }
      }
      if (cleaned > 0) console.log(`  Loops:     cleaned ${cleaned} orphaned loop file${cleaned !== 1 ? 's' : ''}`);
    }
  } catch { /* ok */ }

  // Check for SynaBun updates (npm + github releases), unless Settings > App turned the automatic check off
  if (automaticUpdateCheck()) {
    try { await checkSynabunUpdate(); } catch {}
  } else {
    console.log('  Updates:   automatic check off (Settings > App)');
  }

  // Prune any external CLI tool left in our node_modules before the version
  // check runs — defends against `npm install` not auto-pruning packages that
  // were removed from package.json (recurring source of phantom-version
  // badges, e.g. v2.1.89 from a stale @anthropic-ai/claude-code).
  try { pruneBundledCliTools(); } catch {}

  // Check for CLI tool updates — fire-and-forget so boot isn't serialized
  // behind N subprocess probes + registry fetches; the route's stale-while-
  // revalidate handles the cold-cache window.
  checkToolVersions().catch(() => {});

  // Auto-start OpenCode server on boot so downstream UIs (Automation Studio,
  // OpenCode panel, Settings) see providers/models immediately without the
  // user having to click Start each time.
  try {
    const ready = await ensureOpencodeServer();
    if (ready) console.log(`  OpenCode:  auto-started on :${_ocpPort}`);
    else console.log('  OpenCode:  auto-start skipped (binary missing or failed to launch)');
  } catch (err) {
    console.warn('  OpenCode:  auto-start error:', err.message);
  }
});

// ═══════════════════════════════════════════
// TERMINAL — WebSocket Server
// ═══════════════════════════════════════════

// perMessageDeflate deliberately OFF: localhost/LAN bandwidth is free while
// zlib adds per-frame CPU + latency on the terminal hot path.
const wss = new WebSocketServer({ noServer: true, perMessageDeflate: false });

/** Public origins SynaBun is reached through: the running Cloudflare tunnel, the invite proxy in use (ui-invite.js) and the names of SYNABUN_ALLOWED_HOSTS. Their host names are the only non-local names the Host rule (HTTP: lib/request-gate.js; WebSocket Origin check; the editor's routes) accepts. */
function publicWebOrigins() {
  // The tunnel's and the invite proxy's addresses are the names requests from outside arrive under, never the
  // owner's own. In this list only the owner's own names stand without a scheme (lib/http-guards.js accepts the
  // pages of such a host as an Origin on any port): an invite address that was saved without one stands as its
  // https origin, and a name of SYNABUN_ALLOWED_HOSTS that is one of theirs adds nothing.
  const outside = remoteWebOrigins();
  const theirs = hostsOf(outside);
  const origins = outside.map((each) => (hostNameOf(each) ? `https://${each}` : each));
  // Names the owner added: SYNABUN_ALLOWED_HOSTS as the server was started with it (the shell's own value: it
  // keeps applying), and the line of the data home's .env as it is now, read with dotenv's own parser
  // (savedValueOf): the line counts for what dotenv gave it when the server started. A name added to the file is
  // answered at the next request, and one taken out of it is refused at the next request: no restart either way.
  const own = extraHostNames(startedAllowedHosts.value, savedValueOf(ENV_PATH));
  origins.push(...own.filter((each) => each.includes('://') || !theirs.includes(hostNameOf(each))));
  return origins;
}

/** The names requests from outside arrive under: the running Cloudflare tunnel's and the invite proxy's in use. Whatever names one of them is remote, with CF-Connecting-IP or without (lib/request-gate.js isRemote): it needs an invite session and is never the owner. The names of SYNABUN_ALLOWED_HOSTS are not among them: those are the owner's own for this computer. */
function remoteWebOrigins() {
  const origins = [];
  if (tunnelUrl) origins.push(tunnelUrl);
  const proxy = loadInviteProxy();
  if (proxy?.useProxy && proxy.proxyUrl) origins.push(proxy.proxyUrl);
  return origins;
}

httpServer.on('upgrade', function onUpgrade(req, socket, head) {
  // The Host rule first, as in front of every route (lib/request-gate.js): an upgrade whose Host is not one of
  // this server's names is refused, on every /ws/* path and with an Origin or without one. The Origin rule
  // below lets a client without an Origin pass, so without this a request under any name reached /ws/sync and
  // the terminal handoff. A name that is not known while this computer's names are still being read (its
  // Bonjour name right after a start) is asked again when they are, as a route's request is: the handler then
  // starts over, once. A name that is known never waits.
  if (!requestGates.ownHost(req)) {
    if (!requestGates.ownHostAfterNames(req, socket, () => onUpgrade(req, socket, head))) refuseUpgrade(socket, 403);
    return;
  }

  // What comes in from outside (the tunnel, the invite proxy's name) opens no socket without an invite session
  if (requestGates.isRemote(req) && !isValidInviteSession(req)) {
    socket.destroy();
    return;
  }

  // Cross-site WebSocket hijacking and DNS rebinding: CORS does not cover
  // WebSockets, so any page open in the user's browser could connect to /ws/*
  // (terminals, the Assistant, sync). A browser's Origin must be a loopback
  // origin on PORT, the tunnel / invite proxy origin, or this server as the
  // request reached it, and that last one only when the Host is one of our own
  // names (loopback, an IP literal, this machine, the tunnel / invite proxy
  // host): a rebound page's Host and Origin agree too, on the attacker's name.
  // Clients that send no Origin are not browsers and pass. Every /ws/* path,
  // before the terminal handoff to the pty-host. See lib/http-guards.js.
  if (!isAllowedWebSocketOrigin(req, { port: PORT, allowedOrigins: publicWebOrigins })) {
    refuseUpgrade(socket, 403);
    return;
  }

  const url = new URL(req.url, `http://localhost:${PORT}`);

  // Permission-based WS upgrade blocking for guests
  const guest = isGuestRequest(req);
  if (guest) {
    if (url.pathname.startsWith('/ws/terminal/') && !invitePermissions.terminal) { socket.destroy(); return; }
    if (url.pathname.startsWith('/ws/browser/') && !invitePermissions.browser) { socket.destroy(); return; }
    if (['/ws/claude-skin', '/ws/codex-skin', '/ws/opencode-v2'].includes(url.pathname) || url.pathname.startsWith('/ws/assistant/')) {
      socket.destroy();
      return;
    }
    // Whiteboard + sync always allowed (read-only viewing; sync needed for permission delivery)
  }

  // Owner authority by peer identity (lib/owner-authority.js): an owner's socket (a terminal, the agent panels, the
  // Assistant, the browser panel) is refused to SynaBun's automation browser, a relay, another SynaBun server, a
  // remote login and an agent's tree that does not say it is an agent's call; the sync socket stays open for them,
  // read-only. The peer is looked up once, then the handler runs again from the top with the answer on the request.
  if (!req._synabunOwnerChecked && (_ownerAuthority.socketScope(url.pathname).owner || _ownerAuthority.socketScope(url.pathname).readOnly)) {
    req._synabunOwnerChecked = true;
    _ownerAuthority.checkUpgrade(req, url.pathname).then((verdict) => {
      if (verdict.refuse) { refuseUpgrade(socket, 403); return; }
      if (verdict.readOnly) req._synabunReadOnly = true;
      onUpgrade(req, socket, head);
    }, () => onUpgrade(req, socket, head));
    return;
  }

  // Terminal sockets belong to the pty-host: hand the raw socket over (after
  // the auth checks above) so this event loop never touches terminal bytes.
  // The host answers unknown ids with {type:'error', message:'Session not found'}.
  if (url.pathname.startsWith('/ws/terminal/')) {
    let sessionId = url.pathname.slice('/ws/terminal/'.length);
    try { sessionId = decodeURIComponent(sessionId); } catch {}
    terminalHost.handoffUpgrade(req, socket, head, sessionId);
    return;
  }

  if (url.pathname.startsWith('/ws/browser/') || url.pathname.startsWith('/ws/assistant/') || url.pathname === '/ws/whiteboard' || url.pathname === '/ws/cards' || url.pathname === '/ws/sync' || url.pathname === '/ws/claude-skin' || url.pathname === '/ws/codex-skin' || url.pathname === '/ws/opencode-v2' || url.pathname === '/ws/sessions') {
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  } else {
    socket.destroy();
  }
});

wss.on('connection', (ws, req) => {
  const url = new URL(req.url, `http://localhost:${PORT}`);

  // ── Route: Real-time sync (multi-client state broadcast) ──
  if (url.pathname === '/ws/sync') {
    handleSyncWebSocket(ws, req);
    return;
  }

  // ── Route: Whiteboard (Claude MCP integration) ──
  if (url.pathname === '/ws/whiteboard') {
    handleWhiteboardWebSocket(ws, req);
    return;
  }

  // ── Route: Cards (Claude MCP integration) ──
  if (url.pathname === '/ws/cards') {
    handleCardsWebSocket(ws);
    return;
  }

  // ── Route: Browser session ──
  if (url.pathname.startsWith('/ws/browser/')) {
    handleBrowserWebSocket(ws, url);
    return;
  }

  // ── Route: Session monitor ──
  if (url.pathname === '/ws/sessions') {
    handleSessionMonitorWebSocket(ws);
    return;
  }

  // ── Route: Claude Skin chat ──
  if (url.pathname === '/ws/claude-skin') {
    handleClaudeSkinWebSocket(ws);
    return;
  }

  // ── Route: Main assistant (bottom CLI region) ──
  if (url.pathname.startsWith('/ws/assistant/')) {
    if (_assistantRuntime) _assistantRuntime.handleWebSocket(ws, url).catch((err) => { try { ws.close(1011, err?.message || 'assistant error'); } catch {} });
    else { try { ws.close(1011, 'assistant unavailable'); } catch {} }
    return;
  }

  // ── Route: Codex Skin chat ──
  if (url.pathname === '/ws/codex-skin') {
    handleCodexSkinWebSocket(ws);
    return;
  }

  // ── Route: OpenCode V2 (clean-slate sidepanel) ──
  if (url.pathname === '/ws/opencode-v2') {
    handleOpencodeV2Ws(ws);
    return;
  }

  // ── Terminal sessions ── are handed off to the pty-host in the upgrade
  // handler (lib/pty-host); nothing else should reach this point.
  try { ws.close(1008, 'Unsupported WebSocket path'); } catch {}
});

// ═══════════════════════════════════════════
// WHITEBOARD — WebSocket Handler (Claude MCP ↔ Browser)
// ═══════════════════════════════════════════

function handleWhiteboardWebSocket(ws, req) {
  whiteboardClients.add(ws);
  ws._isGuest = !!(req && isGuestRequest(req));
  ws._wbClient = {
    clientId: 'ws-' + randomBytes(3).toString('hex'),
    viewport: null,
    focusActive: false,
    visible: true,
    lastSeen: Date.now(),
    protocol: 1,          // 2 once the client sends a clientId (understands `batch`)
    isGuest: ws._isGuest,
  };
  console.log(`[ws-whiteboard] Client connected (total: ${whiteboardClients.size})`);

  // Send init with current element count
  try {
    const wb = loadWhiteboard();
    ws.send(JSON.stringify({ type: 'init', elementCount: wb.elements.length, protocol: 2, clientId: ws._wbClient.clientId }));
  } catch { /* ignore */ }

  const guestBlocked = () => ws._isGuest && !invitePermissions.whiteboard;

  ws.on('message', (raw) => {
    try {
      const msg = JSON.parse(raw.toString());
      const c = ws._wbClient;
      c.lastSeen = Date.now();

      if (msg.type === 'viewport') {
        const w = Number(msg.width), h = Number(msg.height);
        if (Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0) {
          c.viewport = {
            width: Math.round(w),
            height: Math.round(h),
            xOffset: Math.round(Number(msg.xOffset) || 0),
            yOffset: Math.round(Number(msg.yOffset) || 0),
          };
        }
        if (typeof msg.clientId === 'string' && msg.clientId) { c.clientId = msg.clientId.slice(0, 64); c.protocol = 2; }
        c.focusActive = !!msg.focusActive;
        c.visible = msg.visible !== false;
        const v = c.viewport;
        console.log(`[ws-whiteboard] Viewport ${c.clientId}: ${v ? `${v.width}x${v.height} (xOffset: ${v.xOffset}, yOffset: ${v.yOffset})` : 'invalid'} focus=${c.focusActive} visible=${c.visible}`);
      }

      // Browser-measured sizes of auto-sized text/list cards → geometry truth.
      // Merged into the store only; never re-broadcast (each window measures itself).
      if (msg.type === 'geometry' && Array.isArray(msg.items)) {
        if (guestBlocked()) return;
        const wb = loadWhiteboard();
        const byId = new Map(wb.elements.map(e => [e.id, e]));
        let changed = false;
        for (const item of msg.items.slice(0, 500)) {
          const el = item && byId.get(String(item.id));
          if (!el || (el.type !== 'text' && el.type !== 'list')) continue;
          const w = Number(item.width), h = Number(item.height);
          if (!(w >= 1 && w <= 20000 && h >= 1 && h <= 20000)) continue;
          if (el.measured && el.width === w && el.height === h) continue;
          el.width = w;
          el.height = h;
          el.measured = true;
          delete el.estimated;
          changed = true;
        }
        if (changed) saveWhiteboard(wb);
      }

      if (msg.type === 'screenshot:response' && msg.requestId) {
        const pending = whiteboardPendingScreenshots.get(msg.requestId);
        if (pending) {
          clearTimeout(pending.timer);
          whiteboardPendingScreenshots.delete(msg.requestId);
          pending.resolve({
            data: msg.data,
            width: msg.width,
            height: msg.height,
            scale: msg.scale,
            xOffset: msg.xOffset,
            yOffset: msg.yOffset,
            crop: msg.crop,
            from: { clientId: c.clientId, viewport: c.viewport },
          });
        }
      }

      if (msg.type === 'screenshot:error' && msg.requestId) {
        const pending = whiteboardPendingScreenshots.get(msg.requestId);
        if (pending) {
          clearTimeout(pending.timer);
          whiteboardPendingScreenshots.delete(msg.requestId);
          pending.reject(new Error(msg.error || 'Screenshot failed'));
        }
      }

      // Save whiteboard image to temp file and return path for clipboard copy
      if (msg.type === 'image_save' && msg.data) {
        const ext = (msg.mimeType === 'image/jpeg') ? 'jpg' : 'png';
        const tmpPath = join(IMAGES_DIR, `synabun-wbimg-${Date.now()}.${ext}`);
        try {
          writeFileSync(tmpPath, Buffer.from(msg.data, 'base64'));
          ws.send(JSON.stringify({ type: 'image_saved', path: tmpPath }));
        } catch (err) {
          ws.send(JSON.stringify({ type: 'error', message: `Image save failed: ${err.message}` }));
        }
      }

      // Client pushes full state sync after local mutation — save and relay to other clients
      if (msg.type === 'state:sync' && msg.snapshot) {
        if (guestBlocked()) return;
        const snapshot = msg.snapshot;
        if (!Array.isArray(snapshot.elements)) return;
        const current = loadWhiteboard();
        mergeMeasuredSizes(snapshot.elements, current.elements);
        normalizeWhiteboardElements(snapshot.elements);
        const next = { elements: snapshot.elements, nextZIndex: snapshot.nextZIndex || 1 };
        saveWhiteboard(next);
        broadcastToWhiteboard({ type: 'state:full', snapshot: next }, ws);
      }
    } catch { /* ignore malformed */ }
  });

  ws.on('close', () => {
    whiteboardClients.delete(ws);
    console.log(`[ws-whiteboard] Client disconnected (remaining: ${whiteboardClients.size})`);
  });
}

// ── Screenshot Watcher → auto-paste to whiteboard (cross-platform) ──
{
  // Resolve screenshot directory and filename pattern per platform
  let _screenshotDir = null;
  let _screenshotPattern = null;

  if (process.platform === 'darwin') {
    try {
      _screenshotDir = execSync('defaults read com.apple.screencapture location', { encoding: 'utf8' }).trim();
    } catch { /* not set — use default */ }
    if (!_screenshotDir || !existsSync(_screenshotDir)) _screenshotDir = join(os.homedir(), 'Desktop');
    // macOS screenshot filenames: "Screenshot ..." (EN), "Captura de..." (ES/PT)
    _screenshotPattern = /^(Screenshot\b|Captura de).*\.png$/i;
  } else if (process.platform === 'win32') {
    // Windows Snipping Tool / Print Screen saves to Pictures\Screenshots
    const candidates = [
      join(os.homedir(), 'Pictures', 'Screenshots'),
      join(os.homedir(), 'OneDrive', 'Pictures', 'Screenshots'),
      join(os.homedir(), 'Pictures'),
    ];
    _screenshotDir = candidates.find(d => existsSync(d)) || null;
    // Windows screenshot filenames: "Screenshot 2026-03-19 ..." or "Screenshot (123).png"
    _screenshotPattern = /^Screenshot.*\.(png|jpg|jpeg)$/i;
  } else {
    // Linux: GNOME Screenshot, Spectacle, Flameshot, etc.
    const candidates = [
      join(os.homedir(), 'Pictures', 'Screenshots'),
      join(os.homedir(), 'Pictures'),
      join(os.homedir(), 'Imagens', 'Screenshots'), // pt-BR
      join(os.homedir(), 'Imagens'),
    ];
    _screenshotDir = candidates.find(d => existsSync(d)) || null;
    // Linux screenshot filenames vary: "Screenshot from ...", "screenshot-...", etc.
    _screenshotPattern = /^(Screenshot|screenshot).*\.(png|jpg|jpeg)$/i;
  }

  if (_screenshotDir) {
    const _seenScreenshots = new Set();
    // Seed with existing files so we don't process old screenshots on startup
    try {
      for (const f of readdirSync(_screenshotDir)) {
        if (_screenshotPattern.test(f)) _seenScreenshots.add(f);
      }
    } catch { /* ignore */ }

    let _debounceTimer = null;
    try {
      fsWatch(_screenshotDir, (eventType, filename) => {
        if (!filename) return;
        if (!_screenshotPattern.test(filename)) return;
        if (_seenScreenshots.has(filename)) return;
        _seenScreenshots.add(filename);

        // Debounce — OS may fire multiple events per file
        clearTimeout(_debounceTimer);
        _debounceTimer = setTimeout(() => {
          const filePath = join(_screenshotDir, filename);
          try {
            if (!existsSync(filePath)) return;
            const stat = statSync(filePath);
            if (stat.size < 100) return; // still being written
            const buf = readFileSync(filePath);
            const ext = extname(filename).toLowerCase();
            const mime = ext === '.jpg' || ext === '.jpeg' ? 'image/jpeg' : 'image/png';
            if (_imageRecentlySeen(buf)) return;
            // Save a copy to data/images/ for reliable access (avoids macOS temp/permission issues)
            const localName = `screenshot-${Date.now()}${ext}`;
            const localPath = join(IMAGES_DIR, localName);
            try { writeFileSync(localPath, buf); } catch {}
            const dataUrl = `data:${mime};base64,${buf.toString('base64')}`;
            console.log(`[screenshot-watcher] New screenshot detected: ${filename} (${(stat.size / 1024).toFixed(0)}KB) → ${localName}`);
            broadcastToWhiteboard({ type: 'screenshot:auto', dataUrl, filename, localPath });
          } catch (err) {
            console.warn(`[screenshot-watcher] Failed to process ${filename}:`, err.message);
          }
        }, 500);
      });
      console.log(`[screenshot-watcher] Watching: ${_screenshotDir}`);
    } catch (err) {
      console.warn('[screenshot-watcher] Could not watch screenshot directory:', err.message);
    }
  } else {
    console.log('[screenshot-watcher] No screenshot directory found for this platform');
  }
}

// Shared dedup across fs watcher + clipboard watcher — Win+PrtScr fires both.
const _recentImageHashes = new Map();
const _IMAGE_DEDUP_TTL = 5000;
function _imageRecentlySeen(buf) {
  const hash = createHash('sha256').update(buf).digest('hex');
  const now = Date.now();
  for (const [h, ts] of _recentImageHashes) {
    if (now - ts > _IMAGE_DEDUP_TTL) _recentImageHashes.delete(h);
  }
  if (_recentImageHashes.has(hash)) return true;
  _recentImageHashes.set(hash, now);
  return false;
}

// ── Clipboard Image Watcher → auto-paste to whiteboard (Windows only) ──
// Mac screenshots always go to a file (handled above). On Windows, PrintScreen
// and Snipping Tool often land only in the clipboard, so we poll it via PS.
if (process.platform === 'win32') {
  const _psScript = [
    "Add-Type -AssemblyName System.Windows.Forms",
    "Add-Type -AssemblyName System.Drawing",
    "if ([System.Windows.Forms.Clipboard]::ContainsImage()) {",
    "  try {",
    "    $img = [System.Windows.Forms.Clipboard]::GetImage()",
    "    $ms = New-Object System.IO.MemoryStream",
    "    $img.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)",
    "    [Convert]::ToBase64String($ms.ToArray())",
    "  } catch { 'NONE' }",
    "} else { 'NONE' }",
  ].join('; ');
  const _psEncoded = Buffer.from(_psScript, 'utf16le').toString('base64');
  const _psArgs = ['-Sta', '-NoProfile', '-NonInteractive', '-EncodedCommand', _psEncoded];

  let _clipLastHash = null;
  let _clipPolling = false;
  let _clipFailures = 0;
  let _clipIntervalId = null;

  const _pollClipboard = (seed = false) => {
    if (_clipPolling) return;
    _clipPolling = true;
    let child;
    try {
      child = spawn('powershell.exe', _psArgs, { windowsHide: true });
    } catch (err) {
      _clipPolling = false;
      if (_clipIntervalId) clearInterval(_clipIntervalId);
      console.warn('[clipboard-watcher] Could not spawn PowerShell:', err.message);
      return;
    }
    let stdout = '';
    const killTimer = setTimeout(() => { try { child.kill(); } catch {} }, 5000);
    child.stdout.on('data', (d) => { stdout += d.toString('utf8'); });
    child.on('error', () => { /* surface via close */ });
    child.on('close', (code) => {
      clearTimeout(killTimer);
      _clipPolling = false;
      if (code !== 0 && code !== null) {
        _clipFailures++;
        if (_clipFailures >= 5 && _clipIntervalId) {
          clearInterval(_clipIntervalId);
          console.warn('[clipboard-watcher] Disabled after repeated PowerShell failures');
        }
        return;
      }
      _clipFailures = 0;
      const out = stdout.trim();
      if (!out || out === 'NONE') return;
      try {
        const buf = Buffer.from(out, 'base64');
        if (buf.length < 100) return;
        const hash = createHash('sha256').update(buf).digest('hex');
        if (hash === _clipLastHash) return;
        _clipLastHash = hash;
        if (seed) return; // Suppress whatever was already in clipboard at startup
        if (_imageRecentlySeen(buf)) return;
        const localName = `screenshot-${Date.now()}.png`;
        const localPath = join(IMAGES_DIR, localName);
        try { writeFileSync(localPath, buf); } catch {}
        const dataUrl = `data:image/png;base64,${out}`;
        console.log(`[clipboard-watcher] New clipboard image (${(buf.length / 1024).toFixed(0)}KB) → ${localName}`);
        broadcastToWhiteboard({ type: 'screenshot:auto', dataUrl, filename: localName, localPath });
      } catch (err) {
        console.warn('[clipboard-watcher] Failed to process clipboard image:', err.message);
      }
    });
  };

  _pollClipboard(true); // seed: record current clipboard hash without broadcasting
  _clipIntervalId = setInterval(() => _pollClipboard(false), 1500);
  console.log('[clipboard-watcher] Windows clipboard image polling enabled');
}

// ── Cards WebSocket clients (Claude MCP integration) ──
const cardsClients = new Set(); // Set<WebSocket>
const cardsPendingOps = new Map(); // requestId → { resolve, reject, timer }
let cardsViewport = { width: 1920, height: 1080 }; // updated by browser on WS connect + resize

function broadcastToCards(message, excludeWs = null) {
  const data = JSON.stringify(message);
  for (const client of cardsClients) {
    if (client !== excludeWs && client.readyState === 1) client.send(data);
  }
}

function handleCardsWebSocket(ws) {
  cardsClients.add(ws);
  console.log(`[ws-cards] Client connected (total: ${cardsClients.size})`);

  // Send init with current open card count
  try {
    const state = loadUiState();
    const raw = state['neural-open-cards'];
    const cards = raw ? (typeof raw === 'string' ? JSON.parse(raw) : raw) : [];
    ws.send(JSON.stringify({ type: 'init', openCount: cards.length }));
  } catch { /* ignore */ }

  ws.on('message', (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === 'viewport') {
        cardsViewport = { width: msg.width, height: msg.height };
        console.log(`[ws-cards] Viewport: ${msg.width}x${msg.height}`);
      }

      // ACK responses from browser for card operations (open/close/update)
      if (msg.type === 'ack' && msg.requestId) {
        const pending = cardsPendingOps.get(msg.requestId);
        if (pending) {
          clearTimeout(pending.timer);
          cardsPendingOps.delete(msg.requestId);
          if (msg.ok) {
            pending.resolve(msg.result || {});
          } else {
            pending.reject(new Error(msg.error || 'Operation failed'));
          }
        }
      }

      // Screenshot response from browser
      if (msg.type === 'screenshot:response' && msg.requestId) {
        const pending = cardsPendingOps.get(msg.requestId);
        if (pending) {
          clearTimeout(pending.timer);
          cardsPendingOps.delete(msg.requestId);
          pending.resolve(msg.data);
        }
      }

      if (msg.type === 'screenshot:error' && msg.requestId) {
        const pending = cardsPendingOps.get(msg.requestId);
        if (pending) {
          clearTimeout(pending.timer);
          cardsPendingOps.delete(msg.requestId);
          pending.reject(new Error(msg.error || 'Screenshot failed'));
        }
      }
    } catch { /* ignore malformed */ }
  });

  ws.on('close', () => {
    cardsClients.delete(ws);
    console.log(`[ws-cards] Client disconnected (remaining: ${cardsClients.size})`);
  });
}

// ═══════════════════════════════════════════
// BROWSER — WebSocket Handler
// ═══════════════════════════════════════════

async function handleBrowserWebSocket(ws, url) {
  const sessionId = url.pathname.replace('/ws/browser/', '');
  const session = browserSessions.get(sessionId);

  if (!session) {
    ws.send(JSON.stringify({ type: 'error', message: 'Browser session not found' }));
    ws.close();
    return;
  }

  console.log('[ws-browser] Client connected for session', sessionId, 'persistent:', !!session._isPersistent, 'clients:', session.clients.size + 1);
  session.clients.add(ws);
  if (session.graceTimer) { clearTimeout(session.graceTimer); session.graceTimer = null; }

  // Validate the browser page is still alive before reusing the session
  try {
    await session.page.evaluate('1');
  } catch {
    console.warn('[ws-browser] Page is dead for session', sessionId, '— destroying zombie');
    session.clients.delete(ws);
    await destroyBrowserSession(sessionId);
    ws.send(JSON.stringify({ type: 'error', message: 'Browser session expired' }));
    ws.close();
    return;
  }

  // Send current state including tab info
  ws.send(JSON.stringify({
    type: 'init',
    url: session.currentUrl,
    title: session.title,
    activeTabId: session.activeTabId || null,
    tabs: session.tabs ? [...session.tabs.entries()].map(([tid, t]) => ({
      id: tid, url: t.url, title: t.title, active: tid === session.activeTabId,
    })) : [],
  }));

  // Start screencast if not already running
  try { await startScreencast(session); } catch (err) {
    console.error('[ws-browser] Screencast start failed:', err.message);
    ws.send(JSON.stringify({ type: 'error', message: `Screencast start failed: ${err.message}` }));
  }

  ws.on('message', async (raw) => {
    try {
      const msg = JSON.parse(raw.toString());

      if (msg.type === 'navigate' && msg.url) {
        try {
          await session.page.goto(msg.url, { waitUntil: 'domcontentloaded', timeout: 15000 });
          session.currentUrl = session.page.url();
          session.title = await session.page.title().catch(() => '');
        } catch (err) {
          ws.send(JSON.stringify({ type: 'error', message: err.message }));
        }
      } else if (msg.type === 'back') {
        await session.page.goBack({ timeout: 10000 }).catch(() => {});
      } else if (msg.type === 'forward') {
        await session.page.goForward({ timeout: 10000 }).catch(() => {});
      } else if (msg.type === 'reload') {
        await session.page.reload({ timeout: 15000 }).catch(() => {});
      } else if (msg.type === 'click') {
        // Forward mouse click at coordinates relative to viewport
        await session.page.mouse.click(msg.x, msg.y, {
          button: msg.button || 'left',
        }).catch(() => {});
      } else if (msg.type === 'dblclick') {
        await session.page.mouse.dblclick(msg.x, msg.y).catch(() => {});
      } else if (msg.type === 'mousemove') {
        await session.page.mouse.move(msg.x, msg.y).catch(() => {});
      } else if (msg.type === 'mousedown') {
        await session.page.mouse.down({ button: msg.button || 'left' }).catch(() => {});
      } else if (msg.type === 'mouseup') {
        await session.page.mouse.up({ button: msg.button || 'left' }).catch(() => {});
      } else if (msg.type === 'wheel') {
        await session.page.mouse.wheel(msg.deltaX || 0, msg.deltaY || 0).catch(() => {});
      } else if (msg.type === 'keydown') {
        await session.page.keyboard.down(msg.key).catch(() => {});
      } else if (msg.type === 'keyup') {
        await session.page.keyboard.up(msg.key).catch(() => {});
      } else if (msg.type === 'keypress') {
        // For typing text characters
        await session.page.keyboard.type(msg.text || '').catch(() => {});
      } else if (msg.type === 'pause-screencast') {
        await stopScreencast(session).catch(() => {});
      } else if (msg.type === 'resume-screencast') {
        if (session.screencastActive) {
          // Already streaming (throttled) — restart at full rate
          const scCfg = loadBrowserConfig().screencast || {};
          await session.cdpSession.send('Page.startScreencast', {
            format: scCfg.format || 'jpeg',
            quality: scCfg.quality ?? 80,
            maxWidth: scCfg.maxWidth || 1280,
            maxHeight: scCfg.maxHeight || 800,
            everyNthFrame: scCfg.everyNthFrame || 2,
          }).catch(() => {});
        } else {
          // Was fully paused — start fresh
          await startScreencast(session).catch(() => {});
        }
      } else if (msg.type === 'throttle-screencast') {
        // Reduce to ~2fps for non-focused browser windows
        if (session.screencastActive) {
          const scCfg = loadBrowserConfig().screencast || {};
          await session.cdpSession.send('Page.startScreencast', {
            format: scCfg.format || 'jpeg',
            quality: Math.min(scCfg.quality ?? 80, 50),
            maxWidth: scCfg.maxWidth || 1280,
            maxHeight: scCfg.maxHeight || 800,
            everyNthFrame: 15,
          }).catch(() => {});
        }
      } else if (msg.type === 'resize') {
        // Resize viewport and update screencast dimensions without stopping
        const w = Math.max(320, Math.min(3840, msg.width || 1280));
        const h = Math.max(200, Math.min(2160, msg.height || 800));
        await session.page.setViewportSize({ width: w, height: h }).catch(() => {});
        // Send new startScreencast directly — CDP replaces params atomically, no gap
        const scCfg2 = loadBrowserConfig().screencast || {};
        await session.cdpSession.send('Page.startScreencast', {
          format: scCfg2.format || 'jpeg',
          quality: scCfg2.quality ?? 80,
          maxWidth: w, maxHeight: h,
          everyNthFrame: scCfg2.everyNthFrame || 2,
        }).catch(() => {});
        session.screencastActive = true;
      } else if (msg.type === 'switch-tab' && msg.tabId) {
        // Client requests tab switch
        try {
          await _switchSessionTab(session, sessionId, msg.tabId);
        } catch (err) {
          ws.send(JSON.stringify({ type: 'error', message: `Tab switch failed: ${err.message}` }));
        }
      } else if (msg.type === 'new-tab') {
        // Client requests new tab
        try {
          const tab = await createSessionTab(session, sessionId, msg.url || 'about:blank');
          await _switchSessionTab(session, sessionId, tab.tabId);
          ws.send(JSON.stringify({ type: 'tab-created', tabId: tab.tabId, url: tab.url, title: tab.title }));
        } catch (err) {
          ws.send(JSON.stringify({ type: 'error', message: `New tab failed: ${err.message}` }));
        }
      } else if (msg.type === 'close-tab' && msg.tabId) {
        // Client requests tab close
        try {
          await closeSessionTab(session, sessionId, msg.tabId);
        } catch (err) {
          ws.send(JSON.stringify({ type: 'error', message: `Close tab failed: ${err.message}` }));
        }
      }
    } catch { /* ignore malformed */ }
  });

  ws.on('close', () => {
    session.clients.delete(ws);
    if (session.clients.size === 0 && browserSessions.has(sessionId)) {
      // Stop screencast when nobody is watching
      stopScreencast(session).catch(() => {});
      // Grace period before killing browser
      session.graceTimer = setTimeout(async () => {
        if (session.clients.size === 0 && browserSessions.has(sessionId)) {
          // Don't destroy if an active agent, loop, or interactive session owns a
          // tab here (in-memory — no file I/O race)
          if (session._agentOwnedSet?.size > 0 || session._loopOwned?.size > 0 || session._interactiveOwned?.size > 0) {
            console.log(`[browser] Grace period: skipping destroy — active agent/loop/interactive owner uses session ${sessionId}`);
            return;
          }
          await destroyBrowserSession(sessionId);
        }
      }, BROWSER_GRACE_PERIOD_MS);
    }
  });
}

// ═══════════════════════════════════════════
// SESSION SNAPSHOT — Periodic save for resume
// ═══════════════════════════════════════════
// Windows kills node hard on terminal close — no signals fire.
// Instead, heartbeat every 30s to keep last-session.json current.

const SESSION_SNAPSHOT_INTERVAL_MS = 30_000;
const SERVER_START_TIME = Date.now();
const RESUME_GRACE_PERIOD_MS = 120_000; // 2 min — don't delete snapshot before client can check

function saveSessionSnapshot() {
  const sessions = [];
  const seen = new Set(); // dedup — avoid resuming same Claude session twice

  // First pass: sessions with known claudeSessionId (from resume or detect endpoint)
  for (const [id, session] of terminalSessions) {
    if (session.profile !== 'claude-code') continue;
    if (!session.claudeSessionId) continue;
    if (seen.has(session.claudeSessionId)) continue;
    seen.add(session.claudeSessionId);
    sessions.push({ profile: 'claude-code', cwd: session.cwd, claudeSessionId: session.claudeSessionId });
  }

  // Second pass: sessions without known ID — try detection, excluding already-claimed IDs
  for (const [id, session] of terminalSessions) {
    if (session.profile !== 'claude-code') continue;
    if (session.claudeSessionId) continue; // already handled
    const csid = detectClaudeSessionForCwd(session.cwd, session.createdAt, seen);
    if (!csid) continue;
    seen.add(csid);
    session.claudeSessionId = csid; // cache it
    sessions.push({ profile: 'claude-code', cwd: session.cwd, claudeSessionId: csid });
  }

  if (sessions.length === 0) {
    // Don't delete during grace period — client may not have checked for resume yet
    if (Date.now() - SERVER_START_TIME < RESUME_GRACE_PERIOD_MS) return;
    // No Claude Code sessions — clean up stale snapshot
    try { if (existsSync(LAST_SESSION_PATH)) unlinkSync(LAST_SESSION_PATH); } catch {}
    return;
  }

  try {
    writeFileSync(LAST_SESSION_PATH, JSON.stringify({ timestamp: Date.now(), sessions }, null, 2), 'utf-8');
  } catch {}
}

// Heartbeat: snapshot active sessions every 30s
setInterval(saveSessionSnapshot, SESSION_SNAPSHOT_INTERVAL_MS);

// Also try to save on clean shutdown (works with Ctrl+C, not window close)
// Manual termination paths (Ctrl+C, kill, parent shell exit) all flow through
// gracefulShutdown — same teardown the in-app restart/shutdown/update paths
// use. Without this, hand-killed servers still leave orphaned opencode +
// agent children holding file handles, which blocks `npm i -g synabun`.
process.on('SIGINT', async () => {
  console.log('\n[server] SIGINT received.');
  await gracefulShutdown('sigint');
  await flushLoopLogs().catch(() => {});
  process.exit(0);
});
process.on('SIGTERM', async () => {
  console.log('\n[server] SIGTERM received.');
  await gracefulShutdown('sigterm');
  await flushLoopLogs().catch(() => {});
  process.exit(0);
});
// `exit` fires after process.exit() — only safe for synchronous final tasks.
// gracefulShutdown is async so we cannot await here; just snapshot + ocp stop
// best-effort. The async paths above are the primary teardown.
//
// The SIGKILL below is the fix for the onnxruntime-node macOS at-exit abort
// (`libc++abi: ... mutex lock failed`). ORT always leaves ~4 ThreadPoolTempl
// worker threads alive (single-threaded session options reduce but cannot
// remove them); when the process exits normally, `__cxa_finalize` destroys the
// threadpool's static mutex while those threads are live → std::terminate. This
// `exit` handler is the single choke point every exit path passes through, so
// after the synchronous cleanup we SIGKILL ourselves: uncatchable, runs no C++
// destructors, and all flushing is already done so nothing is lost. Verified:
// self-SIGKILL from inside `exit` terminates 137-clean with no abort.
// Exception: the supervised-restart path needs its exit code (75) to reach the
// supervisor, so it sets `_preserveExitCode` and we let it exit normally.
process.on('exit', () => {
  try { setKeepAwake(false); } catch {}
  try { restoreSleepSync(); } catch {}
  try { terminalHost.killNow(); } catch {}
  try { _whatsapp?.killNow(); } catch {}
  try { tunnel.killNow(); } catch {}
  try { gitBash.cancel(); } catch {}
  try { stopOpencodeServer(); } catch {}
  try { editorCompletionServe.stop('exit'); } catch {}
  try { _claudeBridge?.shutdownAllBridges?.(); } catch {}
  try { saveSessionSnapshot(); } catch {}
  try { flushUiStateSync(); } catch {}
  try { flushWhiteboardSync(); } catch {}
  try { flushCostDataSync(); } catch {}
  try { memoryMap.flushSync(); } catch {}
  if (_preserveExitCode) return;
  try { process.kill(process.pid, 'SIGKILL'); } catch {}
});
